/**
 * Template Grouping Configuration
 *
 * Maps all prompt templates to named groups for left panel navigation
 * in the Vault prompt editor UI.
 */

import { PROMPT_TEMPLATES } from '$lib/services/prompts/templates'
import type { PromptTemplate } from '$lib/services/prompts/types'

export interface TemplateGroup {
  name: string
  templates: PromptTemplate[]
}

/** Template IDs mapped to display group names */
const TEMPLATE_GROUP_MAP: Record<string, string> = {
  // Story Generation
  adventure: 'Story Generation',
  'editor-adventure': 'Story Generation',

  // Analysis
  classifier: 'Analysis',
  'style-reviewer': 'Analysis',
  'lorebook-classifier': 'Analysis',
  'tier3-entry-selection': 'Analysis',

  // Memory
  'chapter-analysis': 'Memory',
  'chapter-summarization': 'Memory',
  'retrieval-decision': 'Memory',
  'lore-management': 'Memory',
  'interactive-lorebook': 'Memory',
  'interactive-lorebook-greeting': 'Memory',
  'agentic-retrieval': 'Memory',

  // Suggestions & Actions
  'action-choices': 'Suggestions & Actions',
  'timeline-fill': 'Suggestions & Actions',
  'timeline-fill-answer': 'Suggestions & Actions',
  'interactive-editor-assistant': 'Suggestions & Actions',

  // Image
  'image-style-soft-anime': 'Image',
  'image-style-semi-realistic': 'Image',
  'image-style-photorealistic': 'Image',
  'image-prompt-analysis': 'Image',
  'image-prompt-analysis-reference': 'Image',
  'image-portrait-generation': 'Image',
  'background-image-prompt-analysis': 'Image',

  // Translation
  'translate-narration': 'Translation',
  'translate-input': 'Translation',
  'translate-ui': 'Translation',
  'translate-action-choices': 'Translation',
  'translate-wizard-content': 'Translation',

  // Wizard
  'setting-expansion': 'Wizard',
  'setting-refinement': 'Wizard',
  'protagonist-generation': 'Wizard',
  'character-elaboration': 'Wizard',
  'character-refinement': 'Wizard',
  'supporting-characters': 'Wizard',
  'opening-generation-adventure': 'Wizard',
  'opening-refinement-adventure': 'Wizard',
  'character-card-import': 'Wizard',
  'vault-character-import': 'Wizard',
  'st-import-style-detection': 'Wizard',
  'st-import-style-rewrite': 'Wizard',
  'st-import-creative-cleanup': 'Wizard',
}

/** Group display order */
const GROUP_ORDER = [
  'Story Generation',
  'Analysis',
  'Memory',
  'Suggestions & Actions',
  'Image',
  'Translation',
  'Wizard',
]

/**
 * Build template groups from PROMPT_TEMPLATES.
 * Returns ordered array of groups, each containing their templates.
 */
export function getTemplateGroups(): TemplateGroup[] {
  const groupMap = new Map<string, PromptTemplate[]>()

  for (const template of PROMPT_TEMPLATES) {
    const groupName = TEMPLATE_GROUP_MAP[template.id] ?? 'Other'
    if (!groupMap.has(groupName)) {
      groupMap.set(groupName, [])
    }
    groupMap.get(groupName)!.push(template)
  }

  // Include 'Other' group at the end if it exists
  const orderedGroups = GROUP_ORDER.filter((name) => groupMap.has(name))
  if (groupMap.has('Other')) {
    orderedGroups.push('Other')
  }

  return orderedGroups.map((name) => ({
    name,
    templates: groupMap.get(name)!,
  }))
}

/** Get the group name for a template ID */
export function getTemplateGroup(templateId: string): string {
  return TEMPLATE_GROUP_MAP[templateId] ?? 'Other'
}

/**
 * Type definitions and constants for the Setup Wizard
 */

import type { Wand2 } from 'lucide-svelte'
import type { Genre, Tense } from '$lib/services/ai/wizard'
import { LorebookImportExport } from '$lib/services/lorebookImportExport'
import type { POV, EntryType } from '$lib/types'

/**
 * An imported lorebook with its entries and metadata
 */
export interface ImportedLorebookItem {
  id: string
  vaultId?: string // If imported from vault
  filename: string
  result: LorebookImportExport.LorebookImportResult
  entries: LorebookImportExport.ImportedEntry[]
  expanded: boolean
  /** Whether this lorebook is currently being processed (parsing or classifying) */
  isLoading?: boolean
  /** Current loading phase message (e.g., "Parsing...", "Classifying entries...") */
  loadingMessage?: string
  /** Classification progress for this specific lorebook */
  classificationProgress?: { current: number; total: number }
}

/**
 * Genre option for display in the wizard
 */
export interface GenreOption {
  id: Genre
  name: string
  icon: typeof Wand2
  description: string
}

/**
 * POV option for display in the wizard
 */
export interface POVOption {
  id: POV
  label: string
  example: string
}

/**
 * Tense option for display in the wizard
 */
export interface TenseOption {
  id: Tense
  label: string
  example: string
}

/**
 * Get entry type color class
 */
export function getTypeColor(type: EntryType): string {
  switch (type) {
    case 'character':
      return 'text-blue-400'
    case 'location':
      return 'text-green-400'
    case 'item':
      return 'text-yellow-400'
    case 'faction':
      return 'text-purple-400'
    case 'concept':
      return 'text-cyan-400'
    case 'event':
      return 'text-red-400'
    default:
      return 'text-surface-400'
  }
}

/**
 * Get type counts from entries array
 */
export function getTypeCounts(
  entries: LorebookImportExport.ImportedEntry[],
): Record<string, number> {
  return {
    character: entries.filter((e) => e.type === 'character').length,
    location: entries.filter((e) => e.type === 'location').length,
    item: entries.filter((e) => e.type === 'item').length,
    faction: entries.filter((e) => e.type === 'faction').length,
    concept: entries.filter((e) => e.type === 'concept').length,
    event: entries.filter((e) => e.type === 'event').length,
  }
}

/**
 * Style {{user}} placeholders in text for display
 */
export function styleUserPlaceholders(text: string): string {
  return text.replace(
    /\{\{user\}\}/gi,
    '<span class="inline-flex items-center px-1.5 py-0.5 mx-0.5 rounded bg-primary-600/30 text-primary-300 text-xs font-mono border border-primary-500/40">{{user}}</span>',
  )
}

/**
 * Replace {{user}} placeholders with actual name
 */
export function replaceUserPlaceholders(text: string, name: string): string {
  if (!text) return text
  return text.replace(/\{\{user\}\}/gi, name)
}

/**
 * Tone presets for writing style
 */
export const tonePresets = [
  'Immersive and engaging',
  'Dark and atmospheric',
  'Light and whimsical',
  'Gritty and realistic',
  'Poetic and lyrical',
  'Action-packed and fast-paced',
]

/**
 * Tense options
 */
export const tenseOptions: TenseOption[] = [
  { id: 'present', label: 'Present', example: 'You see a door.' },
  { id: 'past', label: 'Past', example: 'You saw a door.' },
]

import { generatePlainText } from '$lib/services/ai/sdk'
import { renderStoryPrompt } from '$lib/services/prompts'
import type { EntryMetadata } from '$lib/types'

export type NarrativeHelperAudience = 'full_table' | 'player_subset' | 'private_player'
export type NarrativeHelperMood = 'tense' | 'mystical' | 'dramatic' | 'light' | 'neutral'

export interface NarrativeHelperExpandInput {
  storyId: string
  summary: string
  sceneSummary?: string
  mood?: NarrativeHelperMood
  audience?: NarrativeHelperAudience
  includeFactCheck?: boolean
  signal?: AbortSignal
}

export interface NarrativeHelperRegenerateInput {
  storyId: string
  summary: string
  previousText?: string
  tone?: NarrativeHelperMood | 'more_direct' | 'more_poetic'
  signal?: AbortSignal
}

export function buildNarrativeHelperMetadata(
  summary: string,
  generatedNarration: string,
): EntryMetadata {
  return {
    source: 'gm-narration-helper',
    narrativeHelper: {
      summary,
      generatedNarration,
      createdAt: new Date().toISOString(),
    },
  } as EntryMetadata
}

export class NarrativeHelperService {
  async expandSummary(input: NarrativeHelperExpandInput): Promise<string> {
    const summary = input.summary.trim()
    if (!summary) throw new Error('A summary is required before narration expansion.')

    const scene = input.sceneSummary?.trim() || 'No extra scene context was supplied.'
    const audience = input.audience ?? 'full_table'
    const mood = input.mood ?? 'neutral'
    const prompt = await renderStoryPrompt(input.storyId, 'narrative-helper', {
      narrativeHelperOperation: 'expand',
      summary,
      sceneSummary: scene,
      audience,
      mood,
      includeFactCheck: input.includeFactCheck ? 'yes' : 'no',
      previousNarration: '',
    })

    return generatePlainText(
      {
        presetId: 'agentic',
        system: prompt.system,
        prompt: prompt.user,
        signal: input.signal,
      },
      'narrative-helper',
    )
  }

  async regenerate(input: NarrativeHelperRegenerateInput): Promise<string> {
    const summary = input.summary.trim()
    if (!summary) throw new Error('A summary is required before regeneration.')
    const prompt = await renderStoryPrompt(input.storyId, 'narrative-helper', {
      narrativeHelperOperation: 'regenerate',
      summary,
      sceneSummary: 'No extra scene context was supplied.',
      audience: 'full_table',
      mood: input.tone ?? 'neutral',
      includeFactCheck: 'no',
      previousNarration: input.previousText?.trim() || '(none)',
    })

    return generatePlainText(
      {
        presetId: 'agentic',
        system: prompt.system,
        prompt: prompt.user,
        signal: input.signal,
      },
      'narrative-helper',
    )
  }
}

export const narrativeHelperService = new NarrativeHelperService()

import { generateStructured } from '$lib/services/ai/sdk'
import { z } from 'zod'
import type { Campaign, CampaignSettings } from '$lib/types'

const encounterPrerollSchema = z.object({
  name: z.string().min(1),
  enemies: z.string().min(1),
  difficulty: z.enum(['trivial', 'easy', 'moderate', 'hard', 'deadly']),
  description: z.string().min(1),
  environmentalHazards: z.string().optional(),
})

const lootPrerollSchema = z.object({
  itemName: z.string().min(1),
  rarity: z.enum(['common', 'uncommon', 'rare', 'very_rare', 'legendary']),
  type: z.string().min(1),
  description: z.string().min(1),
  estimatedGold: z.number().min(0),
})

export interface PrerolledEncounter {
  id: string
  name: string
  enemies: string
  difficulty: 'trivial' | 'easy' | 'moderate' | 'hard' | 'deadly'
  description: string
  environmentalHazards?: string
}

export interface PrerolledLoot {
  id: string
  itemName: string
  rarity: 'common' | 'uncommon' | 'rare' | 'very_rare' | 'legendary'
  type: string
  description: string
  estimatedGold: number
}

export class PrerollService {
  async prerollEncountersForSession(
    campaign: Campaign,
    settings: CampaignSettings,
    sceneMode: string,
    count: number = 15,
  ): Promise<PrerolledEncounter[]> {
    if (count <= 0) throw new Error('Encounter count must be at least 1')
    if (count > 30) throw new Error('Cannot pre-roll more than 30 encounters at once')

    const encounters: PrerolledEncounter[] = []
    const systemPrompt = [
      `You are generating tabletop RPG encounters for a campaign in ${settings.worldCharter ? 'a specific world' : 'a generic fantasy setting'}.`,
      `Scene mode: ${sceneMode}`,
      `Party intensity level: ${settings.nsfwIntensity}/8`,
      'Generate varied, interesting encounters that fit the current scene mode.',
      'Difficulty should vary across the set.',
    ].join('\n')

    for (let i = 0; i < count; i++) {
      const result = await generateStructured(
        {
          presetId: 'agentic',
          schema: encounterPrerollSchema,
          system: systemPrompt,
          prompt: `Generate encounter ${i + 1}/${count} for a ${sceneMode} scene. Return JSON only.`,
        },
        'preroll-encounter',
      )

      encounters.push({
        id: crypto.randomUUID(),
        name: result.name,
        enemies: result.enemies,
        difficulty: result.difficulty,
        description: result.description,
        environmentalHazards: result.environmentalHazards,
      })
    }

    return encounters
  }

  async prerollLootForSession(
    campaign: Campaign,
    settings: CampaignSettings,
    expectedEnemyCount: number = 5,
  ): Promise<PrerolledLoot[]> {
    if (expectedEnemyCount <= 0) throw new Error('Expected enemy count must be at least 1')

    const lootItems: PrerolledLoot[] = []
    const count = Math.min(expectedEnemyCount + 2, 10) // Pre-roll 2 extra in case GM needs more

    const systemPrompt = [
      `You are generating loot drops for a tabletop RPG campaign.`,
      `Campaign intensity: ${settings.nsfwIntensity}/8`,
      `Expected enemy count: ${expectedEnemyCount}`,
      'Generate varied loot appropriate for the campaign tone.',
      'Include a mix of rarities, but skew common->uncommon for low enemy counts.',
    ].join('\n')

    for (let i = 0; i < count; i++) {
      const result = await generateStructured(
        {
          presetId: 'agentic',
          schema: lootPrerollSchema,
          system: systemPrompt,
          prompt: `Generate loot item ${i + 1}/${count}. Return JSON only.`,
        },
        'preroll-loot',
      )

      lootItems.push({
        id: crypto.randomUUID(),
        itemName: result.itemName,
        rarity: result.rarity,
        type: result.type,
        description: result.description,
        estimatedGold: result.estimatedGold,
      })
    }

    return lootItems
  }
}

export const prerollService = new PrerollService()

import { z } from 'zod'
import { generateStructured } from '$lib/services/ai/sdk'
import { ContextBuilder } from '$lib/services/context/context-builder'
import { packService } from '$lib/services/packs/pack-service'
import type { AIPlayerProposal, InteractionAudience } from '$lib/types'

const proposalResultSchema = z.object({
  action: z.string().min(1),
  reasoning: z.string().min(1),
  confidence: z.number().min(1).max(10),
})

export interface AIPlayerProposalRequest {
  storyId: string
  campaignId: string
  aiPlayerId: string
  characterId: string
  sceneMode: string
  sceneSummary: string
  recentActions?: string[]
  goal?: string
  targetLength?: string
  audience?: InteractionAudience
}

export class AIPlayerProposalService {
  async generateProposal(request: AIPlayerProposalRequest): Promise<AIPlayerProposal> {
    const audience = request.audience ?? { kind: 'full_table' as const }
    const context = await ContextBuilder.forAIPlayer(
      request.storyId,
      request.aiPlayerId,
      undefined,
      audience,
      request.recentActions,
    )
    context.add({
      sceneMode: request.sceneMode,
      narrativeResponse: request.sceneSummary,
      aiPlayerSceneGoal: request.goal ?? '',
      aiPlayerTargetLength: request.targetLength ?? '',
      aiPlayerRecentActions: (request.recentActions ?? []).join('\n'),
    })
    // Guard against a pack missing this template row, which would otherwise render
    // empty and silently fall back to the generic prompt below with no GM guidance.
    await packService.ensurePromptTemplateComplete(context.getPackId(), 'ai-player-proposal')
    const renderedContext = context.getContext()
    const proposalPrompt = await context.render('ai-player-proposal')
    const result = await generateStructured(
      {
        presetId: 'agentic',
        schema: proposalResultSchema,
        system: proposalPrompt.system || renderedContext.aiPlayerPrompt || 'You are an AI Player.',
        prompt: proposalPrompt.user || 'Propose one concrete, playable action for your character.',
      },
      'aiPlayerProposal',
    )

    return {
      id: crypto.randomUUID(),
      aiPlayerId: request.aiPlayerId,
      characterId: request.characterId,
      campaignId: request.campaignId,
      sceneMode: request.sceneMode,
      action: result.action,
      reasoning: result.reasoning,
      confidence: result.confidence,
      reviewStatus: 'pending',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }
  }

  async generateProposals(requests: AIPlayerProposalRequest[]): Promise<AIPlayerProposal[]> {
    return Promise.all(requests.map((request) => this.generateProposal(request)))
  }
}

export const aiPlayerProposalService = new AIPlayerProposalService()

/**
 * Service Factory
 *
 * Factory for creating AI service instances.
 * Services receive a service ID and resolve presets dynamically via settings.getServicePresetId().
 */

import { settings } from '$lib/stores/settings.svelte'
import { NarrativeService } from '../generation/NarrativeService'
import { ClassifierService } from '../generation/ClassifierService'
import { MemoryService } from '../generation/MemoryService'
import { ActionChoicesService } from '../generation/ActionChoicesService'
import { DisclosureGateService } from '../generation/DisclosureGateService'
import { DirectorOutliningAssistantService } from '../generation/DirectorOutliningAssistantService'
import { InteractiveDirectorAssistantService } from '../generation/InteractiveDirectorAssistantService'
import { InteractiveEditorAssistantService } from '../generation/InteractiveEditorAssistantService'
import { StyleReviewerService } from '../generation/StyleReviewerService'
import { EntryInjector, type ContextConfig } from '../generation/EntryInjector'
import { LoreManagementService } from '../lorebook/LoreManagementService'
import { AgenticRetrievalService } from '../retrieval/AgenticRetrievalService'
import { TimelineFillService } from '../retrieval/TimelineFillService'
import {
  EntryRetrievalService,
  getEntryRetrievalConfigFromSettings,
} from '../retrieval/EntryRetrievalService'
import { TranslationService } from '../utils/TranslationService'
import { ImageAnalysisService } from '../image/ImageAnalysisService'
import { BackgroundImageService } from '../image/BackgroundImageService'
import { RulesetAssistantService } from '../ruleset/RulesetAssistantService'
import { PersonalityService } from '../../ai-player/personality-service'

/**
 * Factory class for creating AI services.
 */
export class ServiceFactory {
  // ===== Service Instance Creators =====

  /**
   * Create a narrative service instance.
   * This is the core service for story generation.
   * Uses main narrative profile directly (no preset needed).
   */
  createNarrativeService(): NarrativeService {
    return new NarrativeService()
  }

  /**
   * Create a classifier service instance.
   */
  createClassifierService(): ClassifierService {
    return new ClassifierService(
      'classifier',
      settings.systemServicesSettings.classifier.chatHistoryTruncation ?? 100,
    )
  }

  /**
   * Create a memory service instance.
   */
  createMemoryService(): MemoryService {
    return new MemoryService('memory')
  }

  /**
   * Create an action choices service instance.
   */
  createActionChoicesService(): ActionChoicesService {
    return new ActionChoicesService('actionChoices')
  }

  createAIPlayerPersonalityService(): PersonalityService {
    return new PersonalityService()
  }

  /**
   * Create a disclosure gate service instance.
   */
  createDisclosureGateService(): DisclosureGateService {
    return new DisclosureGateService('disclosureGate')
  }

  /**
   * Create a director outlining assistant service instance.
   */
  createDirectorOutliningAssistantService(): DirectorOutliningAssistantService {
    return new DirectorOutliningAssistantService('directorOutliningAssistant')
  }

  /**
   * Create an interactive director assistant service instance.
   */
  createInteractiveDirectorAssistantService(): InteractiveDirectorAssistantService {
    return new InteractiveDirectorAssistantService('directorOutliningAssistant')
  }

  /**
   * Create an interactive editor assistant service instance.
   */
  createInteractiveEditorAssistantService(): InteractiveEditorAssistantService {
    return new InteractiveEditorAssistantService('editorAssistant')
  }

  /**
   * Create a style reviewer service instance.
   */
  createStyleReviewerService(): StyleReviewerService {
    return new StyleReviewerService('styleReviewer')
  }

  createRulesetAssistantService(): RulesetAssistantService {
    return new RulesetAssistantService('rulesetAssistant')
  }

  /**
   * Create an entry injector instance.
   */
  createEntryInjector(config?: Partial<ContextConfig>): EntryInjector {
    return new EntryInjector(config, 'entryRetrieval')
  }

  /**
   * Create an entry retrieval service instance.
   */
  createEntryRetrievalService(): EntryRetrievalService {
    const config = getEntryRetrievalConfigFromSettings()
    return new EntryRetrievalService(config, 'entryRetrieval')
  }

  /**
   * Create a lore management service instance.
   */
  createLoreManagementService(): LoreManagementService {
    const loreManagementSettings = settings.systemServicesSettings.loreManagement
    return new LoreManagementService('loreManagement', loreManagementSettings.maxIterations)
  }

  /**
   * Create an agentic retrieval service instance.
   */
  createAgenticRetrievalService(): AgenticRetrievalService {
    const agenticRetrievalSettings = settings.systemServicesSettings.agenticRetrieval
    return new AgenticRetrievalService('agenticRetrieval', agenticRetrievalSettings.maxIterations)
  }

  /**
   * Create a timeline fill service instance.
   */
  createTimelineFillService(): TimelineFillService {
    const timelineFillSettings = settings.systemServicesSettings.timelineFill
    return new TimelineFillService('timelineFill', timelineFillSettings.maxQueries)
  }

  /**
   * Create a timeline fill service for chapter queries.
   */
  createChapterQueryService(): TimelineFillService {
    const timelineFillSettings = settings.systemServicesSettings.timelineFill
    return new TimelineFillService('chapterQuery', timelineFillSettings.maxQueries)
  }

  /**
   * Create a translation service instance for a specific translation type.
   */
  createTranslationService(
    type: 'narration' | 'input' | 'ui' | 'suggestions' | 'actionChoices' | 'wizard',
  ): TranslationService {
    return new TranslationService(`translation:${type}`)
  }

  /**
   * Create an image analysis service instance.
   * Used for "analyzed" mode where LLM identifies imageable scenes in narrative.
   */
  createImageAnalysisService(): ImageAnalysisService {
    return new ImageAnalysisService('imageGeneration')
  }

  /**
   * Create a background image service instance.
   */
  createBackgroundImageService(): BackgroundImageService {
    const imageSettings = settings.systemServicesSettings.imageGeneration
    if (!imageSettings.backgroundProfileId) {
      throw new Error('Background profile ID is missing')
    }
    return new BackgroundImageService('bgImageGeneration', imageSettings)
  }
}

// Export singleton instance
export const serviceFactory = new ServiceFactory()

import { generateStructured } from '../sdk/generate'
import { z } from 'zod'
/**
 * Classifier Service
 *
 * Extracts world state from narrative responses (characters, locations, items, story beats).
 * Uses the Vercel AI SDK for structured output with Zod schema validation.
 *
 * NOTE: For classifier output types (CharacterUpdate, NewCharacter, etc.),
 * import directly from '$lib/services/ai/sdk/schemas/classifier'.
 *
 * Prompt generation flows through ContextBuilder + Liquid templates.
 */

import type {
  Story,
  StoryEntry,
  Character,
  Location,
  Item,
  StoryBeat,
  TimeTracker,
} from '$lib/types'
import { BaseAIService } from '../BaseAIService'
import { ContextBuilder } from '$lib/services/context'
import { database } from '$lib/services/database'
import { templateEngine } from '$lib/services/templates/engine'
import { createLogger } from '$lib/log'
import { stripPicTags } from '$lib/utils/inlineImageParser'
import { formatCharacterAppearance } from '$lib/utils/characterAppearance'
import {
  buildClassificationResultSchema,
  clampNumber,
  type ClassificationResult,
} from '../sdk/schemas/classifier'
import { buildExtendedClassificationSchema } from '../sdk/schemas/runtime-variables'
import type { RuntimeVariable, RuntimeEntityType } from '$lib/services/packs/types'

const log = createLogger('Classifier')

type ClothingMetadata = {
  isClothing?: boolean
  coveredZones?: string[]
  exposedZones?: string[]
  durability?: number
  maxDurability?: number
  unusable?: boolean
}

type InferredClothingState = {
  name: string
  clothingState: {
    damageSeverity?: 'minor' | 'moderate' | 'major' | 'destroyed'
    newlyExposedZones?: string[]
    restoredZones?: string[]
    repaired?: boolean
  }
}

type InferredMoneyUpdate = {
  delta: number
  transactionType?:
    | 'purchase'
    | 'sale'
    | 'reward'
    | 'loot'
    | 'wage'
    | 'fee'
    | 'bribe'
    | 'theft'
    | 'gamble'
    | 'other'
  reason?: string
  deniedPurchase?: boolean
  attemptedCost?: number
}

const llmMoneyUpdateSchema = z.object({
  delta: z.number(),
  transactionType: z
    .enum([
      'purchase',
      'sale',
      'reward',
      'loot',
      'wage',
      'fee',
      'bribe',
      'theft',
      'gamble',
      'other',
    ])
    .optional(),
  reason: z.string().optional(),
  deniedPurchase: z.boolean().optional(),
  attemptedCost: z.number().optional(),
})

const llmMoneyExtractionSchema = z.object({
  moneyUpdate: llmMoneyUpdateSchema.nullable().optional(),
})

/**
 * Context for classification.
 */
export interface ClassificationContext {
  storyId: string
  story: Story
  narrativeResponse: string
  userAction: string
  existingCharacters: Character[]
  existingLocations: Location[]
  existingItems: Item[]
  existingStoryBeats: StoryBeat[]
}

/**
 * Service that classifies narrative responses to extract world state changes.
 */
export class ClassifierService extends BaseAIService {
  private chatHistoryTruncation: number

  constructor(serviceId: string, chatHistoryTruncation: number = 100) {
    super(serviceId)
    this.chatHistoryTruncation = chatHistoryTruncation
  }

  private getToggle(
    story: Story,
    key: keyof NonNullable<Story['settings']>,
    defaultValue: boolean,
  ): boolean {
    const value = story.settings?.[key]
    return typeof value === 'boolean' ? value : defaultValue
  }

  /**
   * Classify a narrative response to extract world state changes.
   * When the story's pack defines runtime variables, the schema is dynamically
   * extended to include inline runtime variable extraction in the same LLM pass.
   */
  async classify(
    context: ClassificationContext,
    visibleEntries?: StoryEntry[],
    currentStoryTime?: TimeTracker | null,
  ): Promise<ClassificationResult> {
    log('classify', {
      narrativeLength: context.narrativeResponse.length,
      existingCharacters: context.existingCharacters.length,
      existingLocations: context.existingLocations.length,
      existingItems: context.existingItems.length,
      existingStoryBeats: context.existingStoryBeats.length,
    })

    const mode = context.story.mode ?? 'adventure'
    const characterClassificationEnabled = this.getToggle(
      context.story,
      'characterClassificationEnabled',
      true,
    )
    const locationClassificationEnabled = this.getToggle(
      context.story,
      'locationClassificationEnabled',
      true,
    )
    const inventoryClassificationEnabled = this.getToggle(
      context.story,
      'inventoryClassificationEnabled',
      true,
    )
    const storyBeatClassificationEnabled = this.getToggle(
      context.story,
      'storyBeatClassificationEnabled',
      true,
    )
    const sceneClassificationEnabled = this.getToggle(
      context.story,
      'sceneClassificationEnabled',
      true,
    )
    const timeClassificationEnabled = this.getToggle(
      context.story,
      'timeClassificationEnabled',
      true,
    )
    const runtimeVarClassificationEnabled = this.getToggle(
      context.story,
      'runtimeVarClassificationEnabled',
      true,
    )
    const moneyClassificationEnabled =
      !!context.story.settings?.moneySystemEnabled &&
      this.getToggle(context.story, 'moneyClassificationEnabled', true)

    const itemAcquisitionFallbackEnabled =
      inventoryClassificationEnabled &&
      this.getToggle(context.story, 'itemAcquisitionFallbackEnabled', true)
    const clothingStateFallbackEnabled =
      inventoryClassificationEnabled &&
      this.getToggle(context.story, 'clothingStateFallbackEnabled', true)
    const moneyFallbackEnabled =
      moneyClassificationEnabled && this.getToggle(context.story, 'moneyFallbackEnabled', true)
    const moneyRecoveryEnabled =
      moneyClassificationEnabled && this.getToggle(context.story, 'moneyRecoveryEnabled', true)

    // Load runtime variable definitions for the story's pack (if any)
    let runtimeVars: RuntimeVariable[] = []
    let runtimeVarsByType: Record<string, RuntimeVariable[]> = {}
    if (runtimeVarClassificationEnabled) {
      const packId = await database.getStoryPackId(context.storyId)
      if (packId) {
        runtimeVars = await database.getRuntimeVariables(packId)
        runtimeVarsByType = this.groupByEntityType(runtimeVars)
      }
    }

    const baseSchema = buildClassificationResultSchema({
      characterClassificationEnabled,
      locationClassificationEnabled,
      inventoryClassificationEnabled,
      storyBeatClassificationEnabled,
      sceneClassificationEnabled,
      timeClassificationEnabled,
      moneyClassificationEnabled,
    })

    // Build the schema: extended with inline vars if runtime variables exist, else base
    const schema =
      runtimeVars.length > 0
        ? buildExtendedClassificationSchema(runtimeVarsByType, baseSchema)
        : baseSchema

    // Format existing entities for the prompt
    const existingCharacters = characterClassificationEnabled
      ? this.formatExistingCharacters(context.existingCharacters, context.existingItems)
      : '(character classification disabled for this story)'
    const existingLocations = locationClassificationEnabled
      ? context.existingLocations.map((l) => l.name).join(', ') || '(none)'
      : '(location classification disabled for this story)'
    const existingItems = inventoryClassificationEnabled
      ? this.formatExistingItems(context.existingItems)
      : '(item classification disabled for this story)'
    const existingBeats = storyBeatClassificationEnabled
      ? this.formatExistingBeats(context.existingStoryBeats)
      : '(story beat classification disabled for this story)'

    // Build chat history block if entries provided
    const chatHistoryBlock = visibleEntries
      ? this.buildChatHistoryBlock(visibleEntries, currentStoryTime)
      : ''

    // Build time info
    const currentTimeInfo = currentStoryTime
      ? `Current story time: Year ${currentStoryTime.years}, Day ${currentStoryTime.days}, ${String(currentStoryTime.hours).padStart(2, '0')}:${String(currentStoryTime.minutes).padStart(2, '0')}`
      : ''

    // Build custom variable instructions for the prompt
    const customVariableInstructions =
      runtimeVars.length > 0 ? this.buildCustomVarInstructions(runtimeVarsByType) : ''

    // Create ContextBuilder from story -- auto-populates mode, pov, tense, genre, etc.
    const ctx = await ContextBuilder.forStory(context.storyId)

    // Add all runtime variables explicitly via ctx.add()
    ctx.add({
      genre: context.story.genre ? `Genre: ${context.story.genre}` : '',
      mode,
      entityCounts: `${context.existingCharacters.length} characters, ${context.existingLocations.length} locations, ${context.existingItems.length} items`,
      currentTimeInfo,
      chatHistoryBlock,
      inputLabel: 'Player Action',
      userAction: stripPicTags(context.userAction),
      narrativeResponse: stripPicTags(context.narrativeResponse),
      existingCharacters,
      existingLocations,
      existingItems,
      existingBeats,
      storyBeatTypes: storyBeatClassificationEnabled
        ? 'milestone, quest, revelation, event, plot_point'
        : '(story beat classification disabled)',
      itemLocationOptions: 'inventory, worn, ground, or specific location name',
      defaultItemLocation: 'inventory',
      sceneLocationDesc: sceneClassificationEnabled
        ? 'Name of current location if identifiable, null otherwise'
        : '(scene classification disabled)',
      clothingSystemInstructions:
        inventoryClassificationEnabled && context.story.settings?.clothingSystemEnabled
          ? '## Clothing System Active\nKnown clothing items may include durability and covered/exposed zones. When narration damages, tears, ruins, removes, repairs, or re-covers an existing clothing item, update that item via itemUpdates.changes.clothingState rather than creating a new item.'
          : '',
      moneySystemInstructions: moneyClassificationEnabled
        ? `## Money System Active\nCurrency name: ${(context.story.settings?.moneyName ?? 'gold').trim() || 'gold'}\nCurrent money: ${Math.max(0, Math.floor(context.story.settings?.moneyAmount ?? 0))}\nCRITICAL: If this passage includes a transaction cue (buy/sell/pay/spend/cost/reward/loot/wage) and any explicit amount/currency, you MUST output scene.moneyUpdate.\nUse delta as net money change (negative spend, positive gain).\nFor unaffordable purchases, set deniedPurchase=true and delta=0.`
        : '',
      customVariableInstructions,
      characterClassificationEnabled,
      locationClassificationEnabled,
      inventoryClassificationEnabled,
      storyBeatClassificationEnabled,
      sceneClassificationEnabled,
      timeClassificationEnabled,
      moneyClassificationEnabled,
    })

    // Render through the classifier template
    const { system, user: prompt } = await ctx.render('classifier')

    try {
      const result = (await generateStructured(
        {
          presetId: this.presetId,
          schema,
          system,
          prompt,
        },
        'classifier',
      )) as ClassificationResult

      if (!characterClassificationEnabled) {
        result.entryUpdates.characterUpdates = []
        result.entryUpdates.newCharacters = []
      }

      if (!locationClassificationEnabled) {
        result.entryUpdates.locationUpdates = []
        result.entryUpdates.newLocations = []
      }

      if (!inventoryClassificationEnabled) {
        result.entryUpdates.itemUpdates = []
        result.entryUpdates.newItems = []
      }

      if (!storyBeatClassificationEnabled) {
        result.entryUpdates.storyBeatUpdates = []
        result.entryUpdates.newStoryBeats = []
      }

      if (!sceneClassificationEnabled) {
        result.scene.currentLocationName = null
        result.scene.presentCharacterNames = []
      }

      if (!timeClassificationEnabled) {
        result.scene.timeProgression = 'none'
      }

      if (!moneyClassificationEnabled) {
        delete result.scene.moneyUpdate
      } else {
        if (moneyRecoveryEnabled) {
          this.markMoneyExtractionMiss(result, context)
          await this.tryLlmMoneyRecovery(result, context)
        }
      }

      if (itemAcquisitionFallbackEnabled) {
        this.applyItemAcquisitionFallback(result, context)
      }
      if (clothingStateFallbackEnabled) {
        this.applyClothingStateFallback(result, context)
      }
      if (moneyFallbackEnabled) {
        this.applyMoneyFallback(result, context)
      }

      // Post-process: clamp number values to min/max constraints
      if (runtimeVars.length > 0) {
        this.clampRuntimeVarNumbers(result, runtimeVarsByType)
      }

      // Attach runtime variable definitions for use by applyClassificationResult
      if (runtimeVars.length > 0) {
        result._runtimeVarDefs = runtimeVars
      }

      log('classify complete', {
        characterUpdates: result.entryUpdates.characterUpdates.length,
        newCharacters: result.entryUpdates.newCharacters.length,
        locationUpdates: result.entryUpdates.locationUpdates.length,
        newLocations: result.entryUpdates.newLocations.length,
        itemUpdates: result.entryUpdates.itemUpdates.length,
        newItems: result.entryUpdates.newItems.length,
        storyBeatUpdates: result.entryUpdates.storyBeatUpdates.length,
        newStoryBeats: result.entryUpdates.newStoryBeats.length,
        timeProgression: result.scene.timeProgression,
        hasRuntimeVars: runtimeVars.length > 0,
      })

      return result
    } catch (error) {
      log('classify failed', error)
      const fallbackResult: ClassificationResult = {
        entryUpdates: {
          characterUpdates: [],
          locationUpdates: [],
          itemUpdates: [],
          storyBeatUpdates: [],
          newCharacters: [],
          newLocations: [],
          newItems: [],
          newStoryBeats: [],
        },
        scene: {
          currentLocationName: null,
          presentCharacterNames: [],
          timeProgression: 'none',
        },
        _classifierFallbackUsed: true,
        _classifierError: error instanceof Error ? error.message : String(error),
      }
      if (itemAcquisitionFallbackEnabled) {
        this.applyItemAcquisitionFallback(fallbackResult, context)
      }
      if (clothingStateFallbackEnabled) {
        this.applyClothingStateFallback(fallbackResult, context)
      }
      if (moneyFallbackEnabled) {
        this.applyMoneyFallback(fallbackResult, context)
      }
      if (moneyRecoveryEnabled) {
        this.markMoneyExtractionMiss(fallbackResult, context)
      }
      // Return empty result on failure
      return fallbackResult
    }
  }

  private markMoneyExtractionMiss(
    result: ClassificationResult,
    context: ClassificationContext,
  ): void {
    if (!context.story.settings?.moneySystemEnabled) return
    if (result.scene.moneyUpdate) return

    const text = `${context.userAction}\n${context.narrativeResponse}`.toLowerCase()
    const transactionCue =
      /\b(buy|bought|purchase|purchased|pay|paid|spend|spent|cost|fee|fees|rent|bribe|sell|sold|earn|earned|gain|gained|reward|wage|loot|found|profit|payment)\b/i
    const amountCue = /\b\d+(?:\.\d+)?\b/
    const currencyName = (context.story.settings.moneyName ?? 'gold').trim().toLowerCase() || 'gold'
    const currencyCue = new RegExp(
      `\\b(${currencyName.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}|gold|coin|coins|credits?|cash|dollars?|bucks?|crowns?|gp)\\b`,
      'i',
    )

    const likelyMoneyEvent =
      transactionCue.test(text) && (amountCue.test(text) || currencyCue.test(text))

    if (!likelyMoneyEvent) return

    result._moneyExtractionMissed = true
    result._moneyExtractionMissReason =
      'Classifier omitted scene.moneyUpdate despite transaction cues and amount/currency cues in passage.'

    log('Classifier money extraction miss detected', {
      storyId: context.storyId,
      currencyName,
    })
  }

  private async tryLlmMoneyRecovery(
    result: ClassificationResult,
    context: ClassificationContext,
  ): Promise<void> {
    if (!result._moneyExtractionMissed) return
    if (result.scene.moneyUpdate) return

    const currencyName = (context.story.settings?.moneyName ?? 'gold').trim() || 'gold'
    const currentMoney = Math.max(0, Math.floor(context.story.settings?.moneyAmount ?? 0))

    const system = await this.buildMoneyRecoverySystemPrompt(context)

    const prompt = [
      'Money extraction context:',
      `- Currency name: ${currencyName}`,
      `- Current money: ${currentMoney}`,
      '- Rules:',
      '  - If buy/pay/spend/cost/fee/bribe indicates money loss, delta must be negative.',
      '  - If sell/reward/loot/wage/earn indicates gain, delta must be positive.',
      '  - If purchase fails due to insufficient funds, set deniedPurchase=true and delta=0.',
      '',
      'User action:',
      context.userAction,
      '',
      'Narrative response:',
      context.narrativeResponse,
    ].join('\n')

    try {
      const recovered = await generateStructured(
        {
          presetId: this.presetId,
          schema: llmMoneyExtractionSchema,
          system,
          prompt,
        },
        'classifier',
      )

      const recoveredMoney = recovered?.moneyUpdate
      if (recoveredMoney) {
        result.scene.moneyUpdate = {
          delta: recoveredMoney.delta,
          transactionType: recoveredMoney.transactionType,
          reason: recoveredMoney.reason,
          deniedPurchase: recoveredMoney.deniedPurchase,
          attemptedCost: recoveredMoney.attemptedCost,
        }
        result._moneyExtractionMissed = false
        result._moneyExtractionMissReason = undefined

        log('Recovered moneyUpdate via secondary LLM pass', {
          delta: recoveredMoney.delta,
          transactionType: recoveredMoney.transactionType,
          deniedPurchase: recoveredMoney.deniedPurchase ?? false,
        })
      }
    } catch (error) {
      log('Secondary LLM money recovery failed', error)
    }
  }

  private async buildMoneyRecoverySystemPrompt(context: ClassificationContext): Promise<string> {
    const packId = (await database.getStoryPackId(context.storyId)) ?? 'default-pack'
    const template =
      (await database.getPackTemplate(packId, 'classifier-money-recovery')) ??
      (packId !== 'default-pack'
        ? await database.getPackTemplate('default-pack', 'classifier-money-recovery')
        : null)

    if (!template?.content?.trim()) {
      return 'Extract only money changes from the passage. Return JSON only. If no clear money change occurred, return {"moneyUpdate": null}. Use negative delta for spending and positive delta for earnings.'
    }

    const templateVars: Record<string, string> = {
      storyTitle: String(context.story.title ?? ''),
      storyMode: String(context.story.mode ?? 'adventure'),
      moneyName: String(context.story.settings?.moneyName ?? 'gold'),
    }

    return templateEngine.render(template.content, templateVars) ?? ''
  }

  /**
   * Fallback: infer acquired items from narration when classifier output misses them.
   * This is intentionally conservative and only runs when no item changes were extracted.
   */
  private applyItemAcquisitionFallback(
    result: ClassificationResult,
    context: ClassificationContext,
  ): void {
    if (result.entryUpdates.newItems.length > 0 || result.entryUpdates.itemUpdates.length > 0) {
      return
    }

    const inferred = this.inferAcquiredItemsFromNarrative(
      context.narrativeResponse,
      context.userAction,
      context.existingItems,
    )

    if (inferred.length === 0) return

    result.entryUpdates.newItems.push(...inferred)

    log('Applied item acquisition fallback', {
      inferredCount: inferred.length,
      inferredItems: inferred.map((i) => i.name),
    })
  }

  private inferAcquiredItemsFromNarrative(
    narrative: string,
    userAction: string,
    existingItems: Item[],
  ): Array<{
    name: string
    description?: string
    quantity?: number
    location?: string
    equipped?: boolean
  }> {
    const text = `${userAction}\n${narrative}`
    const lower = text.toLowerCase()

    const acquisitionCue =
      /\b(given|hands over|handed|receives?|accepted|takes?|took|caught|opens?|opened|drawstring|peers inside|inside the|satchel|pack|pouch|chest|backpack|inventory)\b/i

    if (!acquisitionCue.test(lower)) {
      return []
    }

    const existingNames = new Set(existingItems.map((i) => i.name.trim().toLowerCase()))
    const inferred: Array<{
      name: string
      description?: string
      quantity?: number
      location?: string
      equipped?: boolean
    }> = []
    const inferredNames = new Set<string>()

    const parseCountWord = (raw: string): number | null => {
      const value = raw.toLowerCase().trim()
      if (/^\d+$/.test(value)) return Number(value)
      const lookup: Record<string, number> = {
        a: 1,
        an: 1,
        one: 1,
        two: 2,
        three: 3,
        four: 4,
        five: 5,
        six: 6,
        seven: 7,
        eight: 8,
        nine: 9,
        ten: 10,
      }
      return lookup[value] ?? null
    }

    const singularize = (name: string): string => {
      if (name.length > 4 && /ies$/i.test(name)) return name.replace(/ies$/i, 'y')
      if (name.length > 3 && /s$/i.test(name)) return name.replace(/s$/i, '')
      return name
    }

    const addCandidate = (raw: string, quantity = 1) => {
      const name = raw
        .replace(/^[\s,.;:]+|[\s,.;:]+$/g, '')
        .replace(/^and\s+/i, '')
        .replace(/\s{2,}/g, ' ')
        .trim()

      if (name.length < 3 || name.length > 80) return

      const normalized = singularize(name).toLowerCase()
      if (existingNames.has(normalized) || inferredNames.has(normalized)) return

      inferred.push({
        name: singularize(name),
        quantity: Math.max(1, Math.floor(quantity)),
        location: 'inventory',
        equipped: false,
      })
      inferredNames.add(normalized)
    }

    // Pattern A: list-like item introductions (A/An ... rests/lies/nestled/is ...)
    const listPattern =
      /(?:^|[.!?]\s+)(?:and\s+)?(?:a|an)\s+([^.,;\n—]+?)(?:\s+(?:rests|lies|nestled|sits|is|in|with|at)\b|[.,;\n—])/gim

    for (const match of narrative.matchAll(listPattern)) {
      addCandidate(match[1])
      if (inferred.length >= 8) break
    }

    // Pattern B: explanatory references after acquisition ("The rope is...", "The dagger...")
    if (inferred.length < 8) {
      const explPattern =
        /\bthe\s+([a-z][a-z0-9' -]{2,60}?)\s+(?:is|are|was|were|catches|rests)\b/gim
      for (const match of narrative.matchAll(explPattern)) {
        addCandidate(match[1])
        if (inferred.length >= 8) break
      }
    }

    // Pattern C: quantity-first acquisitions in inventory/container phrasing
    // e.g., "Two sewing kits join the satchel's growing contents."
    if (inferred.length < 8) {
      const qtyJoinPattern =
        /\b(\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten)\s+([a-z][a-z0-9' -]{2,60}?)\s+(?:join|joins|joined|added to|go(?:es)? into|into|in)\s+(?:the\s+)?(?:satchel|pack|pouch|backpack|inventory|bag|drawer|contents?)\b/gim
      for (const match of narrative.matchAll(qtyJoinPattern)) {
        const quantity = parseCountWord(match[1]) ?? 1
        addCandidate(match[2], quantity)
        if (inferred.length >= 8) break
      }
    }

    // Only keep candidates that look like concrete items, not abstract phrases.
    const badEndings = ['scene', 'corridors', 'display', 'shelf', 'stockings', 'tail']
    return inferred.filter((item) => {
      const n = item.name.toLowerCase()
      return !badEndings.some((bad) => n.endsWith(bad))
    })
  }

  /**
   * Fallback: infer clothing damage/repair state from narration when classifier misses it.
   * Runs only when clothing system is enabled and no clothingState updates are present.
   */
  private applyClothingStateFallback(
    result: ClassificationResult,
    context: ClassificationContext,
  ): void {
    if (!context.story.settings?.clothingSystemEnabled) return

    const hasClassifierClothingState = result.entryUpdates.itemUpdates.some(
      (u) => !!(u.changes as Record<string, unknown>)?.clothingState,
    )
    if (hasClassifierClothingState) return

    const inferred = this.inferClothingStateFromNarrative(
      context.narrativeResponse,
      context.userAction,
      context.existingItems,
    )
    if (inferred.length === 0) return

    for (const inf of inferred) {
      const existing = result.entryUpdates.itemUpdates.find(
        (u) => u.name.toLowerCase() === inf.name.toLowerCase(),
      )
      if (existing) {
        ;(existing.changes as Record<string, unknown>).clothingState = inf.clothingState
      } else {
        result.entryUpdates.itemUpdates.push({
          name: inf.name,
          changes: {
            clothingState: inf.clothingState,
          },
        } as ClassificationResult['entryUpdates']['itemUpdates'][number])
      }
    }

    log('Applied clothing state fallback', {
      inferredCount: inferred.length,
      items: inferred.map((i) => i.name),
    })
  }

  private inferClothingStateFromNarrative(
    narrative: string,
    userAction: string,
    existingItems: Item[],
  ): InferredClothingState[] {
    const text = `${userAction}\n${narrative}`.toLowerCase()

    const damageCue =
      /\b(torn|ripped|shredded|frayed|split|damaged|ruined|destroyed|snapped|slashed|cut open|falls away|torn off|ripped off|stripped)\b/i
    const repairCue =
      /\b(repair|repaired|mend|mended|sew|sewn|stitch|stitched|patch|patched|fixed)\b/i

    if (!damageCue.test(text) && !repairCue.test(text)) {
      return []
    }

    const clothingItems = existingItems.filter((item) => {
      const metadata = (item.metadata ?? {}) as Record<string, unknown>
      const clothing = metadata.clothing as ClothingMetadata | undefined
      return item.equipped && !!clothing?.isClothing
    })

    if (clothingItems.length === 0) return []

    const inferSeverity = ():
      | InferredClothingState['clothingState']['damageSeverity']
      | undefined => {
      if (
        /\b(destroyed|ruined|torn off|ripped off|falls away|shredded to|in tatters)\b/i.test(text)
      ) {
        return 'destroyed'
      }
      if (/\b(shredded|ripped open|torn open|slashed through|split wide)\b/i.test(text)) {
        return 'major'
      }
      if (/\b(torn|ripped|split|frayed|damaged|snapped)\b/i.test(text)) {
        return 'moderate'
      }
      if (/\b(scuffed|strained|worn|snagged|stretched)\b/i.test(text)) {
        return 'minor'
      }
      return undefined
    }

    const zoneMap: Array<{ zone: string; pattern: RegExp }> = [
      { zone: 'chest', pattern: /\b(chest|breasts?|cleavage|bust)\b/i },
      { zone: 'hips', pattern: /\b(hips?|pelvis|crotch|pussy|groin)\b/i },
      { zone: 'legs', pattern: /\b(legs?|thighs?|calves?)\b/i },
      { zone: 'torso', pattern: /\b(torso|stomach|belly|abdomen|back)\b/i },
      { zone: 'arms', pattern: /\b(arms?)\b/i },
      { zone: 'hands', pattern: /\b(hands?)\b/i },
      { zone: 'feet', pattern: /\b(feet|foot|ankles?)\b/i },
    ]

    const mentionedZones = zoneMap.filter((z) => z.pattern.test(text)).map((z) => z.zone)

    const results: InferredClothingState[] = []
    for (const item of clothingItems) {
      const name = item.name.toLowerCase()
      const nameTokens = name.split(/[^a-z0-9]+/).filter((t) => t.length > 2)
      const explicitNameMention = text.includes(name)
      const partialNameMention = nameTokens.some((token) => text.includes(token))

      const clothingMeta = ((item.metadata ?? {}) as Record<string, unknown>).clothing as
        | ClothingMetadata
        | undefined
      const coveredZones = Array.isArray(clothingMeta?.coveredZones)
        ? clothingMeta.coveredZones
        : []

      const relevantZones = mentionedZones.filter((zone) => coveredZones.includes(zone))

      // Conservative guard: require explicit item mention, or a single equipped clothing item.
      if (!explicitNameMention && !(partialNameMention && clothingItems.length === 1)) {
        continue
      }

      const severity = inferSeverity()
      const repaired = repairCue.test(text)

      const clothingState: InferredClothingState['clothingState'] = {}
      if (severity) clothingState.damageSeverity = severity
      if (repaired) clothingState.repaired = true

      if (repairCue.test(text)) {
        if (relevantZones.length > 0) clothingState.restoredZones = relevantZones
      } else if (damageCue.test(text)) {
        if (relevantZones.length > 0) clothingState.newlyExposedZones = relevantZones
      }

      if (
        !clothingState.damageSeverity &&
        !clothingState.repaired &&
        (!clothingState.newlyExposedZones || clothingState.newlyExposedZones.length === 0) &&
        (!clothingState.restoredZones || clothingState.restoredZones.length === 0)
      ) {
        continue
      }

      results.push({
        name: item.name,
        clothingState,
      })
    }

    return results
  }

  /**
   * Fallback: infer money change from narration when classifier misses it.
   * Runs only when money system is enabled and scene.moneyUpdate is absent.
   */
  private applyMoneyFallback(result: ClassificationResult, context: ClassificationContext): void {
    if (!context.story.settings?.moneySystemEnabled) return

    // Only trust classifier-provided money updates when they carry a meaningful event.
    // Some models return a default/no-op moneyUpdate object (delta=0), which would
    // otherwise suppress heuristic extraction.
    const existing = result.scene.moneyUpdate
    const hasMeaningfulClassifierMoneyUpdate =
      !!existing &&
      ((Number.isFinite(existing.delta) && Math.abs(existing.delta) > 0) ||
        !!existing.deniedPurchase)
    if (hasMeaningfulClassifierMoneyUpdate) return

    const currencyName = (context.story.settings.moneyName ?? 'gold').trim() || 'gold'
    const currentMoney = Math.max(0, Math.floor(context.story.settings.moneyAmount ?? 0))

    const inferred = this.inferMoneyUpdateFromNarrative(
      context.narrativeResponse,
      context.userAction,
      currencyName,
      currentMoney,
    )

    if (!inferred) return

    result.scene.moneyUpdate = inferred

    log('Applied money fallback', {
      delta: inferred.delta,
      type: inferred.transactionType,
      deniedPurchase: inferred.deniedPurchase ?? false,
      attemptedCost: inferred.attemptedCost,
    })
  }

  private inferMoneyUpdateFromNarrative(
    narrative: string,
    userAction: string,
    currencyName: string,
    currentMoney: number,
  ): InferredMoneyUpdate | null {
    const text = `${userAction}\n${narrative}`
    const lower = text.toLowerCase()

    const escapeRegex = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

    const parseNumberWords = (raw: string): number | null => {
      const units: Record<string, number> = {
        zero: 0,
        one: 1,
        two: 2,
        three: 3,
        four: 4,
        five: 5,
        six: 6,
        seven: 7,
        eight: 8,
        nine: 9,
        ten: 10,
        eleven: 11,
        twelve: 12,
        thirteen: 13,
        fourteen: 14,
        fifteen: 15,
        sixteen: 16,
        seventeen: 17,
        eighteen: 18,
        nineteen: 19,
      }
      const tens: Record<string, number> = {
        twenty: 20,
        thirty: 30,
        forty: 40,
        fifty: 50,
        sixty: 60,
        seventy: 70,
        eighty: 80,
        ninety: 90,
      }

      const tokens = raw.toLowerCase().replace(/-/g, ' ').split(/\s+/).filter(Boolean)

      if (tokens.length === 0) return null

      let total = 0
      let current = 0
      let sawNumberToken = false

      for (const token of tokens) {
        if (token === 'and') continue
        if (token in units) {
          current += units[token]
          sawNumberToken = true
          continue
        }
        if (token in tens) {
          current += tens[token]
          sawNumberToken = true
          continue
        }
        if (token === 'hundred') {
          current = (current || 1) * 100
          sawNumberToken = true
          continue
        }
        if (token === 'thousand') {
          total += (current || 1) * 1000
          current = 0
          sawNumberToken = true
          continue
        }
        return null
      }

      if (!sawNumberToken) return null
      const value = total + current
      return value >= 0 ? value : null
    }

    const parseAmountToken = (raw: string): number | null => {
      const trimmed = raw.trim().toLowerCase()
      const numeric = Number(trimmed)
      if (Number.isFinite(numeric)) return numeric
      return parseNumberWords(trimmed)
    }

    const deniedPurchasePattern =
      /\b(can'?t afford|cannot afford|could not afford|too expensive|insufficient funds|not enough (?:money|gold|credits|cash|coins))\b/i
    const spendCuePattern =
      /\b(buy|bought|purchase|purchased|pay|paid|spend|spent|cost|fee|fees|bribe|tip|rent)\b/i
    const earnCuePattern =
      /\b(sell|sold|earn|earned|gain|gained|find|found|loot|reward|wage|profit|payment)\b/i

    const amountMatches = Array.from(text.matchAll(/\b(\d+(?:\.\d+)?)\b/g)).map((m) => ({
      amount: Number(m[1]),
      index: m.index ?? -1,
    }))

    const currencyNameEscaped = escapeRegex(currencyName.trim())
    const currencyWordPattern =
      '(?:gold|coins?|credits?|cash|dollars?|bucks?|crowns?|gp' +
      (currencyNameEscaped ? `|${currencyNameEscaped}` : '') +
      ')'
    const numberWordsPattern =
      '(?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|and|-)+'

    const wordAmountMatches = Array.from(
      lower.matchAll(new RegExp(`\\b(${numberWordsPattern})\\s+${currencyWordPattern}\\b`, 'gi')),
    )
      .map((m) => {
        const parsed = parseNumberWords(m[1])
        return {
          amount: parsed,
          index: m.index ?? -1,
        }
      })
      .filter((m): m is { amount: number; index: number } => typeof m.amount === 'number')

    amountMatches.push(...wordAmountMatches)

    const currencyLower = currencyName.toLowerCase()
    const currencyTokens = currencyLower.split(/\s+/).filter((t) => t.length > 1)
    const nearCurrency = (idx: number): boolean => {
      if (idx < 0) return false
      const start = Math.max(0, idx - 24)
      const end = Math.min(lower.length, idx + 24)
      const window = lower.slice(start, end)
      if (window.includes(currencyLower)) return true
      return currencyTokens.some((token) => window.includes(token))
    }

    const currencyAmounts = amountMatches.filter((m) => nearCurrency(m.index))
    const candidateAmounts = currencyAmounts.length > 0 ? currencyAmounts : amountMatches

    if (deniedPurchasePattern.test(lower)) {
      const attemptedRaw = candidateAmounts.find((m) => m.amount > 0)?.amount
      const attemptedCost =
        typeof attemptedRaw === 'number' && attemptedRaw > currentMoney ? attemptedRaw : undefined
      return {
        delta: 0,
        transactionType: 'purchase',
        deniedPurchase: true,
        attemptedCost,
        reason: 'Purchase denied due to insufficient funds',
      }
    }

    let spent = 0
    let earned = 0

    for (const match of candidateAmounts) {
      if (!(match.amount > 0) || match.index < 0) continue
      const start = Math.max(0, match.index - 36)
      const end = Math.min(lower.length, match.index + 36)
      const window = lower.slice(start, end)

      const spendHit = spendCuePattern.test(window)
      const earnHit = earnCuePattern.test(window)

      if (spendHit && !earnHit) {
        spent += match.amount
      } else if (earnHit && !spendHit) {
        earned += match.amount
      }
    }

    // Fallback to phrase-level patterns when amount-window matching failed.
    if (spent === 0) {
      for (const m of lower.matchAll(
        /\b(?:pay|paid|spent|cost(?:s)?|buy|bought|purchase(?:d)?)\s+(?:for\s+)?(\d+(?:\.\d+)?)\b/g,
      )) {
        spent += Number(m[1])
      }

      // Word-number variant: "paid fifty", "spent twenty".
      for (const m of lower.matchAll(
        /\b(?:pay|paid|spent|cost(?:s)?|buy|bought|purchase(?:d)?)\s+(?:for\s+)?((?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|and|-|\s)+)\b/g,
      )) {
        const parsed = parseAmountToken(m[1])
        if (parsed && parsed > 0) spent += parsed
      }

      // Handles phrasing like "purchased two sewing kits for 50 gold".
      for (const m of lower.matchAll(
        /\b(?:buy|bought|purchase(?:d)?|ordered?|acquire(?:d)?)\b[\s\S]{0,80}?\bfor\s+(\d+(?:\.\d+)?)\b/g,
      )) {
        spent += Number(m[1])
      }

      // Word-number variant: "purchased ... for fifty gold".
      for (const m of lower.matchAll(
        /\b(?:buy|bought|purchase(?:d)?|ordered?|acquire(?:d)?)\b[\s\S]{0,80}?\bfor\s+((?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|and|-|\s)+)\b/g,
      )) {
        const parsed = parseAmountToken(m[1])
        if (parsed && parsed > 0) spent += parsed
      }

      // Handles phrasing like "it cost 50 gold" / "price was 50".
      for (const m of lower.matchAll(
        /\b(?:cost(?:s|ing)?|price(?:d)?\s+(?:at|was)|total(?:ed)?)\s+(\d+(?:\.\d+)?)\b/g,
      )) {
        spent += Number(m[1])
      }

      // Word-number variant: "it cost fifty gold" / "price was fifty".
      for (const m of lower.matchAll(
        /\b(?:cost(?:s|ing)?|price(?:d)?\s+(?:at|was)|total(?:ed)?)\s+((?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|and|-|\s)+)\b/g,
      )) {
        const parsed = parseAmountToken(m[1])
        if (parsed && parsed > 0) spent += parsed
      }
    }
    if (earned === 0) {
      for (const m of lower.matchAll(
        /\b(?:sell|sold|earned|gain(?:ed)?|found|loot(?:ed)?|reward(?:ed)?|paid\s+you)\s+(\d+(?:\.\d+)?)\b/g,
      )) {
        earned += Number(m[1])
      }

      // Word-number variant: "earned fifty", "rewarded forty".
      for (const m of lower.matchAll(
        /\b(?:sell|sold|earned|gain(?:ed)?|found|loot(?:ed)?|reward(?:ed)?|paid\s+you)\s+((?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|and|-|\s)+)\b/g,
      )) {
        const parsed = parseAmountToken(m[1])
        if (parsed && parsed > 0) earned += parsed
      }
    }

    // Conservative final fallback: single currency amount + clear spend/earn cue in passage.
    if (spent === 0 && earned === 0 && candidateAmounts.length === 1) {
      const amount = candidateAmounts[0].amount
      if (amount > 0) {
        const spendPassage = spendCuePattern.test(lower)
        const earnPassage = earnCuePattern.test(lower)
        if (spendPassage && !earnPassage) {
          spent = amount
        } else if (earnPassage && !spendPassage) {
          earned = amount
        }
      }
    }

    const roundedDelta = Math.round((earned - spent) * 100) / 100
    if (roundedDelta === 0) return null

    let transactionType: InferredMoneyUpdate['transactionType'] = 'other'
    if (roundedDelta < 0) {
      if (/\b(bribe|tip)\b/i.test(lower)) transactionType = 'bribe'
      else if (/\b(fee|toll|rent)\b/i.test(lower)) transactionType = 'fee'
      else if (/\b(gamble|bet)\b/i.test(lower)) transactionType = 'gamble'
      else transactionType = 'purchase'
    } else if (roundedDelta > 0) {
      if (/\b(sell|sold)\b/i.test(lower)) transactionType = 'sale'
      else if (/\b(loot|found|treasure)\b/i.test(lower)) transactionType = 'loot'
      else if (/\b(wage|salary|paid\s+you)\b/i.test(lower)) transactionType = 'wage'
      else if (/\b(reward|bounty)\b/i.test(lower)) transactionType = 'reward'
      else transactionType = 'other'
    }

    return {
      delta: roundedDelta,
      transactionType,
      reason: roundedDelta < 0 ? 'Narrative spending detected' : 'Narrative earnings detected',
    }
  }

  /**
   * Group runtime variables by entity type.
   */
  private groupByEntityType(vars: RuntimeVariable[]): Record<string, RuntimeVariable[]> {
    return vars.reduce(
      (acc, v) => {
        if (!acc[v.entityType]) acc[v.entityType] = []
        acc[v.entityType].push(v)
        return acc
      },
      {} as Record<string, RuntimeVariable[]>,
    )
  }

  /**
   * Build the prompt instruction block describing custom variables to track.
   * Grouped by entity type for clarity.
   */
  private buildCustomVarInstructions(varsByType: Record<string, RuntimeVariable[]>): string {
    const ENTITY_TYPE_LABELS: Record<RuntimeEntityType, { updates: string; new: string }> = {
      character: { updates: 'character updates', new: 'new characters' },
      location: { updates: 'location updates', new: 'new locations' },
      item: { updates: 'item updates', new: 'new items' },
      story_beat: { updates: 'story beat updates', new: 'new story beats' },
    }

    const sections: string[] = []

    for (const [entityType, vars] of Object.entries(varsByType)) {
      if (vars.length === 0) continue
      const labels = ENTITY_TYPE_LABELS[entityType as RuntimeEntityType]
      if (!labels) continue

      const varLines = vars.map((v) => {
        let line = `- ${v.variableName}`
        const parts: string[] = []

        // Type description
        if (v.variableType === 'number') {
          let numDesc = 'number'
          if (v.minValue !== undefined && v.maxValue !== undefined) {
            numDesc = `number ${v.minValue}-${v.maxValue}`
          } else if (v.minValue !== undefined) {
            numDesc = `number >= ${v.minValue}`
          } else if (v.maxValue !== undefined) {
            numDesc = `number <= ${v.maxValue}`
          }
          parts.push(numDesc)
        } else if (v.variableType === 'enum' && v.enumOptions?.length) {
          parts.push(`enum: ${v.enumOptions.map((o) => o.value).join('|')}`)
        } else {
          parts.push('text')
        }

        // Required vs optional
        parts.push(
          v.defaultValue !== undefined && v.defaultValue !== null ? 'optional' : 'required',
        )

        // Default value
        if (v.defaultValue !== undefined && v.defaultValue !== null) {
          parts.push(`default: ${v.defaultValue}`)
        }

        line += ` (${parts.join(', ')})`
        if (v.description) line += `: ${v.description}`
        return line
      })

      sections.push(
        `For ${labels.updates}/${labels.new}, include these as direct fields alongside standard fields:\n${varLines.join('\n')}`,
      )
    }

    if (sections.length === 0) return ''

    return `## Custom Variables to Track\n${sections.join('\n\n')}`
  }

  /**
   * Post-process: clamp number-type runtime variable values to min/max constraints.
   * Walks through all entity updates/new entities and clamps inline number values.
   */
  private clampRuntimeVarNumbers(
    result: ClassificationResult,
    varsByType: Record<string, RuntimeVariable[]>,
  ): void {
    const numberDefs = new Map<string, RuntimeVariable>()
    for (const vars of Object.values(varsByType)) {
      for (const v of vars) {
        if (v.variableType === 'number' && (v.minValue !== undefined || v.maxValue !== undefined)) {
          numberDefs.set(v.variableName, v)
        }
      }
    }

    if (numberDefs.size === 0) return

    // Clamp inline number values on an object
    const clampInlineVars = (obj: Record<string, unknown>) => {
      for (const [key, value] of Object.entries(obj)) {
        const def = numberDefs.get(key)
        if (def && typeof value === 'number') {
          obj[key] = clampNumber(value, def.minValue, def.maxValue)
        }
      }
    }

    // Walk all entity types — vars are inline on changes/entity objects
    for (const update of result.entryUpdates.characterUpdates) {
      clampInlineVars(update.changes as unknown as Record<string, unknown>)
    }
    for (const entity of result.entryUpdates.newCharacters) {
      clampInlineVars(entity as unknown as Record<string, unknown>)
    }
    for (const update of result.entryUpdates.locationUpdates) {
      clampInlineVars(update.changes as unknown as Record<string, unknown>)
    }
    for (const entity of result.entryUpdates.newLocations) {
      clampInlineVars(entity as unknown as Record<string, unknown>)
    }
    for (const update of result.entryUpdates.itemUpdates) {
      clampInlineVars(update.changes as unknown as Record<string, unknown>)
    }
    for (const entity of result.entryUpdates.newItems) {
      clampInlineVars(entity as unknown as Record<string, unknown>)
    }
    for (const update of result.entryUpdates.storyBeatUpdates) {
      clampInlineVars(update.changes as unknown as Record<string, unknown>)
    }
    for (const entity of result.entryUpdates.newStoryBeats) {
      clampInlineVars(entity as unknown as Record<string, unknown>)
    }
  }

  /**
   * Format existing characters for the prompt.
   */
  private formatExistingCharacters(characters: Character[], items: Item[]): string {
    if (characters.length === 0) return '(none)'

    return characters
      .map((c) => {
        let entry = `- ${c.name}`
        if (c.relationship) entry += ` (${c.relationship})`
        if (c.status && c.status !== 'active') entry += ` [${c.status}]`
        const appearance = formatCharacterAppearance(c, items)
        if (appearance) entry += `\n  Appearance: ${appearance}`
        return entry
      })
      .join('\n')
  }

  /**
   * Format existing story beats for the prompt.
   */
  private formatExistingBeats(beats: StoryBeat[]): string {
    const activeBeats = beats.filter((b) => b.status === 'active' || b.status === 'pending')
    if (activeBeats.length === 0) return '(none)'

    return activeBeats
      .map((b) => {
        let entry = `- "${b.title}" [${b.status}]`
        if (b.description) entry += `: ${b.description}`
        return entry
      })
      .join('\n')
  }

  private formatExistingItems(items: Item[]): string {
    if (items.length === 0) return '(none)'

    return items
      .map((item) => {
        let entry = `- ${item.name}`
        if (item.quantity > 1) entry += ` (x${item.quantity})`
        if (item.equipped) entry += ' [equipped]'

        const clothing = this.getClothingMetadata(item)
        if (clothing?.isClothing) {
          const coveredZones = Array.isArray(clothing.coveredZones) ? clothing.coveredZones : []
          const exposedZones = Array.isArray(clothing.exposedZones) ? clothing.exposedZones : []
          const effectiveCoveredZones = coveredZones.filter((zone) => !exposedZones.includes(zone))
          const parts: string[] = []
          if (
            typeof clothing.durability === 'number' &&
            typeof clothing.maxDurability === 'number'
          ) {
            parts.push(`durability ${clothing.durability}/${clothing.maxDurability}`)
          }
          if (effectiveCoveredZones.length > 0) {
            parts.push(`covered ${effectiveCoveredZones.join(', ')}`)
          }
          if (exposedZones.length > 0) {
            parts.push(`exposed ${exposedZones.join(', ')}`)
          }
          if (clothing.unusable) {
            parts.push('unusable')
          }
          if (parts.length > 0) {
            entry += ` {Clothing: ${parts.join('; ')}}`
          }
        }

        return entry
      })
      .join('\n')
  }

  private getClothingMetadata(item: Item): ClothingMetadata | null {
    const metadata = (item.metadata ?? {}) as Record<string, unknown>
    const clothing = metadata.clothing
    if (!clothing || typeof clothing !== 'object') return null
    return clothing as ClothingMetadata
  }

  /**
   * Build chat history block for context.
   */
  private buildChatHistoryBlock(entries: StoryEntry[], _currentTime?: TimeTracker | null): string {
    if (entries.length === 0) return ''

    const recentEntries = entries.slice(-this.chatHistoryTruncation)

    const formatted = recentEntries
      .map((e) => {
        const prefix = e.type === 'user_action' ? '[ACTION]' : '[NARRATIVE]'
        let timeInfo = ''
        if (e.metadata?.timeStart) {
          const t = e.metadata.timeStart
          timeInfo = ` (at Y${t.years}D${t.days} ${String(t.hours).padStart(2, '0')}:${String(t.minutes).padStart(2, '0')})`
        }
        // Always strip pic tags for classification to avoid confusion
        const cleanContent = stripPicTags(e.content)
        return `${prefix}${timeInfo} ${cleanContent.slice(0, 500)}${cleanContent.length > 500 ? '...' : ''}`
      })
      .join('\n\n')

    return `## Recent Chat History\n${formatted}\n`
  }
}

import { createLogger } from '$lib/log'
import { database } from '$lib/services/database'
import { templateEngine } from '$lib/services/templates/engine'
import { BaseAIService } from '../BaseAIService'
import type {
  DirectorProposalArtifact,
  Entry,
  Story,
  StoryBeat,
  Character,
  Location,
  Item,
} from '$lib/types'
import { directorProposalSchema, type DirectorProposal } from '../sdk/schemas/director'

const log = createLogger('DirectorOutliningAssistant')

export interface DirectorOutliningAssistantContext {
  story: Story
  brief: string
  recentEntries: string[]
  persist?: boolean
  worldState: {
    characters: Character[]
    locations: Location[]
    items: Item[]
    storyBeats: StoryBeat[]
    lorebookEntries: Entry[]
  }
}

export class DirectorOutliningAssistantService extends BaseAIService {
  constructor(serviceId: string = 'directorOutliningAssistant') {
    super(serviceId)
  }

  async generateProposal(
    context: DirectorOutliningAssistantContext,
  ): Promise<DirectorProposalArtifact> {
    const storyMode = context.story.mode
    const recentEntryBlock = context.recentEntries.length
      ? context.recentEntries.map((entry) => `- ${entry}`).join('\n')
      : '(none)'

    const worldBlock = [
      `Characters: ${context.worldState.characters.map((character) => character.name).join(', ') || '(none)'}`,
      `Locations: ${context.worldState.locations.map((location) => location.name).join(', ') || '(none)'}`,
      `Items: ${context.worldState.items.map((item) => item.name).join(', ') || '(none)'}`,
      `Story beats: ${context.worldState.storyBeats.map((beat) => beat.title).join(', ') || '(none)'}`,
      `Lorebook entries: ${context.worldState.lorebookEntries.map((entry) => entry.name).join(', ') || '(none)'}`,
    ].join('\n')

    const system = await this.buildSystemPrompt(context.story)

    const prompt = [
      `Story mode: ${storyMode}`,
      `Story title: ${context.story.title}`,
      '',
      '## User Brief',
      context.brief.trim() || '(no brief provided)',
      '',
      '## Recent Story Context',
      recentEntryBlock,
      '',
      '## World Snapshot',
      worldBlock,
      '',
      '## Instructions',
      '- Propose a useful outline with a clear title and concise summary.',
      '- Include any new secret atoms as draft-only structures.',
      '- Include safe reveal pathways only if they are plausibly supported by the context.',
      '- Prefer foreshadowing over direct disclosure when possible.',
    ].join('\n')

    const result = await this.generate(
      directorProposalSchema,
      system,
      prompt,
      'director-outlining-assistant',
    )

    const now = Date.now()
    const artifact: DirectorProposalArtifact = {
      id: crypto.randomUUID(),
      storyId: context.story.id,
      authorType: 'assistant',
      proposalType: 'director_outline',
      title: result.title,
      draftPayload: result as DirectorProposal,
      diffPayload: null,
      approvalState: 'pending',
      approvedBy: null,
      approvedAt: null,
      createdAt: now,
      updatedAt: now,
    }

    if (context.persist !== false) {
      await database.addDirectorProposalArtifact(artifact)
      log('Generated director proposal', { storyId: context.story.id, artifactId: artifact.id })
    } else {
      log('Generated director proposal preview', {
        storyId: context.story.id,
        artifactId: artifact.id,
      })
    }
    return artifact
  }

  async listProposals(storyId: string): Promise<DirectorProposalArtifact[]> {
    return database.getDirectorProposalArtifacts(storyId)
  }

  async approveProposal(artifact: DirectorProposalArtifact): Promise<void> {
    await database.updateDirectorProposalArtifact(artifact.id, {
      approvalState: 'approved',
      approvedBy: 'user',
      approvedAt: Date.now(),
    })
  }

  async rejectProposal(artifact: DirectorProposalArtifact): Promise<void> {
    await database.updateDirectorProposalArtifact(artifact.id, {
      approvalState: 'rejected',
      approvedBy: 'user',
      approvedAt: Date.now(),
    })
  }

  private async buildSystemPrompt(story: Story): Promise<string> {
    const packId = (await database.getStoryPackId(story.id)) ?? 'default-pack'
    const template =
      (await database.getPackTemplate(packId, 'director-outlining-assistant')) ??
      (packId !== 'default-pack'
        ? await database.getPackTemplate('default-pack', 'director-outlining-assistant')
        : null)

    if (!template?.content?.trim()) {
      return [
        'You are the Director Outlining Assistant for a fiction workflow.',
        'Draft secret atoms, reveal pathways, and outline beats without committing any change.',
        'Never overwrite or directly emit player-facing narrative.',
        'Keep hidden facts hidden and provide safe foreshadowing hints when appropriate.',
        'Return JSON only.',
      ].join('\n')
    }

    const templateVars: Record<string, string> = {
      storyTitle: String(story.title ?? ''),
      storyMode: String(story.mode ?? 'adventure'),
    }

    return templateEngine.render(template.content, templateVars) ?? ''
  }
}

import { z } from 'zod'
import { BaseAIService } from '../BaseAIService'
import { database } from '$lib/services/database'
import { templateEngine } from '$lib/services/templates/engine'
import type {
  Character,
  Entry,
  EpistemicCharacterKnowledgeEdge,
  EpistemicSecretAtom,
  StoryMode,
} from '$lib/types'

const disclosureGateResultSchema = z.object({
  action: z.enum(['allow', 'rewrite', 'suppress']),
  revisedContent: z.string(),
  notes: z.string().optional(),
  blockedSecrets: z
    .array(
      z.object({
        secretId: z.string(),
        action: z.enum(['rewrite', 'suppress']),
        reason: z.string(),
      }),
    )
    .default([]),
})

type DisclosureGateResult = z.infer<typeof disclosureGateResultSchema>
type DisclosureGateReturn = {
  action: 'allow' | 'rewrite' | 'suppress'
  revisedContent: string
  notes?: string
  blockedSecrets: DisclosureGateResult['blockedSecrets']
}

export interface DisclosureGateInput {
  storyMode: StoryMode
  narrative: string
  characters: Character[]
  lorebookEntries: Entry[]
  secretAtoms: EpistemicSecretAtom[]
  knowledgeEdges: EpistemicCharacterKnowledgeEdge[]
}

function normalizeText(value: string): string {
  return value.toLowerCase().replace(/\s+/g, ' ').trim()
}

function normalizeConfidence(value: number): number {
  if (!Number.isFinite(value)) return 0
  if (Math.abs(value) > 1) return Math.max(0, Math.min(1, value / 100))
  return Math.max(0, Math.min(1, value))
}

function normalizeIntent(value: number): number {
  if (!Number.isFinite(value)) return 0
  if (Math.abs(value) > 1) return Math.max(-1, Math.min(1, value / 10))
  return Math.max(-1, Math.min(1, value))
}

function getPressureWeight(
  tagType: EpistemicCharacterKnowledgeEdge['pressureTags'][number]['type'],
): number {
  switch (tagType) {
    case 'coercion':
      return 1.4
    case 'panic':
    case 'fear':
      return 1.2
    case 'loyalty':
    case 'duty':
      return 1.1
    case 'ideology':
      return 1
    case 'greed':
      return 0.9
    default:
      return 0.8
  }
}

function scoreEdgeRisk(edge: EpistemicCharacterKnowledgeEdge): number {
  const confidenceRisk = 1 - normalizeConfidence(edge.confidence)
  const intentRisk = 1 - (normalizeIntent(edge.disclosureIntent) + 1) / 2
  const pressureRisk = edge.pressureTags.reduce((sum, tag) => {
    const strength = Math.min(10, Math.abs(tag.strength)) / 10
    return sum + strength * getPressureWeight(tag.type)
  }, 0)

  return Math.max(0, Math.min(1, confidenceRisk * 0.45 + intentRisk * 0.25 + pressureRisk * 0.3))
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function replaceInsensitive(source: string, needle: string, replacement: string): string {
  const trimmedNeedle = needle.trim()
  if (!trimmedNeedle) return source
  const pattern = new RegExp(escapeRegExp(trimmedNeedle), 'gi')
  return source.replace(pattern, replacement)
}

function findDirectLeakMatch(narrative: string, secretText: string): boolean {
  const normalizedNarrative = normalizeText(narrative)
  const normalizedSecret = normalizeText(secretText)
  if (!normalizedNarrative || !normalizedSecret) return false
  return normalizedNarrative.includes(normalizedSecret)
}

export class DisclosureGateService extends BaseAIService {
  constructor(serviceId: string = 'disclosureGate') {
    super(serviceId)
  }

  async gateNarrative(input: DisclosureGateInput): Promise<DisclosureGateReturn> {
    if (!input.narrative.trim() || input.secretAtoms.length === 0) {
      return {
        action: 'allow',
        revisedContent: input.narrative,
        blockedSecrets: [],
      }
    }

    const characterNames = new Map(
      input.characters.map((character) => [character.id, character.name]),
    )

    const secretAnalyses = input.secretAtoms.map((atom) => {
      const edges = input.knowledgeEdges.filter((edge) => edge.atomId === atom.id && edge.knows)
      const knowers = edges.map((edge) => {
        const name = edge.characterId ? characterNames.get(edge.characterId) : null
        const resolved = name || edge.characterRefId
        return `${resolved} (intent=${edge.disclosureIntent}, policy=${edge.disclosurePolicy})`
      })
      const highSecrecy = atom.secrecyScope === 'director_only'
      const zeroKnowledge = edges.length === 0
      const directLeak = findDirectLeakMatch(input.narrative, atom.payloadHidden)
      const maxRisk = edges.length > 0 ? Math.max(...edges.map(scoreEdgeRisk)) : 1

      return {
        atom,
        knowers,
        highSecrecy,
        zeroKnowledge,
        directLeak,
        maxRisk,
      }
    })

    const hardSuppressReasons = secretAnalyses.filter(
      (analysis) => analysis.directLeak && (analysis.highSecrecy || analysis.zeroKnowledge),
    )

    if (hardSuppressReasons.length > 0) {
      return {
        action: 'suppress',
        revisedContent: '',
        notes:
          'Hard suppression triggered by a direct leak of a high-secrecy or zero-knowledge secret.',
        blockedSecrets: hardSuppressReasons.map((analysis) => ({
          secretId: analysis.atom.id,
          action: 'suppress' as const,
          reason: analysis.highSecrecy
            ? 'direct leak of director-only secret'
            : 'direct leak without a plausible knowledge path',
        })),
      }
    }

    let deterministicRewrite = input.narrative
    const blockedSecrets: DisclosureGateResult['blockedSecrets'] = []

    for (const analysis of secretAnalyses) {
      if (!analysis.directLeak) continue

      const replacement = analysis.atom.payloadForeshadow?.trim() || '[the detail is withheld]'
      deterministicRewrite = replaceInsensitive(
        deterministicRewrite,
        analysis.atom.payloadHidden,
        replacement,
      )
      blockedSecrets.push({
        secretId: analysis.atom.id,
        action: 'rewrite',
        reason: analysis.highSecrecy
          ? 'direct leak sanitized with foreshadowing'
          : 'direct leak sanitized before the model pass',
      })
    }

    const hiddenEntryLeakReasons = input.lorebookEntries.filter((entry) => {
      const hiddenInfo = entry.hiddenInfo?.trim()
      if (!hiddenInfo) return false
      return findDirectLeakMatch(input.narrative, hiddenInfo)
    })

    for (const entry of hiddenEntryLeakReasons) {
      deterministicRewrite = replaceInsensitive(
        deterministicRewrite,
        entry.hiddenInfo || '',
        '[the detail is withheld]',
      )
      blockedSecrets.push({
        secretId: entry.id,
        action: 'rewrite',
        reason: 'legacy hidden entry fact sanitized before the model pass',
      })
    }

    if (blockedSecrets.length > 0) {
      return {
        action: 'rewrite',
        revisedContent: deterministicRewrite,
        notes: 'Direct leak sanitized without calling the model.',
        blockedSecrets,
      }
    }

    const protectedSecretsBlock = secretAnalyses
      .map((analysis) => {
        const { atom, knowers, highSecrecy, zeroKnowledge, directLeak, maxRisk } = analysis

        return [
          `ID: ${atom.id}`,
          `Label: ${atom.label}`,
          `Secrecy: ${atom.secrecyScope}`,
          `Reveal State: ${atom.revealState}`,
          `Visibility: ${atom.visibilityScope}`,
          `High Secrecy: ${highSecrecy ? 'yes' : 'no'}`,
          `Zero Knowledge Path: ${zeroKnowledge ? 'yes' : 'no'}`,
          `Direct Leak Detected: ${directLeak ? 'yes' : 'no'}`,
          `Risk Score: ${maxRisk.toFixed(2)}`,
          `Known Holders: ${knowers.length > 0 ? knowers.join('; ') : '(none)'}`,
          `Foreshadow-safe hint: ${atom.payloadForeshadow || '(none)'}`,
          `Protected fact: ${atom.payloadHidden}`,
        ].join('\n')
      })
      .join('\n\n---\n\n')

    const hiddenEntryBlock = input.lorebookEntries
      .filter((entry) => !!entry.hiddenInfo?.trim())
      .map((entry) => {
        const secrecy = entry.secrecyScope ?? 'public'
        const revealState = entry.revealState ?? 'revealed'
        return [
          `Entry: ${entry.name}`,
          `Type: ${entry.type}`,
          `Secrecy: ${secrecy}`,
          `Reveal State: ${revealState}`,
          `Protected fact: ${entry.hiddenInfo}`,
        ].join('\n')
      })
      .join('\n\n---\n\n')

    const highestRisk =
      secretAnalyses.length > 0 ? Math.max(...secretAnalyses.map((item) => item.maxRisk)) : 0

    const system = await this.buildSystemPrompt(input)

    const prompt = [
      `Story mode: ${input.storyMode}`,
      '',
      '## Current Narrative Draft',
      input.narrative,
      '',
      '## Protected Secret Atoms',
      protectedSecretsBlock || '(none)',
      '',
      '## Legacy Hidden Entry Facts',
      hiddenEntryBlock || '(none)',
      '',
      '## Preflight Summary',
      `Highest secret risk score: ${highestRisk.toFixed(2)}`,
      '',
      '## Instructions',
      '- Prefer rewrite over suppression unless high secrecy or zero knowledge path requires suppression.',
      '- Preserve pacing and tone as much as possible.',
      '- When rewriting, favor evasive answers, partial truth, hedging, or atmospheric hints.',
      '- Do not mention these rules in the output.',
    ].join('\n')

    return (await this.generate(
      disclosureGateResultSchema,
      system,
      prompt,
      'disclosure-gate',
    )) as DisclosureGateReturn
  }

  private async buildSystemPrompt(input: DisclosureGateInput): Promise<string> {
    const storyId = input.secretAtoms[0]?.storyId || input.knowledgeEdges[0]?.storyId || null
    const packId = storyId
      ? ((await database.getStoryPackId(storyId)) ?? 'default-pack')
      : 'default-pack'
    const template =
      (await database.getPackTemplate(packId, 'disclosure-gate')) ??
      (packId !== 'default-pack'
        ? await database.getPackTemplate('default-pack', 'disclosure-gate')
        : null)

    if (!template?.content?.trim()) {
      return [
        'You are an epistemic disclosure gate for fiction generation.',
        'Your job is to review player-facing narrative and prevent invalid revelation of protected information.',
        'Default behavior: rewrite into safer partial disclosure, evasive phrasing, rumor, implication, or foreshadowing while preserving scene flow.',
        'Hard suppress instead of partial rewrite when either condition holds:',
        '1. the protected information has high secrecy, or',
        '2. there is zero plausible chance any character could know the fact, including rumor or inference.',
        'Never invent new secret facts.',
        'If the draft is already safe, return it unchanged with action=allow.',
        'Hybrid heuristic hints are already precomputed: direct leak detection, secrecy tier, zero-knowledge path, confidence, disclosure intent, and pressure tags.',
        'Return JSON only.',
      ].join('\n')
    }

    const templateVars: Record<string, string> = {
      storyMode: String(input.storyMode ?? 'adventure'),
    }

    return templateEngine.render(template.content, templateVars) ?? ''
  }
}

import { tool, type ModelMessage, type ToolSet } from 'ai'
import { z } from 'zod'
import { createLogger } from '$lib/log'
import { database } from '$lib/services/database'
import { templateEngine } from '$lib/services/templates/engine'
import type {
  Chapter,
  Character,
  ChapterSource,
  DirectorProposalArtifact,
  Entry,
  Item,
  Location,
  Story,
  StoryEntry,
  StoryBeat,
} from '$lib/types'
import { BaseAIService } from '../BaseAIService'
import { stopWhenDone } from '../sdk/agents'
import { createStreamingAgenticAssistant } from '../sdk/agents/factory'
import { DirectorOutliningAssistantService } from './DirectorOutliningAssistantService'

const log = createLogger('InteractiveDirectorAssistant')

export interface DirectorInteractiveContext {
  story: Story
  recentEntries: string[]
  chapters: Chapter[]
  chapterSources: ChapterSource[]
  storyEntries: StoryEntry[]
  chapterEntriesByNumber: Record<string, StoryEntry[]>
  worldState: {
    characters: Character[]
    locations: Location[]
    items: Item[]
    storyBeats: StoryBeat[]
    lorebookEntries: Entry[]
  }
}

export interface DirectorToolCallDisplay {
  id: string
  name: string
  args: Record<string, unknown>
  result: string
  artifact?: DirectorProposalArtifact
}

export interface DirectorChatMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: number
  toolCalls?: DirectorToolCallDisplay[]
  reasoning?: string
}

export type DirectorStreamEvent =
  | { type: 'tool_start'; toolCallId: string; toolName: string; args: Record<string, unknown> }
  | { type: 'tool_end'; toolCall: DirectorToolCallDisplay }
  | { type: 'thinking' }
  | { type: 'message'; message: DirectorChatMessage }
  | { type: 'done' }
  | { type: 'error'; error: string }

export class InteractiveDirectorAssistantService extends BaseAIService {
  private proposalService: DirectorOutliningAssistantService
  private initialized = false
  private conversationHistory: ModelMessage[] = []
  private systemPrompt = ''

  constructor(serviceId: string = 'directorOutliningAssistant') {
    super(serviceId)
    this.proposalService = new DirectorOutliningAssistantService(serviceId)
  }

  async initialize(context: DirectorInteractiveContext): Promise<void> {
    this.conversationHistory = []
    this.systemPrompt = await this.buildSystemPrompt(context.story)
    this.initialized = true
  }

  reset(): void {
    this.initialized = false
    this.conversationHistory = []
    this.systemPrompt = ''
  }

  private buildDirectorTools(context: DirectorInteractiveContext) {
    const createdArtifacts = new Map<string, DirectorProposalArtifact>()
    const lorebookEntries = JSON.parse(
      JSON.stringify(context.worldState.lorebookEntries),
    ) as Entry[]
    const chapters = JSON.parse(JSON.stringify(context.chapters)) as Chapter[]
    const chapterSources = JSON.parse(JSON.stringify(context.chapterSources)) as ChapterSource[]
    const storyEntries = JSON.parse(JSON.stringify(context.storyEntries)) as StoryEntry[]
    const chapterEntriesByNumber = JSON.parse(
      JSON.stringify(context.chapterEntriesByNumber),
    ) as Record<string, StoryEntry[]>

    const tools = {
      search_lorebook_entries: tool({
        description:
          'Search lorebook entries by keyword, name, alias, or entry type. Use this when planning needs lore context from specific domains.',
        inputSchema: z.object({
          query: z
            .string()
            .optional()
            .describe('Optional search text across name, description, aliases, and keywords.'),
          type: z
            .string()
            .optional()
            .describe(
              'Optional entry type filter such as character, location, item, concept, event.',
            ),
          limit: z.number().optional().default(10).describe('Maximum entries to return.'),
        }),
        execute: async ({
          query,
          type,
          limit,
        }: {
          query?: string
          type?: string
          limit?: number
        }) => {
          let filtered = lorebookEntries

          if (type?.trim()) {
            const expectedType = type.trim().toLowerCase()
            filtered = filtered.filter((entry) => entry.type.toLowerCase() === expectedType)
          }

          if (query?.trim()) {
            const term = query.trim().toLowerCase()
            filtered = filtered.filter(
              (entry) =>
                entry.name.toLowerCase().includes(term) ||
                entry.description.toLowerCase().includes(term) ||
                entry.aliases.some((alias) => alias.toLowerCase().includes(term)) ||
                entry.injection.keywords.some((keyword) => keyword.toLowerCase().includes(term)),
            )
          }

          const selected = filtered.slice(0, limit ?? 10)
          return {
            total: filtered.length,
            entries: selected.map((entry) => ({
              id: entry.id,
              name: entry.name,
              type: entry.type,
              description:
                entry.description.length > 240
                  ? `${entry.description.slice(0, 240)}...`
                  : entry.description,
              aliases: entry.aliases,
              keywords: entry.injection.keywords,
            })),
          }
        },
      }),

      read_lorebook_entry: tool({
        description:
          'Read a full lorebook entry by id or exact name when detailed lore is needed for planning.',
        inputSchema: z.object({
          id: z.string().optional().describe('Entry id to read.'),
          name: z.string().optional().describe('Exact entry name to read when id is unknown.'),
        }),
        execute: async ({ id, name }: { id?: string; name?: string }) => {
          const trimmedId = id?.trim()
          const trimmedName = name?.trim().toLowerCase()
          const entry = lorebookEntries.find(
            (candidate) =>
              (trimmedId ? candidate.id === trimmedId : false) ||
              (trimmedName ? candidate.name.toLowerCase() === trimmedName : false),
          )

          if (!entry) {
            return {
              found: false,
              message: 'No matching lorebook entry found.',
            }
          }

          return {
            found: true,
            entry: {
              id: entry.id,
              name: entry.name,
              type: entry.type,
              description: entry.description,
              hiddenInfo: entry.hiddenInfo,
              aliases: entry.aliases,
              keywords: entry.injection.keywords,
              mentionCount: entry.mentionCount,
              updatedAt: entry.updatedAt,
            },
          }
        },
      }),

      list_chapters: tool({
        description:
          'List chapter summaries for timeline planning. Use this for future chapter planning where recent scene text may not be relevant.',
        inputSchema: z.object({
          limit: z.number().optional().default(30).describe('Maximum chapters to return.'),
        }),
        execute: async ({ limit }: { limit?: number }) => {
          const selected = chapters.slice(0, limit ?? 30)
          return {
            total: chapters.length,
            chapters: selected.map((chapter) => ({
              number: chapter.number,
              title: chapter.title,
              summary:
                chapter.summary.length > 500
                  ? `${chapter.summary.slice(0, 500)}...`
                  : chapter.summary,
              keywords: chapter.keywords,
              characters: chapter.characters,
              locations: chapter.locations,
              plotThreads: chapter.plotThreads,
            })),
          }
        },
      }),

      read_chapter: tool({
        description:
          'Read one chapter summary and optionally include chapter entry excerpts when deeper event detail is needed.',
        inputSchema: z.object({
          chapterNumber: z.number().describe('Chapter number to inspect.'),
          includeEntries: z
            .boolean()
            .optional()
            .default(false)
            .describe('Include chapter entry text excerpts.'),
          entryLimit: z.number().optional().default(24).describe('Max chapter entries to include.'),
        }),
        execute: async ({
          chapterNumber,
          includeEntries,
          entryLimit,
        }: {
          chapterNumber: number
          includeEntries?: boolean
          entryLimit?: number
        }) => {
          const chapter = chapters.find((candidate) => candidate.number === chapterNumber)
          if (!chapter) {
            return {
              found: false,
              message: `Chapter ${chapterNumber} not found.`,
            }
          }

          const key = String(chapterNumber)
          const chapterEntries = chapterEntriesByNumber[key] ?? []

          return {
            found: true,
            chapter: {
              number: chapter.number,
              title: chapter.title,
              summary: chapter.summary,
              keywords: chapter.keywords,
              characters: chapter.characters,
              locations: chapter.locations,
              plotThreads: chapter.plotThreads,
              emotionalTone: chapter.emotionalTone,
            },
            entries: includeEntries
              ? chapterEntries.slice(0, entryLimit ?? 24).map((entry) => ({
                  type: entry.type,
                  content: entry.content,
                  createdAt: entry.createdAt,
                }))
              : undefined,
            entryCount: chapterEntries.length,
          }
        },
      }),

      search_story_text: tool({
        description:
          'Search current story text entries by keyword. Use this when the conversation needs exact recent or historical phrasing/events.',
        inputSchema: z.object({
          query: z.string().describe('Search term for story text content.'),
          limit: z.number().optional().default(12).describe('Maximum matches to return.'),
        }),
        execute: async ({ query, limit }: { query: string; limit?: number }) => {
          const term = query.trim().toLowerCase()
          const matches = term
            ? storyEntries.filter((entry) => entry.content.toLowerCase().includes(term))
            : []

          return {
            total: matches.length,
            matches: matches.slice(0, limit ?? 12).map((entry) => ({
              id: entry.id,
              type: entry.type,
              content: entry.content,
              createdAt: entry.createdAt,
            })),
          }
        },
      }),

      read_recent_story_text: tool({
        description:
          'Read the most recent story entries. Use only when immediate scene context is needed for planning.',
        inputSchema: z.object({
          count: z.number().optional().default(12).describe('How many recent entries to return.'),
          includeSystem: z
            .boolean()
            .optional()
            .default(false)
            .describe('Whether to include system entries.'),
        }),
        execute: async ({ count, includeSystem }: { count?: number; includeSystem?: boolean }) => {
          const filtered = includeSystem
            ? storyEntries
            : storyEntries.filter((entry) => entry.type !== 'system')
          const selected = filtered.slice(-Math.max(1, count ?? 12))

          return {
            totalAvailable: filtered.length,
            entries: selected.map((entry) => ({
              id: entry.id,
              type: entry.type,
              content: entry.content,
              createdAt: entry.createdAt,
            })),
          }
        },
      }),

      search_chapter_sources: tool({
        description:
          'Search imported chapter source text by filename, title, or full raw content. Use this when the summary is insufficient and you need exact past details.',
        inputSchema: z.object({
          query: z.string().describe('Search term for raw chapter source text.'),
          limit: z.number().optional().default(6).describe('Maximum results to return.'),
        }),
        execute: async ({ query, limit }: { query: string; limit?: number }) => {
          const term = query.trim().toLowerCase()
          const matches = chapterSources.filter((source) => {
            const haystack = [source.title, source.sourceFilename ?? '', source.rawText]
              .join('\n')
              .toLowerCase()
            return haystack.includes(term)
          })

          return {
            total: matches.length,
            sources: matches.slice(0, limit ?? 6).map((source) => {
              const content = source.rawText.trim()
              const hitIndex = content.toLowerCase().indexOf(term)
              const excerptStart = hitIndex >= 0 ? Math.max(0, hitIndex - 180) : 0
              const excerptEnd =
                hitIndex >= 0
                  ? Math.min(content.length, hitIndex + 420)
                  : Math.min(content.length, 560)
              const excerpt = content.slice(excerptStart, excerptEnd)
              return {
                id: source.id,
                title: source.title,
                sourceFilename: source.sourceFilename,
                chapterNumber: source.chapterNumber,
                summary: source.summary,
                excerpt:
                  excerpt.length < content.length
                    ? `${excerpt}${excerptEnd < content.length ? '...' : ''}`
                    : excerpt,
              }
            }),
          }
        },
      }),

      read_chapter_source: tool({
        description:
          'Read a full imported chapter source by id or exact title when detailed historical context is needed.',
        inputSchema: z.object({
          id: z.string().optional().describe('Source id to read.'),
          title: z.string().optional().describe('Exact source title to read when id is unknown.'),
        }),
        execute: async ({ id, title }: { id?: string; title?: string }) => {
          const trimmedId = id?.trim()
          const trimmedTitle = title?.trim().toLowerCase()
          const source = chapterSources.find(
            (candidate) =>
              (trimmedId ? candidate.id === trimmedId : false) ||
              (trimmedTitle ? candidate.title.toLowerCase() === trimmedTitle : false),
          )

          if (!source) {
            return { found: false, message: 'No matching chapter source found.' }
          }

          return {
            found: true,
            source: {
              id: source.id,
              title: source.title,
              sourceFilename: source.sourceFilename,
              chapterNumber: source.chapterNumber,
              summary: source.summary,
              rawText: source.rawText,
            },
          }
        },
      }),

      create_director_proposal_draft: tool({
        description:
          'Create a pending director proposal artifact when the user asks to capture the current brainstorming into a draft plan.',
        inputSchema: z.object({
          objective: z
            .string()
            .describe('A concise objective for the draft proposal based on current conversation.'),
          titleHint: z
            .string()
            .optional()
            .describe('Optional short title hint to emphasize in the generated draft.'),
        }),
        execute: async ({ objective, titleHint }: { objective: string; titleHint?: string }) => {
          const brief = titleHint?.trim()
            ? `${objective.trim()}\n\nPreferred draft title: ${titleHint.trim()}`
            : objective.trim()

          const artifact = await this.proposalService.generateProposal({
            story: context.story,
            brief,
            recentEntries: context.recentEntries,
            worldState: context.worldState,
            persist: true,
          })

          createdArtifacts.set(artifact.id, artifact)

          return {
            success: true,
            artifactId: artifact.id,
            title: artifact.title,
            summary:
              typeof artifact.draftPayload?.summary === 'string'
                ? artifact.draftPayload.summary
                : null,
            message: `Created pending draft proposal \"${artifact.title ?? 'Untitled proposal'}\".`,
          }
        },
      }),
    }

    return {
      tools,
      createdArtifacts,
    }
  }

  async *sendMessageStreaming(
    context: DirectorInteractiveContext,
    userMessage: string,
    signal?: AbortSignal,
  ): AsyncGenerator<DirectorStreamEvent> {
    if (!this.initialized) {
      await this.initialize(context)
    }

    const { tools, createdArtifacts } = this.buildDirectorTools(context)

    this.conversationHistory.push({
      role: 'user',
      content: userMessage,
    })

    try {
      const assistant = createStreamingAgenticAssistant(
        {
          presetId: this.presetId,
          instructions: this.systemPrompt,
          tools: tools as ToolSet,
          stopWhen: stopWhenDone(20),
          signal,
        },
        'interactive-director-assistant',
      )

      const streamResult = await assistant.stream({ messages: this.conversationHistory })

      const currentToolCalls: Array<{
        id: string
        name: string
        args: Record<string, unknown>
        claimed: boolean
      }> = []

      let stepContent = ''
      let stepReasoning: string | undefined
      let stepToolCalls: DirectorToolCallDisplay[] = []

      for await (const event of streamResult.fullStream) {
        switch (event.type) {
          case 'start-step':
            stepContent = ''
            stepReasoning = undefined
            stepToolCalls = []
            currentToolCalls.length = 0
            break

          case 'reasoning-start':
          case 'reasoning-delta':
            if (event.type === 'reasoning-delta') {
              stepReasoning = (stepReasoning || '') + event.text
            }
            yield { type: 'thinking' }
            break

          case 'text-delta':
            stepContent += event.text
            break

          case 'tool-call':
            currentToolCalls.push({
              id: event.toolCallId,
              name: event.toolName,
              args: event.input as Record<string, unknown>,
              claimed: false,
            })
            yield {
              type: 'tool_start',
              toolCallId: event.toolCallId,
              toolName: event.toolName,
              args: event.input as Record<string, unknown>,
            }
            break

          case 'tool-result': {
            const info = currentToolCalls.find((tc) => tc.id === event.toolCallId && !tc.claimed)
            if (info) info.claimed = true

            if (!info) break

            const toolResult = 'result' in event ? event.result : event.output
            const resultRecord =
              toolResult && typeof toolResult === 'object'
                ? (toolResult as Record<string, unknown>)
                : undefined

            const artifactId =
              resultRecord && typeof resultRecord.artifactId === 'string'
                ? resultRecord.artifactId
                : null

            const toolCall: DirectorToolCallDisplay = {
              id: event.toolCallId,
              name: info.name,
              args: info.args,
              result: typeof toolResult === 'string' ? toolResult : JSON.stringify(toolResult),
              artifact: artifactId ? createdArtifacts.get(artifactId) : undefined,
            }

            stepToolCalls.push(toolCall)
            yield { type: 'tool_end', toolCall }
            break
          }

          case 'finish-step':
            if (stepContent || stepToolCalls.length > 0) {
              yield {
                type: 'message',
                message: {
                  id: `dir-step-${Date.now()}`,
                  role: 'assistant',
                  content: stepContent,
                  timestamp: Date.now(),
                  toolCalls: stepToolCalls.length > 0 ? [...stepToolCalls] : undefined,
                  reasoning: stepReasoning,
                },
              }
            }
            break

          case 'error':
            yield { type: 'error', error: String(event.error) }
            return
        }
      }

      const responseMessages = await streamResult.response
      this.conversationHistory.push(...responseMessages.messages)
      yield { type: 'done' }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      log('Interactive director stream failed', { message })
      yield { type: 'error', error: message }
    }
  }

  private async buildSystemPrompt(story: Story): Promise<string> {
    const packId = (await database.getStoryPackId(story.id)) ?? 'default-pack'
    const template =
      (await database.getPackTemplate(packId, 'interactive-director-assistant')) ??
      (packId !== 'default-pack'
        ? await database.getPackTemplate('default-pack', 'interactive-director-assistant')
        : null)

    const fallback = [
      'You are a collaborative Director Assistant for interactive fiction planning.',
      'Hold a natural brainstorming conversation with the user and refine ideas step by step.',
      'Ingest context selectively via tools: lorebook, chapter summaries, chapter text, and current story text only when needed for the current user request.',
      'Do NOT create proposal artifacts on every turn.',
      'Only call the create_director_proposal_draft tool when the user clearly asks to capture or draft the plan.',
      'When not drafting, reply conversationally and help sharpen premise, pacing, reveals, and beat structure.',
      'Keep hidden facts protected and prefer foreshadowing for sensitive reveals.',
    ].join('\n')

    if (!template?.content?.trim()) {
      return fallback
    }

    return (
      templateEngine.render(template.content, {
        storyTitle: story.title,
        storyMode: story.mode,
      }) || fallback
    )
  }
}

import { tool, type ModelMessage, type ToolSet } from 'ai'
import { z } from 'zod'
import { createLogger } from '$lib/log'
import { database } from '$lib/services/database'
import { templateEngine } from '$lib/services/templates/engine'
import type {
  Chapter,
  Character,
  EditorConversation,
  Entry,
  Item,
  Location,
  Story,
  StoryEntry,
  StoryBeat,
} from '$lib/types'
import { BaseAIService } from '../BaseAIService'
import { stopWhenDone } from '../sdk/agents'
import { createStreamingAgenticAssistant } from '../sdk/agents/factory'

const log = createLogger('InteractiveEditorAssistant')

export interface EditorInteractiveContext {
  story: Story
  recentEntries: string[]
  chapters: Chapter[]
  storyEntries: StoryEntry[]
  chapterEntriesByNumber: Record<string, StoryEntry[]>
  worldState: {
    characters: Character[]
    locations: Location[]
    items: Item[]
    storyBeats: StoryBeat[]
    lorebookEntries: Entry[]
  }
}

export interface EditorProposedEdit {
  id: string
  entryId: string
  entryType: StoryEntry['type']
  revisedEntryType?: StoryEntry['type']
  originalContent: string
  revisedContent: string
  reason: string
  reprocessChapter: boolean
  rerunLorebookPass: boolean
}

export interface EditorToolCallDisplay {
  id: string
  name: string
  args: Record<string, unknown>
  result: string
  edit?: EditorProposedEdit
}

export interface EditorChatMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: number
  toolCalls?: EditorToolCallDisplay[]
  reasoning?: string
}

export type EditorStreamEvent =
  | { type: 'tool_start'; toolCallId: string; toolName: string; args: Record<string, unknown> }
  | { type: 'tool_end'; toolCall: EditorToolCallDisplay }
  | { type: 'thinking' }
  | { type: 'message'; message: EditorChatMessage }
  | { type: 'done' }
  | { type: 'error'; error: string }

export class InteractiveEditorAssistantService extends BaseAIService {
  private initialized = false
  private conversationHistory: ModelMessage[] = []
  private systemPrompt = ''
  private conversationId: string | null = null

  constructor(serviceId: string = 'editorAssistant') {
    super(serviceId)
  }

  async initialize(context: EditorInteractiveContext): Promise<void> {
    this.conversationHistory = []
    this.systemPrompt = await this.buildSystemPrompt(context.story)
    this.initialized = true
  }

  reset(): void {
    this.initialized = false
    this.conversationHistory = []
    this.systemPrompt = ''
    this.conversationId = null
  }

  async listConversations(storyId: string): Promise<EditorConversation[]> {
    return database.listEditorConversations(storyId)
  }

  async renameConversation(conversationId: string, title: string): Promise<void> {
    await database.saveEditorConversation(conversationId, { title })
  }

  async deleteConversation(conversationId: string): Promise<void> {
    await database.deleteEditorConversation(conversationId)
    if (this.conversationId === conversationId) {
      this.reset()
    }
  }

  async saveConversation(
    storyId: string,
    chatMessages: EditorChatMessage[],
    pendingEdits: EditorProposedEdit[],
    uiState?: { selectedTargetEntryId?: string | null },
  ): Promise<string> {
    const messagesJson = JSON.stringify(this.conversationHistory)
    const chatMessagesJson = JSON.stringify(chatMessages)
    const pendingEditsJson = JSON.stringify(pendingEdits)
    const uiStateJson = JSON.stringify(uiState ?? {})

    if (this.conversationId) {
      await database.saveEditorConversation(this.conversationId, {
        messages: messagesJson,
        chatMessages: chatMessagesJson,
        pendingEdits: pendingEditsJson,
        uiState: uiStateJson,
      })
      return this.conversationId
    }

    const id = `ec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
    const title = this.generateTitle(chatMessages)
    const now = new Date().toISOString()

    await database.createEditorConversation({
      id,
      storyId,
      title,
      createdAt: now,
      updatedAt: now,
      messages: messagesJson,
      chatMessages: chatMessagesJson,
      pendingEdits: pendingEditsJson,
      uiState: uiStateJson,
    })

    this.conversationId = id
    return id
  }

  async loadConversation(conversationId: string): Promise<{
    chatMessages: EditorChatMessage[]
    pendingEdits: EditorProposedEdit[]
    selectedTargetEntryId: string | null
  } | null> {
    const conversation = await database.loadEditorConversation(conversationId)
    if (!conversation) {
      return null
    }

    try {
      this.conversationHistory = JSON.parse(conversation.messages) as ModelMessage[]
      this.conversationId = conversationId
      this.initialized = true

      const chatMessages = JSON.parse(conversation.chatMessages) as EditorChatMessage[]
      const pendingEdits = JSON.parse(conversation.pendingEdits) as EditorProposedEdit[]
      const parsedUi = conversation.uiState ? JSON.parse(conversation.uiState) : {}
      const selectedTargetEntryId =
        parsedUi && typeof parsedUi.selectedTargetEntryId === 'string'
          ? parsedUi.selectedTargetEntryId
          : null

      return {
        chatMessages,
        pendingEdits,
        selectedTargetEntryId,
      }
    } catch (error) {
      log('Failed to parse editor conversation payload', { conversationId, error })
      return null
    }
  }

  getConversationId(): string | null {
    return this.conversationId
  }

  private buildTools(context: EditorInteractiveContext) {
    const edits = new Map<string, EditorProposedEdit>()
    const lorebookEntries = JSON.parse(
      JSON.stringify(context.worldState.lorebookEntries),
    ) as Entry[]
    const chapters = JSON.parse(JSON.stringify(context.chapters)) as Chapter[]
    const storyEntries = JSON.parse(JSON.stringify(context.storyEntries)) as StoryEntry[]
    const chapterEntriesByNumber = JSON.parse(
      JSON.stringify(context.chapterEntriesByNumber),
    ) as Record<string, StoryEntry[]>

    const tools = {
      search_lorebook_entries: tool({
        description:
          'Search lorebook entries by keyword, name, alias, or entry type when editing needs canon reference.',
        inputSchema: z.object({
          query: z.string().optional(),
          type: z.string().optional(),
          limit: z.number().optional().default(10),
        }),
        execute: async ({
          query,
          type,
          limit,
        }: {
          query?: string
          type?: string
          limit?: number
        }) => {
          let filtered = lorebookEntries

          if (type?.trim()) {
            const expectedType = type.trim().toLowerCase()
            filtered = filtered.filter((entry) => entry.type.toLowerCase() === expectedType)
          }

          if (query?.trim()) {
            const term = query.trim().toLowerCase()
            filtered = filtered.filter(
              (entry) =>
                entry.name.toLowerCase().includes(term) ||
                entry.description.toLowerCase().includes(term) ||
                entry.aliases.some((alias) => alias.toLowerCase().includes(term)) ||
                entry.injection.keywords.some((keyword) => keyword.toLowerCase().includes(term)),
            )
          }

          return {
            total: filtered.length,
            entries: filtered.slice(0, limit ?? 10).map((entry) => ({
              id: entry.id,
              name: entry.name,
              type: entry.type,
              description:
                entry.description.length > 240
                  ? `${entry.description.slice(0, 240)}...`
                  : entry.description,
              aliases: entry.aliases,
              keywords: entry.injection.keywords,
            })),
          }
        },
      }),

      read_lorebook_entry: tool({
        description: 'Read a full lorebook entry by id or exact name for precise editing context.',
        inputSchema: z.object({
          id: z.string().optional(),
          name: z.string().optional(),
        }),
        execute: async ({ id, name }: { id?: string; name?: string }) => {
          const trimmedId = id?.trim()
          const trimmedName = name?.trim().toLowerCase()
          const entry = lorebookEntries.find(
            (candidate) =>
              (trimmedId ? candidate.id === trimmedId : false) ||
              (trimmedName ? candidate.name.toLowerCase() === trimmedName : false),
          )

          if (!entry) {
            return { found: false, message: 'No matching lorebook entry found.' }
          }

          return {
            found: true,
            entry: {
              id: entry.id,
              name: entry.name,
              type: entry.type,
              description: entry.description,
              hiddenInfo: entry.hiddenInfo,
              aliases: entry.aliases,
              keywords: entry.injection.keywords,
            },
          }
        },
      }),

      list_chapters: tool({
        description: 'List chapter summaries for pacing and continuity editing.',
        inputSchema: z.object({
          limit: z.number().optional().default(30),
        }),
        execute: async ({ limit }: { limit?: number }) => {
          const selected = chapters.slice(0, limit ?? 30)
          return {
            total: chapters.length,
            chapters: selected.map((chapter) => ({
              number: chapter.number,
              title: chapter.title,
              summary:
                chapter.summary.length > 500
                  ? `${chapter.summary.slice(0, 500)}...`
                  : chapter.summary,
              keywords: chapter.keywords,
              characters: chapter.characters,
              locations: chapter.locations,
              plotThreads: chapter.plotThreads,
            })),
          }
        },
      }),

      read_chapter: tool({
        description:
          'Read chapter summary and optionally entry excerpts when detailed rewrite continuity is needed.',
        inputSchema: z.object({
          chapterNumber: z.number(),
          includeEntries: z.boolean().optional().default(false),
          entryLimit: z.number().optional().default(24),
        }),
        execute: async ({
          chapterNumber,
          includeEntries,
          entryLimit,
        }: {
          chapterNumber: number
          includeEntries?: boolean
          entryLimit?: number
        }) => {
          const chapter = chapters.find((candidate) => candidate.number === chapterNumber)
          if (!chapter) {
            return { found: false, message: `Chapter ${chapterNumber} not found.` }
          }

          const chapterEntries = chapterEntriesByNumber[String(chapterNumber)] ?? []

          return {
            found: true,
            chapter: {
              number: chapter.number,
              title: chapter.title,
              summary: chapter.summary,
              keywords: chapter.keywords,
              characters: chapter.characters,
              locations: chapter.locations,
              plotThreads: chapter.plotThreads,
              emotionalTone: chapter.emotionalTone,
            },
            entries: includeEntries
              ? chapterEntries.slice(0, entryLimit ?? 24).map((entry) => ({
                  id: entry.id,
                  type: entry.type,
                  content: entry.content,
                  createdAt: entry.createdAt,
                }))
              : undefined,
            entryCount: chapterEntries.length,
          }
        },
      }),

      search_story_text: tool({
        description:
          'Search current story text entries by keyword. Use this to locate exact passages for edits.',
        inputSchema: z.object({
          query: z.string(),
          limit: z.number().optional().default(12),
        }),
        execute: async ({ query, limit }: { query: string; limit?: number }) => {
          const term = query.trim().toLowerCase()
          const matches = term
            ? storyEntries.filter((entry) => entry.content.toLowerCase().includes(term))
            : []

          return {
            total: matches.length,
            matches: matches.slice(0, limit ?? 12).map((entry) => ({
              id: entry.id,
              type: entry.type,
              position: entry.position,
              content: entry.content,
              createdAt: entry.createdAt,
            })),
          }
        },
      }),

      read_recent_story_text: tool({
        description:
          'Read the most recent story entries for immediate scene-level editing context.',
        inputSchema: z.object({
          count: z.number().optional().default(12),
          includeSystem: z.boolean().optional().default(false),
        }),
        execute: async ({ count, includeSystem }: { count?: number; includeSystem?: boolean }) => {
          const filtered = includeSystem
            ? storyEntries
            : storyEntries.filter((entry) => entry.type !== 'system')
          const selected = filtered.slice(-Math.max(1, count ?? 12))

          return {
            totalAvailable: filtered.length,
            entries: selected.map((entry) => ({
              id: entry.id,
              type: entry.type,
              position: entry.position,
              content: entry.content,
              createdAt: entry.createdAt,
            })),
          }
        },
      }),

      apply_story_entry_edit: tool({
        description:
          'Commit a specific rewrite for an existing story entry when the user explicitly approves making text changes.',
        inputSchema: z.object({
          entryId: z.string().describe('Story entry ID to edit.'),
          revisedContent: z.string().describe('Full revised replacement text for the entry.'),
          revisedType: z
            .enum(['user_action', 'narration', 'system'])
            .optional()
            .describe('Optional new entry type when the rewrite should change the message role.'),
          reason: z.string().optional().describe('Short rationale for this edit.'),
          reprocessChapter: z
            .boolean()
            .optional()
            .default(true)
            .describe('Whether to re-summarize the affected chapter after edit.'),
          rerunLorebookPass: z
            .boolean()
            .optional()
            .default(false)
            .describe('Whether to run a lorebook management pass on chapter context after edit.'),
        }),
        execute: async ({
          entryId,
          revisedContent,
          revisedType,
          reason,
          reprocessChapter,
          rerunLorebookPass,
        }: {
          entryId: string
          revisedContent: string
          revisedType?: StoryEntry['type']
          reason?: string
          reprocessChapter?: boolean
          rerunLorebookPass?: boolean
        }) => {
          const entry = storyEntries.find((candidate) => candidate.id === entryId)
          if (!entry) {
            return { success: false, message: `Entry ${entryId} was not found.` }
          }
          if (entry.type === 'system') {
            return { success: false, message: 'System entries cannot be edited by this tool.' }
          }

          const revised = revisedContent.trim()
          if (!revised) {
            return { success: false, message: 'Revised content cannot be empty.' }
          }

          const edit: EditorProposedEdit = {
            id: crypto.randomUUID(),
            entryId: entry.id,
            entryType: entry.type,
            revisedEntryType: revisedType ?? entry.type,
            originalContent: entry.content,
            revisedContent,
            reason: reason?.trim() || 'Editorial rewrite requested in conversation.',
            reprocessChapter: reprocessChapter ?? true,
            rerunLorebookPass: rerunLorebookPass ?? false,
          }
          edits.set(edit.id, edit)

          return {
            success: true,
            editId: edit.id,
            entryId: edit.entryId,
            entryType: edit.entryType,
            message: `Prepared edit for entry ${entry.position} (${entry.type}).`,
          }
        },
      }),
    }

    return { tools, edits }
  }

  async *sendMessageStreaming(
    context: EditorInteractiveContext,
    userMessage: string,
    signal?: AbortSignal,
  ): AsyncGenerator<EditorStreamEvent> {
    if (!this.initialized) {
      await this.initialize(context)
    }

    const { tools, edits } = this.buildTools(context)

    this.conversationHistory.push({ role: 'user', content: userMessage })

    try {
      const assistant = createStreamingAgenticAssistant(
        {
          presetId: this.presetId,
          instructions: this.systemPrompt,
          tools: tools as ToolSet,
          stopWhen: stopWhenDone(20),
          signal,
        },
        'interactive-editor-assistant',
      )

      const streamResult = await assistant.stream({ messages: this.conversationHistory })

      const currentToolCalls: Array<{
        id: string
        name: string
        args: Record<string, unknown>
        claimed: boolean
      }> = []

      let stepContent = ''
      let stepReasoning: string | undefined
      let stepToolCalls: EditorToolCallDisplay[] = []

      for await (const event of streamResult.fullStream) {
        switch (event.type) {
          case 'start-step':
            stepContent = ''
            stepReasoning = undefined
            stepToolCalls = []
            currentToolCalls.length = 0
            break

          case 'reasoning-start':
          case 'reasoning-delta':
            if (event.type === 'reasoning-delta') {
              stepReasoning = (stepReasoning || '') + event.text
            }
            yield { type: 'thinking' }
            break

          case 'text-delta':
            stepContent += event.text
            break

          case 'tool-call':
            currentToolCalls.push({
              id: event.toolCallId,
              name: event.toolName,
              args: event.input as Record<string, unknown>,
              claimed: false,
            })
            yield {
              type: 'tool_start',
              toolCallId: event.toolCallId,
              toolName: event.toolName,
              args: event.input as Record<string, unknown>,
            }
            break

          case 'tool-result': {
            const info = currentToolCalls.find((tc) => tc.id === event.toolCallId && !tc.claimed)
            if (info) info.claimed = true
            if (!info) break

            const toolResult = 'result' in event ? event.result : event.output
            const resultRecord =
              toolResult && typeof toolResult === 'object'
                ? (toolResult as Record<string, unknown>)
                : undefined

            const editId =
              resultRecord && typeof resultRecord.editId === 'string' ? resultRecord.editId : null

            const toolCall: EditorToolCallDisplay = {
              id: event.toolCallId,
              name: info.name,
              args: info.args,
              result: typeof toolResult === 'string' ? toolResult : JSON.stringify(toolResult),
              edit: editId ? edits.get(editId) : undefined,
            }

            stepToolCalls.push(toolCall)
            yield { type: 'tool_end', toolCall }
            break
          }

          case 'finish-step':
            if (stepContent || stepToolCalls.length > 0) {
              yield {
                type: 'message',
                message: {
                  id: `editor-step-${Date.now()}`,
                  role: 'assistant',
                  content: stepContent,
                  timestamp: Date.now(),
                  toolCalls: stepToolCalls.length > 0 ? [...stepToolCalls] : undefined,
                  reasoning: stepReasoning,
                },
              }
            }
            break

          case 'error':
            yield { type: 'error', error: String(event.error) }
            return
        }
      }

      const responseMessages = await streamResult.response
      this.conversationHistory.push(...responseMessages.messages)
      yield { type: 'done' }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      log('Interactive editor stream failed', { message })
      yield { type: 'error', error: message }
    }
  }

  private async buildSystemPrompt(story: Story): Promise<string> {
    const packId = (await database.getStoryPackId(story.id)) ?? 'default-pack'
    const template =
      (await database.getPackTemplate(packId, 'interactive-editor-assistant')) ??
      (packId !== 'default-pack'
        ? await database.getPackTemplate('default-pack', 'interactive-editor-assistant')
        : null)

    const fallback = [
      'You are a collaborative fiction Editor Assistant for draft improvement.',
      'Discuss pacing, clarity, continuity, characterization, and scene impact conversationally.',
      'Use tools to reference lorebook entries, chapter summaries, chapter entries, and story text.',
      'Do NOT force edits by default. Explain suggested improvements first and get user alignment.',
      'When the user explicitly asks to rewrite, revise, convert, or edit a specific existing entry, you MUST call apply_story_entry_edit to queue that edit.',
      'If the user names multiple existing entries, queue one apply_story_entry_edit call per entry instead of only returning prose blocks in chat.',
      'Do not return full rewritten entry bodies in chat unless the matching apply_story_entry_edit call has already been queued, or the user explicitly asks for prose-only suggestions without queueing edits.',
      'If the rewrite should change an entry role, include revisedType in the tool call.',
      'When applying edits, preserve canon continuity and voice unless user asks for a tonal shift.',
      'Keep edits grounded in available story context and avoid introducing unsupported facts.',
    ].join('\n')

    if (!template?.content?.trim()) {
      return fallback
    }

    return (
      templateEngine.render(template.content, {
        storyTitle: story.title,
        storyMode: story.mode,
      }) || fallback
    )
  }

  private generateTitle(chatMessages: EditorChatMessage[]): string {
    const firstUser = chatMessages.find((message) => message.role === 'user')
    const content = firstUser?.content?.trim()

    if (!content) return 'New Conversation'
    if (content.length <= 50) return content

    const truncated = content.slice(0, 50)
    const lastSpace = truncated.lastIndexOf(' ')
    return `${lastSpace > 20 ? truncated.slice(0, lastSpace) : truncated}...`
  }
}

/**
 * Narrative Service
 *
 * The core service that generates story responses.
 * This is the heart of the application - it handles narrative generation
 * both streaming and non-streaming.
 *
 * Unlike other services that use the preset system, NarrativeService uses
 * the main narrative profile directly (apiSettings.defaultModel, temperature, maxTokens).
 *
 * Uses ContextBuilder for prompt generation through the unified Liquid template pipeline.
 */

import { streamNarrative, generateNarrative } from '../sdk/generate'
import { ContextBuilder } from '$lib/services/context'
import { StyleReviewerService } from './StyleReviewerService'
import { templateEngine } from '$lib/services/templates/engine'
import { createLogger } from '$lib/log'
import { stripPicTags } from '$lib/utils/inlineImageParser'
import type { StreamChunk } from '../core/types'
import type {
  Story,
  StoryEntry,
  Entry,
  Character,
  Location,
  Item,
  StoryBeat,
  Chapter,
  TimeTracker,
} from '$lib/types'
import type { StyleReviewResult } from './StyleReviewerService'
import type { TimelineFillResult } from '../retrieval/TimelineFillService'

const log = createLogger('Narrative')

/**
 * World state context for prompt building
 */
export interface WorldStateContext {
  characters: Character[]
  locations: Location[]
  items: Item[]
  storyBeats: StoryBeat[]
  currentLocation?: Location
  chapters?: Chapter[]
  actingProtagonistName?: string
  actingProtagonistDescription?: string | null
  guidedRegenerationNudge?: string
  guidedRegenerationPreviousNarration?: string
}

/**
 * World state context for narrative generation.
 * Extends the base WorldStateContext with lorebook entries.
 */
export interface NarrativeWorldState extends WorldStateContext {
  lorebookEntries?: Entry[]
}

/**
 * Format a TimeTracker into a human-readable string for the narrative prompt.
 * Always returns a value, defaulting to Year 1, Day 1, 0 hours 0 minutes if null.
 */
export function formatStoryTime(time: TimeTracker | null | undefined): string {
  const t = time ?? { years: 0, days: 0, hours: 0, minutes: 0 }
  const year = t.years + 1
  const day = t.days + 1
  return `Year ${year}, Day ${day}, ${t.hours} hours ${t.minutes} minutes`
}

/**
 * Build a block containing chapter summaries for injection into the system prompt.
 * Per design doc: summarized entries are excluded from direct context,
 * but their summaries provide narrative continuity.
 */
export function buildChapterSummariesBlock(
  chapters: Chapter[],
  timelineFillResult?: TimelineFillResult | null,
): string {
  if (chapters.length === 0) return ''

  let block = '\n\n<story_history>\n'
  block += '## Previous Chapters\n'
  block +=
    'The following chapters have occurred earlier in the story. Use them for continuity and context.\n\n'

  for (const chapter of chapters) {
    block += `### Chapter ${chapter.number}`
    if (chapter.title) {
      block += `: ${chapter.title}`
    }
    block += '\n'

    const startTime = formatStoryTime(chapter.startTime)
    const endTime = formatStoryTime(chapter.endTime)
    if (startTime && endTime) {
      block += `*Time: ${startTime} \u2192 ${endTime}*\n`
    } else if (startTime) {
      block += `*Time: ${startTime}*\n`
    }

    block += chapter.summary
    block += '\n'

    const metadata: string[] = []
    if (chapter.characters.length > 0) {
      metadata.push(`Characters: ${chapter.characters.join(', ')}`)
    }
    if (chapter.locations.length > 0) {
      metadata.push(`Locations: ${chapter.locations.join(', ')}`)
    }
    if (chapter.emotionalTone) {
      metadata.push(`Tone: ${chapter.emotionalTone}`)
    }
    if (metadata.length > 0) {
      block += `*${metadata.join(' | ')}*\n`
    }
    block += '\n'
  }

  if (timelineFillResult && timelineFillResult.responses.length > 0) {
    block += '## Retrieved Context\n'
    block +=
      'The following information was retrieved from past chapters and is relevant to the current scene:\n\n'

    for (const response of timelineFillResult.responses) {
      const chapterLabel =
        response.chapterNumbers.length === 1
          ? `Chapter ${response.chapterNumbers[0]}`
          : `Chapters ${response.chapterNumbers.join(', ')}`

      block += `**${chapterLabel}**\n`
      block += `Q: ${response.query}\n`
      block += `A: ${response.answer}\n\n`
    }
  }

  block += '</story_history>'
  return block
}

/**
 * Options for narrative generation.
 */
export interface NarrativeOptions {
  /** Pre-built tiered context block for injection */
  tieredContextBlock?: string
  /** Style review results for avoiding repetition */
  styleReview?: StyleReviewResult | null
  /** Retrieved chapter context from memory system */
  retrievedChapterContext?: string | null
  /** Abort signal for cancellation */
  signal?: AbortSignal
  /** Timeline fill result for Q&A injection */
  timelineFillResult?: TimelineFillResult | null
}

export type ManualEditorPassOptions = NarrativeOptions

/**
 * Service for generating narrative responses.
 *
 * This service uses the main narrative profile from apiSettings directly,
 * rather than going through the preset system. This ensures narrative
 * generation uses the user's primary model and settings.
 *
 * Prompt generation flows through ContextBuilder + Liquid templates.
 */
export class NarrativeService {
  /**
   * Create a new NarrativeService.
   * No preset required - uses main narrative profile from settings.
   */
  constructor() {
    // No configuration needed - uses main profile directly
  }

  /**
   * Stream a narrative response.
   *
   * This is the primary method used by the UI for real-time narrative generation.
   * Yields StreamChunk objects as text arrives from the model.
   */
  async *stream(
    entries: StoryEntry[],
    worldState: NarrativeWorldState,
    story?: Story | null,
    options: NarrativeOptions = {},
  ): AsyncIterable<StreamChunk> {
    const { tieredContextBlock, styleReview, retrievedChapterContext, signal, timelineFillResult } =
      options

    log('stream', {
      entriesCount: entries.length,
      hasTieredContext: !!tieredContextBlock,
      hasStyleReview: !!styleReview,
      hasRetrievedContext: !!retrievedChapterContext,
      hasTimelineFill: !!timelineFillResult,
    })

    // Build system prompt via ContextBuilder pipeline
    const { systemPrompt, primingMessage } = await this.buildPrompts(
      story,
      worldState,
      tieredContextBlock,
      styleReview,
      retrievedChapterContext,
      timelineFillResult,
    )

    // Build the user prompt from entries
    const mode = story?.mode ?? 'adventure'
    const inlineImageMode = story?.settings?.imageGenerationMode === 'inline'
    const userPrompt = this.buildUserPrompt(
      entries,
      mode,
      inlineImageMode,
      worldState.guidedRegenerationPreviousNarration,
      worldState.guidedRegenerationNudge,
      worldState.actingProtagonistName,
    )

    const firstPassPrompt = `${primingMessage}\n\n${userPrompt}`
    const editingPassEnabled = this.isEditingPassEnabled(story)

    try {
      // Default path: single-pass streaming
      if (!editingPassEnabled) {
        const stream = streamNarrative({
          system: systemPrompt,
          prompt: firstPassPrompt,
          signal,
        })

        // Use fullStream to capture both text and reasoning
        // - Native reasoning providers (Anthropic, OpenAI) emit reasoning-delta parts
        // - Models using <think> tags have reasoning extracted by extractReasoningMiddleware
        for await (const part of stream.fullStream) {
          if (part.type === 'reasoning-delta') {
            // Reasoning delta from native providers or extracted from <think> tags
            yield { content: '', reasoning: (part as { text?: string }).text, done: false }
          } else if (part.type === 'text-delta') {
            // Regular text content
            yield { content: (part as { text?: string }).text || '', done: false }
          }
          // Ignore other part types (reasoning-start, reasoning-end, tool calls, finish, etc.)
        }

        yield { content: '', done: true }
        return
      }

      // Hidden two-pass path:
      // 1) Generate draft
      // 2) Edit draft with mode-specific editor prompt
      // 3) Stream edited output to user
      const firstPassDraft = await generateNarrative({
        system: systemPrompt,
        prompt: firstPassPrompt,
        signal,
      })

      const editorSystemPrompt = await this.buildEditorSystemPrompt(
        story,
        worldState,
        tieredContextBlock,
        styleReview,
        retrievedChapterContext,
        timelineFillResult,
      )

      if (!editorSystemPrompt) {
        log('editor pass unavailable; falling back to first pass draft')
        yield { content: firstPassDraft, done: false }
        yield { content: '', done: true }
        return
      }

      const editorUserPrompt = this.buildEditorPassUserPrompt(firstPassDraft)

      try {
        const editorStream = streamNarrative({
          system: editorSystemPrompt,
          prompt: editorUserPrompt,
          signal,
        })

        for await (const part of editorStream.fullStream) {
          if (part.type === 'reasoning-delta') {
            yield { content: '', reasoning: (part as { text?: string }).text, done: false }
          } else if (part.type === 'text-delta') {
            yield { content: (part as { text?: string }).text || '', done: false }
          }
        }

        yield { content: '', done: true }
        return
      } catch (editorError) {
        log('editor pass failed; falling back to first pass draft', editorError)
        yield { content: firstPassDraft, done: false }
        yield { content: '', done: true }
        return
      }
    } catch (error) {
      log('stream error', error)
      // Re-throw to let caller handle the error
      throw error
    }
  }

  /**
   * Generate a complete narrative response (non-streaming).
   *
   * Used for scenarios where streaming is not needed or supported.
   */
  async generate(
    entries: StoryEntry[],
    worldState: NarrativeWorldState,
    story?: Story | null,
    options: Omit<NarrativeOptions, 'timelineFillResult'> = {},
  ): Promise<string> {
    const { tieredContextBlock, styleReview, retrievedChapterContext, signal } = options

    log('generate', { entriesCount: entries.length })

    // Build system prompt via ContextBuilder pipeline
    const { systemPrompt, primingMessage } = await this.buildPrompts(
      story,
      worldState,
      tieredContextBlock,
      styleReview,
      retrievedChapterContext,
    )

    const mode = story?.mode ?? 'adventure'
    const inlineImageMode = story?.settings?.imageGenerationMode === 'inline'
    const userPrompt = this.buildUserPrompt(
      entries,
      mode,
      inlineImageMode,
      worldState.guidedRegenerationPreviousNarration,
      worldState.guidedRegenerationNudge,
      worldState.actingProtagonistName,
    )

    const firstPassPrompt = `${primingMessage}\n\n${userPrompt}`
    const editingPassEnabled = this.isEditingPassEnabled(story)

    if (!editingPassEnabled) {
      return generateNarrative({
        system: systemPrompt,
        prompt: firstPassPrompt,
        signal,
      })
    }

    const firstPassDraft = await generateNarrative({
      system: systemPrompt,
      prompt: firstPassPrompt,
      signal,
    })

    const editorSystemPrompt = await this.buildEditorSystemPrompt(
      story,
      worldState,
      tieredContextBlock,
      styleReview,
      retrievedChapterContext,
      null,
    )

    if (!editorSystemPrompt) {
      log('editor pass unavailable; returning first pass draft')
      return firstPassDraft
    }

    try {
      return await generateNarrative({
        system: editorSystemPrompt,
        prompt: this.buildEditorPassUserPrompt(firstPassDraft),
        signal,
      })
    } catch (editorError) {
      log('editor pass failed; returning first pass draft', editorError)
      return firstPassDraft
    }
  }

  /**
   * Apply a manual editor pass to existing narrative prose.
   * Uses mode-specific editor templates and returns the edited prose.
   */
  async applyManualEditorPass(
    draft: string,
    worldState: NarrativeWorldState,
    story?: Story | null,
    options: ManualEditorPassOptions = {},
  ): Promise<string> {
    const { tieredContextBlock, styleReview, retrievedChapterContext, signal, timelineFillResult } =
      options

    // Manual editor pass should honor the currently active prompt configuration:
    // story custom system prompt (if set) or active pack/mode narrative template.
    const { systemPrompt } = await this.buildPrompts(
      story,
      worldState,
      tieredContextBlock,
      styleReview,
      retrievedChapterContext,
      timelineFillResult,
    )

    return generateNarrative({
      system: systemPrompt,
      prompt: this.buildEditorPassUserPrompt(draft),
      signal,
    })
  }

  /**
   * Build system and priming prompts through the ContextBuilder pipeline.
   *
   * Creates a ContextBuilder from the story, adds runtime variables
   * (tiered context, chapter summaries, style guidance), then renders
   * through the Liquid template for the story's mode.
   */
  private async buildPrompts(
    story: Story | null | undefined,
    worldState: NarrativeWorldState,
    tieredContextBlock?: string,
    styleReview?: StyleReviewResult | null,
    retrievedChapterContext?: string | null,
    timelineFillResult?: TimelineFillResult | null,
  ): Promise<{ systemPrompt: string; primingMessage: string }> {
    const { mode, ctx } = await this.buildNarrativeContext(
      story,
      worldState,
      tieredContextBlock,
      styleReview,
      retrievedChapterContext,
      timelineFillResult,
    )

    // Render system prompt — use per-story override when set, otherwise fall back to pack template
    let systemPrompt: string
    const customPrompt = story?.settings?.customSystemPrompt
    if (customPrompt) {
      const rendered = templateEngine.render(customPrompt, ctx.getContext())
      if (rendered === null) {
        throw new Error(
          'Custom system prompt contains a Liquid syntax error. Edit it in Story Settings.',
        )
      }
      const intensityContract = ctx.getContext().safetyContentIntensity
      systemPrompt = intensityContract ? `${rendered}\n\n${intensityContract}` : rendered
    } else {
      const { system } = await ctx.render('adventure')
      systemPrompt = system
    }

    // Build priming message based on pov/tense
    const context = ctx.getContext()
    const primingMessage =
      (context.narrativePriming as string) ||
      `You are the narrator of this interactive adventure. Resolve the currently acting character's action.`

    log('buildPrompts complete', {
      mode,
      usingCustomPrompt: !!customPrompt,
      systemPromptLength: systemPrompt.length,
      primingMessageLength: primingMessage.length,
    })

    return { systemPrompt, primingMessage }
  }

  private isEditingPassEnabled(story: Story | null | undefined): boolean {
    return story?.settings?.editingPassBeforeDisplayEnabled === true
  }

  private buildEditorPassUserPrompt(firstPassDraft: string): string {
    return [
      'Edit the draft below according to your system instructions.',
      'Preserve continuity, concrete facts, and scene outcomes.',
      'Return revised prose only.',
      '',
      '## Draft',
      firstPassDraft,
    ].join('\n')
  }

  private async buildEditorSystemPrompt(
    story: Story | null | undefined,
    worldState: NarrativeWorldState,
    tieredContextBlock?: string,
    styleReview?: StyleReviewResult | null,
    retrievedChapterContext?: string | null,
    timelineFillResult?: TimelineFillResult | null,
  ): Promise<string | null> {
    try {
      const { ctx } = await this.buildNarrativeContext(
        story,
        worldState,
        tieredContextBlock,
        styleReview,
        retrievedChapterContext,
        timelineFillResult,
      )

      const { system } = await ctx.render('editor-adventure')
      return system?.trim() ? system : null
    } catch (error) {
      log('buildEditorSystemPrompt failed', error)
      return null
    }
  }

  private async buildNarrativeContext(
    story: Story | null | undefined,
    worldState: NarrativeWorldState,
    tieredContextBlock?: string,
    styleReview?: StyleReviewResult | null,
    retrievedChapterContext?: string | null,
    timelineFillResult?: TimelineFillResult | null,
  ): Promise<{ mode: 'adventure'; ctx: ContextBuilder }> {
    const mode = story?.mode ?? 'adventure'

    let ctx: ContextBuilder

    if (story?.id) {
      ctx = await ContextBuilder.forStory(story.id)
    } else {
      ctx = new ContextBuilder()
      ctx.add({
        mode,
        pov: story?.settings?.pov ?? 'second',
        tense: story?.settings?.tense ?? 'present',
        protagonistName: 'the protagonist',
      })
    }

    if (tieredContextBlock) {
      ctx.add({ tieredContextBlock })
    }

    if (retrievedChapterContext) {
      ctx.add({ retrievedChapterContext })
    }

    if (worldState.chapters && worldState.chapters.length > 0) {
      const chapterSummaries = buildChapterSummariesBlock(worldState.chapters, timelineFillResult)
      if (chapterSummaries) {
        ctx.add({ chapterSummaries })
      }
    }

    const actingProtagonistName = worldState.actingProtagonistName?.trim()
    if (actingProtagonistName) {
      ctx.add({
        protagonistName: actingProtagonistName,
        protagonistDescription: worldState.actingProtagonistDescription ?? '',
        activeActorName: actingProtagonistName,
      })
    }

    if (styleReview && styleReview.phrases.length > 0) {
      const styleGuidance = StyleReviewerService.formatForPromptInjection(styleReview)
      if (styleGuidance) {
        ctx.add({ styleGuidance })
      }
    }

    const guidanceNudge = worldState.guidedRegenerationNudge?.trim()
    if (guidanceNudge) {
      ctx.add({ guidedRegenerationNudge: guidanceNudge })
    }

    return { mode, ctx }
  }

  /**
   * Build the user prompt from recent story entries.
   *
   * Formats entries as a conversation history with the current action highlighted.
   */
  private buildUserPrompt(
    entries: StoryEntry[],
    mode: 'adventure',
    inlineImageMode: boolean = false,
    guidedRegenerationPreviousNarration?: string,
    guidedRegenerationNudge?: string,
    actingProtagonistName?: string,
  ): string {
    // Use all entries passed - these are already the visible (non-summarized) entries
    // Truncation/context management happens upstream via the memory system

    // Format entries based on mode
    const historyParts: string[] = []
    for (const entry of entries) {
      // Strip <pic> tags if not in inline mode to prevent AI from immitating them
      const content = inlineImageMode ? entry.content : stripPicTags(entry.content)

      if (entry.type === 'user_action') {
        historyParts.push(`[ACTION] ${content}`)
      } else if (entry.type === 'narration') {
        historyParts.push(`[NARRATIVE]\n${content}`)
      }
    }

    // Get the last user action as the current input
    const lastUserAction = [...entries].reverse().find((e) => e.type === 'user_action')
    const currentAction = lastUserAction
      ? inlineImageMode
        ? lastUserAction.content
        : stripPicTags(lastUserAction.content)
      : ''

    // Build final prompt
    let prompt = ''

    if (historyParts.length > 1) {
      // Include history minus the last action (which becomes current)
      prompt += '## Recent Story:\n'
      prompt += historyParts.slice(0, -1).join('\n\n')
      prompt += '\n\n'
    }

    prompt += '## Current Action:\n'
    if (actingProtagonistName?.trim()) {
      prompt += `Acting character for this action: ${actingProtagonistName.trim()}\n`
      prompt += `Resolve the current action as ${actingProtagonistName.trim()}'s action, not another character's action.\n`
    }
    prompt += currentAction
    prompt += '\n\n'

    const previousDraft = guidedRegenerationPreviousNarration?.trim()
    if (previousDraft) {
      const draftContent = inlineImageMode ? previousDraft : stripPicTags(previousDraft)
      prompt += '## Previous Narrative Draft (Revise This):\n'
      prompt += draftContent
      prompt += '\n\n'
      prompt +=
        'Regenerate by revising this draft, not by starting from scratch. Keep valid details and flow, then correct inaccuracies and apply the guidance notes naturally.\n\n'
    }

    const guidance = guidedRegenerationNudge?.trim()
    if (guidance) {
      const checklist = guidance
        .split(/[.!?]+(?:\s+|$)/)
        .map((s) => s.trim())
        .filter((s) => s.length > 0)
        .slice(0, 6)

      prompt += '## Guided Regeneration Notes (Soft Priority):\n'
      prompt +=
        'Use these as subtle steering notes for this regeneration. Try to address each point where it naturally fits the scene and continuity.\n'

      if (checklist.length > 0) {
        for (const item of checklist) {
          prompt += `- ${item}\n`
        }
      } else {
        prompt += `- ${guidance}\n`
      }

      prompt += '\n'
    }

    prompt += 'Continue the narrative:'

    return prompt
  }
}

/**
 * Classifier Schema
 *
 * Zod schema for validating world state extraction from narrative responses.
 * The .describe() calls provide semantic guidance to LLMs via schema introspection.
 */

import { z } from 'zod'
import type { RuntimeVariable } from '$lib/services/packs/types'

// ============================================================================
// Visual Descriptors Schema
// ============================================================================

export const visualDescriptorsSchema = z
  .object({
    face: z.string().describe('Skin tone, facial features, expression, age indicators').optional(),
    hair: z
      .string()
      .describe('Color, length, style, texture (e.g., "wavy auburn hair to shoulders")')
      .optional(),
    eyes: z
      .string()
      .describe('Color, shape, notable features (e.g., "sharp green eyes")')
      .optional(),
    build: z
      .string()
      .describe('Height, body type, posture (e.g., "tall and lean", "broad-shouldered")')
      .optional(),
    clothing: z
      .string()
      .describe('Full outfit description (e.g., "worn leather armor over gray tunic")')
      .optional(),
    accessories: z
      .string()
      .describe('Jewelry, weapons, bags, distinctive items (e.g., "silver pendant, sword at hip")')
      .optional(),
    distinguishing: z
      .string()
      .describe('Scars, tattoos, birthmarks if any (e.g., "scar across left cheek")')
      .optional(),
  })
  .describe(
    'Visual appearance details for image generation - invent plausible details if not explicitly described',
  )

export type VisualDescriptors = z.infer<typeof visualDescriptorsSchema>

// ============================================================================
// Character Schemas
// ============================================================================

export const characterUpdateSchema = z.object({
  name: z.string().describe('Exact name of existing character to update'),
  changes: z.object({
    status: z
      .enum(['active', 'inactive', 'deceased'])
      .describe('active=present, inactive=away, deceased=dead')
      .optional(),
    relationship: z.string().describe('New relationship to protagonist').optional(),
    newTraits: z.array(z.string()).describe('Personality traits to add').optional(),
    removeTraits: z.array(z.string()).describe('Traits no longer applicable').optional(),
    visualDescriptors: visualDescriptorsSchema
      .describe('Complete visual appearance - replaces existing descriptors')
      .optional(),
  }),
})

export const newCharacterSchema = z.object({
  name: z.string().describe("Character's proper name"),
  description: z.string().describe('One sentence description').optional(),
  relationship: z.string().describe('friend, enemy, ally, neutral, or unknown').optional(),
  traits: z.array(z.string()).describe('Personality traits').optional(),
  visualDescriptors: visualDescriptorsSchema
    .describe('Complete visual appearance - ALL categories should be filled')
    .optional(),
  status: z
    .enum(['active', 'inactive', 'deceased'])
    .describe('active if present in scene')
    .optional(),
})

// ============================================================================
// Location Schemas
// ============================================================================

