export interface ClassificationSchemaOptions {
  characterClassificationEnabled?: boolean
  locationClassificationEnabled?: boolean
  inventoryClassificationEnabled?: boolean
  storyBeatClassificationEnabled?: boolean
  sceneClassificationEnabled?: boolean
  timeClassificationEnabled?: boolean
  moneyClassificationEnabled?: boolean
}

/**
 * Build a classifier result schema with subprocess fields removed when disabled.
 * This keeps JSON schema requests aligned with active classifier toggles.
 */
export function buildClassificationResultSchema(
  options: ClassificationSchemaOptions,
): z.ZodTypeAny {
  let entry: z.AnyZodObject = entryUpdatesSchema
  let scene: z.AnyZodObject = sceneSchema

  if (!options.characterClassificationEnabled) {
    entry = entry.omit({ characterUpdates: true, newCharacters: true })
  }
  if (!options.locationClassificationEnabled) {
    entry = entry.omit({ locationUpdates: true, newLocations: true })
  }
  if (!options.inventoryClassificationEnabled) {
    entry = entry.omit({ itemUpdates: true, newItems: true })
  }
  if (!options.storyBeatClassificationEnabled) {
    entry = entry.omit({ storyBeatUpdates: true, newStoryBeats: true })
  }

  if (!options.sceneClassificationEnabled) {
    scene = scene.omit({ currentLocationName: true, presentCharacterNames: true })
  }
  if (!options.timeClassificationEnabled) {
    scene = scene.omit({ timeProgression: true })
  }
  if (!options.moneyClassificationEnabled) {
    scene = scene.omit({ moneyUpdate: true })
  }

  return z.object({ entryUpdates: entry, scene })
}

