/**
 * Runtime Variables Schema Factory
 *
 * Dynamically builds Zod schemas from RuntimeVariable definitions at runtime.
 * Used by the ClassifierService to extend the base classification schema with
 * custom variable extraction when a story's pack defines runtime variables.
 *
 * Key design decisions:
 * - Runtime vars are added as INLINE fields (not nested under `customVars`)
 * - Single-element enums use z.literal() directly (z.union crashes with <2 items)
 * - Number min/max are included in .describe() for LLM guidance; clamped post-extraction
 * - Variables with defaultValue are marked .optional() in the schema
 * - The LLM sees variableName as the key, but stored values are keyed by defId
 */

import { z } from 'zod'
import type { RuntimeVariable, RuntimeEntityType } from '$lib/services/packs/types'
import {
  classificationResultSchema,
  entryUpdatesSchema,
  characterUpdateSchema,
  newCharacterSchema,
  locationUpdateSchema,
  newLocationSchema,
  itemUpdateSchema,
  newItemSchema,
  storyBeatUpdateSchema,
  newStoryBeatSchema,
  sceneSchema as defaultSceneSchema,
} from './classifier'

// ============================================================================
// Variable Description Builder
// ============================================================================

/**
 * Build a description string for a runtime variable, including min/max range for numbers.
 * This becomes the `// comment` in the schema the LLM sees.
 */
function buildVariableDescription(def: RuntimeVariable): string {
  const desc = def.description || def.displayName

  if (def.variableType === 'number') {
    if (def.minValue !== undefined && def.maxValue !== undefined) {
      return `${desc} (range: ${def.minValue}-${def.maxValue})`
    } else if (def.minValue !== undefined) {
      return `${desc} (min: ${def.minValue})`
    } else if (def.maxValue !== undefined) {
      return `${desc} (max: ${def.maxValue})`
    }
  }

  return desc
}

// ============================================================================
// Single Variable Schema Builder
// ============================================================================

/**
 * Build the base (non-optional) Zod schema for a runtime variable.
 * Used internally; call buildVariableSchema() for the version with optionality.
 */
function buildVariableBaseSchema(def: RuntimeVariable): z.ZodTypeAny {
  const desc = buildVariableDescription(def)

  switch (def.variableType) {
    case 'text':
      return z.string().describe(desc)

    case 'number':
      return z.number().describe(desc)

    case 'enum': {
      const options = def.enumOptions ?? []
      if (options.length === 0) return z.string().describe(desc)
      if (options.length === 1) return z.literal(options[0].value).describe(desc)

      const literals = options.map((opt) => z.literal(opt.value)) as [
        z.ZodLiteral<string>,
        z.ZodLiteral<string>,
        ...z.ZodLiteral<string>[],
      ]
      return z.union(literals).describe(desc)
    }

    default:
      return z.string().describe(desc)
  }
}

/**
 * Build a Zod schema for a single runtime variable definition.
 * Variables with a defaultValue are marked .optional().
 */
export function buildVariableSchema(def: RuntimeVariable): z.ZodTypeAny {
  const base = buildVariableBaseSchema(def)
  const hasDefault = def.defaultValue !== undefined && def.defaultValue !== null
  return hasDefault ? base.optional() : base
}

// ============================================================================
// Entity Variable Shape Builder
// ============================================================================

/**
 * Build a Zod shape (Record of field schemas) for runtime variables of one entity type.
 * Returns null if no variables.
 *
 * @param allOptional - true for update schemas (only include changed fields),
 *                      false for new entity schemas (required fields stay required)
 */
export function buildEntityVarsShape(
  variables: RuntimeVariable[],
  allOptional: boolean,
): z.ZodRawShape | null {
  if (variables.length === 0) return null

  const shape: z.ZodRawShape = {}
  for (const def of variables) {
    // For updates: all vars optional (only send what changed)
    // For new entities: respect defaultValue-based optionality
    shape[def.variableName] = allOptional
      ? buildVariableBaseSchema(def).optional()
      : buildVariableSchema(def)
  }

  return shape
}

// ============================================================================
// Extended Classification Schema Builder
// ============================================================================

/**
 * Map from RuntimeEntityType to the classifier schema field names.
 */
const ENTITY_TYPE_TO_SCHEMA_FIELDS: Record<RuntimeEntityType, { updates: string; new: string }> = {
  character: { updates: 'characterUpdates', new: 'newCharacters' },
  location: { updates: 'locationUpdates', new: 'newLocations' },
  item: { updates: 'itemUpdates', new: 'newItems' },
  story_beat: { updates: 'storyBeatUpdates', new: 'newStoryBeats' },
}

/**
 * Base update/new schemas per entity type -- used to extend with inline vars.
 */
const BASE_UPDATE_SCHEMAS: Record<RuntimeEntityType, z.ZodObject<z.ZodRawShape>> = {
  character: characterUpdateSchema as unknown as z.ZodObject<z.ZodRawShape>,
  location: locationUpdateSchema as unknown as z.ZodObject<z.ZodRawShape>,
  item: itemUpdateSchema as unknown as z.ZodObject<z.ZodRawShape>,
  story_beat: storyBeatUpdateSchema as unknown as z.ZodObject<z.ZodRawShape>,
}

const BASE_NEW_SCHEMAS: Record<RuntimeEntityType, z.ZodObject<z.ZodRawShape>> = {
  character: newCharacterSchema as unknown as z.ZodObject<z.ZodRawShape>,
  location: newLocationSchema as unknown as z.ZodObject<z.ZodRawShape>,
  item: newItemSchema as unknown as z.ZodObject<z.ZodRawShape>,
  story_beat: newStoryBeatSchema as unknown as z.ZodObject<z.ZodRawShape>,
}

/**
 * Build an extended classification schema that includes runtime variable fields
 * INLINE on entity update/new schemas (not nested under a `customVars` object).
 *
 * For each entity type with runtime variables:
 * - Update schemas get var fields added directly inside their `changes` object (all optional)
 * - New entity schemas get var fields added at the top level (with default-based optionality)
 *
 * If no runtime variables exist for any entity type, returns the base schema unchanged.
 */
export function buildExtendedClassificationSchema(
  runtimeVarsByEntityType: Record<string, RuntimeVariable[]>,
  baseSchema?: z.ZodTypeAny,
): z.ZodType {
  const resolvedBase = baseSchema ?? classificationResultSchema

  // Check if there are any runtime variables at all
  const entityTypes = Object.keys(runtimeVarsByEntityType) as RuntimeEntityType[]
  const typesWithVars = entityTypes.filter(
    (type) => runtimeVarsByEntityType[type] && runtimeVarsByEntityType[type].length > 0,
  )

  if (typesWithVars.length === 0) {
    return resolvedBase
  }

  const baseEntry =
    (resolvedBase as z.ZodObject<z.ZodRawShape>).shape?.entryUpdates instanceof z.ZodObject
      ? ((resolvedBase as z.ZodObject<z.ZodRawShape>).shape
          .entryUpdates as z.ZodObject<z.ZodRawShape>)
      : entryUpdatesSchema

  const baseScene =
    (resolvedBase as z.ZodObject<z.ZodRawShape>).shape?.scene instanceof z.ZodObject
      ? ((resolvedBase as z.ZodObject<z.ZodRawShape>).shape.scene as z.ZodObject<z.ZodRawShape>)
      : defaultSceneSchema

  // Build extended sub-schemas for each entity type with variables
  const entryUpdatesShape: Record<string, z.ZodTypeAny> = {}

  for (const entityType of ['character', 'location', 'item', 'story_beat'] as RuntimeEntityType[]) {
    const fields = ENTITY_TYPE_TO_SCHEMA_FIELDS[entityType]
    const updatesEnabled = Object.prototype.hasOwnProperty.call(baseEntry.shape, fields.updates)
    const newEnabled = Object.prototype.hasOwnProperty.call(baseEntry.shape, fields.new)
    if (!updatesEnabled && !newEnabled) {
      continue
    }

    const vars = runtimeVarsByEntityType[entityType]
    const updateVarsShape = vars ? buildEntityVarsShape(vars, true) : null
    const newVarsShape = vars ? buildEntityVarsShape(vars, false) : null

    if (updateVarsShape) {
      // Extend the update schema: add var fields directly inside `changes`
      const baseUpdate = BASE_UPDATE_SCHEMAS[entityType]
      const originalChanges = (baseUpdate.shape as Record<string, z.ZodTypeAny>).changes

      if (updatesEnabled && originalChanges && originalChanges instanceof z.ZodObject) {
        const extendedChanges = originalChanges.extend(updateVarsShape)
        const extendedUpdate = baseUpdate.extend({ changes: extendedChanges })
        entryUpdatesShape[fields.updates] = z.array(extendedUpdate).default([])
      } else if (updatesEnabled) {
        entryUpdatesShape[fields.updates] = z.array(baseUpdate).default([])
      }

      // Extend the new entity schema: add var fields at top level
      if (newEnabled) {
        const baseNew = BASE_NEW_SCHEMAS[entityType]
        const extendedNew = baseNew.extend(newVarsShape!)
        entryUpdatesShape[fields.new] = z.array(extendedNew).default([])
      }
    } else {
      // No variables for this entity type: use base schemas
      if (updatesEnabled) {
        entryUpdatesShape[fields.updates] = z.array(BASE_UPDATE_SCHEMAS[entityType]).default([])
      }
      if (newEnabled) {
        entryUpdatesShape[fields.new] = z.array(BASE_NEW_SCHEMAS[entityType]).default([])
      }
    }
  }

  return z.object({
    entryUpdates: z.object(entryUpdatesShape),
    scene: baseScene,
  })
}

/**
 * Extract inline runtime variable values from an LLM-generated object.
 * Filters the object's entries against known variable names from defsByName.
 */
export function extractInlineCustomVars(
  obj: Record<string, unknown>,
  defsByName: Map<string, RuntimeVariable>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(obj)) {
    if (defsByName.has(key) && value !== undefined) {
      result[key] = value
    }
  }
  return result
}

/**
 * Text-To-Speech (TTS) Service
 * Provides audio generation via OpenAI-compatible APIs (and others) with streaming support.
 * Designed for extensibility to support multiple TTS providers.
 */

import { PROVIDERS } from '../sdk/providers/config'
import { corsFetch } from '$lib/services/discovery/utils'

// Constants
export const DEFAULT_SPEECH_RATE = 1.0
export const DEFAULT_PITCH = 1.0
export const DEFAULT_VOLUME = 1.0

// TTS Configuration - matches TTSServiceSettings in settings.svelte.ts
export interface TTSSettings {
  enabled: boolean
  endpoint: string
  apiKey: string
  model: string
  voice: string
  speed: number
  autoPlay: boolean
  excludedCharacters: string
  removeHtmlTags: boolean
  removeAllHtmlContent: boolean
  htmlTagsToRemoveContent: string
  provider: 'openai' | 'google' | 'microsoft'
  volume: number
  volumeOverride: boolean
  providerVoices: Record<string, string>
}

export interface TTSVoice {
  name: string
  id: string
  lang: string
}

/**
 * Sort voices with Microsoft voices prioritized first
 */
function sortVoicesByPriority(voices: TTSVoice[]): TTSVoice[] {
  return voices.sort((a, b) => {
    const aMicrosoft = a.name.toLowerCase().includes('microsoft')
    const bMicrosoft = b.name.toLowerCase().includes('microsoft')
    if (aMicrosoft && !bMicrosoft) return -1
    if (!aMicrosoft && bMicrosoft) return 1
    return a.name.localeCompare(b.name)
  })
}

/**
 * Map SpeechSynthesisError to user-friendly error message
 */
function mapSpeechErrorToMessage(error: string): string {
  const errorMap: Record<string, string> = {
    canceled: 'Speech was canceled',
    interrupted: 'Speech was interrupted',
    'audio-busy': 'Audio device is busy',
    'audio-hardware': 'Audio hardware error',
    network: 'Network error during speech synthesis',
    'synthesis-unavailable': 'Speech synthesis is unavailable',
    'synthesis-failed': 'Speech synthesis failed',
    'language-unavailable': 'Selected language is not available',
    'voice-unavailable': 'Selected voice is not available',
    'text-too-long': 'Text is too long for speech synthesis',
    'invalid-argument': 'Invalid speech synthesis argument',
    'not-allowed': 'Speech synthesis not allowed (may require user interaction)',
  }
  return errorMap[error] || 'Speech synthesis failed'
}

/**
 * Base TTS Provider - extend this for custom implementations
 */
export abstract class TTSProvider {
  private currentAudio: HTMLAudioElement | null = null

  abstract get name(): string
  abstract get maxChunkLength(): number

  /**
   * Get available voices for this provider
   */
  abstract getAvailableVoices(): Promise<TTSVoice[]>

  /**
   * Generate TTS audio for a single text chunk.
   */
  protected abstract generateChunk(text: string, voice: string): Promise<Blob>

  /**
   * Generate TTS audio, splitting long text into chunks.
   */
  async generateSpeech(text: string, voice: string): Promise<Blob[]> {
    if (!text || text.trim().length === 0) {
      throw new Error('TTS: Cannot generate speech for empty text')
    }

    const chunks = splitTextForTTS(text, this.maxChunkLength)
    const blobs: Blob[] = []
    for (const chunk of chunks) {
      blobs.push(await this.generateChunk(chunk, voice))
    }
    return blobs
  }

  protected stopped = false

  /**
   * Play a single audio blob using HTML Audio element.
   * Creates a fresh element each time to avoid GStreamer crashes on Linux.
   */
  private playSingleBlob(
    blob: Blob,
    onProgress?: (progress: number, duration: number) => void,
    playbackRate = 1.0,
    volume = 1.0,
    volumeOverride = false,
  ): Promise<void> {
    return new Promise((resolve, reject) => {
      const url = URL.createObjectURL(blob)
      const audio = new Audio()
      this.currentAudio = audio
      if (volumeOverride) {
        audio.volume = volume
      }

      const cleanup = () => {
        audio.oncanplaythrough = null
        audio.onended = null
        audio.onerror = null
        audio.ontimeupdate = null
        // Release the PulseAudio/PipeWire stream by fully detaching the source
        audio.pause()
        URL.revokeObjectURL(url)
        audio.removeAttribute('src')
        audio.load()
      }

      audio.onerror = (e) => {
        if (this.currentAudio !== audio) return
        console.error('[TTS] Audio playback error:', e)
        cleanup()
        this.currentAudio = null
        reject(new Error('Failed to play audio'))
      }

      audio.onended = () => {
        if (this.currentAudio !== audio) return
        cleanup()
        this.currentAudio = null
        resolve()
      }

      if (onProgress) {
        audio.ontimeupdate = () => {
          if (audio.duration) {
            onProgress(audio.currentTime, audio.duration)
          }
        }
      }

      audio.oncanplaythrough = () => {
        if (this.currentAudio !== audio) return
        try {
          if (playbackRate !== 1.0) {
            audio.playbackRate = playbackRate
          }
          audio.play().catch((err) => {
            if (this.currentAudio !== audio) return
            console.error('[TTS] Play failed:', err)
            cleanup()
            this.currentAudio = null
            reject(err)
          })
        } catch (err) {
          if (this.currentAudio !== audio) return
          console.error('[TTS] Error during playback setup:', err)
          cleanup()
          this.currentAudio = null
          reject(err)
        }
      }

      audio.src = url
      audio.load()
    })
  }

  /**
   * Generate and play TTS audio in a streaming pipeline.
   * Playback starts as soon as the first chunk is ready while remaining chunks
   * are generated in the background.
   */
  async streamAndPlay(
    text: string,
    voice: string,
    onProgress?: (progress: number) => void,
    playbackRate = 1.0,
    volume = 1.0,
    volumeOverride = false,
  ): Promise<void> {
    if (!text || text.trim().length === 0) {
      throw new Error('TTS: Cannot generate speech for empty text')
    }

    this.stopAudio()
    this.stopped = false

    const textChunks = splitTextForTTS(text, this.maxChunkLength)
    const totalChunks = textChunks.length

    // Queue: generated blobs ready for playback
    const ready: Blob[] = []
    let generationDone = false
    let generationError: Error | null = null

    // Signal mechanism for producer -> consumer notification
    let notifyChunk: () => void
    let chunkAvailable = new Promise<void>((resolve) => {
      notifyChunk = resolve
    })
    const signalChunk = () => {
      notifyChunk()
      chunkAvailable = new Promise<void>((resolve) => {
        notifyChunk = resolve
      })
    }

    // Producer: generate chunks in background with retry
    const MAX_RETRIES = 2
    const produceAll = async () => {
      try {
        for (const chunk of textChunks) {
          if (this.stopped) return
          let lastErr: Error | null = null
          for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
            try {
              const blob = await this.generateChunk(chunk, voice)
              ready.push(blob)
              signalChunk()
              lastErr = null
              break
            } catch (err) {
              lastErr = err instanceof Error ? err : new Error(String(err))
              if (attempt < MAX_RETRIES) {
                console.warn(
                  `[TTS] Chunk generation failed (attempt ${attempt + 1}/${MAX_RETRIES + 1}), retrying...`,
                  lastErr,
                )
              }
            }
          }
          if (lastErr) throw lastErr
        }
      } catch (err) {
        generationError = err instanceof Error ? err : new Error(String(err))
      } finally {
        generationDone = true
        signalChunk()
      }
    }

    const generationPromise = produceAll()

    // Consumer: play chunks as they become available
    let playedIndex = 0
    while (true) {
      if (this.stopped) return

      if (playedIndex < ready.length) {
        const chunkProgress = onProgress
          ? (currentTime: number, duration: number) => {
              const base = (playedIndex / totalChunks) * 100
              const within = (currentTime / duration) * (1 / totalChunks) * 100
              onProgress(base + within)
            }
          : undefined

        await this.playSingleBlob(
          ready[playedIndex],
          chunkProgress,
          playbackRate,
          volume,
          volumeOverride,
        )
        playedIndex++
      } else if (generationDone) {
        if (generationError) throw generationError
        break
      } else {
        await chunkAvailable
      }
    }

    await generationPromise
  }

  /**
   * Stop current playback
   */
  stopAudio(): void {
    this.stopped = true
    if (this.currentAudio) {
      const audio = this.currentAudio
      // Clear reference FIRST to prevent callbacks from firing
      this.currentAudio = null

      try {
        // Clear all handlers to prevent any callbacks
        audio.oncanplaythrough = null
        audio.onended = null
        audio.onerror = null
        audio.ontimeupdate = null

        audio.pause()
        audio.removeAttribute('src')
        audio.load()
      } catch {
        // Ignore errors during cleanup
      }
    }
  }

  /**
   * Get current playback state
   */
  getPlaybackState(): { playing: boolean; progress: number; duration: number } {
    if (!this.currentAudio) {
      return { playing: false, progress: 0, duration: 0 }
    }
    return {
      playing: !this.currentAudio.paused,
      progress: this.currentAudio.currentTime,
      duration: this.currentAudio.duration || 0,
    }
  }
}

/**
 * Split text into chunks for TTS (Google Translate has ~200 char limit)
 * Similar to SillyTavern's splitRecursive approach
 */
function splitTextForTTS(text: string, maxLength = 200): string[] {
  if (!text || text.length === 0) return []
  if (text.length <= maxLength) return [text]

  const chunks: string[] = []
  // Priority: paragraph breaks, sentence ends, commas, spaces
  const delimiters = ['\n\n', '\n', '. ', '! ', '? ', ', ', ' ']

  let remaining = text
  while (remaining.length > 0) {
    if (remaining.length <= maxLength) {
      chunks.push(remaining)
      break
    }

    let splitIndex = -1
    // Try each delimiter in priority order
    for (const delimiter of delimiters) {
      const searchRange = remaining.substring(0, maxLength)
      const lastIndex = searchRange.lastIndexOf(delimiter)
      if (lastIndex > 0) {
        splitIndex = lastIndex + delimiter.length
        break
      }
    }

    // If no delimiter found, force split at maxLength
    if (splitIndex === -1) {
      splitIndex = maxLength
    }

    const chunk = remaining.substring(0, splitIndex).trim()
    if (chunk.length > 0) {
      chunks.push(chunk)
    }
    remaining = remaining.substring(splitIndex).trim()
  }

  return chunks
}

