import { generateText } from '$lib/services/ai/sdk'
import { TableTalkOrchestrator } from '$lib/services/campaign/table-talk-orchestrator'
import type { CharacterStats } from '$lib/types'

export type SessionZeroPhase =
  | 'introductions'
  | 'premises'
  | 'character_creation'
  | 'bonding'
  | 'secrets'
  | 'complete'
  | null

/**
 * Session Zero Phase content returned to UI
 */
export interface SessionZeroPhaseContent {
  phase: SessionZeroPhase
  type: 'narration' | 'interaction' | 'character_sheet_modal' | 'complete'
  content?: string
  characterToAdjust?: CharacterStats | null
  proposedAdjustments?: Record<string, string | number | null>
  nextAction?: string
  estimatedDuration?: string
}

/**
 * AI Player introduction for Introductions phase
 */
export interface AIPlayerIntroduction {
  characterId: string
  characterName: string
  introduction: string
  personality: string
  initialTableTalk?: string
}

/**
 * World premise description for Premises phase
 */
export interface WorldPremise {
  settingDescription: string
  toneExpectation: string
  aiGeneratedQuestions: string[]
}

/**
 * Session Zero Orchestrator
 *
 * Coordinates the 5-phase onboarding for AI player campaigns:
 * 1. Introductions - AI characters introduce themselves
 * 2. Premises - GM describes world, AI players ask questions
 * 3. Character Creation - AI stats proposed, GM approves
 * 4. Party Bonding - IC dialogue between AI characters
 * 5. Establish Secrets - GM assigns secrets to characters
 *
 * All phases run in the main Player Chat UI, with Character Sheet modal
 * overlaying for stat review/approval.
 */
export class SessionZeroOrchestrator {
  /**
   * Start Session Zero - Phase 1: Introductions
   * AI characters introduce themselves with personality
   */
  static async startIntroductions(aiPlayers: CharacterStats[]): Promise<SessionZeroPhaseContent[]> {
    const phases: SessionZeroPhaseContent[] = []

    // System message: Session Zero starting
    phases.push({
      phase: 'introductions',
      type: 'narration',
      content: '🎭 **Session Zero: Introductions**\n\nMeet your party members!',
      nextAction: 'ai_introduce',
      estimatedDuration: '3-5 minutes',
    })

    // Generate introduction for each AI player
    for (const player of aiPlayers) {
      const intro = await this.generateCharacterIntroduction(player)
      phases.push({
        phase: 'introductions',
        type: 'interaction',
        content: intro.introduction,
        nextAction: 'table_talk',
      })

      // Optional: Table talk reaction from other players
      if (Math.random() < 0.6) {
        const reaction = await this.generateTableTalkReaction(
          aiPlayers.filter((p) => p.id !== player.id),
          `${player.name} just introduced themselves as "${player.background}".`,
          4, // moderate intensity
        )
        if (reaction) {
          phases.push({
            phase: 'introductions',
            type: 'interaction',
            content: reaction,
            nextAction: 'continue',
          })
        }
      }
    }

    return phases
  }

  /**
   * Phase 2: Premises
   * GM describes world/setting, AI players ask clarifying questions
   */
  static async startPremises(
    premiseDescription: string,
    aiPlayers: CharacterStats[],
  ): Promise<SessionZeroPhaseContent[]> {
    const phases: SessionZeroPhaseContent[] = []

    // System message
    phases.push({
      phase: 'premises',
      type: 'narration',
      content: `📍 **Session Zero: Campaign Premises**\n\n${premiseDescription}`,
      nextAction: 'ai_questions',
      estimatedDuration: '5-10 minutes',
    })

    // Generate 1-2 questions per AI player
    for (const player of aiPlayers) {
      const questions = await this.generateCharacterQuestions(player, premiseDescription, 2)
      for (const question of questions) {
        phases.push({
          phase: 'premises',
          type: 'interaction',
          content: `💭 ${player.name}: "${question}"`,
          nextAction: 'gm_answer',
        })
      }
    }

    // System message: ready to move on
    phases.push({
      phase: 'premises',
      type: 'narration',
      content: '✓ Questions answered. Ready for Character Creation?',
      nextAction: 'proceed',
    })

    return phases
  }

  /**
   * Phase 3: Character Creation
   * AI proposes character stats, GM approves/edits
   */
  static async startCharacterCreation(
    aiPlayers: CharacterStats[],
  ): Promise<SessionZeroPhaseContent[]> {
    const phases: SessionZeroPhaseContent[] = []

    // System message
    phases.push({
      phase: 'character_creation',
      type: 'narration',
      content:
        '⚔️ **Session Zero: Character Creation**\n\nAI characters will suggest their starting stats.',
      nextAction: 'sheet_modal',
      estimatedDuration: '5-10 minutes',
    })

    // For each AI player, show character sheet modal
    for (const player of aiPlayers) {
      const proposedStats = await this.generateCharacterStats(player)
      phases.push({
        phase: 'character_creation',
        type: 'character_sheet_modal',
        characterToAdjust: player,
        proposedAdjustments: proposedStats,
        nextAction: 'gm_approve',
      })

      // Brief intro message after approval
      phases.push({
        phase: 'character_creation',
        type: 'narration',
        content: `✓ ${player.name} is ready to adventure!`,
        nextAction: 'continue',
      })
    }

    return phases
  }

  /**
   * Phase 4: Party Bonding
   * AI characters interact IC with brief bonding dialogue
   */
  static async startPartyBonding(aiPlayers: CharacterStats[]): Promise<SessionZeroPhaseContent[]> {
    const phases: SessionZeroPhaseContent[] = []

    // System message
    phases.push({
      phase: 'bonding',
      type: 'narration',
      content: '💝 **Session Zero: Party Bonding**\n\nThe party members get to know each other.',
      nextAction: 'ic_dialogue',
      estimatedDuration: '3-5 minutes',
    })

    // Generate 2-3 rounds of IC dialogue
    for (let round = 0; round < 3; round++) {
      const actor = aiPlayers[round % aiPlayers.length]
      const targets = aiPlayers.filter((p) => p.id !== actor.id)

      if (targets.length === 0) continue

      const dialogue = await this.generateBondingDialogue(actor, targets)
      phases.push({
        phase: 'bonding',
        type: 'interaction',
        content: `${actor.name}: "${dialogue}"`,
        nextAction: 'ic_response',
      })

      // Optional table talk reaction
      if (Math.random() < 0.5) {
        const reaction = await this.generateTableTalkReaction(
          targets,
          dialogue,
          5, // higher intensity for bonding
        )
        if (reaction) {
          phases.push({
            phase: 'bonding',
            type: 'interaction',
            content: reaction,
            nextAction: 'continue',
          })
        }
      }
    }

    return phases
  }

  /**
   * Phase 5: Establish Secrets
   * GM assigns secrets to AI characters (which other players know)
   */
  static async startSecrets(aiPlayers: CharacterStats[]): Promise<SessionZeroPhaseContent[]> {
    const phases: SessionZeroPhaseContent[] = []

    // System message
    phases.push({
      phase: 'secrets',
      type: 'narration',
      content:
        '🔐 **Session Zero: Establish Secrets**\n\nEach character has a secret others might uncover.',
      nextAction: 'secret_assignment',
      estimatedDuration: '3-5 minutes',
    })

    // For each character, allow secret assignment
    for (const player of aiPlayers) {
      const suggestedSecrets = await this.generateCharacterSecrets(player, aiPlayers)
      phases.push({
        phase: 'secrets',
        type: 'interaction',
        content: `💭 ${player.name} might have secret: "${suggestedSecrets[0]}"`,
        nextAction: 'gm_decide',
      })
    }

    // Complete
    phases.push({
      phase: 'complete',
      type: 'narration',
      content: '✅ **Session Zero Complete!**\n\nYour party is ready. Campaign begins now.',
      nextAction: 'start_campaign',
    })

    return phases
  }

  // ==================== Private Helper Methods ====================

  /**
   * Generate a character introduction (name, personality, background)
   */
  private static async generateCharacterIntroduction(
    character: CharacterStats,
  ): Promise<AIPlayerIntroduction> {
    const prompt = `Generate a brief, charming introduction for a TTRPG character.

Character: ${character.name}
Background: ${character.background}
Personality: ${character.personality}

Write a 1-2 sentence introduction they would say about themselves, in first person.
Include their role/class and something memorable about them.`

    const introText = await generateText(prompt, {
      model: 'gpt-4o-mini',
      presetId: 'narrative',
      maxTokens: 150,
    })

    return {
      characterId: character.id,
      characterName: character.name,
      introduction: `🎭 **${character.name}**: "${introText}"`,
      personality: character.personality ?? 'Unknown personality',
    }
  }

  /**
   * Generate clarifying questions about the world premise
   */
  private static async generateCharacterQuestions(
    character: CharacterStats,
    premiseDescription: string,
    count: number = 2,
  ): Promise<string[]> {
    const prompt = `As the character ${character.name} (${character.personality}), 
generate ${count} natural, curious questions about this campaign setting:

${premiseDescription}

Questions should be:
- In character (reflect their personality and background)
- Practical (about the world, not game mechanics)
- Open-ended (invite GM response)

Return ONLY the questions, one per line, without numbering.`

    const response = await generateText(prompt, {
      model: 'gpt-4o-mini',
      presetId: 'narrative',
      maxTokens: 200,
    })

    return response
      .split('\n')
      .map((q) => q.trim())
      .filter((q) => q.length > 0)
      .slice(0, count)
  }

  /**
   * Generate proposed character stats for Session Zero
   */
  private static async generateCharacterStats(
    _character: CharacterStats,
  ): Promise<Record<string, string | number>> {
    // Simplified proposal - in real system, would call full character generation
    return {
      healthMax: Math.floor(Math.random() * 8) + 12, // 12-20
      energyMax: Math.floor(Math.random() * 4) + 6, // 6-10
      health: Math.floor(Math.random() * 8) + 12,
      energy: Math.floor(Math.random() * 4) + 6,
    }
  }

  /**
   * Generate bonding dialogue between characters
   */
  private static async generateBondingDialogue(
    actor: CharacterStats,
    targets: CharacterStats[],
  ): Promise<string> {
    const targetNames = targets.map((t) => t.name).join(', ')
    const prompt = `As ${actor.name} (${actor.personality}), 
generate one line of bonding dialogue directed at your companions: ${targetNames}.

Make it:
- In character (reflect personality and background)
- Warm and party-building
- 1 sentence max
- Natural (as if spoken at a table)

Return ONLY the dialogue, no character name or quotation marks.`

    return await generateText(prompt, {
      model: 'gpt-4o-mini',
      presetId: 'narrative',
      maxTokens: 100,
    })
  }

  /**
   * Generate table talk reaction to an event
   */
  private static async generateTableTalkReaction(
    players: CharacterStats[],
    event: string,
    intensity: number,
  ): Promise<string | null> {
    // Determine if reaction happens at this intensity
    const reactionChance = intensity / 8
    if (Math.random() > reactionChance) return null

    const actor = players[Math.floor(Math.random() * players.length)]
    if (!actor) return null

    return await TableTalkOrchestrator.generateReaction({
      storyId: 'session-zero',
      campaignId: 'session-zero',
      aiPlayerId: actor.id,
      character: { name: actor.name },
      recentAction: event,
      otherCharacters: players.map((player) => ({ name: player.name })),
      sceneContext: 'Session Zero bonding',
      tableTalkIntensity: intensity,
    }).then((r) => `💬 ${r.characterName} (OOC): "${r.content}"`)
  }

  /**
   * Generate suggested secrets for character
   */
  private static async generateCharacterSecrets(
    character: CharacterStats,
    otherPlayers: CharacterStats[],
  ): Promise<string[]> {
    const others = otherPlayers
      .filter((p) => p.id !== character.id)
      .map((p) => p.name)
      .join(', ')

    const prompt = `Generate 2-3 interesting character secrets for ${character.name} 
in a TTRPG setting. Secrets should involve:
- A hidden motivation or loyalty
- A connection to other party members: ${others}
- Something that could create interesting dramatic moments

Return ONLY the secrets, one per line, without numbering or quotes.`

    const response = await generateText(prompt, {
      model: 'gpt-4o-mini',
      presetId: 'narrative',
      maxTokens: 200,
    })

    return response
      .split('\n')
      .map((s) => s.trim())
      .filter((s) => s.length > 0)
      .slice(0, 3)
  }
}

/**
 * G.7.1: Table Talk Orchestrator
 *
 * Generates out-of-character banter and reactions from AI players
 * based on the intensity slider (0-8) setting.
 *
 * Intensity levels:
 * 0 = Silent (no OOC reactions)
 * 1-2 = Minimal (occasional brief reactions)
 * 3-4 = Moderate (regular friendly banter)
 * 5-6 = High (active engagement, jokes, strategizing)
 * 7-8 = Very High (constant chatter, memes, roleplay)
 */

import { generatePlainText, generateStructured } from '$lib/services/ai/sdk'
import type { AIPlayerPersonality } from '$lib/types'
import { z } from 'zod'
import { renderStoryPrompt } from '$lib/services/prompts'
import { ContextBuilder } from '$lib/services/context/context-builder'
import { packService } from '$lib/services/packs/pack-service'
import { database } from '$lib/services/database'
import type { Entry } from '$lib/types'

const responderSelectionSchema = z.object({
  responderIds: z.array(z.string()).max(3),
  conversationEnded: z.boolean(),
})

export interface TableTalkParticipant {
  name: string
  playerName?: string
  personality?: AIPlayerPersonality | null
}

export interface TableTalkRequest {
  storyId?: string
  campaignId: string
  aiPlayerId: string
  character: TableTalkParticipant
  recentAction: string
  otherCharacters: TableTalkParticipant[]
  sceneContext: string
  tableTalkIntensity: number // 0-8
  recentTranscript?: string[]
  forceResponse?: boolean
}

export interface TableTalkReaction {
  id: string
  aiPlayerId: string
  characterName: string
  content: string
  sentiment: 'positive' | 'neutral' | 'negative' | 'humorous'
  emoji: string
  intensity: number
}

export interface TableTalkResponderCandidate {
  id: string
  name: string
}

export function selectTableTalkLore(
  entries: Entry[],
  query: string,
  characterName: string,
): Entry[] {
  const normalizedQuery = query.toLowerCase()
  const normalizedCharacterName = characterName.toLowerCase()
  return entries
    .filter((entry) => {
      if (entry.deleted || entry.injection.mode === 'never') return false
      if (entry.injection.mode === 'always') return true
      const terms = [entry.name, ...entry.aliases, ...entry.injection.keywords]
        .map((term) => term.trim().toLowerCase())
        .filter(Boolean)
      return terms.some(
        (term) =>
          normalizedQuery.includes(term) ||
          term.includes(normalizedCharacterName) ||
          normalizedCharacterName.includes(term),
      )
    })
    .sort((left, right) => right.injection.priority - left.injection.priority)
    .slice(0, 12)
}

export class TableTalkOrchestrator {
  private static buildPlayerProfileContext(participant: TableTalkParticipant): string {
    const personality = participant.personality
    if (!personality) return '## Persistent Player Personality\nNo profile details recorded.'
    return [
      '## Persistent Player Personality',
      `Core motivation: ${personality.coreMotivation}`,
      `Playstyle: ${personality.primaryPlaystyle}`,
      `Risk tolerance: ${personality.riskTolerance}/10`,
      `Humor style: ${personality.humorStyle || 'none specified'}`,
      `Decision speed: ${personality.decisionSpeed}`,
      `Combat approach: ${personality.combatApproach || 'not specified'}`,
      `Social priorities: ${(personality.socialPriorities ?? []).join(', ') || 'none recorded'}`,
      `Red lines: ${(personality.redLines ?? []).join(', ') || 'none recorded'}`,
    ].join('\n')
  }

  private static async buildWorldContext(request: TableTalkRequest): Promise<string> {
    const storyId = request.storyId ?? 'session-zero'
    const story = await database.getStory(storyId)
    const entries = story ? await database.getEntriesForBranch(storyId, story.currentBranchId) : []
    const query = [request.recentAction, ...(request.recentTranscript ?? [])].join('\n')
    const relevantEntries = selectTableTalkLore(entries, query, request.character.name)
    return relevantEntries.length
      ? [
          '## Relevant Public World and Lorebook Context',
          ...relevantEntries.map(
            (entry) => `- [${entry.type}] ${entry.name}: ${entry.description}`,
          ),
        ].join('\n')
      : '## Relevant Public World and Lorebook Context\n- No matching public lorebook entries.'
  }

  static async selectResponders(request: {
    storyId: string
    gmMessage: string
    candidates: TableTalkResponderCandidate[]
    recentTranscript?: string[]
    maximumResponders: number
  }): Promise<string[]> {
    if (request.candidates.length === 0 || request.maximumResponders <= 0) return []

    const prompt = await renderStoryPrompt(request.storyId, 'ai-player-table-talk-routing', {
      gmTableMessage: request.gmMessage,
      tableTalkCandidates: request.candidates
        .map((candidate) => `- ${candidate.id}: ${candidate.name}`)
        .join('\n'),
      recentTableTalkTranscript: request.recentTranscript?.join('\n') || '(none)',
      maximumResponders: Math.min(request.maximumResponders, request.candidates.length),
    })
    const result = await generateStructured(
      {
        presetId: 'suggestions',
        schema: responderSelectionSchema,
        system: prompt.system,
        prompt: prompt.user,
      },
      'tableTalkResponderSelection',
    )

    if (result.conversationEnded) return []
    const validIds = new Set(request.candidates.map((candidate) => candidate.id))
    return [...new Set(result.responderIds)]
      .filter((id) => validIds.has(id))
      .slice(0, request.maximumResponders)
  }

  /**
   * Generate a table talk reaction based on intensity and scene
   */
  static async generateReaction(request: TableTalkRequest): Promise<TableTalkReaction> {
    if (request.tableTalkIntensity === 0) {
      return {
        id: crypto.randomUUID(),
        aiPlayerId: request.aiPlayerId,
        characterName: request.character.name,
        content: '',
        sentiment: 'neutral',
        emoji: '',
        intensity: 0,
      }
    }

    const intensityLabel = this.getIntensityLabel(request.tableTalkIntensity)
    const shouldReact =
      request.forceResponse || this.shouldGenerateReaction(request.tableTalkIntensity)

    if (!shouldReact) {
      return {
        id: crypto.randomUUID(),
        aiPlayerId: request.aiPlayerId,
        characterName: request.character.name,
        content: '',
        sentiment: 'neutral',
        emoji: '',
        intensity: request.tableTalkIntensity,
      }
    }

    const storyId = request.storyId ?? 'session-zero'
    const aiPlayerName = request.character.playerName ?? request.character.name
    const decisionContext = await ContextBuilder.forAIPlayer(
      storyId,
      request.aiPlayerId,
      undefined,
      { kind: 'full_table' },
      request.recentTranscript,
    )
    const existingContext = decisionContext.getContext()
    const profileContext =
      typeof existingContext.aiPlayerProfileContext === 'string' &&
      existingContext.aiPlayerProfileContext.trim()
        ? existingContext.aiPlayerProfileContext
        : this.buildPlayerProfileContext(request.character)
    const worldContext = await this.buildWorldContext(request)
    decisionContext.add({
      aiPlayerName,
      aiPlayerCharacterName: request.character.playerName ? request.character.name : '',
      aiPlayerProfileContext: `${profileContext}\n\n${worldContext}`,
    })
    await packService.ensurePromptTemplateComplete(
      decisionContext.getPackId(),
      'ai-player-decision',
    )
    const decisionPrompt = await decisionContext.render('ai-player-decision')
    if (!decisionPrompt.system.trim()) {
      throw new Error('Prompt pack is missing required system content for ai-player-decision')
    }
    const prompt = await renderStoryPrompt(storyId, 'ai-player-table-talk-reaction', {
      aiPlayerDecisionPrompt: decisionPrompt.system,
      tableTalkPlayerName: request.character.playerName ?? request.character.name,
      tableTalkCharacterName: request.character.name,
      tableTalkPlaystyle: request.character.personality?.primaryPlaystyle || 'balanced',
      recentAction: request.recentAction,
      sceneMode: request.sceneContext,
      otherTableParticipants: request.otherCharacters.map((character) => character.name).join(', '),
      recentTableTalkTranscript: request.recentTranscript?.join('\n') || '(none)',
      tableTalkIntensityLabel: intensityLabel,
      tableTalkIntensity: request.tableTalkIntensity,
    })
    const systemPrompt = prompt.system.includes(decisionPrompt.system)
      ? prompt.system
      : `${decisionPrompt.system}\n\n${prompt.system}`

    const content = await generatePlainText(
      {
        presetId: 'agentic',
        system: systemPrompt,
        prompt: prompt.user,
      },
      'tableTalkReaction',
    )

    const sentiment = this.detectSentiment(content)
    const emoji = this.selectEmoji(sentiment, request.tableTalkIntensity)

    return {
      id: crypto.randomUUID(),
      aiPlayerId: request.aiPlayerId,
      characterName: request.character.playerName
        ? `${request.character.playerName} (${request.character.name})`
        : request.character.name,
      content: content.trim(),
      sentiment,
      emoji,
      intensity: request.tableTalkIntensity,
    }
  }

  /**
   * Determine if we should generate a reaction at this intensity level
   * Lower intensities skip some reactions to avoid spam
   */
  private static shouldGenerateReaction(intensity: number): boolean {
    if (intensity === 0) return false
    if (intensity <= 2) return Math.random() < 0.3 // 30% chance
    if (intensity <= 4) return Math.random() < 0.6 // 60% chance
    return true // 100% for 5+
  }

  /**
   * Get human-readable intensity label
   */
  private static getIntensityLabel(intensity: number): string {
    switch (true) {
      case intensity === 0:
        return 'Silent'
      case intensity <= 2:
        return 'Minimal'
      case intensity <= 4:
        return 'Moderate'
      case intensity <= 6:
        return 'High'
      default:
        return 'Very High'
    }
  }

  /**
   * Detect sentiment from generated text
   */
  private static detectSentiment(text: string): 'positive' | 'neutral' | 'negative' | 'humorous' {
    const lower = text.toLowerCase()

    // Check for humor indicators
    if (lower.match(/😂|lol|haha|rofl|💀|dead|that's hilarious/i)) {
      return 'humorous'
    }

    // Check for positive indicators
    if (lower.match(/great|nice|awesome|excellent|love|👍|nice one/i)) {
      return 'positive'
    }

    // Check for negative indicators
    if (lower.match(/oh no|nope|terrible|bad|fail|rip|that sucks/i)) {
      return 'negative'
    }

    return 'neutral'
  }

  /**
   * Select emoji based on sentiment and intensity
   */
  private static selectEmoji(
    sentiment: 'positive' | 'neutral' | 'negative' | 'humorous',
    intensity: number,
  ): string {
    if (intensity === 0) return ''

    switch (sentiment) {
      case 'positive':
        return intensity >= 5 ? '🎉' : '👍'
      case 'negative':
        return intensity >= 5 ? '💀' : '😬'
      case 'humorous':
        return '😂'
      default:
        return intensity >= 5 ? '💬' : ''
    }
  }

  /**
   * Generate table talk reactions for multiple AI players
   */
  static async generateReactionsForTable(
    requests: TableTalkRequest[],
  ): Promise<TableTalkReaction[]> {
    return Promise.all(requests.map((r) => this.generateReaction(r)))
  }

  /**
   * Calculate delay before generating reactions
   * Higher intensity = faster reactions
   */
  static getReactionDelayMs(intensity: number): number {
    switch (true) {
      case intensity === 0:
        return 0 // Never react
      case intensity <= 2:
        return 3000 + Math.random() * 3000 // 3-6 seconds
      case intensity <= 4:
        return 1500 + Math.random() * 2000 // 1.5-3.5 seconds
      case intensity <= 6:
        return 500 + Math.random() * 1500 // 0.5-2 seconds
      default:
        return Math.random() * 1000 // 0-1 second
    }
  }
}

export const tableTalkOrchestrator = new TableTalkOrchestrator()

import { createLogger } from '$lib/log'
import { BaseAIService } from '$lib/services/ai/BaseAIService'
import type { GeneratedCharacter } from '$lib/services/ai/sdk'
import type { Genre } from '$lib/services/ai/wizard'
import { ContextBuilder } from '$lib/services/context'
import { cardImportResultSchema, vaultCharacterImportSchema } from './schemas'
import type { CardImportResult, ParsedCard, SanitizedCharacter } from './types'
import { parseJson } from './parseJson'

const log = createLogger('characterCardImport:aiService')

function normalizeUserMacro(text: string): string {
  if (!text) return ''
  return text.replace(/\{\{user}}/gi, '{{user}}')
}

function buildCardContext(card: ParsedCard): string {
  const sections: string[] = []

  if (card.scenario.trim()) {
    sections.push(`<scenario>\n${normalizeUserMacro(card.scenario)}\n</scenario>`)
  }
  if (card.description.trim()) {
    sections.push(
      `<character_description>\n${normalizeUserMacro(card.description)}\n</character_description>`,
    )
  }
  if (card.personality.trim()) {
    sections.push(`<personality>\n${normalizeUserMacro(card.personality)}\n</personality>`)
  }
  if (card.exampleMessages.trim()) {
    sections.push(
      `<example_messages>\n${normalizeUserMacro(card.exampleMessages)}\n</example_messages>`,
    )
  }

  return sections.join('\n\n')
}

class AIService extends BaseAIService {
  constructor(serviceId: string = 'characterCardImport') {
    super(serviceId)
  }

  async convertCardToScenario(parsedCard: ParsedCard, genre: Genre): Promise<CardImportResult> {
    const cardTitle = parsedCard.name
    const cardContent = buildCardContext(parsedCard)

    const ctx = new ContextBuilder()
    ctx.add({ title: cardTitle, genre, cardContent })
    const { system, user: prompt } = await ctx.render('character-card-import')

    const result = await this.generate(
      cardImportResultSchema,
      system,
      prompt,
      'character-card-import',
      {
        reasoningEffortOverride: 'low',
        reasoningMaxTokensOverride: 512,
      },
    )

    const npcs: GeneratedCharacter[] = result.npcs.map((npc) => ({
      name: npc.name,
      role: npc.role,
      description: npc.description,
      relationship: npc.relationship,
      traits: npc.personality
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean),
    }))

    log('Card import successful', {
      primaryCharacter: result.primaryCharacterName,
      npcCount: npcs.length,
    })

    return {
      success: true,
      settingSeed: result.settingSeed,
      npcs,
      primaryCharacterName: result.primaryCharacterName,
      storyTitle: result.primaryCharacterName || cardTitle,
      firstMessage: normalizeUserMacro(parsedCard.firstMessage),
      alternateGreetings: parsedCard.alternateGreetings.map((g) => normalizeUserMacro(g)),
      errors: [],
    }
  }

  async sanitizeCharacterCard(parsedCard: ParsedCard): Promise<SanitizedCharacter> {
    const cardContent = buildCardContext(parsedCard)

    const ctx = new ContextBuilder()
    ctx.add({ cardContent })
    const { system, user: prompt } = await ctx.render('vault-character-import')

    const result = await this.generate(
      vaultCharacterImportSchema,
      system,
      prompt,
      'vault-character-import',
      {
        reasoningEffortOverride: 'low',
        reasoningMaxTokensOverride: 512,
      },
    )

    log('Character sanitization successful', { name: result.name })

    return {
      name: result.name,
      description: result.description,
      traits: result.traits,
      visualDescriptors: result.visualDescriptors,
    }
  }
}

const aiService = new AIService()

/**
 * Convert a parsed character card into a clean character card using LLM.
 */
export async function clean(
  jsonString: string,
  genre: Genre = 'fantasy',
): Promise<CardImportResult> {
  const card = parseJson(jsonString)
  if (!card) {
    return {
      success: false,
      settingSeed: '',
      npcs: [],
      primaryCharacterName: '',
      storyTitle: '',
      firstMessage: '',
      alternateGreetings: [],
      errors: [
        'Failed to parse character card. Please ensure the file is a valid SillyTavern character card JSON.',
      ],
    }
  }

  log('Parsed card:', { name: card.name, version: card.version })

  return await aiService.convertCardToScenario(card, genre)
}

/**
 * Sanitize a character card using LLM to extract clean character data.
 */
export async function sanitize(jsonString: string): Promise<SanitizedCharacter | null> {
  const card = parseJson(jsonString)
  if (!card) {
    log('Failed to parse card for sanitization')
    return null
  }

  return await aiService.sanitizeCharacterCard(card)
}

/**
 * ContextBuilder
 *
 * Flat variable store + template renderer. Services add variables
 * via .add(), then render templates via .render(). Variables accumulate
 * across services -- all templates can access all variables.
 *
 * External templates (image styles, lorebook tools) don't use ContextBuilder.
 * Services fetch those directly from the pack and inject data programmatically.
 */

import { database } from '$lib/services/database'
import { templateEngine } from '$lib/services/templates/engine'
import { createLogger } from '$lib/log'
import { getContentIntensityLevel } from '$lib/services/content-intensity'
import type { RenderResult } from './types'
import type { Character, InteractionAudience, Item, Location, StoryBeat } from '$lib/types'
import type { RuntimeVariable, RuntimeVarsMap } from '$lib/services/packs/types'
import { TurnDirector } from '$lib/services/campaign/turn-director'
import {
  deriveEffectiveAIPlayerTraits,
  personalityService,
  renderAIPlayerVoiceProfile,
} from '$lib/services/ai-player/personality-service'
import {
  loadRelevantMemories,
  renderMemoriesForPrompt,
} from '$lib/services/ai-player/memory-service'

const log = createLogger('ContextBuilder')

export class ContextBuilder {
  private context: Record<string, any> = {}
  private packId: string = 'default-pack'

  constructor(packId?: string) {
    if (packId) this.packId = packId
  }

  /**
   * Convenience factory: create a ContextBuilder pre-populated from a story.
   * Loads story settings, protagonist, location, time, and pack custom variables.
   */
  static async forStory(storyId: string, packIdOverride?: string): Promise<ContextBuilder> {
    const story = await database.getStory(storyId)
    if (!story) {
      log('forStory: story not found', { storyId })
      return new ContextBuilder()
    }

    const packId = packIdOverride || (await database.getStoryPackId(storyId)) || 'default-pack'
    const builder = new ContextBuilder(packId)

    // Load story data into context
    const moneySystemEnabled = story.settings?.moneySystemEnabled ?? false
    const moneyName = (story.settings?.moneyName ?? 'gold').trim() || 'gold'
    const currentMoney = Math.max(0, Math.floor(story.settings?.moneyAmount ?? 0))

    builder.add({
      mode: story.mode || 'adventure',
      pov: story.settings?.pov || 'second',
      tense: story.settings?.tense || 'present',
      genre: story.genre || '',
      tone: story.settings?.tone || '',
      themes: story.settings?.themes?.join(', ') || '',
      settingDescription: story.description || '',
      visualProseMode: story.settings?.visualProseMode || false,
      inlineImageMode: story.settings?.imageGenerationMode === 'inline',
      moneySystemEnabled,
      moneyName,
      currentMoney,
      moneyState: moneySystemEnabled ? `${currentMoney} ${moneyName}` : '',
    })

    if (story.settings?.imageGenerationMode === 'inline') {
      const template = await database.getPackTemplate(packId, 'narrative-inline-images')
      builder.add({
        inlineImageInstructions: template?.content
          ? (templateEngine.render(template.content, builder.context) ?? '')
          : '',
      })
    }
    if (story.settings?.visualProseMode) {
      const template = await database.getPackTemplate(packId, 'narrative-visual-prose')
      builder.add({
        visualProseInstructions: template?.content
          ? (templateEngine.render(template.content, builder.context) ?? '')
          : '',
      })
    }

    // Protagonist
    const characters = await database.getCharacters(storyId)
    const protagonist = characters.find((c) => c.relationship === 'self')
    builder.add({
      protagonistName: protagonist?.name || 'the protagonist',
      protagonistDescription: protagonist?.description || '',
      activeActorName: protagonist?.name || 'the protagonist',
    })

    // Campaign agency context is additive. Legacy/archive stories have no campaign
    // overlay and retain the existing protagonist-only variables above.
    try {
      const campaign = await database.getCampaignByStoryId(storyId)
      if (campaign) {
        const campaignSettings = await database.getCampaignSettings(campaign.id)
        const sceneTurnState = await database.getSceneTurnState(campaign.id, null)
        const ruleset = campaign.rulesetId ? await database.getRuleset(campaign.rulesetId) : null
        const checkRules = campaign.rulesetId
          ? await database.getRulesetCheckRules(campaign.rulesetId)
          : []
        const recentRollEntries = await database.getRollLedger(campaign.id, { limit: 5 })
        const partyMembers = await database.getCampaignPartyMembers(campaign.id)
        const actorProfiles = await database.getActorControlProfiles(campaign.id)
        const campaignThreads = await database.getCampaignThreads(campaign.id)
        const campaignThreadBeats = await database.getCampaignThreadBeats(campaign.id)
        const sessions = await database.getCampaignSessions(campaign.id)
        const activeSession = sessions.find((session) => session.status === 'active') ?? null
        const sessionParty = activeSession
          ? await database.getSessionPartyMembers(activeSession.id)
          : []
        const characterById = new Map(characters.map((character) => [character.id, character]))
        const profileByCharacterId = new Map(
          actorProfiles.map((profile) => [profile.characterId, profile]),
        )
        const rosterMembers = (activeSession ? sessionParty : partyMembers)
          .map((member) => {
            const character = characterById.get(member.characterId)
            if (!character) return null
            return { member, character }
          })
          .filter((value): value is NonNullable<typeof value> => value !== null)

        const primaryCharacter = activeSession
          ? characterById.get(activeSession.primaryCharacterId)
          : protagonist
        const companions = rosterMembers.filter(
          ({ member }) => member.characterId !== primaryCharacter?.id,
        )
        const companionAgencyContext = companions
          .map(({ member, character }) => {
            const profile = profileByCharacterId.get(character.id)
            const details = [
              profile?.motivations && `motivations: ${profile.motivations}`,
              profile?.priorities && `priorities: ${profile.priorities}`,
              profile?.fears && `fears: ${profile.fears}`,
              profile?.valuePriorities && `values: ${profile.valuePriorities}`,
              profile?.redLines && `red lines: ${profile.redLines}`,
              profile?.tacticalPreferences && `tactics: ${profile.tacticalPreferences}`,
            ].filter(Boolean)
            return `${character.name}: narrative=${member.narrativeControlMode}, combat=${member.combatControlMode}${details.length > 0 ? `; ${details.join('; ')}` : ''}`
          })
          .join('\n')
        const beatsByThreadId = new Map<string, typeof campaignThreadBeats>()
        for (const beat of campaignThreadBeats) {
          const current = beatsByThreadId.get(beat.threadId) ?? []
          current.push(beat)
          beatsByThreadId.set(beat.threadId, current)
        }
        const formatThread = (thread: (typeof campaignThreads)[number]) => {
          const clock =
            thread.clockMax !== null
              ? `, clock ${thread.clockValue}/${thread.clockMax}`
              : thread.clockValue > 0
                ? `, clock ${thread.clockValue}`
                : ''
          const stakes = thread.stakes ? ` Stakes: ${thread.stakes}` : ''
          const summary = thread.summary ? `: ${thread.summary}` : ''
          const beats = (beatsByThreadId.get(thread.id) ?? [])
            .filter((beat) => beat.visibility === thread.visibility)
            .slice(-3)
            .map((beat) => `${beat.title}${beat.summary ? ` (${beat.summary})` : ''}`)
          const beatText = beats.length > 0 ? ` Recent beats: ${beats.join('; ')}.` : ''
          return `- [${thread.threadType}, ${thread.status}${clock}] ${thread.title}${summary}.${stakes}${beatText}`
        }
        const activeCampaignThreads = campaignThreads
          .filter((thread) => thread.status === 'active' || thread.status === 'dormant')
          .filter((thread) => thread.visibility === 'player_safe')
          .map(formatThread)
          .join('\n')
        const activeMember = rosterMembers.find(
          ({ member }) => member.characterId === sceneTurnState?.activeActorId,
        )
        const turnType = new TurnDirector().getNextTurnType({
          sceneMode: (sceneTurnState?.sceneMode ??
            'free') as import('$lib/services/campaign/turn-order-service').SceneMode,
          activeActor: sceneTurnState?.activeActorId
            ? {
                id: sceneTurnState.activeActorId,
                name:
                  characterById.get(sceneTurnState.activeActorId)?.name ??
                  sceneTurnState.activeActorId,
                category:
                  activeMember?.member.actorCategory === 'primary_player_character'
                    ? 'player'
                    : 'ally',
              }
            : null,
        })
        const directorOnlyCampaignThreads = campaignThreads
          .filter((thread) => thread.status === 'active' || thread.status === 'dormant')
          .filter((thread) => thread.visibility === 'director_only')
          .map(formatThread)
          .join('\n')
        const rulesetDigest = ruleset
          ? [
              `Ruleset: ${ruleset.name}`,
              ruleset.diceSystem ? `Dice system: ${ruleset.diceSystem}` : '',
              checkRules.length > 0
                ? `Checks: ${checkRules.map((rule) => `${rule.label} (${rule.notation})`).join(', ')}`
                : '',
            ]
              .filter(Boolean)
              .join('\n')
          : ''
        const recentRolls = recentRollEntries
          .map(
            (roll) =>
              `${roll.notation} = ${roll.total}${roll.dc === null ? '' : ` vs DC ${roll.dc}`} (${roll.outcome ?? 'unresolved'})`,
          )
          .join('\n')

        const nsfwIntensity = campaignSettings?.nsfwIntensity ?? 0
        const nsfwIntensityLabel = getContentIntensityLevel(nsfwIntensity).label

        builder.add({
          campaignTitle: campaign.title,
          contentIntensity: campaignSettings?.nsfwIntensity ?? 0,
          worldCharter: campaignSettings?.worldCharter ?? '',
          gmPersona: campaignSettings?.gmPersona ?? '',
          nsfwIntensity,
          nsfwIntensityLabel,
          rulesetDigest,
          recentRolls,
          pendingRoll: '',
          turnType,
          sceneMode: sceneTurnState?.sceneMode ?? '',
          turnOrderMode: sceneTurnState?.turnOrderMode ?? '',
          activeActorName: sceneTurnState?.activeActorId
            ? (characterById.get(sceneTurnState.activeActorId)?.name ??
              sceneTurnState.activeActorId)
            : '',
          upcomingActors:
            sceneTurnState?.actorOrder
              .filter((actorId) => actorId !== sceneTurnState.activeActorId)
              .slice(0, 4)
              .map((actorId) => characterById.get(actorId)?.name ?? actorId)
              .join(', ') ?? '',
          activeCampaignThreads,
          directorOnlyCampaignThreads,
          campaignSessionNumber: activeSession?.sessionNumber ?? '',
          primaryCharacterName: primaryCharacter?.name || protagonist?.name || '',
          primaryCharacterDescription: primaryCharacter?.description || '',
          partyRoster: rosterMembers
            .map(({ member, character }) => {
              const profile = profileByCharacterId.get(character.id)
              const agency = profile?.motivations ? ` motivations: ${profile.motivations}` : ''
              return `${character.name} (${member.actorCategory}, narrative: ${member.narrativeControlMode}, combat: ${member.combatControlMode})${agency}`
            })
            .join('\n'),
          companionRoster: companions.map(({ character }) => character.name).join(', '),
          companionAgencyContext,
          companionAgency:
            'Active companions retain their own voices, motivations, priorities, and personal decisions. Player requests are not guaranteed commands.',
          combatControlPolicy: activeSession?.combatControlPolicy ?? 'companions_autonomous',
        })
      }
    } catch (error) {
      // Campaign context is optional while older databases finish applying migrations.
      log('Campaign agency context unavailable; using legacy story context', { storyId, error })
    }

    // Current location
    const locations = await database.getLocations(storyId)
    const currentLocation = locations.find((l) => l.current)
    builder.add({ currentLocation: currentLocation?.name || '' })

    // Story time
    if (story.timeTracker) {
      const t = story.timeTracker
      builder.add({
        storyTime: `Year ${t.years + 1}, Day ${t.days + 1}, ${t.hours} hours ${t.minutes} minutes`,
      })
    }

    // Pack custom variable defaults
    await builder.loadCustomVariables()

    // Override pack variable defaults with story-specific values
    const storyVarValues = await database.getStoryCustomVariables(story.id)
    if (storyVarValues) {
      builder.add(storyVarValues)
    }

    // Runtime variable values from entities
    const items = await database.getItems(storyId)
    const storyBeats = await database.getStoryBeats(storyId)
    await builder.loadRuntimeVariableContext(characters, locations, items, storyBeats, protagonist)
    await builder.loadAgencyPromptContext()

    log('forStory complete', {
      storyId,
      packId,
      contextKeys: Object.keys(builder.context).length,
      storyVarOverrides: storyVarValues ? Object.keys(storyVarValues).length : 0,
    })
    return builder
  }

  static async forAIPlayer(
    storyId: string,
    aiPlayerId: string,
    packIdOverride?: string,
    audience: InteractionAudience = { kind: 'full_table' },
    /** Recent chat lines (any actor, in order) the AI Player should treat as already said. */
    recentTranscript?: string[],
  ): Promise<ContextBuilder> {
    const builder = await ContextBuilder.forStory(storyId, packIdOverride)
    const campaign = await database.getCampaignByStoryId(storyId)
    if (!campaign) return builder

    const [player, assignments, relationships, secrets, allPlayers, abilities] = await Promise.all([
      database.getAIPlayer(aiPlayerId),
      database.getPlayerCharactersForCampaign(campaign.id),
      database.getAIPlayerRelationships(aiPlayerId),
      database.getPlayerLevelSecrets(campaign.id, aiPlayerId),
      database.listAIPlayers(),
      campaign.rulesetId ? database.getRulesetAbilities(campaign.rulesetId) : Promise.resolve([]),
    ])
    const assignment = assignments.find((item) => item.aiPlayerId === aiPlayerId)
    if (!player || !assignment) return builder

    const characters = await database.getCharacters(storyId)
    const character = characters.find((item) => item.id === assignment.characterId)
    if (!character) return builder

    const assignedPlayerIds = new Set(assignments.map((item) => item.aiPlayerId))
    const visiblePeerPlayerIds = new Set(
      audience.kind === 'full_table'
        ? assignedPlayerIds
        : audience.kind === 'private_player'
          ? [aiPlayerId]
          : [...audience.aiPlayerIds, aiPlayerId],
    )
    const otherPlayers = allPlayers
      .filter(
        (item) =>
          item.id !== aiPlayerId &&
          assignedPlayerIds.has(item.id) &&
          visiblePeerPlayerIds.has(item.id),
      )
      .map((item) => ({ name: item.name, relationship: 'active campaign player' }))
    const otherPlayerVoiceProfiles = allPlayers
      .filter(
        (item) =>
          item.id !== aiPlayerId &&
          assignedPlayerIds.has(item.id) &&
          visiblePeerPlayerIds.has(item.id),
      )
      .map((item) => renderAIPlayerVoiceProfile(item))

    const memories = await loadRelevantMemories(aiPlayerId, {
      campaignId: campaign.id,
      query: [
        ...(recentTranscript ?? []),
        builder.getContext().narrativeResponse ?? '',
        character.name,
      ].join('\n'),
    })
    const renderedMemories = renderMemoriesForPrompt(memories, campaign.id)

    const sceneText = builder.getContext().narrativeResponse ?? ''
    const dynamicTraits = deriveEffectiveAIPlayerTraits(player, sceneText, recentTranscript ?? [])
    const rendered = personalityService.renderDynamicPrompt(player, assignment, {
      campaignTitle: campaign.title,
      sceneMode: builder.getContext().sceneMode ?? '',
      sceneSummary: sceneText,
      contentIntensity: builder.getContext().nsfwIntensity ?? 0,
      characterName: character.name,
      characterDescription: character.description ?? '',
      characterTraits: character.traits,
      otherPlayers,
      characterSecrets: assignment.characterSecrets,
      playerLevelSecrets: secrets,
      relationships,
      abilities,
      memories: renderedMemories,
    })

    builder.add({
      aiPlayerId,
      aiPlayerName: player.name,
      aiPlayerCharacterName: character.name,
      aiPlayerImmersion: dynamicTraits.immersion,
      aiPlayerArousal: dynamicTraits.arousal,
      aiPlayerVisibleSecrets: rendered.visibleSecrets.join('\n'),
      aiPlayerMemories: renderedMemories || 'No relevant memories recalled.',
      aiPlayerProfileContext: rendered.systemPrompt,
      aiPlayerVoiceProfile: renderAIPlayerVoiceProfile(player),
      otherAIPlayerVoices:
        otherPlayerVoiceProfiles.join('\n\n') || 'No other AI Players are present.',
      priorAIPlayerMessages:
        recentTranscript && recentTranscript.length > 0
          ? recentTranscript.join('\n')
          : 'No earlier AI Player messages were supplied for this turn.',
    })
    const voicePrompt = await builder.render('ai-player-voice')
    if (voicePrompt.system.trim()) {
      builder.add({
        aiPlayerVoicePrompt: voicePrompt.system,
        aiPlayerProfileContext: `${voicePrompt.system}\n\n${rendered.systemPrompt}`,
      })
    }
    const decisionPrompt = await builder.render('ai-player-decision')
    builder.add({
      aiPlayerDecisionPrompt: decisionPrompt.system || rendered.systemPrompt,
      aiPlayerPrompt: decisionPrompt.system || rendered.systemPrompt,
    })
    return builder
  }

  /**
   * Merge variables into context. Returns this for chaining.
   */
  add(data: Record<string, any>): this {
    Object.assign(this.context, data)
    return this
  }

  /**
   * Render a template from the active pack through LiquidJS.
   */
  async render(templateId: string): Promise<RenderResult> {
    log('render', { templateId, packId: this.packId })

    const systemTemplate = await database.getPackTemplate(this.packId, templateId)
    if (!systemTemplate) {
      log('WARNING: system template not found', { templateId, packId: this.packId })
    }
    const userTemplate = await database.getPackTemplate(this.packId, `${templateId}-user`)
    if (!userTemplate) {
      log('WARNING: user template not found', {
        templateId: `${templateId}-user`,
        packId: this.packId,
      })
    }

    const systemResult = systemTemplate?.content
      ? templateEngine.render(systemTemplate.content, this.context)
      : ''
    if (systemResult === null) {
      log('ERROR: system template render failed, using raw content', { templateId })
    }
    const userResult = userTemplate?.content
      ? templateEngine.render(userTemplate.content, this.context)
      : ''
    if (userResult === null) {
      log('ERROR: user template render failed, using raw content', { templateId })
    }

    return {
      system: systemResult ?? systemTemplate?.content ?? '',
      user: userResult ?? userTemplate?.content ?? '',
    }
  }

  /**
   * Get a copy of the current context. Useful for debugging.
   */
  getContext(): Record<string, any> {
    return { ...this.context }
  }

  /**
   * Get the active pack ID.
   */
  getPackId(): string {
    return this.packId
  }

  /**
   * Load custom variable defaults from the active pack.
   * Only sets variables not already in context.
   */
  private async loadCustomVariables(): Promise<void> {
    try {
      const variables = await database.getPackVariables(this.packId)
      for (const v of variables) {
        if (!(v.variableName in this.context)) {
          this.context[v.variableName] = v.defaultValue ?? ''
        }
      }
    } catch (error) {
      log('loadCustomVariables failed', { packId: this.packId, error })
    }
  }

  private async loadAgencyPromptContext(): Promise<void> {
    const templateIds = [
      ['agencyCore', 'agency-core'],
      ['agencyCompanionVoice', 'agency-companion-voice'],
      ['agencyCompanionCombat', 'agency-companion-combat'],
      ['gmCore', 'gm-core'],
      ['turnOrderContext', 'turn-order-context'],
      ['sceneContext', 'scene-context'],
      ['narrativeTurnContext', 'narrative-turn'],
      ['worldCharterContext', 'world-charter-context'],
      ['rulesDigestContext', 'rules-digest-context'],
      ['partyRosterContext', 'party-roster-context'],
      ['narrativePriming', 'narrative-priming'],
      ['safetyCoreRules', 'safety-core-rules'],
      ['safetyGuardrails', 'safety-guardrails'],
      ['safetyContentIntensity', 'safety-content-intensity'],
      ['safetyContentBans', 'safety-content-bans'],
      ['safetyMechanicsConstraints', 'safety-mechanics-constraints'],
      ['agencyContext', 'agency-context'],
    ] as const

    for (const [contextKey, templateId] of templateIds) {
      try {
        const template = await database.getPackTemplate(this.packId, templateId)
        this.context[contextKey] = template?.content
          ? (templateEngine.render(template.content, this.context) ?? '')
          : ''
      } catch (error) {
        this.context[contextKey] = ''
        log('loadAgencyPromptContext failed', { packId: this.packId, templateId, error })
      }
    }
  }

  /**
   * Load runtime variable values from story entities and add formatted text blocks
   * to the context. Each entity type gets a separate variable:
   *   runtimeVars_characters, runtimeVars_locations, runtimeVars_items,
   *   runtimeVars_storyBeats, runtimeVars_protagonist
   *
   * Format per entity: "EntityName: VarLabel = value, VarLabel = value"
   * Empty string when no runtime variables are defined or no values exist.
   */
  private async loadRuntimeVariableContext(
    characters: Character[],
    locations: Location[],
    items: Item[],
    storyBeats: StoryBeat[],
    protagonist: Character | undefined,
  ): Promise<void> {
    try {
      const defs = await database.getRuntimeVariables(this.packId)
      if (defs.length === 0) {
        this.add({
          runtimeVars_characters: '',
          runtimeVars_locations: '',
          runtimeVars_items: '',
          runtimeVars_storyBeats: '',
          runtimeVars_protagonist: '',
        })
        return
      }

      // Group definitions by entity type for fast lookup
      const defsByType: Record<string, RuntimeVariable[]> = {}
      for (const d of defs) {
        if (!defsByType[d.entityType]) defsByType[d.entityType] = []
        defsByType[d.entityType].push(d)
      }

      const formatEntities = (
        entities: Array<{ name: string; metadata: Record<string, unknown> | null }>,
        entityType: string,
      ): string => {
        const typeDefs = defsByType[entityType]
        if (!typeDefs || typeDefs.length === 0) return ''

        const lines: string[] = []
        for (const entity of entities) {
          const runtimeVars = (entity.metadata as Record<string, unknown> | null)?.runtimeVars as
            | RuntimeVarsMap
            | undefined
          if (!runtimeVars) continue

          const pairs: string[] = []
          for (const def of typeDefs) {
            const entry = runtimeVars[def.id]
            if (entry && entry.v != null && entry.v !== '') {
              pairs.push(`${def.displayName} = ${entry.v}`)
            }
          }
          if (pairs.length > 0) {
            lines.push(`${entity.name}: ${pairs.join(', ')}`)
          }
        }
        return lines.join('\n')
      }

      // Format entity name helper for story beats (uses title instead of name)
      const beatsWithName = storyBeats.map((b) => ({
        name: b.title,
        metadata: b.metadata,
      }))

      const runtimeVarsCharacters = formatEntities(characters, 'character')
      const runtimeVarsLocations = formatEntities(locations, 'location')
      const runtimeVarsItems = formatEntities(items, 'item')
      const runtimeVarsStoryBeats = formatEntities(beatsWithName, 'story_beat')

      // Protagonist-specific: filter to just the protagonist
      let runtimeVarsProtagonist = ''
      if (protagonist) {
        runtimeVarsProtagonist = formatEntities([protagonist], 'character')
      }

      this.add({
        runtimeVars_characters: runtimeVarsCharacters,
        runtimeVars_locations: runtimeVarsLocations,
        runtimeVars_items: runtimeVarsItems,
        runtimeVars_storyBeats: runtimeVarsStoryBeats,
        runtimeVars_protagonist: runtimeVarsProtagonist,
      })

      log('loadRuntimeVariableContext', {
        packId: this.packId,
        defCount: defs.length,
        hasCharVars: runtimeVarsCharacters.length > 0,
        hasLocVars: runtimeVarsLocations.length > 0,
        hasItemVars: runtimeVarsItems.length > 0,
        hasBeatVars: runtimeVarsStoryBeats.length > 0,
        hasProtagonistVars: runtimeVarsProtagonist.length > 0,
      })
    } catch (error) {
      log('loadRuntimeVariableContext failed', { packId: this.packId, error })
      this.add({
        runtimeVars_characters: '',
        runtimeVars_locations: '',
        runtimeVars_items: '',
        runtimeVars_storyBeats: '',
        runtimeVars_protagonist: '',
      })
    }
  }
}

/**
 * FandomService - MediaWiki API client for Fandom wikis
 *
 * Uses Tauri's HTTP plugin via corsFetch to bypass CORS restrictions.
 * Provides search and article fetching capabilities for creating lorebook entries.
 * Supports section-by-section reading to avoid fetching entire large articles at once.
 */

import { corsFetch } from '../discovery/utils'

export interface FandomSearchResult {
  title: string
  snippet: string
  pageid: number
  wordcount: number
}

export interface FandomSection {
  index: string
  number: string
  line: string // Section title
  level: string // Heading level (1-6)
}

export interface FandomArticleInfo {
  title: string
  pageid: number
  sections: FandomSection[]
  categories: string[]
}

export interface FandomSectionContent {
  title: string
  sectionTitle: string
  sectionIndex: string
  content: string
}

interface MediaWikiSearchResponse {
  query?: {
    search: Array<{
      title: string
      snippet: string
      pageid: number
      wordcount: number
    }>
  }
  error?: {
    code: string
    info: string
  }
}

interface MediaWikiParseResponse {
  parse?: {
    title: string
    pageid: number
    // Text can be string (formatversion=2) or object with '*' key (formatversion=1)
    text?: string | { '*': string }
    sections: Array<{ line: string; number: string; index: string; level: string }>
    // Categories can be in formatversion=2 or formatversion=1 format
    categories: Array<{ category: string; hidden?: boolean } | { '*': string }>
  }
  error?: {
    code: string
    info: string
  }
}

export class FandomService {
  /**
   * Build the base API URL for a Fandom wiki
   */
  private getApiUrl(wiki: string): string {
    // Normalize wiki name (lowercase, no spaces)
    const normalizedWiki = wiki.toLowerCase().replace(/\s+/g, '')
    return `https://${normalizedWiki}.fandom.com/api.php`
  }

  /**
   * Search for articles on a Fandom wiki
   */
  async search(wiki: string, query: string, limit: number = 10): Promise<FandomSearchResult[]> {
    const apiUrl = this.getApiUrl(wiki)
    const params = new URLSearchParams({
      action: 'query',
      list: 'search',
      srsearch: query,
      srlimit: String(Math.min(limit, 50)), // MediaWiki caps at 50
      format: 'json',
      formatversion: '2',
    })

    const url = `${apiUrl}?${params.toString()}`

    try {
      const response = await corsFetch(url)

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      const data = (await response.json()) as MediaWikiSearchResponse

      if (data.error) {
        throw new Error(`MediaWiki API error: ${data.error.info}`)
      }

      if (!data.query?.search) {
        return []
      }

      return data.query.search.map((item) => ({
        title: item.title,
        snippet: this.stripHtmlTags(item.snippet),
        pageid: item.pageid,
        wordcount: item.wordcount,
      }))
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error'
      throw new Error(`Failed to search ${wiki} wiki: ${message}`)
    }
  }

  /**
   * Get article info including section list (without full content)
   * This is a lightweight call to understand the article structure before fetching sections.
   */
  async getArticleInfo(wiki: string, title: string): Promise<FandomArticleInfo> {
    const apiUrl = this.getApiUrl(wiki)
    const params = new URLSearchParams({
      action: 'parse',
      page: title,
      prop: 'sections|categories',
      format: 'json',
      formatversion: '2',
    })

    const url = `${apiUrl}?${params.toString()}`

    try {
      const response = await corsFetch(url)

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      const data = (await response.json()) as MediaWikiParseResponse

      if (data.error) {
        if (data.error.code === 'missingtitle') {
          throw new Error(`Article "${title}" not found on ${wiki} wiki`)
        }
        throw new Error(`MediaWiki API error: ${data.error.info}`)
      }

      if (!data.parse) {
        throw new Error(`No content returned for "${title}"`)
      }

      return {
        title: data.parse.title,
        pageid: data.parse.pageid,
        sections: data.parse.sections.map((sec) => ({
          index: sec.index,
          number: sec.number,
          line: sec.line,
          level: sec.level,
        })),
        categories: data.parse.categories.map((cat) =>
          'category' in cat ? cat.category : cat['*'],
        ),
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error'
      throw new Error(`Failed to get article info for "${title}" from ${wiki} wiki: ${message}`)
    }
  }

  /**
   * Fetch a specific section of an article by section index.
   * Use section=0 for the lead/intro section (content before first heading).
   */
  async getSection(
    wiki: string,
    title: string,
    sectionIndex: string,
  ): Promise<FandomSectionContent> {
    const apiUrl = this.getApiUrl(wiki)
    const params = new URLSearchParams({
      action: 'parse',
      page: title,
      section: sectionIndex,
      prop: 'text',
      format: 'json',
      formatversion: '2',
    })

    const url = `${apiUrl}?${params.toString()}`

    try {
      const response = await corsFetch(url)

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      const data = (await response.json()) as MediaWikiParseResponse

      if (data.error) {
        if (data.error.code === 'missingtitle') {
          throw new Error(`Article "${title}" not found on ${wiki} wiki`)
        }
        if (data.error.code === 'nosuchsection') {
          throw new Error(`Section ${sectionIndex} not found in article "${title}"`)
        }
        throw new Error(`MediaWiki API error: ${data.error.info}`)
      }

      if (!data.parse) {
        throw new Error(`No content returned for section ${sectionIndex} of "${title}"`)
      }

      // Handle both formatversion=2 (text as string) and formatversion=1 (text as object with '*')
      const parseText = data.parse.text
      let rawHtml: string
      if (typeof parseText === 'string') {
        rawHtml = parseText
      } else if (parseText && typeof parseText === 'object' && '*' in parseText) {
        rawHtml = (parseText as { '*': string })['*']
      } else if (parseText === undefined || parseText === null) {
        throw new Error(
          `No text content returned for section ${sectionIndex}. The section may be empty or the wiki may restrict API access.`,
        )
      } else {
        throw new Error(
          `Unexpected text format in API response for section ${sectionIndex}: ${typeof parseText}`,
        )
      }

      const plainText = this.htmlToPlainText(rawHtml)

      // Extract section title from the content if present
      const sectionTitleMatch = plainText.match(/^##?\s*(.+?)(?:\n|$)/)
      const sectionTitle = sectionTitleMatch
        ? sectionTitleMatch[1].trim()
        : sectionIndex === '0'
          ? 'Introduction'
          : `Section ${sectionIndex}`

      return {
        title: data.parse.title,
        sectionTitle,
        sectionIndex,
        content: plainText,
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to fetch section ${sectionIndex} of "${title}" from ${wiki} wiki: ${message}`,
      )
    }
  }

  /**
   * Fetch the lead section (introduction, section 0) of an article.
   * This is typically a good summary to start with.
   */
  async getLeadSection(wiki: string, title: string): Promise<FandomSectionContent> {
    return this.getSection(wiki, title, '0')
  }

  /**
   * Convert wiki HTML to clean plain text
   * Removes navigation elements, scripts, styles, and converts structure to readable format
   */
  htmlToPlainText(html: string): string {
    // Remove script and style tags with their content
    let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')

    // Remove navigation boxes, infoboxes, and other structural elements
    text = text.replace(
      /<div[^>]*class="[^"]*(?:navbox|infobox|toc|mw-references|reference|reflist|noprint|catlinks|messagebox)[^"]*"[^>]*>[\s\S]*?<\/div>/gi,
      '',
    )
    text = text.replace(
      /<table[^>]*class="[^"]*(?:navbox|infobox|wikitable)[^"]*"[^>]*>[\s\S]*?<\/table>/gi,
      '',
    )
    text = text.replace(/<aside[^>]*>[\s\S]*?<\/aside>/gi, '')

    // Remove figure elements (usually contain images)
    text = text.replace(/<figure[^>]*>[\s\S]*?<\/figure>/gi, '')

    // Remove remaining images and thumbs
    text = text.replace(/<div[^>]*class="[^"]*thumb[^"]*"[^>]*>[\s\S]*?<\/div>/gi, '')
    text = text.replace(/<img[^>]*>/gi, '')

    // Convert headers to markdown-style markers
    text = text.replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n\n# $1\n\n')
    text = text.replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n\n## $1\n\n')
    text = text.replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n\n### $1\n\n')
    text = text.replace(/<h4[^>]*>([\s\S]*?)<\/h4>/gi, '\n\n#### $1\n\n')
    text = text.replace(/<h5[^>]*>([\s\S]*?)<\/h5>/gi, '\n\n##### $1\n\n')
    text = text.replace(/<h6[^>]*>([\s\S]*?)<\/h6>/gi, '\n\n###### $1\n\n')

    // Convert paragraphs and breaks
    text = text.replace(/<\/p>/gi, '\n\n')
    text = text.replace(/<br\s*\/?>/gi, '\n')
    text = text.replace(/<\/div>/gi, '\n')

    // Convert list items
    text = text.replace(/<li[^>]*>/gi, '- ')
    text = text.replace(/<\/li>/gi, '\n')

    // Remove reference markers like [1], [2], etc.
    text = text.replace(/<sup[^>]*class="[^"]*reference[^"]*"[^>]*>[\s\S]*?<\/sup>/gi, '')
    text = text.replace(/\[\d+\]/g, '')

    // Remove edit section links
    text = text.replace(/<span[^>]*class="[^"]*mw-editsection[^"]*"[^>]*>[\s\S]*?<\/span>/gi, '')

    // Strip all remaining HTML tags
    text = text.replace(/<[^>]+>/g, '')

    // Decode HTML entities
    text = this.decodeHtmlEntities(text)

    // Clean up whitespace
    text = text.replace(/\n{3,}/g, '\n\n') // Max 2 consecutive newlines
    text = text.replace(/[ \t]+/g, ' ') // Collapse horizontal whitespace
    text = text.replace(/\n +/g, '\n') // Remove leading spaces on lines
    text = text.replace(/ +\n/g, '\n') // Remove trailing spaces on lines
    text = text.trim()

    return text
  }

  /**
   * Strip HTML tags from a string (simple version for search snippets)
   */
  private stripHtmlTags(html: string): string {
    return html
      .replace(/<[^>]+>/g, '')
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
  }

  /**
   * Decode common HTML entities
   */
  private decodeHtmlEntities(text: string): string {
    const entities: Record<string, string> = {
      '&nbsp;': ' ',
      '&amp;': '&',
      '&lt;': '<',
      '&gt;': '>',
      '&quot;': '"',
      '&#39;': "'",
      '&apos;': "'",
      '&ndash;': '-',
      '&mdash;': '-',
      '&hellip;': '...',
      '&lsquo;': "'",
      '&rsquo;': "'",
      '&ldquo;': '"',
      '&rdquo;': '"',
      '&bull;': '*',
      '&copy;': '(c)',
      '&reg;': '(R)',
      '&trade;': '(TM)',
      '&times;': 'x',
      '&divide;': '/',
      '&frac12;': '1/2',
      '&frac14;': '1/4',
      '&frac34;': '3/4',
    }

    let result = text
    for (const [entity, replacement] of Object.entries(entities)) {
      result = result.replace(new RegExp(entity, 'gi'), replacement)
    }

    // Handle numeric entities
    result = result.replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)))
    result = result.replace(/&#x([0-9a-f]+);/gi, (_, code) =>
      String.fromCharCode(parseInt(code, 16)),
    )

    return result
  }
}

/**
 * ChapterBatchService - Orchestrates batch chapterization of a pre-existing
 * entry history (e.g. after a SillyTavern import). Boundaries are precomputed
 * deterministically by ChapterBatchPlanner.
 *
 * Runs sequentially chapter-by-chapter:
 * 1. For each chapter:
 *    a. Creates the chapter (strictly sequential summary generation).
 *    b. Estimates the timeline duration and assigns the timeline bracket (sequential).
 *    c. Runs classification to update characters/locations/items (sequential).
 * 2. After all chapters are processed, runs a single lore management pass
 *    over the whole batch to update lorebook entries.
 *
 * Running sequentially prevents rate limits, keeps code simple, and ensures
 * each step receives the updated entity and time state from the previous chapter.
 */

import type { Chapter, Entry, StoryEntry, StoryMode, POV, Tense, TimeTracker } from '$lib/types'
import type { ClassificationResult } from '$lib/services/ai/sdk'
import { planChapterBoundaries } from './ChapterBatchPlanner'
import {
  LoreManagementCoordinator,
  type LoreManagementDependencies,
  type LoreManagementCallbacks,
  type LoreManagementUICallbacks,
} from './LoreManagementCoordinator'
import { createLogger } from '$lib/log'

const log = createLogger('ChapterBatchService')

export interface ChapterBatchServiceDependencies {
  buildAndSaveChapter: (startIndex: number, endIndex: number) => Promise<Chapter>
  runLoreManagement: LoreManagementDependencies['runLoreManagement']
  estimateChapterTimeline: (summary: string) => Promise<TimeTracker>
  getTimeTracker: () => TimeTracker
  setTimeTracker: (time: TimeTracker) => Promise<void>
  updateChapterTimes: (
    chapterId: string,
    startTime: TimeTracker,
    endTime: TimeTracker,
  ) => Promise<void>
  getChapterEntries: (chapter: Chapter) => StoryEntry[]
  classifyChapter: (content: string, currentTime: TimeTracker) => Promise<ClassificationResult>
  applyClassificationResult: (result: ClassificationResult) => Promise<void>
}

export interface ChapterBatchInput {
  entries: StoryEntry[]
  startIndex: number
  tokenThreshold: number
  chapterBuffer: number
  includeLorebook: boolean
  includeTimeline: boolean
  includeClassification: boolean
  storyId: string
  currentBranchId: string | null
  lorebookEntries: Entry[]
  mode: StoryMode
  pov: POV
  tense: Tense
}

export interface ChapterBatchCallbacks {
  isCancelled: () => boolean
  onChapterProgress: (current: number, total: number) => void
  onTimelineProgress?: (current: number, total: number) => void
  onClassificationProgress?: (current: number, total: number) => void
  onPhaseMessage?: (message: string) => void
  onChapterProcessed?: (report: ChapterBatchChapterReport) => void
  awaitReviewDecision?: (
    report: ChapterBatchChapterReport,
  ) => Promise<'continue' | 'abort'> | 'continue' | 'abort'
  loreCallbacks: LoreManagementCallbacks
  loreUICallbacks?: LoreManagementUICallbacks
}

export interface ChapterBatchChapterReport {
  chapter: Chapter
  startIndex: number
  endIndex: number
  characters: string[]
  locations: string[]
  items: string[]
  storyBeats: string[]
  errors: string[]
}

export interface ChapterBatchResult {
  chapters: Chapter[]
  cancelled: boolean
}

export class ChapterBatchService {
  private deps: ChapterBatchServiceDependencies

  constructor(deps: ChapterBatchServiceDependencies) {
    this.deps = deps
  }

  async run(
    input: ChapterBatchInput,
    callbacks: ChapterBatchCallbacks,
  ): Promise<ChapterBatchResult> {
    const boundaries = planChapterBoundaries(
      input.entries,
      input.tokenThreshold,
      input.chapterBuffer,
      input.startIndex,
    )

    log('Batch planned', { boundaryCount: boundaries.length, startIndex: input.startIndex })

    const chapters: Chapter[] = []
    let time = this.deps.getTimeTracker()
    const totalChapters = boundaries.length

    callbacks.onChapterProgress(0, totalChapters)

    for (let i = 0; i < boundaries.length; i++) {
      if (callbacks.isCancelled()) {
        log('Batch cancelled during execution', {
          chaptersCreated: chapters.length,
          planned: totalChapters,
        })
        return { chapters, cancelled: true }
      }

      const boundary = boundaries[i]
      callbacks.onPhaseMessage?.(`Starting chapter ${i + 1} of ${totalChapters}`)

      // 1. Generate and save chapter
      callbacks.onPhaseMessage?.(`Summarizing chapter ${i + 1} of ${totalChapters}`)
      let chapter = await this.deps.buildAndSaveChapter(boundary.startIndex, boundary.endIndex)
      chapters.push(chapter)
      const chapterIndex = chapters.length - 1
      callbacks.onChapterProgress(chapters.length, totalChapters)
      callbacks.onPhaseMessage?.(`Chapter ${i + 1} summary complete`)

      let classificationResult: ClassificationResult | null = null

      // 2. Timeline (sequential)
      if (input.includeTimeline) {
        callbacks.onPhaseMessage?.(`Estimating timeline for chapter ${i + 1} of ${totalChapters}`)
        callbacks.onTimelineProgress?.(chapterIndex, totalChapters)
        const delta = await this.deps.estimateChapterTimeline(chapter.summary)
        const startTime = time
        await this.deps.setTimeTracker({
          years: startTime.years + delta.years,
          days: startTime.days + delta.days,
          hours: startTime.hours + delta.hours,
          minutes: startTime.minutes + delta.minutes,
        })
        time = this.deps.getTimeTracker()
        await this.deps.updateChapterTimes(chapter.id, startTime, time)
        chapter = { ...chapter, startTime, endTime: time }
        chapters[chapterIndex] = chapter
        callbacks.onTimelineProgress?.(chapterIndex + 1, totalChapters)
      }

      // 3. Classification (sequential)
      if (input.includeClassification) {
        callbacks.onPhaseMessage?.(`Classifying chapter ${i + 1} of ${totalChapters}`)
        callbacks.onClassificationProgress?.(chapterIndex, totalChapters)
        const rawText = this.deps
          .getChapterEntries(chapter)
          .map((e) => `[${e.type}]: ${e.content}`)
          .join('\n\n')
        const content = `Chapter summary: ${chapter.summary}\n\nFull chapter content:\n${rawText}`
        const currentTime = chapter.endTime ?? this.deps.getTimeTracker()
        const result = await this.deps.classifyChapter(content, currentTime)
        result.scene.timeProgression = 'none'
        await this.deps.applyClassificationResult(result)
        classificationResult = result
        callbacks.onClassificationProgress?.(chapterIndex + 1, totalChapters)
      }

      const report: ChapterBatchChapterReport = {
        chapter,
        startIndex: boundary.startIndex,
        endIndex: boundary.endIndex,
        characters: classificationResult?.entryUpdates.newCharacters.map((c) => c.name) ?? [],
        locations: classificationResult?.entryUpdates.newLocations.map((l) => l.name) ?? [],
        items: classificationResult?.entryUpdates.newItems.map((item) => item.name) ?? [],
        storyBeats:
          classificationResult?.entryUpdates.newStoryBeats.map((beat) => beat.title) ?? [],
        errors: [],
      }

      callbacks.onChapterProcessed?.(report)

      if (callbacks.awaitReviewDecision) {
        callbacks.onPhaseMessage?.(`Review chapter ${i + 1}, then continue or stop`)
        const decision = await callbacks.awaitReviewDecision(report)
        if (decision === 'abort') {
          log('Batch stopped by user review decision', { chaptersCreated: chapters.length })
          return { chapters, cancelled: true }
        }
      }
    }

    if (chapters.length === 0) {
      return { chapters, cancelled: false }
    }

    if (callbacks.isCancelled()) {
      log('Batch cancelled before lore management phase', { chaptersCreated: chapters.length })
      return { chapters, cancelled: true }
    }

    // Phase 4: lore management, a single pass over the whole batch.
    if (input.includeLorebook) {
      callbacks.onPhaseMessage?.('Running lorebook update pass')
      log('Running single lore management pass over batch', { chapterCount: chapters.length })
      const coordinator = new LoreManagementCoordinator({
        runLoreManagement: this.deps.runLoreManagement,
      })
      await coordinator.runSession(
        {
          storyId: input.storyId,
          currentBranchId: input.currentBranchId,
          lorebookEntries: input.lorebookEntries,
          chapters,
          mode: input.mode,
          pov: input.pov,
          tense: input.tense,
        },
        callbacks.loreCallbacks,
        callbacks.loreUICallbacks,
      )
    }

    return { chapters, cancelled: false }
  }
}

/**
 * ChapterService - Handles chapter creation logic extracted from ActionInput.svelte.
 * Coordinates AI analysis and chapter creation without triggering lore management directly.
 */

import type {
  Chapter,
  StoryEntry,
  MemoryConfig,
  TimeTracker,
  StoryMode,
  POV,
  Tense,
} from '$lib/types'
import type { ChapterAnalysis, ChapterSummaryResult } from '$lib/services/ai/sdk/schemas/memory'
import { createLogger } from '$lib/log'

const log = createLogger('ChapterService')

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ChapterAnalysisResult extends ChapterAnalysis {}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ChapterSummaryData extends ChapterSummaryResult {}

export interface ChapterCheckInput {
  storyId: string
  currentBranchId: string | null
  entries: StoryEntry[]
  lastChapterEndIndex: number
  tokensSinceLastChapter: number
  tokensOutsideBuffer: number
  messagesSinceLastChapter: number
  memoryConfig: MemoryConfig
  currentBranchChapters: Chapter[]
  mode: StoryMode
  pov: POV
  tense: Tense
}

export interface ChapterServiceDependencies {
  analyzeForChapter: (
    entries: StoryEntry[],
    lastChapterEndIndex: number,
    config: MemoryConfig,
    tokensOutsideBuffer: number,
    mode?: StoryMode,
    pov?: POV,
    tense?: Tense,
  ) => Promise<ChapterAnalysisResult>

  summarizeChapter: (
    entries: StoryEntry[],
    previousChapters?: Chapter[],
    mode?: StoryMode,
    pov?: POV,
    tense?: Tense,
  ) => Promise<ChapterSummaryData>

  getNextChapterNumber: () => Promise<number>
  addChapter: (chapter: Chapter) => Promise<void>
}

export interface ChapterCreationResult {
  created: boolean
  chapter?: Chapter
  loreManagementTriggered: boolean
}

export class ChapterService {
  private deps: ChapterServiceDependencies

  constructor(deps: ChapterServiceDependencies) {
    this.deps = deps
  }

  async checkAndCreateChapter(input: ChapterCheckInput): Promise<ChapterCreationResult> {
    const { entries, tokensOutsideBuffer, memoryConfig, currentBranchChapters, mode, pov, tense } =
      input

    log('checkAndCreateChapter', {
      tokensSinceLastChapter: input.tokensSinceLastChapter,
      tokensOutsideBuffer,
      tokenThreshold: memoryConfig.tokenThreshold,
      messagesOutsideBuffer: input.messagesSinceLastChapter - memoryConfig.chapterBuffer,
    })

    if (tokensOutsideBuffer === 0) {
      log('No messages outside buffer, skipping')
      return { created: false, loreManagementTriggered: false }
    }

    if (tokensOutsideBuffer < memoryConfig.tokenThreshold) {
      log('Tokens outside buffer below threshold, skipping', {
        tokensOutsideBuffer,
        tokenThreshold: memoryConfig.tokenThreshold,
      })
      return { created: false, loreManagementTriggered: false }
    }

    // Chapter endpoints must stay outside the protected tail buffer.
    const protectedCount = Math.max(0, memoryConfig.chapterBuffer)
    const maxSelectableEndIndex = Math.max(0, entries.length - protectedCount)
    const startIndex = input.lastChapterEndIndex
    const analysisEntries = entries.slice(startIndex, maxSelectableEndIndex)
    if (maxSelectableEndIndex <= startIndex) {
      log('No non-protected entries available for chapter end, skipping', {
        startIndex,
        maxSelectableEndIndex,
        protectedCount,
      })
      return { created: false, loreManagementTriggered: false }
    }

    const analysis = await this.deps.analyzeForChapter(
      analysisEntries,
      input.lastChapterEndIndex,
      memoryConfig,
      tokensOutsideBuffer,
      mode,
      pov,
      tense,
    )

    if (!analysis.shouldCreateChapter) {
      log('No chapter needed yet')
      return { created: false, loreManagementTriggered: false }
    }

    const clampedEndIndex = Math.min(
      Math.max(analysis.optimalEndIndex, startIndex + 1),
      maxSelectableEndIndex,
    )

    if (clampedEndIndex !== analysis.optimalEndIndex) {
      log('Adjusted chapter endpoint to non-protected range', {
        requestedEndIndex: analysis.optimalEndIndex,
        clampedEndIndex,
        startIndex,
        maxSelectableEndIndex,
      })
    }

    log('Creating new chapter', {
      optimalEndIndex: analysis.optimalEndIndex,
      finalEndIndex: clampedEndIndex,
      maxSelectableEndIndex,
    })

    const chapterEntries = entries.slice(startIndex, clampedEndIndex)

    if (chapterEntries.length === 0) {
      log('No entries for chapter')
      return { created: false, loreManagementTriggered: false }
    }

    const previousChapters = [...currentBranchChapters].sort((a, b) => a.number - b.number)
    const summary = await this.deps.summarizeChapter(
      chapterEntries,
      previousChapters,
      mode,
      pov,
      tense,
    )
    const chapterNumber = await this.deps.getNextChapterNumber()

    const firstEntry = chapterEntries[0]
    const lastEntry = chapterEntries[chapterEntries.length - 1]
    const startTime = (firstEntry.metadata?.timeStart as TimeTracker | undefined) ?? null
    const endTime = (lastEntry.metadata?.timeEnd as TimeTracker | undefined) ?? null

    const chapter: Chapter = {
      id: crypto.randomUUID(),
      storyId: input.storyId,
      number: chapterNumber,
      title: analysis.suggestedTitle ?? summary.title ?? null,
      startEntryId: chapterEntries[0].id,
      endEntryId: chapterEntries[chapterEntries.length - 1].id,
      entryCount: chapterEntries.length,
      summary: summary.summary,
      startTime,
      endTime,
      keywords: summary.keywords,
      characters: summary.characters,
      locations: summary.locations,
      plotThreads: summary.plotThreads,
      emotionalTone: summary.emotionalTone ?? null,
      branchId: input.currentBranchId,
      createdAt: Date.now(),
    }

    await this.deps.addChapter(chapter)
    log('Chapter created', { number: chapterNumber, title: chapter.title })

    return { created: true, chapter, loreManagementTriggered: true }
  }
}

/**
 * GenerationPipeline - Orchestrates narrative generation phases
 * Order: pre → retrieval → narrative → [(classification ‖ translation → image) ‖ background ‖ post]
 */

import { createLogger } from '$lib/log'

const log = createLogger('GenerationPipeline')

import type { GenerationEvent, GenerationContext, ErrorEvent, RetrievalResult } from './types'
import type {
  EmbeddedImage,
  ActionInputType,
  TranslationSettings,
  Character,
  StoryBeat,
} from '$lib/types'
import type { StoryMode, POV, Tense } from '$lib/types'
import type { StyleReviewResult } from '$lib/services/ai/generation/StyleReviewerService'
import type { ActivationTracker } from '$lib/services/ai/retrieval/EntryRetrievalService'
import {
  PreGenerationPhase,
  RetrievalPhase,
  NarrativePhase,
  ClassificationPhase,
  TranslationPhase,
  ImagePhase,
  PostGenerationPhase,
  MechanicsPhase,
  type RetrievalDependencies,
  type NarrativeDependencies,
  type ClassificationDependencies,
  type TranslationDependencies,
  type ImageDependencies,
  type PostGenerationDependencies,
  type PreGenerationResult,
  type NarrativeResult,
  type ClassificationPhaseResult,
  type TranslationResult2,
  type ImageResult,
  type PostGenerationResult,
  type MechanicsPhaseResult,
  type PromptContext,
  type ImageSettings,
} from './phases'
import {
  BackgroundImagePhase,
  type BackgroundImageDependencies,
  type BackgroundImageResult,
  type BackgroundImageSettings,
} from './phases/BackgroundImagePhase'
import { mergeGenerators } from '$lib/utils/async'
import { stripInlineControlTags } from '$lib/utils/inlineControlParser'

export interface PipelineDependencies
  extends
    RetrievalDependencies,
    NarrativeDependencies,
    BackgroundImageDependencies,
    ClassificationDependencies,
    TranslationDependencies,
    ImageDependencies,
    PostGenerationDependencies {}

export interface PipelineConfig {
  embeddedImages: EmbeddedImage[]
  rawInput: string
  actionType: ActionInputType
  wasRawActionChoice: boolean
  timelineFillEnabled: boolean
  storyMode: StoryMode
  pov: POV
  tense: Tense
  styleReview: StyleReviewResult | null
  activationTracker?: ActivationTracker
  translationSettings: TranslationSettings
  imageSettings: ImageSettings & BackgroundImageSettings
  promptContext: PromptContext
  disableSuggestions: boolean
  activeThreads: StoryBeat[]
  cachedRetrievalResult?: RetrievalResult | null
}

export interface PipelineResult {
  preGeneration: PreGenerationResult | null
  narrative: NarrativeResult | null
  background: BackgroundImageResult | null
  classification: ClassificationPhaseResult | null
  translation: TranslationResult2 | null
  image: ImageResult | null
  postGeneration: PostGenerationResult | null
  mechanics: MechanicsPhaseResult | null
  aborted: boolean
  fatalError: Error | null
}

export class GenerationPipeline {
  private prePhase = new PreGenerationPhase()
  private retrievalPhase = new RetrievalPhase()
  private narrativePhase: NarrativePhase
  private backgroundPhase: BackgroundImagePhase
  private classificationPhase: ClassificationPhase
  private translationPhase: TranslationPhase
  private imagePhase: ImagePhase
  private postPhase: PostGenerationPhase
  private mechanicsPhase = new MechanicsPhase()

  constructor(private deps: PipelineDependencies) {
    this.narrativePhase = new NarrativePhase(deps)
    this.backgroundPhase = new BackgroundImagePhase(deps)
    this.classificationPhase = new ClassificationPhase(deps)
    this.translationPhase = new TranslationPhase(deps)
    this.imagePhase = new ImagePhase(deps)
    this.postPhase = new PostGenerationPhase(deps)
  }

  async *execute(
    ctx: GenerationContext,
    cfg: PipelineConfig,
  ): AsyncGenerator<GenerationEvent, PipelineResult> {
    const r: PipelineResult = {
      preGeneration: null,
      narrative: null,
      background: null,
      classification: null,
      translation: null,
      image: null,
      postGeneration: null,
      mechanics: null,
      aborted: false,
      fatalError: null,
    }

    try {
      r.preGeneration = yield* this.prePhase.execute({
        context: ctx,
        embeddedImages: cfg.embeddedImages,
        rawInput: cfg.rawInput,
        actionType: cfg.actionType,
        wasRawActionChoice: cfg.wasRawActionChoice,
      })
      if (ctx.abortSignal?.aborted) return { ...r, aborted: true }

      let retrieval: RetrievalResult
      if (cfg.cachedRetrievalResult) {
        log('Using cached retrieval result (regenerate)')
        yield { type: 'phase_start', phase: 'retrieval' } as GenerationEvent
        retrieval = cfg.cachedRetrievalResult
        yield { type: 'phase_complete', phase: 'retrieval', result: retrieval } as GenerationEvent
      } else {
        retrieval = yield* this.retrievalPhase.execute({
          context: ctx,
          dependencies: this.deps,
          timelineFillEnabled: cfg.timelineFillEnabled,
          activationTracker: cfg.activationTracker,
          storyMode: cfg.storyMode,
          pov: cfg.pov,
          tense: cfg.tense,
        })
      }
      if (ctx.abortSignal?.aborted) return { ...r, aborted: true }

      r.narrative = yield* this.narrativePhase.execute({
        visibleEntries: ctx.visibleEntries,
        worldState: ctx.worldState,
        story: ctx.story,
        retrievalResult: retrieval,
        styleReview: cfg.styleReview,
        abortSignal: ctx.abortSignal,
      })
      if (!r.narrative || ctx.abortSignal?.aborted) return { ...r, aborted: true }
      // Control tags are executable metadata, not narrative prose. Remove them
      // before classification, translation, image, and suggestion phases consume
      // the narrative result. ActionInput executes the parsed tags once at the UI boundary.
      r.narrative = { ...r.narrative, content: stripInlineControlTags(r.narrative.content) }

      // All post-narrative phases run in parallel. Image needs classification
      // + translation results, so it chains after them via imagePipeline.
      // Background and postGeneration are fully independent.
      const allPhases = yield* mergeGenerators({
        // [Classification ‖ Translation] → Image (sequential dependency)
        imagePipeline: this.runImagePipeline(
          ctx,
          cfg,
          r.narrative!.content,
          r.preGeneration?.visualProseMode ?? false,
        ),
        // Independent phases
        background: this.backgroundPhase.execute({
          storyId: ctx.story.id,
          storyEntries: ctx.visibleEntries,
          imageSettings: cfg.imageSettings,
          abortSignal: ctx.abortSignal,
        }),
        postGeneration: this.postPhase.execute({
          disableSuggestions: cfg.disableSuggestions,
          entries: ctx.visibleEntries,
          activeThreads: cfg.activeThreads,
          lorebookEntries: ctx.worldState.lorebookEntries,
          promptContext: cfg.promptContext,
          worldState: ctx.worldState,
          narrativeResponse: r.narrative.content,
          pov: cfg.pov,
          translationSettings: cfg.translationSettings,
          abortSignal: ctx.abortSignal,
        }),
        mechanics: this.mechanicsPhase.execute({
          narrativeContent: r.narrative.content,
          worldState: ctx.worldState,
          story: ctx.story,
          campaignId: ctx.story.id,
          abortSignal: ctx.abortSignal,
        }),
      })

      r.classification = allPhases.imagePipeline.classification
      r.translation = allPhases.imagePipeline.translation
      r.image = allPhases.imagePipeline.image
      r.background = allPhases.background
      r.postGeneration = allPhases.postGeneration
      r.mechanics = allPhases.mechanics
      if (ctx.abortSignal?.aborted) return { ...r, aborted: true }

      return r
    } catch (error) {
      r.fatalError = error instanceof Error ? error : new Error(String(error))
      yield { type: 'error', phase: 'pre', error: r.fatalError, fatal: true } satisfies ErrorEvent
      return r
    }
  }

  /**
   * Runs classification and translation in parallel, then image once both complete.
   * This way image starts as soon as its dependencies are ready, without waiting
   * for unrelated phases like postGeneration or background.
   */
  private async *runImagePipeline(
    ctx: GenerationContext,
    cfg: PipelineConfig,
    narrativeContent: string,
    isVisualProse: boolean,
  ): AsyncGenerator<
    GenerationEvent,
    {
      classification: ClassificationPhaseResult | null
      translation: TranslationResult2
      image: ImageResult
    }
  > {
    const imageDeps = yield* mergeGenerators({
      classification: this.classificationPhase.execute({
        narrativeContent,
        narrativeEntryId: ctx.userAction.entryId,
        userActionContent: ctx.userAction.content,
        worldState: ctx.worldState,
        story: ctx.story,
        visibleEntries: ctx.visibleEntries,
        abortSignal: ctx.abortSignal,
      }),
      translation: this.translationPhase.execute({
        narrativeContent,
        narrativeEntryId: ctx.userAction.entryId,
        isVisualProse,
        translationSettings: cfg.translationSettings,
        abortSignal: ctx.abortSignal,
      }),
    })

    if (ctx.abortSignal?.aborted) {
      return {
        classification: imageDeps.classification,
        translation: imageDeps.translation,
        image: { started: false, skippedReason: 'aborted' },
      }
    }

    const imageInput = this.buildImageInput(
      ctx,
      cfg,
      narrativeContent,
      imageDeps.classification,
      imageDeps.translation,
    )
    const image = yield* this.imagePhase.execute(imageInput)

    return {
      classification: imageDeps.classification,
      translation: imageDeps.translation,
      image,
    }
  }

  private buildImageInput(
    ctx: GenerationContext,
    cfg: PipelineConfig,
    narrativeContent: string,
    classification: ClassificationPhaseResult | null,
    translation: TranslationResult2,
  ) {
    const names = classification?.classificationResult?.scene?.presentCharacterNames ?? []
    const presentCharacters: Character[] = ctx.worldState.characters.filter((c) =>
      names.includes(c.name),
    )
    return {
      storyId: ctx.story.id,
      entryId: ctx.narrationEntryId || ctx.userAction.entryId,
      narrativeContent,
      userAction: ctx.userAction.content,
      presentCharacters,
      currentLocation: ctx.worldState.currentLocation?.name,
      translatedNarrative: translation?.translatedContent ?? undefined,
      translationLanguage: translation?.targetLanguage ?? undefined,
      imageSettings: cfg.imageSettings,
      abortSignal: ctx.abortSignal,
    }
  }
}

/**
 * StyleReviewScheduler - Handles style review scheduling logic extracted from ActionInput.svelte.
 * Manages counter state via callbacks and triggers review when threshold is met.
 */

import type { StoryEntry, StoryMode, POV, Tense } from '$lib/types'
import type { StyleReviewResult } from '$lib/services/ai/generation/StyleReviewerService'
import { createLogger } from '$lib/log'

const log = createLogger('StyleReviewScheduler')

export interface StyleReviewCheckInput {
  storyId: string
  entries: StoryEntry[]
  mode: StoryMode
  pov: POV
  tense: Tense
  enabled: boolean
  triggerInterval: number
  currentCounter: number
  shouldIncrement: boolean
  source: string
}

export interface StyleReviewDependencies {
  analyzeStyle: (
    entries: StoryEntry[],
    mode: StoryMode,
    pov: POV,
    tense: Tense,
  ) => Promise<StyleReviewResult>
}

export interface StyleReviewUICallbacks {
  incrementCounter: () => void
  setLoading: (loading: boolean, storyId: string) => void
  setResult: (result: StyleReviewResult, storyId: string) => void
}

export interface StyleReviewCheckResult {
  triggered: boolean
  result?: StyleReviewResult
}

export class StyleReviewScheduler {
  private deps: StyleReviewDependencies

  constructor(deps: StyleReviewDependencies) {
    this.deps = deps
  }

  /**
   * Check if style review should be triggered and run it if threshold met.
   */
  async checkAndTrigger(
    input: StyleReviewCheckInput,
    uiCallbacks?: StyleReviewUICallbacks,
  ): Promise<StyleReviewCheckResult> {
    const {
      storyId,
      entries,
      mode,
      pov,
      tense,
      enabled,
      triggerInterval,
      currentCounter,
      shouldIncrement,
      source,
    } = input

    if (!enabled || !storyId) return { triggered: false }

    // Increment counter for new messages if requested
    let effectiveCounter = currentCounter
    if (shouldIncrement) {
      effectiveCounter = currentCounter + 1
      uiCallbacks?.incrementCounter()
    }

    log('Style review counter', {
      source,
      storyId,
      counter: effectiveCounter,
      triggerInterval,
      incremented: shouldIncrement,
    })

    if (effectiveCounter < triggerInterval) return { triggered: false }

    log('Triggering style review...')
    uiCallbacks?.setLoading(true, storyId)

    try {
      const result = await this.deps.analyzeStyle(entries, mode, pov, tense)
      uiCallbacks?.setResult(result, storyId)
      log('Style review complete', { phrasesFound: result.phrases.length })
      return { triggered: true, result }
    } catch (error) {
      log('Style review failed (non-fatal)', error)
      return { triggered: false }
    } finally {
      uiCallbacks?.setLoading(false, storyId)
    }
  }
}

/**
 * WorldStateTranslationService - Handles translation of world state entities.
 * Extracts from ActionInput.svelte translateWorldStateElements() logic.
 */

import type { Character, Location, Item, StoryBeat } from '$lib/types'
import type { UITranslationItem } from '$lib/services/ai/utils/TranslationService'
import { hasDescriptors, descriptorsToString } from '$lib/utils/visualDescriptors'
import { createLogger } from '$lib/log'

const log = createLogger('WorldStateTranslationService')

/** New entities from classification result. */
export interface ClassificationNewEntities {
  newCharacters: Array<{
    name: string
    description?: string
    relationship?: string
    traits?: string[]
    visualDescriptors?: Record<string, string>
  }>
  newLocations: Array<{ name: string; description?: string }>
  newItems: Array<{ name: string; description?: string }>
  newStoryBeats: Array<{ title: string; description?: string }>
}

/** Current world state entities for matching. */
export interface WorldStateEntities {
  characters: Character[]
  locations: Location[]
  items: Item[]
  storyBeats: StoryBeat[]
}

/** Callbacks for persisting translations. */
export interface WorldStateTranslationCallbacks {
  updateCharacter: (id: string, data: Record<string, string | string[] | null>) => Promise<void>
  updateLocation: (id: string, data: Record<string, string | null>) => Promise<void>
  updateItem: (id: string, data: Record<string, string | null>) => Promise<void>
  updateStoryBeat: (id: string, data: Record<string, string | null>) => Promise<void>
  refreshWorldState: () => Promise<void>
}

export interface WorldStateTranslationDependencies {
  translateUIElements: (
    items: UITranslationItem[],
    targetLanguage: string,
  ) => Promise<UITranslationItem[]>
}

export interface WorldStateTranslationInput {
  classificationResult: ClassificationNewEntities
  worldState: WorldStateEntities
  targetLanguage: string
}

export interface WorldStateTranslationResult {
  translatedCount: number
}

type EntityType = 'character' | 'location' | 'item' | 'storyBeat'

interface TranslationItem extends UITranslationItem {
  entityType: EntityType
  field: string
  isArray?: boolean
}

export class WorldStateTranslationService {
  constructor(private deps: WorldStateTranslationDependencies) {}

  async translateEntities(
    input: WorldStateTranslationInput,
    callbacks: WorldStateTranslationCallbacks,
  ): Promise<WorldStateTranslationResult> {
    const { classificationResult, worldState, targetLanguage } = input
    const items: TranslationItem[] = []

    // Collect character fields
    for (const char of classificationResult.newCharacters) {
      const db = worldState.characters.find((c) => c.name === char.name)
      if (!db) continue
      items.push({
        id: `${db.id}:name`,
        text: char.name,
        type: 'name',
        entityType: 'character',
        field: 'translatedName',
      })
      if (char.description)
        items.push({
          id: `${db.id}:desc`,
          text: char.description,
          type: 'description',
          entityType: 'character',
          field: 'translatedDescription',
        })
      if (char.relationship)
        items.push({
          id: `${db.id}:rel`,
          text: char.relationship,
          type: 'description',
          entityType: 'character',
          field: 'translatedRelationship',
        })
      if (char.traits?.length)
        items.push({
          id: `${db.id}:traits`,
          text: char.traits.join(', '),
          type: 'description',
          entityType: 'character',
          field: 'translatedTraits',
          isArray: true,
        })
      if (hasDescriptors(char.visualDescriptors))
        items.push({
          id: `${db.id}:visual`,
          text: descriptorsToString(char.visualDescriptors),
          type: 'description',
          entityType: 'character',
          field: 'translatedVisualDescriptors',
        })
    }

    // Collect location fields
    for (const loc of classificationResult.newLocations) {
      const db = worldState.locations.find((l) => l.name === loc.name)
      if (!db) continue
      items.push({
        id: `${db.id}:name`,
        text: loc.name,
        type: 'name',
        entityType: 'location',
        field: 'translatedName',
      })
      if (loc.description)
        items.push({
          id: `${db.id}:desc`,
          text: loc.description,
          type: 'description',
          entityType: 'location',
          field: 'translatedDescription',
        })
    }

    // Collect item fields
    for (const item of classificationResult.newItems) {
      const db = worldState.items.find((i) => i.name === item.name)
      if (!db) continue
      items.push({
        id: `${db.id}:name`,
        text: item.name,
        type: 'name',
        entityType: 'item',
        field: 'translatedName',
      })
      if (item.description)
        items.push({
          id: `${db.id}:desc`,
          text: item.description,
          type: 'description',
          entityType: 'item',
          field: 'translatedDescription',
        })
    }

    // Collect story beat fields
    for (const beat of classificationResult.newStoryBeats) {
      const db = worldState.storyBeats.find((b) => b.title === beat.title)
      if (!db) continue
      items.push({
        id: `${db.id}:title`,
        text: beat.title,
        type: 'title',
        entityType: 'storyBeat',
        field: 'translatedTitle',
      })
      if (beat.description)
        items.push({
          id: `${db.id}:desc`,
          text: beat.description,
          type: 'description',
          entityType: 'storyBeat',
          field: 'translatedDescription',
        })
    }

    if (items.length === 0) return { translatedCount: 0 }

    log('Translating world state elements', { count: items.length, targetLanguage })
    const translated = await this.deps.translateUIElements(
      items.map(({ id, text, type }) => ({ id, text, type })),
      targetLanguage,
    )

    // Apply translations
    for (const t of translated) {
      const [entityId] = t.id.split(':')
      const orig = items.find((i) => i.id === t.id)
      if (!orig) continue

      const value = orig.isArray
        ? t.text
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean)
        : t.text
      const data: Record<string, string | string[] | null> = {
        [orig.field]: value,
        translationLanguage: targetLanguage,
      }

      if (orig.entityType === 'character') await callbacks.updateCharacter(entityId, data)
      else if (orig.entityType === 'location')
        await callbacks.updateLocation(entityId, data as Record<string, string | null>)
      else if (orig.entityType === 'item')
        await callbacks.updateItem(entityId, data as Record<string, string | null>)
      else if (orig.entityType === 'storyBeat')
        await callbacks.updateStoryBeat(entityId, data as Record<string, string | null>)
    }

    await callbacks.refreshWorldState()
    log('World state elements translated', { count: translated.length })
    return { translatedCount: translated.length }
  }
}

/**
 * ClassificationPhase - Handles world state extraction from narrative
 *
 * Responsibilities:
 * - Call classifier service to extract world state changes
 * - Coordinate entity updates (characters, locations, items, story beats)
 * - Yield classification events
 */

import type {
  GenerationEvent,
  PhaseStartEvent,
  PhaseCompleteEvent,
  AbortedEvent,
  ErrorEvent,
  ClassificationCompleteEvent,
  WorldState,
} from '../types'
import type { Story, StoryEntry, TimeTracker } from '$lib/types'
import type { ClassificationResult } from '$lib/services/ai/sdk/schemas/classifier'

/** Dependencies for classification phase - injected to avoid tight coupling */
export interface ClassificationDependencies {
  classifyResponse: (
    narrativeResponse: string,
    userAction: string,
    worldState: WorldState,
    story: Story | null | undefined,
    chatHistoryEntries: StoryEntry[],
    timeTracker: TimeTracker | null | undefined,
  ) => Promise<ClassificationResult>
}

/** Input for the classification phase */
export interface ClassificationInput {
  narrativeContent: string
  narrativeEntryId: string
  userActionContent: string
  worldState: WorldState
  story: Story | null | undefined
  visibleEntries: StoryEntry[]
  abortSignal?: AbortSignal
}

/** Result from classification phase */
export interface ClassificationPhaseResult {
  classificationResult: ClassificationResult
  narrativeEntryId: string
}

/**
 * ClassificationPhase service
 * Extracts world state changes from narrative using AI classifier.
 */
export class ClassificationPhase {
  constructor(private deps: ClassificationDependencies) {}

  /** Execute the classification phase - yields events and returns result */
  async *execute(
    input: ClassificationInput,
  ): AsyncGenerator<GenerationEvent, ClassificationPhaseResult | null> {
    yield { type: 'phase_start', phase: 'classification' } satisfies PhaseStartEvent

    const {
      narrativeContent,
      narrativeEntryId,
      userActionContent,
      worldState,
      story,
      visibleEntries,
      abortSignal,
    } = input

    if (abortSignal?.aborted) {
      yield { type: 'aborted', phase: 'classification' } satisfies AbortedEvent
      return null
    }

    try {
      // Filter out the current narration entry to avoid sending it twice
      // (once in chatHistory, once as narrativeResponse)
      const chatHistoryEntries = visibleEntries.filter((e) => e.id !== narrativeEntryId)

      const classificationResult = await this.deps.classifyResponse(
        narrativeContent,
        userActionContent,
        worldState,
        story,
        chatHistoryEntries,
        story?.timeTracker,
      )

      if (abortSignal?.aborted) {
        yield { type: 'aborted', phase: 'classification' } satisfies AbortedEvent
        return null
      }

      // Emit classification complete event
      yield {
        type: 'classification_complete',
        result: classificationResult,
      } satisfies ClassificationCompleteEvent

      const result: ClassificationPhaseResult = {
        classificationResult,
        narrativeEntryId,
      }

      yield {
        type: 'phase_complete',
        phase: 'classification',
        result,
      } satisfies PhaseCompleteEvent

      return result
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        yield { type: 'aborted', phase: 'classification' } satisfies AbortedEvent
        return null
      }

      // Classification errors are non-fatal - world state just won't be updated
      yield {
        type: 'error',
        phase: 'classification',
        error: error instanceof Error ? error : new Error(String(error)),
        fatal: false,
      } satisfies ErrorEvent

      return null
    }
  }
}

/**
 * MechanicsPhase (Phase 8, tasks 8.3 & 8.4)
 *
 * Parallel/post-narrative mechanics execution phase. Executes mechanics tools,
 * validates resource floors, party size, owner integrity, and content safety guardrails.
 */

import type {
  GenerationEvent,
  PhaseStartEvent,
  PhaseCompleteEvent,
  AbortedEvent,
  ErrorEvent,
  WorldState,
} from '../types'
import type { Story } from '$lib/types'
import { createMechanicsTools } from '$lib/services/ai/sdk/tools/mechanics'

export interface MechanicsInput {
  narrativeContent: string
  worldState: WorldState
  story: Story | null | undefined
  campaignId?: string
  abortSignal?: AbortSignal
}

export interface MechanicsPhaseResult {
  executed: boolean
  summary: string | null
}

export class MechanicsPhase {
  async *execute(input: MechanicsInput): AsyncGenerator<GenerationEvent, MechanicsPhaseResult> {
    yield { type: 'phase_start', phase: 'mechanics' } satisfies PhaseStartEvent

    const { story, campaignId, abortSignal } = input

    if (abortSignal?.aborted) {
      yield { type: 'aborted', phase: 'mechanics' } satisfies AbortedEvent
      return { executed: false, summary: null }
    }

    try {
      const tools = createMechanicsTools(campaignId, story?.id)
      const summary = `Mechanics tools initialized for campaign "${campaignId ?? story?.id ?? 'active'}" with ${Object.keys(tools).length} tools.`

      yield {
        type: 'phase_complete',
        phase: 'mechanics',
        result: { executed: true, summary },
      } satisfies PhaseCompleteEvent

      return { executed: true, summary }
    } catch (error) {
      yield {
        type: 'error',
        phase: 'mechanics',
        error: error instanceof Error ? error : new Error(String(error)),
        fatal: false,
      } satisfies ErrorEvent

      return { executed: false, summary: null }
    }
  }
}

/**
 * NarrativePhase - Handles streaming narrative generation
 *
 * Responsibilities:
 * - Coordinate streaming narrative generation via AIService
 * - Yield narrative chunks as they arrive
 * - Handle abort signals properly
 * - Retry on empty responses (up to 3 attempts)
 */

import type {
  GenerationEvent,
  PhaseStartEvent,
  PhaseCompleteEvent,
  NarrativeChunkEvent,
  AbortedEvent,
  ErrorEvent,
  WorldState,
  RetrievalResult,
} from '../types'
import type { Story, StoryEntry } from '$lib/types'
import type { StyleReviewResult } from '$lib/services/ai/generation/StyleReviewerService'
import type { StreamChunk } from '$lib/services/ai/core/types'

const MAX_EMPTY_RESPONSE_RETRIES = 3

/** Dependencies for narrative phase - injected to avoid tight coupling */
export interface NarrativeDependencies {
  streamNarrative: (
    entries: StoryEntry[],
    worldState: WorldState,
    story: Story | null | undefined,
    useTieredContext: boolean,
    styleReview: StyleReviewResult | null | undefined,
    retrievedContext: string | null | undefined,
    signal: AbortSignal | undefined,
    timelineFillResult: RetrievalResult['timelineFillResult'],
  ) => AsyncIterable<StreamChunk>
}

/** Input for the narrative phase */
export interface NarrativeInput {
  visibleEntries: StoryEntry[]
  worldState: WorldState
  story: Story | null | undefined
  retrievalResult: RetrievalResult
  styleReview: StyleReviewResult | null | undefined
  abortSignal?: AbortSignal
}

/** Result from narrative phase */
export interface NarrativeResult {
  content: string
  reasoning: string
  chunkCount: number
}

/**
 * NarrativePhase service
 * Streams narrative generation, yielding chunks as they arrive.
 * Handles automatic retry on empty responses (up to 3 attempts).
 */
export class NarrativePhase {
  constructor(private deps: NarrativeDependencies) {}

  /** Execute the narrative phase - yields chunk events and phase events */
  async *execute(input: NarrativeInput): AsyncGenerator<GenerationEvent, NarrativeResult | null> {
    yield { type: 'phase_start', phase: 'narrative' } satisfies PhaseStartEvent

    const { visibleEntries, worldState, story, retrievalResult, styleReview, abortSignal } = input
    let fullResponse = ''
    let fullReasoning = ''
    let chunkCount = 0
    let retryCount = 0

    while (retryCount < MAX_EMPTY_RESPONSE_RETRIES) {
      if (abortSignal?.aborted) {
        yield { type: 'aborted', phase: 'narrative' } satisfies AbortedEvent
        return null
      }

      fullResponse = ''
      fullReasoning = ''
      chunkCount = 0

      try {
        for await (const chunk of this.deps.streamNarrative(
          visibleEntries,
          worldState,
          story,
          true, // useTieredContext
          styleReview,
          retrievalResult.combinedContext,
          abortSignal,
          retrievalResult.timelineFillResult,
        )) {
          if (abortSignal?.aborted) {
            yield { type: 'aborted', phase: 'narrative' } satisfies AbortedEvent
            return null
          }

          chunkCount++

          // Accumulate content and reasoning
          if (chunk.content) {
            fullResponse += chunk.content
          }
          if (chunk.reasoning) {
            fullReasoning += chunk.reasoning
          }

          // Yield chunk if there's any content or reasoning to display
          if (chunk.content || chunk.reasoning) {
            yield {
              type: 'narrative_chunk',
              content: chunk.content || '',
              reasoning: chunk.reasoning,
            } satisfies NarrativeChunkEvent
          }

          if (chunk.done) {
            break
          }
        }

        if (fullResponse.trim()) {
          break // Success
        }
        retryCount++
      } catch (error) {
        if (error instanceof Error && error.name === 'AbortError') {
          yield { type: 'aborted', phase: 'narrative' } satisfies AbortedEvent
          return null
        }
        yield {
          type: 'error',
          phase: 'narrative',
          error: error instanceof Error ? error : new Error(String(error)),
          fatal: true,
        } satisfies ErrorEvent
        return null
      }
    }

    if (abortSignal?.aborted) {
      yield { type: 'aborted', phase: 'narrative' } satisfies AbortedEvent
      return null
    }

    if (!fullResponse.trim()) {
      yield {
        type: 'error',
        phase: 'narrative',
        error: new Error(`Empty response after ${MAX_EMPTY_RESPONSE_RETRIES} attempts`),
        fatal: true,
      } satisfies ErrorEvent
      return null
    }

    const result: NarrativeResult = {
      content: fullResponse,
      reasoning: fullReasoning,
      chunkCount,
    }

    yield {
      type: 'phase_complete',
      phase: 'narrative',
      result,
    } satisfies PhaseCompleteEvent

    return result
  }
}

/**
 * PostGenerationPhase - Handles post-generation tasks
 *
 * Responsibilities:
 * - Coordinate action choices generation
 * - Handle translation for action choices if enabled
 *
 * NOTE: Lore management runs after chapter creation (checkAutoSummarize),
 * not as part of the standard post-generation flow.
 */

import type {
  GenerationEvent,
  PhaseStartEvent,
  PhaseCompleteEvent,
  AbortedEvent,
  ErrorEvent,
} from '../types'
import type {
  StoryEntry,
  Entry,
  TranslationSettings,
  Character,
  Location,
  Item,
  StoryBeat,
} from '$lib/types'
import type { ActionChoice } from '$lib/services/ai/sdk/schemas'
import { TranslationService } from '$lib/services/ai/utils/TranslationService'

/** Prompt context for macro expansion */
export interface PromptContext {
  mode: 'adventure'
  pov: 'first' | 'second' | 'third'
  tense: 'past' | 'present'
  protagonistName: string
  activeActorName?: string
  genre?: string
  settingDescription?: string
  tone?: string
  themes?: string[]
}

/** World state for action choices */
export interface PostWorldState {
  characters: Character[]
  locations: Location[]
  items: Item[]
  storyBeats: StoryBeat[]
}

/** Dependencies for post-generation phase */
export interface PostGenerationDependencies {
  generateActionChoices: (
    entries: StoryEntry[],
    worldState: PostWorldState,
    narrativeResponse: string,
    lorebookEntries: Entry[],
    promptContext: PromptContext,
    pov: 'first' | 'second' | 'third',
  ) => Promise<{ choices: ActionChoice[] }>
  translateActionChoices: (
    choices: ActionChoice[],
    targetLanguage: string,
  ) => Promise<ActionChoice[]>
}

/** Input for the post-generation phase */
export interface PostGenerationInput {
  disableSuggestions: boolean
  entries: StoryEntry[]
  activeThreads: StoryBeat[]
  lorebookEntries: Entry[]
  promptContext: PromptContext
  worldState: PostWorldState
  narrativeResponse: string
  pov: 'first' | 'second' | 'third'
  translationSettings: TranslationSettings
  abortSignal?: AbortSignal
}

/** Result from post-generation phase */
export interface PostGenerationResult {
  actionChoices: ActionChoice[] | null
}

/**
 * PostGenerationPhase service
 * Coordinates action choices generation.
 * Errors are non-fatal - generation continues even if action choices fail.
 */
export class PostGenerationPhase {
  constructor(private deps: PostGenerationDependencies) {}

  async *execute(
    input: PostGenerationInput,
  ): AsyncGenerator<GenerationEvent, PostGenerationResult> {
    yield { type: 'phase_start', phase: 'post' } satisfies PhaseStartEvent

    const { disableSuggestions, abortSignal } = input

    if (abortSignal?.aborted) {
      yield { type: 'aborted', phase: 'post' } satisfies AbortedEvent
      return { actionChoices: null }
    }

    const result: PostGenerationResult = { actionChoices: null }

    if (!disableSuggestions) {
      try {
        result.actionChoices = await this.generateActionChoices(input)
      } catch (error) {
        yield this.errorEvent(error)
      }
    }

    yield { type: 'phase_complete', phase: 'post', result } satisfies PhaseCompleteEvent
    return result
  }

  private async generateActionChoices(input: PostGenerationInput): Promise<ActionChoice[]> {
    const {
      entries,
      lorebookEntries,
      promptContext,
      worldState,
      narrativeResponse,
      pov,
      translationSettings,
    } = input
    const { choices } = await this.deps.generateActionChoices(
      entries,
      worldState,
      narrativeResponse,
      lorebookEntries,
      promptContext,
      pov,
    )

    if (TranslationService.shouldTranslate(translationSettings)) {
      try {
        return await this.deps.translateActionChoices(choices, translationSettings.targetLanguage)
      } catch {
        return choices
      }
    }
    return choices
  }

  private errorEvent(error: unknown): ErrorEvent {
    return {
      type: 'error',
      phase: 'post',
      error: error instanceof Error ? error : new Error(String(error)),
      fatal: false,
    }
  }
}

/**
 * RetrievalPhase - Memory and lorebook retrieval
 * Runs timeline fill/agentic retrieval and lorebook entry retrieval in parallel
 */

import type {
  GenerationContext,
  GenerationEvent,
  PhaseStartEvent,
  PhaseCompleteEvent,
  RetrievalResult,
  AbortedEvent,
} from '../types'
import type { StoryMode, POV, Tense } from '$lib/types'
import type { TimelineFillResult } from '$lib/services/ai/retrieval/TimelineFillService'
import type { AgenticRetrievalResult } from '$lib/services/ai/retrieval/AgenticRetrievalService'
import type {
  EntryRetrievalResult,
  ActivationTracker,
} from '$lib/services/ai/retrieval/EntryRetrievalService'

/** Dependencies injected from AIService - phase calls these methods rather than duplicating logic */
export interface RetrievalDependencies {
  shouldUseAgenticRetrieval: (chaptersLength: number) => boolean
  runAgenticRetrieval: (
    userInput: string,
    recentEntries: GenerationContext['visibleEntries'],
    chapters: GenerationContext['worldState']['chapters'],
    entries: GenerationContext['worldState']['lorebookEntries'],
    onQueryChapter: (chapterNumber: number, question: string) => Promise<string>,
    onQueryChapters: (
      startChapter: number,
      endChapter: number,
      question: string,
    ) => Promise<string>,
    signal?: AbortSignal,
    mode?: StoryMode,
    pov?: POV,
    tense?: Tense,
  ) => Promise<AgenticRetrievalResult>
  formatAgenticRetrievalForPrompt: (result: AgenticRetrievalResult) => string
  runTimelineFill: (
    visibleEntries: GenerationContext['visibleEntries'],
    chapters: GenerationContext['worldState']['chapters'],
  ) => Promise<TimelineFillResult>
  answerChapterQuestion: (
    chapterNumber: number,
    question: string,
    chapters: GenerationContext['worldState']['chapters'],
  ) => Promise<string>
  answerChapterRangeQuestion: (
    startChapter: number,
    endChapter: number,
    question: string,
    chapters: GenerationContext['worldState']['chapters'],
  ) => Promise<string>
  getRelevantLorebookEntries: (
    entries: GenerationContext['worldState']['lorebookEntries'],
    userInput: string,
    recentStoryEntries: GenerationContext['visibleEntries'],
    liveState: {
      characters: GenerationContext['worldState']['characters']
      locations: GenerationContext['worldState']['locations']
      items: GenerationContext['worldState']['items']
    },
    activationTracker?: ActivationTracker,
    signal?: AbortSignal,
    storyMode?: StoryMode,
  ) => Promise<EntryRetrievalResult>
}

export interface RetrievalInput {
  context: GenerationContext
  dependencies: RetrievalDependencies
  timelineFillEnabled: boolean
  activationTracker?: ActivationTracker
  storyMode: StoryMode
  pov?: POV
  tense?: Tense
}

export class RetrievalPhase {
  async *execute(input: RetrievalInput): AsyncGenerator<GenerationEvent, RetrievalResult> {
    yield { type: 'phase_start', phase: 'retrieval' } satisfies PhaseStartEvent

    const { context, dependencies, timelineFillEnabled, activationTracker } = input
    const { worldState, visibleEntries, userAction, abortSignal } = context
    const { chapters, lorebookEntries, characters, locations, items, memoryConfig } = worldState

    let chapterContext: string | null = null
    let lorebookContext: string | null = null
    let lorebookRetrievalResult: EntryRetrievalResult | null = null
    let timelineFillResult: TimelineFillResult | null = null

    const tasks: Promise<void>[] = []

    // Task 1: Memory retrieval (timeline fill or agentic)
    if (chapters.length > 0 && timelineFillEnabled && memoryConfig.enableRetrieval) {
      tasks.push(
        this.runMemoryRetrieval(input)
          .then((result) => {
            chapterContext = result.chapterContext
            timelineFillResult = result.timelineFillResult
          })
          .catch((err) => {
            if (err instanceof Error && err.name === 'AbortError') return
            console.warn('[RetrievalPhase] Memory retrieval failed (non-fatal):', err)
          }),
      )
    }

    // Task 2: Lorebook entry retrieval (skip if agentic retrieval handles it)
    const useAgenticRetrieval = dependencies.shouldUseAgenticRetrieval(chapters.length)
    const hasLoreContent =
      lorebookEntries.length > 0 ||
      characters.length > 0 ||
      locations.length > 0 ||
      items.length > 0
    if (hasLoreContent && !useAgenticRetrieval) {
      tasks.push(
        dependencies
          .getRelevantLorebookEntries(
            lorebookEntries,
            userAction.content,
            visibleEntries.slice(-10),
            { characters, locations, items },
            activationTracker,
            abortSignal,
            input.storyMode,
          )
          .then((result) => {
            lorebookRetrievalResult = result
            lorebookContext = result.contextBlock
          })
          .catch((err) => {
            if (err instanceof Error && err.name === 'AbortError') return
            console.warn('[RetrievalPhase] Lorebook retrieval failed (non-fatal):', err)
          }),
      )
    }

    if (tasks.length > 0) await Promise.all(tasks)

    if (abortSignal?.aborted) {
      yield { type: 'aborted', phase: 'retrieval' } satisfies AbortedEvent
      return {
        chapterContext: null,
        lorebookContext: null,
        lorebookRetrievalResult: null,
        timelineFillResult: null,
        combinedContext: null,
      }
    }

    const combinedContext = [chapterContext, lorebookContext].filter(Boolean).join('\n') || null
    const result: RetrievalResult = {
      chapterContext,
      lorebookContext,
      lorebookRetrievalResult,
      timelineFillResult,
      combinedContext,
    }

    yield { type: 'phase_complete', phase: 'retrieval', result } satisfies PhaseCompleteEvent
    return result
  }

  private async runMemoryRetrieval(input: RetrievalInput): Promise<{
    chapterContext: string | null
    timelineFillResult: TimelineFillResult | null
  }> {
    const { context, dependencies, storyMode, pov, tense } = input
    const { worldState, visibleEntries, userAction, abortSignal } = context
    const { chapters, lorebookEntries } = worldState

    if (dependencies.shouldUseAgenticRetrieval(chapters.length)) {
      const result = await dependencies.runAgenticRetrieval(
        userAction.content,
        visibleEntries,
        chapters,
        lorebookEntries,
        (num, q) => dependencies.answerChapterQuestion(num, q, chapters),
        (start, end, q) => dependencies.answerChapterRangeQuestion(start, end, q, chapters),
        abortSignal,
        storyMode,
        pov,
        tense,
      )
      return {
        chapterContext: result.context
          ? dependencies.formatAgenticRetrievalForPrompt(result)
          : null,
        timelineFillResult: null,
      }
    }

    return {
      chapterContext: null,
      timelineFillResult: await dependencies.runTimelineFill(visibleEntries, chapters),
    }
  }
}

/**
 * TranslationPhase - Handles translation of narration and world state elements
 *
 * Responsibilities:
 * - Translate narrative content to target language (if enabled)
 * - Coordinate translations (narration, suggestions, action choices done elsewhere)
 * - Handle translation errors gracefully (non-fatal)
 *
 * NOTE: Translation service is currently stubbed. This phase gracefully handles
 * errors so the pipeline continues even when translation fails.
 */

import type {
  GenerationEvent,
  PhaseStartEvent,
  PhaseCompleteEvent,
  AbortedEvent,
  ErrorEvent,
} from '../types'
import type { TranslationSettings } from '$lib/types'
import type { TranslationResult } from '$lib/services/ai/utils/TranslationService'
import { TranslationService } from '$lib/services/ai/utils/TranslationService'

/** Dependencies for translation phase - injected to avoid tight coupling */
export interface TranslationDependencies {
  translateNarration: (
    content: string,
    targetLanguage: string,
    isVisualProse: boolean,
  ) => Promise<TranslationResult>
}

/** Input for the translation phase */
export interface TranslationInput {
  narrativeContent: string
  narrativeEntryId: string
  isVisualProse: boolean
  translationSettings: TranslationSettings
  abortSignal?: AbortSignal
}

/** Result from translation phase */
export interface TranslationResult2 {
  translated: boolean
  translatedContent: string | null
  targetLanguage: string | null
}

/**
 * TranslationPhase service
 * Translates narrative content to target language.
 * Errors are non-fatal - if translation fails, the pipeline continues with original content.
 */
export class TranslationPhase {
  constructor(private deps: TranslationDependencies) {}

  /** Execute the translation phase - yields events and returns result */
  async *execute(input: TranslationInput): AsyncGenerator<GenerationEvent, TranslationResult2> {
    yield { type: 'phase_start', phase: 'translation' } satisfies PhaseStartEvent

    const { narrativeContent, isVisualProse, translationSettings, abortSignal } = input

    // Check if translation should be skipped
    if (!TranslationService.shouldTranslateNarration(translationSettings)) {
      const result: TranslationResult2 = {
        translated: false,
        translatedContent: null,
        targetLanguage: null,
      }

      yield {
        type: 'phase_complete',
        phase: 'translation',
        result,
      } satisfies PhaseCompleteEvent

      return result
    }

    if (abortSignal?.aborted) {
      yield { type: 'aborted', phase: 'translation' } satisfies AbortedEvent
      return {
        translated: false,
        translatedContent: null,
        targetLanguage: null,
      }
    }

    const targetLanguage = translationSettings.targetLanguage

    try {
      const translationResult = await this.deps.translateNarration(
        narrativeContent,
        targetLanguage,
        isVisualProse,
      )

      if (abortSignal?.aborted) {
        yield { type: 'aborted', phase: 'translation' } satisfies AbortedEvent
        return {
          translated: false,
          translatedContent: null,
          targetLanguage: null,
        }
      }

      const result: TranslationResult2 = {
        translated: true,
        translatedContent: translationResult.translatedContent,
        targetLanguage,
      }

      yield {
        type: 'phase_complete',
        phase: 'translation',
        result,
      } satisfies PhaseCompleteEvent

      return result
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        yield { type: 'aborted', phase: 'translation' } satisfies AbortedEvent
        return {
          translated: false,
          translatedContent: null,
          targetLanguage: null,
        }
      }

      // Translation errors are non-fatal - log and continue with original content
      yield {
        type: 'error',
        phase: 'translation',
        error: error instanceof Error ? error : new Error(String(error)),
        fatal: false,
      } satisfies ErrorEvent

      return {
        translated: false,
        translatedContent: null,
        targetLanguage: null,
      }
    }
  }
}

import { settings } from '$lib/stores/settings.svelte'
/**
 * LorebookClassifierService
 *
 * LLM-based entry type classification service
 */

import { createLogger } from '$lib/log'
import type { StoryMode, EntryType } from '$lib/types'
import { BaseAIService } from '$lib/services/ai/BaseAIService'
import { lorebookClassificationResultSchema } from '$lib/services/ai/sdk/schemas'
import { ContextBuilder } from '$lib/services/context'
import type { ImportedEntry } from '../types'

const log = createLogger('LorebookClassifierService')

export class LorebookClassifierService extends BaseAIService {
  constructor(serviceId: string = 'lorebookClassifier') {
    super(serviceId)
  }

  async classifyEntries(
    entries: ImportedEntry[],
    onProgress?: (classified: number, total: number) => void,
    mode: StoryMode = 'adventure',
  ): Promise<ImportedEntry[]> {
    if (entries.length === 0) return entries

    const lorebookSettings = settings.serviceSpecificSettings?.lorebookClassifier
    const BATCH_SIZE = lorebookSettings?.batchSize ?? 50
    const MAX_CONCURRENT = lorebookSettings?.maxConcurrent ?? 5

    const result = [...entries]
    let classified = 0

    const batchStarts: number[] = []
    for (let i = 0; i < entries.length; i += BATCH_SIZE) {
      batchStarts.push(i)
    }

    for (let ci = 0; ci < batchStarts.length; ci += MAX_CONCURRENT) {
      const concurrentStarts = batchStarts.slice(ci, ci + MAX_CONCURRENT)

      const batchPromises = concurrentStarts.map(async (startIndex) => {
        const batch = entries.slice(startIndex, startIndex + BATCH_SIZE)

        const entriesJson = JSON.stringify(
          batch.map((entry, batchIndex) => ({
            index: batchIndex,
            name: entry.name,
            content: entry.description.slice(0, 500),
            keywords: entry.keywords.slice(0, 10),
          })),
          null,
          2,
        )

        const ctx = new ContextBuilder()
        ctx.add({ mode, pov: 'second', tense: 'present', protagonistName: '', entriesJson })
        const { system, user: prompt } = await ctx.render('lorebook-classifier')

        let classifications: Array<{ index: number; type: string }> = []
        try {
          classifications = await this.generate(
            lorebookClassificationResultSchema,
            system,
            prompt,
            'lorebook-classifier',
          )
        } catch (err) {
          log('Failed to classify batch starting at ' + startIndex, err)
        }

        return { startIndex, batch, classifications }
      })

      const batchResults = await Promise.all(batchPromises)

      for (const { startIndex, batch, classifications } of batchResults) {
        for (const classification of classifications) {
          const globalIndex = startIndex + classification.index
          if (globalIndex < result.length) {
            result[globalIndex] = {
              ...result[globalIndex],
              type: classification.type as EntryType,
            }
          }
        }

        classified += batch.length
        if (onProgress) {
          onProgress(classified, entries.length)
        }

        log('Classified batch', {
          batchStart: startIndex,
          batchSize: BATCH_SIZE,
          maxConcurrent: MAX_CONCURRENT,
          classified,
          total: entries.length,
        })
      }
    }

    return result
  }
}

/**
 * Pure validation/mutation-shape functions for Phase 3 mechanics: resource
 * clamps, ability-use costs, item equip/transfer, and clothing durability.
 * No I/O here — callers (mechanics-service.ts) persist the results.
 */

import type { CampaignPartyMember, Item, ResourceValue, Ruleset, RulesetSlot } from '$lib/types'
import { validateItemOwnership } from '$lib/services/campaign/campaign-rules'

/** Clamps a value into [min, max] (max may be omitted for unbounded resources). */
export function clampResourceValue(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

/** Applies a delta to a resource, clamping the result to [0, max]. Never allows negative current. */
export function applyResourceDelta(resource: ResourceValue, delta: number): ResourceValue {
  return { ...resource, current: clampResourceValue(resource.current + delta, 0, resource.max) }
}

/** Throws if the given money amount would go negative. */
export function validateMoneyAmount(amount: number): void {
  if (amount < 0) {
    throw new Error('Money amount cannot go negative')
  }
}

/**
 * Validates and applies an ability's resource cost. Throws if the character
 * doesn't have enough of the resource (ability-use floor validation).
 */
export function useAbilityResource(resource: ResourceValue, cost: number): ResourceValue {
  if (resource.current < cost) {
    throw new Error(
      `Not enough resource to use this ability (need ${cost}, have ${resource.current})`,
    )
  }
  return applyResourceDelta(resource, -cost)
}

/** Validates a slot key exists on the ruleset and no other item already occupies it for this owner. */
export function validateEquipSlot(
  item: Pick<Item, 'id' | 'ownerCharacterId'>,
  slotKey: string,
  rulesetSlots: RulesetSlot[],
  currentlyEquipped: Item[],
): void {
  if (!rulesetSlots.some((slot) => slot.key === slotKey)) {
    throw new Error(`Unknown equipment slot: "${slotKey}"`)
  }
  const conflict = currentlyEquipped.find(
    (candidate) =>
      candidate.id !== item.id &&
      candidate.ownerCharacterId === item.ownerCharacterId &&
      candidate.slotKey === slotKey &&
      candidate.equipped,
  )
  if (conflict) {
    throw new Error(`Slot "${slotKey}" is already occupied by another item`)
  }
}

/**
 * Validates transferring an item to a new owner (or to the shared stash if
 * `toCharacterId` is null). Reuses the same eligibility rule as ownership
 * assignment so a transfer can never hand an item to an ineligible character.
 */
export function validateItemTransfer(
  item: Item,
  campaignStoryId: string | null,
  members: CampaignPartyMember[],
  toCharacterId: string | null,
): void {
  validateItemOwnership(item, campaignStoryId, members, { ownerCharacterId: toCharacterId })
}

/** Clamps a clothing durability change to [0, maxDurability]; ownership is inherent to the item row. */
export function applyClothingDurabilityDelta(
  currentDurability: number,
  delta: number,
  maxDurability: number,
): number {
  return clampResourceValue(currentDurability + delta, 0, maxDurability)
}

/**
 * Slot-based carry validation: at most one equipped item per named slot per
 * owner. This is deliberately NOT a weight/encumbrance system — Item has no
 * weight field, and adding one would be a broad schema change out of scope
 * for this pass. Revisit if full encumbrance is required later.
 */
export function validateSlotCarryLimit(
  ownerCharacterId: string | null,
  slotKey: string,
  items: Item[],
): void {
  const occupants = items.filter(
    (item) =>
      item.ownerCharacterId === ownerCharacterId && item.slotKey === slotKey && item.equipped,
  )
  if (occupants.length > 1) {
    throw new Error(`More than one item is equipped in slot "${slotKey}" for this character`)
  }
}

export function validateEncumbrance(
  ownerCharacterId: string,
  items: Item[],
  ruleset: Pick<Ruleset, 'encumbranceMode' | 'encumbranceCapacityFormula'>,
  capacity: number,
): void {
  if (ruleset.encumbranceMode === 'slot') return
  const carriedWeight = items
    .filter((item) => item.ownerCharacterId === ownerCharacterId && item.location === 'inventory')
    .reduce((total, item) => total + Math.max(0, item.weight ?? 0) * Math.max(0, item.quantity), 0)
  if (carriedWeight > capacity) {
    throw new Error(`Carrying capacity exceeded (${carriedWeight} / ${capacity})`)
  }
}

/** Counts carried item stacks against a ruleset's slot capacity; equipped wearable items use named slots instead. */
export function validateInventorySlotCapacity(
  ownerCharacterId: string,
  items: Item[],
  capacity: number,
): void {
  const carriedSlots = items.filter(
    (item) =>
      item.ownerCharacterId === ownerCharacterId &&
      item.location === 'inventory' &&
      (!item.equipped || isArmorItem(item)),
  ).length
  if (carriedSlots > capacity) {
    throw new Error(`Inventory slot capacity exceeded (${carriedSlots} / ${capacity})`)
  }
}

/** Armor occupies carry capacity even when equipped; ordinary clothing only uses wearable slots. */
export function isArmorItem(item: Pick<Item, 'name' | 'metadata'>): boolean {
  const metadata = item.metadata?.armor
  if (typeof metadata === 'boolean') return metadata
  if (metadata && typeof metadata === 'object' && 'isArmor' in metadata) {
    return metadata.isArmor === true
  }
  return /\b(armor|armour|breastplate|cuirass|chainmail|mail|plate armor|scale armor|shield)\b/i.test(
    item.name,
  )
}

/**
 * GUARDRAIL (hard ban, task 3.11/3.12): mechanics-driven state mutations must
 * never compel a sexual act or override a character's consent, even under
 * coercive/mind-control narrative framing. No Phase 3 mechanic (resources,
 * abilities, inventory) can express this today, so this is a deliberate no-op —
 * but it is the single choke point every future mutation type MUST call before
 * applying an effect. Any future mind-control/coercion mechanic must throw here
 * rather than allow the mutation through.
 */
export function assertNoCoercedConsentMutation(_mutation: { kind: string; note?: string }): void {
