  async updateExperimentalFeatures(updates: Partial<ExperimentalFeatures>) {
    // Enforce dependencies: rollbackOnDelete requires stateTracking
    if (
      updates.rollbackOnDelete &&
      !this.experimentalFeatures.stateTracking &&
      !updates.stateTracking
    ) {
      updates.rollbackOnDelete = false
    }
    // lightweightBranches requires stateTracking
    if (
      updates.lightweightBranches &&
      !this.experimentalFeatures.stateTracking &&
      !updates.stateTracking
    ) {
      updates.lightweightBranches = false
    }
    // Disabling stateTracking cascades
    if (updates.stateTracking === false) {
      updates.rollbackOnDelete = false
      updates.lightweightBranches = false
    }

    // Disabling epistemic workflow cascades to disable all related sub-features.
    if (updates.epistemicWorkflowEnabled === false) {
      updates.epistemicGateAdventureEnabled = false
      updates.epistemicDisclosureGateEnabled = false
      updates.directorOutliningAssistantEnabled = false
      updates.epistemicCostOverlayEnabled = false
    }

    // Keep execution mode within known values if a malformed value was injected.
    if (
      updates.epistemicExecutionMode &&
      updates.epistemicExecutionMode !== 'quality' &&
      updates.epistemicExecutionMode !== 'fast'
    ) {
      updates.epistemicExecutionMode = 'quality'
    }

    const effectiveWorkflowEnabled =
      updates.epistemicWorkflowEnabled ?? this.experimentalFeatures.epistemicWorkflowEnabled
    const effectiveExecutionMode =
      updates.epistemicExecutionMode ?? this.experimentalFeatures.epistemicExecutionMode

    // Contract: disclosure gate always runs in fast mode when workflow is enabled.
    if (effectiveWorkflowEnabled && effectiveExecutionMode === 'fast') {
      updates.epistemicDisclosureGateEnabled = true
    }

    this.experimentalFeatures = { ...this.experimentalFeatures, ...updates }
    await this.saveExperimentalFeatures()
  }

