  // Activation tracking methods for lorebook stickiness

  // Track the current story ID for activation persistence
  private currentActivationStoryId: string | null = null

  /**
   * Create an activation tracker for the current story position.
   * The tracker maintains references to our state so activations are persisted.
   */
  getActivationTracker(storyPosition: number): ActivationTracker {
    const previousPosition = this.currentStoryPosition
    this.currentStoryPosition = storyPosition
    const tracker = new SimpleActivationTracker(storyPosition)
    // Create a fresh copy of activation data for the tracker
    const activationDataCopy = Object.fromEntries(Object.entries(this.activationData))
    tracker.loadActivationData(activationDataCopy)

    console.log('[UI] getActivationTracker called', {
      previousPosition,
      newPosition: storyPosition,
      activationDataEntryCount: Object.keys(activationDataCopy).length,
      activationEntryIds: Object.keys(activationDataCopy),
    })

    return tracker
  }

  /**
   * Update activation data after retrieval completes.
   * Called with the tracker that was modified during retrieval.
   */
  updateActivationData(tracker: SimpleActivationTracker, storyId?: string) {
    this.activationData = tracker.getActivationData()
    // Prune old activations (beyond max stickiness of 10 turns)
    tracker.pruneOldActivations(10)
    this.activationData = tracker.getActivationData()

    // Persist to database
    const targetStoryId = storyId || this.currentActivationStoryId
    if (targetStoryId) {
      this.saveActivationData(targetStoryId)
    }
  }

  /**
   * Clear activation data (e.g., when switching stories).
   */
  clearActivationData() {
    this.activationData = {}
    this.currentStoryPosition = 0
    this.currentActivationStoryId = null
  }

  /**
   * Save activation data to the database for persistence.
   */
  saveActivationData(storyId: string) {
    this.currentActivationStoryId = storyId
    const data: PersistedActivationData = {
      storyId,
      activationData: { ...this.activationData },
      storyPosition: this.currentStoryPosition,
    }
    database.setSetting('lorebook_activation', JSON.stringify(data)).catch((err) => {
      console.warn('[UI] Failed to persist activation data:', err)
    })
  }

  /**
   * Load activation data from the database for a story.
   * Called when a story is loaded.
   */
  async loadActivationData(storyId: string) {
    try {
      const data = await database.getSetting('lorebook_activation')
      if (data) {
        const parsed: PersistedActivationData = JSON.parse(data)
        // Only restore if it's for the same story
        if (parsed.storyId === storyId) {
          this.activationData = parsed.activationData
          this.currentStoryPosition = parsed.storyPosition
          this.currentActivationStoryId = storyId
          console.log('[UI] Restored activation data for story:', storyId, {
            entriesCount: Object.keys(parsed.activationData).length,
            storyPosition: parsed.storyPosition,
          })
          return
        }
      }
      // No matching data found, start fresh
      this.activationData = {}
      this.currentStoryPosition = 0
      this.currentActivationStoryId = storyId
    } catch (err) {
      console.warn('[UI] Failed to load persisted activation data:', err)
      this.activationData = {}
      this.currentStoryPosition = 0
      this.currentActivationStoryId = storyId
    }
  }

  /**
   * Get current activation data for debugging.
   */
  getActivationDebugInfo(): { data: Record<string, number>; position: number } {
    return {
      data: { ...this.activationData },
      position: this.currentStoryPosition,
    }
  }

  // Toast notification state
  toastVisible = $state(false)
  toastMessage = $state('')
  toastType = $state<'error' | 'warning' | 'info' | 'success'>('info')
  toastHovering = $state(false)
  private toastTimeout: ReturnType<typeof setTimeout> | null = null

  /**
   * Show a toast notification.
   * @param message - The message to display
   * @param type - The type of toast (error, warning, info)
   * @param duration - Duration in milliseconds (default: 4000, errors use 8000)
   */
  showToast(
    message: string,
    type: 'error' | 'warning' | 'info' | 'success' = 'info',
    duration?: number,
  ) {
    const capitalized = message.charAt(0).toUpperCase() + message.slice(1)
    this.toastMessage = capitalized
    this.toastType = type
    this.toastVisible = true
    this.toastHovering = false

    if (this.toastTimeout) {
      clearTimeout(this.toastTimeout)
    }

    const autoDuration = duration ?? (type === 'error' ? 8000 : 4000)

    this.toastTimeout = setTimeout(() => {
      if (!this.toastHovering) {
        this.toastVisible = false
      }
    }, autoDuration)
  }

  setToastHovering(hovering: boolean) {
    this.toastHovering = hovering
    if (hovering && this.toastTimeout) {
      clearTimeout(this.toastTimeout)
    } else if (!hovering && this.toastVisible) {
      const autoDuration = this.toastType === 'error' ? 8000 : 4000
      this.toastTimeout = setTimeout(() => {
        this.toastVisible = false
      }, autoDuration)
    }
  }

  /**
   * Hide toast notification.
   */
  hideToast() {
    this.toastVisible = false
    if (this.toastTimeout) {
      clearTimeout(this.toastTimeout)
      this.toastTimeout = null
    }
  }

  // Settings navigation state
  private settingsActiveTab = $state<string>('api')

  /**
   * Get the active settings tab to navigate to.
   */
  get settingsTab(): string {
    return this.settingsActiveTab
  }

  /**
   * Open settings modal and navigate to the API tab to fix profiles.
   */
  openSettingsToApiTab() {
    this.settingsActiveTab = 'api'
    this.settingsModalOpen = true
  }

  /**
   * Open settings modal and navigate to the Generation tab to configure models.
   */
  openSettingsToGenerationTab() {
    this.settingsActiveTab = 'generation'
    this.settingsModalOpen = true
  }

  /**
   * Set the active settings tab.
   */
  setSettingsTab(tab: string) {
    this.settingsActiveTab = tab
  }

  set settingsTab(v: string) {
    this.settingsActiveTab = v
  }

  // -- App visibility tracking (Android background generation) ---------------

  /** Start tracking document visibility changes for background generation detection. */
  initVisibilityTracking() {
    if (typeof document === 'undefined') return
    // Avoid double-init
    if (this.visibilityCleanup) return

    const handler = () => {
      const hidden = document.hidden
      this.isAppBackgrounded = hidden
      if (hidden && this.isGenerating) {
        this.wasBackgroundedDuringGeneration = true
      }
    }

    document.addEventListener('visibilitychange', handler)
    this.visibilityCleanup = () => document.removeEventListener('visibilitychange', handler)
  }

  /** Clean up visibility tracking listener. */
  destroyVisibilityTracking() {
    this.visibilityCleanup?.()
    this.visibilityCleanup = null
  }

  /** Reset the backgrounded-during-generation flag (call when a new generation starts). */
  resetBackgroundedFlag() {
    this.wasBackgroundedDuringGeneration = false
  }
}

export const ui = new UIStore()

/**
 * Centralized store for the Vault Entity Editor.
 *
 * Single source of truth for:
 *  - Pending changes (from AI tool calls)
 *  - Active editor state (which entity is being edited)
 *  - Preview lorebook (derived from vault store + active change)
 *  - Approval / rejection / edit workflows
 */

import type { VaultPendingChange } from '$lib/services/ai/sdk/schemas'
import type { VaultLorebook, VaultLorebookEntry } from '$lib/types'
import type { InteractiveVaultService } from '$lib/services/ai/vault/InteractiveVaultService'
import { lorebookVault } from './lorebookVault.svelte'
import { characterVault } from './characterVault.svelte'
import { scenarioVault } from './scenarioVault.svelte'
import { SvelteMap } from 'svelte/reactivity'
import { composePendingOnto, scenarioToRecord, characterToRecord } from '$lib/utils/vaultMerge'

class VaultEditorStore {
  // ── Core state ────────────────────────────────────────────────────────

  /** All pending changes across the conversation */
  pendingChanges = $state<VaultPendingChange[]>([])

  /** The change currently open in the entity editor */
  activeChange = $state<VaultPendingChange | null>(null)

  /** Whether the entity editor panel is visible */
  editorOpen = $state(false)

  /** Whether the lorebook editor has unsaved local changes */
  editorDirty = $state(false)

  /** Whether the editor is in view mode (direct editing, no approval workflow) */
  viewMode = $state(false)

  /** Entity ID being viewed (for saving edits in view mode) */
  viewEntityId = $state<string | null>(null)

  /** Entity type being viewed (for routing saves in view mode) */
  viewEntityType = $state<string | null>(null)

  /** Edited versions of pending changes (user modifications before approval) */
  private _editedChanges = $state<SvelteMap<string, VaultPendingChange>>(new SvelteMap())

  // ── Derived values ────────────────────────────────────────────────────

  /** Number of pending (not yet approved/rejected) changes */
  get pendingCount(): number {
    return this.pendingChanges.filter((c) => c.status === 'pending').length
  }

  /**
   * Composed preview for the active entity. Starts from the current vault
   * state (which includes already-approved changes) and overlays remaining
   * pending updates so the editor always reflects reality. Returns null for
   * lorebook-related entities (they use previewLorebook) or when there's no
   * active change.
   */
  get composedData(): Record<string, unknown> | null {
    const change = this.activeChange
    if (!change) return null
    if (change.entityType === 'lorebook' || change.entityType === 'lorebook-entry') return null
    if (change.action !== 'update') return null
    if (!('previous' in change) || !change.previous) return null

    const entityId =
      change.entityType === 'scenario' || change.entityType === 'character' ? change.entityId : null
    if (!entityId) return null

    const pending = this._pendingChangesWithEditOverlay(change.entityType, entityId)

    const base = this._getVaultBase(change.entityType, entityId, change.previous)
    return composePendingOnto(base, pending)
  }

  /**
   * Build a base record from the current vault state for the given entity
   * type and ID. Falls back to `previous` when the entity isn't found
   * (e.g. create actions where the entity doesn't exist in the vault yet).
   */
  private _getVaultBase(
    entityType: string,
    entityId: string,
    previous: Record<string, unknown>,
  ): Record<string, unknown> {
    if (entityType === 'scenario') {
      const live = scenarioVault.getById(entityId)
      if (live) return scenarioToRecord(live)
    } else if (entityType === 'character') {
      const live = characterVault.getById(entityId)
      if (live) return characterToRecord(live)
    }
    return JSON.parse(JSON.stringify(previous))
  }

  /**
   * Collect pending changes for an entity, applying any user edits
   * on top of the original change data/previous.
   */
  private _pendingChangesWithEditOverlay(
    entityType: string,
    entityId: string,
  ): Array<{ data: Record<string, unknown>; previous: Record<string, unknown> }> {
    return this.pendingChanges
      .filter(
        (c) =>
          c.status === 'pending' &&
          c.entityType === entityType &&
          'entityId' in c &&
          c.entityId === entityId &&
          'data' in c &&
          'previous' in c,
      )
      .map((c) => {
        const effective = this._editedChanges.get(c.id) ?? c
        return {
          data: (effective as { data: Record<string, unknown> }).data,
          previous: (effective as { previous: Record<string, unknown> }).previous,
        }
      })
      .filter((c) => c.data && c.previous)
  }

  /**
   * Compose pending changes for an entity onto a base state.
   * Unlike `composedData` (which requires `activeChange`), this works
   * from any base state and entity ID — used by view mode to overlay
   * unapproved changes onto the current vault entity.
   */
  composePendingChanges(
    base: Record<string, unknown>,
    entityType: 'character' | 'scenario',
    entityId: string,
  ): Record<string, unknown> {
    const pending = this._pendingChangesWithEditOverlay(entityType, entityId)
    if (pending.length === 0) return base
    return composePendingOnto(base, pending)
  }

  /** Human-readable breakdown of pending changes by type */
  get pendingBreakdown(): string {
    const pending = this.pendingChanges.filter((c) => c.status === 'pending')
    const counts: Record<string, number> = {}
    for (const c of pending) {
      switch (c.entityType) {
        case 'character':
          counts['character'] = (counts['character'] ?? 0) + 1
          break
        case 'lorebook-entry':
          counts['entry'] = (counts['entry'] ?? 0) + 1
          break
        case 'scenario':
          counts['scenario'] = (counts['scenario'] ?? 0) + 1
          break
        case 'lorebook':
          counts['lorebook'] = (counts['lorebook'] ?? 0) + 1
          break
      }
    }
    return Object.entries(counts)
      .map(([type, count]) => {
        const noun = count > 1 ? (type === 'entry' ? 'entries' : `${type}s`) : type
        return `${count} ${noun}`
      })
      .join(', ')
  }

  /** Lorebook ID associated with the active change (if any) */
  get currentLorebookId(): string | null {
    const change = this.activeChange
    if (!change) return null
    if (change.entityType === 'lorebook') return change.entityId
    if (change.entityType === 'lorebook-entry') return change.lorebookId
    return null
  }

  /** Pending lorebook-entry changes for the currently-open lorebook */
  get pendingEntries(): Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>[] {
    const lorebookId = this.currentLorebookId
    if (!lorebookId) return []
    return this.pendingChanges
      .filter(
        (c): c is Extract<VaultPendingChange, { entityType: 'lorebook-entry' }> =>
          c.entityType === 'lorebook-entry' &&
          c.lorebookId === lorebookId &&
          c.status === 'pending',
      )
      .map((c) => (this._editedChanges.get(c.id) as typeof c) ?? c)
  }

  /** Preview lorebook for the active change — reads live from vault store */
  get previewLorebook(): VaultLorebook | null {
    let change = this.activeChange
    if (!change) return null

    // Use edited version if available
    change = this._editedChanges.get(change.id) ?? change

    if (change.entityType === 'lorebook-entry') {
      const lorebook = lorebookVault.getById(change.lorebookId)
      if (!lorebook) return null
      const copy = JSON.parse(JSON.stringify(lorebook)) as VaultLorebook

      // Overlay ALL pending changes for this lorebook onto the preview copy
      // Process deletes/merges in descending index order to avoid shifting
      const entryChanges = this.pendingChanges
        .filter(
          (c): c is Extract<VaultPendingChange, { entityType: 'lorebook-entry' }> =>
            c.entityType === 'lorebook-entry' &&
            c.status === 'pending' &&
            (c as Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>).lorebookId ===
              change.lorebookId,
        )
        .map(
          (c) =>
            (this._editedChanges.get(c.id) ?? c) as Extract<
              VaultPendingChange,
              { entityType: 'lorebook-entry' }
            >,
        )

      const deletesAndMerges = entryChanges.filter(
        (
          c,
        ): c is Extract<
          VaultPendingChange,
          { entityType: 'lorebook-entry'; action: 'delete' | 'merge' }
        > => c.action === 'delete' || c.action === 'merge',
      )
      const creates = entryChanges.filter(
        (c): c is Extract<VaultPendingChange, { entityType: 'lorebook-entry'; action: 'create' }> =>
          c.action === 'create',
      )
      const updates = entryChanges.filter(
        (c): c is Extract<VaultPendingChange, { entityType: 'lorebook-entry'; action: 'update' }> =>
          c.action === 'update',
      )

      // Apply updates before deletes/merges so index references are stable
      // (updates don't add/remove entries, so they don't shift positions)
      for (const entryChange of updates) {
        if (
          typeof entryChange.entryIndex === 'number' &&
          entryChange.entryIndex >= 0 &&
          entryChange.entryIndex < copy.entries.length
        ) {
          const safeData = Object.fromEntries(
            Object.entries(entryChange.data ?? {}).filter(([_, v]) => v !== ''),
          ) as Partial<VaultLorebookEntry>
          copy.entries[entryChange.entryIndex] = {
            ...copy.entries[entryChange.entryIndex],
            ...safeData,
          }
        }
      }

      deletesAndMerges.sort((a, b) => {
        const aIdx = a.action === 'delete' ? a.entryIndex : Math.max(...a.entryIndices)
        const bIdx = b.action === 'delete' ? b.entryIndex : Math.max(...b.entryIndices)
        return bIdx - aIdx
      })

      for (const entryChange of deletesAndMerges) {
        switch (entryChange.action) {
          case 'delete':
            if (
              typeof entryChange.entryIndex === 'number' &&
              entryChange.entryIndex >= 0 &&
              entryChange.entryIndex < copy.entries.length
            ) {
              copy.entries.splice(entryChange.entryIndex, 1)
            }
            break
          case 'merge':
            if (entryChange.entryIndices) {
              const sorted = [...entryChange.entryIndices].sort((a, b) => b - a)
              for (const idx of sorted) {
                if (idx >= 0 && idx < copy.entries.length) {
                  copy.entries.splice(idx, 1)
                }
              }
              copy.entries.push(entryChange.data)
            }
            break
        }
      }

      for (const entryChange of creates) {
        if (!copy.entries.some((e) => e.name === entryChange.data.name)) {
          copy.entries.push(entryChange.data)
        }
      }

      return copy
    }

    if (change.entityType === 'lorebook' && 'data' in change) {
      // Try vault first (the lorebook may already be approved & saved)
      const existing = lorebookVault.getById(change.entityId)
      if (existing) {
        return JSON.parse(JSON.stringify(existing)) as VaultLorebook
      }
      // Not yet approved — construct a preview from the change data
      return {
        id: change.entityId,
        name: change.data.name,
        description: change.data.description,
        tags: change.data.tags,
        entries: [],
        metadata: {
          format: 'aventura',
          totalEntries: 0,
          entryBreakdown: {
            character: 0,
            location: 0,
            item: 0,
            faction: 0,
            concept: 0,
            event: 0,
          } as Record<string, number>,
        },
        favorite: false,
        source: 'manual',
        originalFilename: null,
        originalStoryId: null,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      } as VaultLorebook
    }

    return null
  }

  /** Initial entry index for the lorebook editor (for scroll-to-entry) */
  get initialEntryIndex(): number | null {
    const change = this.activeChange
    if (!change) return null
    if (change.entityType !== 'lorebook-entry') return null

    if ((change.action === 'create' || change.action === 'merge') && 'data' in change) {
      const pendingIdx = this.pendingEntries.findIndex((c) => c.id === change.id)
      return pendingIdx >= 0 ? -100 - pendingIdx : null
    }
    if (change.action === 'update' && typeof change.entryIndex === 'number') {
      return change.entryIndex
    }
    return null
  }

  // ── Mutation methods ──────────────────────────────────────────────────

  /**
   * Add a pending change (with deduplication by ID).
   * Does NOT auto-open the editor — call openEditorForChange() separately.
   */
  addPendingChange(change: VaultPendingChange): void {
    if (!this.pendingChanges.some((c) => c.id === change.id)) {
      this.pendingChanges = [...this.pendingChanges, change]
    }
  }

  /**
   * Smart editor open: opens for the given change, but skips if the editor
   * is already showing the same lorebook (to avoid resetting state).
   * Exits view mode so the approval workflow is active for the new change.
   */
  openEditorSmart(change: VaultPendingChange): void {
    if (this.isShowingSameLorebook(change)) return
    this.viewMode = false
    this.viewEntityId = null
    this.viewEntityType = null
    this.activeChange = change
    this.editorOpen = true
  }

  /** Force-open the editor for a specific change */
  openEditor(change: VaultPendingChange): void {
    this.viewMode = false
    this.viewEntityId = null
    this.viewEntityType = null
    this.activeChange = change
    this.editorOpen = true
  }

  /** Open the editor in view mode for direct editing (no approval workflow) */
  openViewer(change: VaultPendingChange, entityId: string, entityType: string): void {
    this.activeChange = change
    this.editorOpen = true
    this.viewMode = true
    this.viewEntityId = entityId
    this.viewEntityType = entityType
  }

  /** Close the editor panel */
  closeEditor(): void {
    this.activeChange = null
    this.editorOpen = false
    this.viewMode = false
    this.viewEntityId = null
    this.viewEntityType = null
  }

  /**
   * Record a user edit to a pending change (for "edit before approve" flow).
   * Stores the modified change so approval uses the edited version.
   */
  updateChangeData(changeId: string, updatedChange: VaultPendingChange): void {
    this._editedChanges = new SvelteMap(this._editedChanges).set(changeId, updatedChange)
  }

  /** Return the edited version of a change if one exists, otherwise the original. */
  getEffectiveChange(change: VaultPendingChange): VaultPendingChange {
    return this._editedChanges.get(change.id) ?? change
  }

  /**
   * Approve a single pending change.
   * Uses the edited version if the user modified it before approving.
   * Re-indexes remaining pending lorebook-entry changes if this approval
   * shifts array indices (delete / merge).
   */
  async approve(change: VaultPendingChange, service: InteractiveVaultService): Promise<void> {
    if (change.status !== 'pending') return

    const effectiveChange = this._editedChanges.get(change.id) ?? change
    await service.applyChange(effectiveChange)
    service.handleApproval(change, true)

    // Clean up edited version
    const edits = new SvelteMap(this._editedChanges)
    edits.delete(change.id)
    this._editedChanges = edits

    // Mark as approved
    for (const c of this.pendingChanges) {
      if (c.id === change.id) c.status = 'approved'
    }

    // Re-index remaining pending changes whose indices may have shifted
    this._reindexAfterApproval(effectiveChange)

    // Auto-close logic: keep open for lorebook-related, close for others
    this._autoCloseAfterAction(change)

    // Trigger reactivity
    this.pendingChanges = [...this.pendingChanges]
  }

  /** Reject a single pending change */
  reject(change: VaultPendingChange, service: InteractiveVaultService): void {
    if (change.status !== 'pending') return
    service.handleApproval(change, false)

    const edits = new SvelteMap(this._editedChanges)
    edits.delete(change.id)
    this._editedChanges = edits

    for (const c of this.pendingChanges) {
      if (c.id === change.id) c.status = 'rejected'
    }

    this._autoCloseAfterAction(change)
    this.pendingChanges = [...this.pendingChanges]
  }

  /** Approve all pending changes — processes deletes/merges in descending index order to avoid shifting */
  async approveAll(service: InteractiveVaultService): Promise<string | null> {
    const pending = this.pendingChanges.filter((c) => c.status === 'pending')

    // Separate by type and action
    const lorebookEntryChanges = pending.filter(
      (c): c is Extract<VaultPendingChange, { entityType: 'lorebook-entry' }> =>
        c.entityType === 'lorebook-entry',
    )
    const otherChanges = pending.filter((c) => c.entityType !== 'lorebook-entry')

    // For lorebook-entry changes: group by lorebook, then process deletes/merges in descending order
    const byLorebook = new SvelteMap<
      string,
      Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>[]
    >()
    for (const change of lorebookEntryChanges) {
      const group = byLorebook.get(change.lorebookId) ?? []
      group.push(change)
      byLorebook.set(change.lorebookId, group)
    }

    // Process each lorebook's changes: deletes/merges descending, then creates/updates ascending
    for (const [_lorebookId, changes] of byLorebook) {
      const deletesAndMerges = changes.filter((c) => c.action === 'delete' || c.action === 'merge')
      const createsAndUpdates = changes.filter(
        (c) => c.action === 'create' || c.action === 'update',
      )

      // Sort deletes/merges by descending entryIndex (or highest entryIndex for merges)
      deletesAndMerges.sort((a, b) => {
        const aIdx = a.action === 'delete' ? a.entryIndex : Math.max(...a.entryIndices)
        const bIdx = b.action === 'delete' ? b.entryIndex : Math.max(...b.entryIndices)
        return bIdx - aIdx
      })

      // Process deletes/merges first (descending order)
      for (const change of deletesAndMerges) {
        try {
          const effectiveChange = this._editedChanges.get(change.id) ?? change
          await service.applyChange(effectiveChange)
          service.handleApproval(change, true)

          const edits = new SvelteMap(this._editedChanges)
          edits.delete(change.id)
          this._editedChanges = edits

          for (const c of this.pendingChanges) {
            if (c.id === change.id) c.status = 'approved'
          }

          // Re-index remaining pending changes after each delete/merge
          this._reindexAfterApproval(effectiveChange)
        } catch (e) {
          return e instanceof Error ? e.message : 'Failed to apply change'
        }
      }

      // Process creates/updates (order doesn't matter for index shifting)
      for (const change of createsAndUpdates) {
        try {
          const effectiveChange = this._editedChanges.get(change.id) ?? change
          await service.applyChange(effectiveChange)
          service.handleApproval(change, true)

          const edits = new SvelteMap(this._editedChanges)
          edits.delete(change.id)
          this._editedChanges = edits

          for (const c of this.pendingChanges) {
            if (c.id === change.id) c.status = 'approved'
          }
        } catch (e) {
          return e instanceof Error ? e.message : 'Failed to apply change'
        }
      }
    }

    // Process non-lorebook-entry changes (characters, scenarios, lorebooks)
    for (const change of otherChanges) {
      try {
        const effectiveChange = this._editedChanges.get(change.id) ?? change
        await service.applyChange(effectiveChange)
        service.handleApproval(change, true)

        const edits = new SvelteMap(this._editedChanges)
        edits.delete(change.id)
        this._editedChanges = edits

        for (const c of this.pendingChanges) {
          if (c.id === change.id) c.status = 'approved'
        }
      } catch (e) {
        return e instanceof Error ? e.message : 'Failed to apply change'
      }
    }

    // Auto-close unless active editor is lorebook-related
    if (this.activeChange) {
      this._autoCloseAfterAction(this.activeChange)
    }

    this.pendingChanges = [...this.pendingChanges]
    return null // success
  }

  /** Get the live version of a change (includes pending status updates) */
  getLiveChange(changeId: string): VaultPendingChange | undefined {
    return this.pendingChanges.find((c) => c.id === changeId)
  }

  /** Reset all editor state (for new conversations) */
  reset(): void {
    this.pendingChanges = []
    this.activeChange = null
    this.editorOpen = false
    this.editorDirty = false
    this.viewMode = false
    this.viewEntityId = null
    this.viewEntityType = null
    this._editedChanges = new SvelteMap()
  }

  // ── Internal helpers ──────────────────────────────────────────────────

  /** Check if the editor is already showing a lorebook matching the incoming change */
  private isShowingSameLorebook(incoming: VaultPendingChange): boolean {
    if (!this.editorOpen || !this.activeChange) return false

    const activeType = this.activeChange.entityType
    if (activeType !== 'lorebook' && activeType !== 'lorebook-entry') return false

    const activeLorebookId = this.currentLorebookId
    const incomingLorebookId =
      incoming.entityType === 'lorebook-entry'
        ? incoming.lorebookId
        : incoming.entityType === 'lorebook'
          ? incoming.entityId
          : null

    return incomingLorebookId != null && activeLorebookId === incomingLorebookId
  }

  /** After approval/rejection, keep the editor open for continued iteration.
   * For characters and scenarios, transition to view mode so the user can
   * review the updated entity and make direct edits or request more changes.
   * For lorebook deletes, close entirely (the entity is gone).
   *
   * If the editor is currently showing a different change for the same entity
   * type & ID, still transition to view mode so the user sees the updated
   * entity including the just-approved change. If it's a different entity
   * entirely, skip the transition so we don't yank the user to a different
   * entity.
   */
  private _autoCloseAfterAction(change: VaultPendingChange): void {
    const isLorebook = change.entityType === 'lorebook'
    const isLorebookEntry = change.entityType === 'lorebook-entry'
    const isDelete = change.action === 'delete'

    // Lorebook deletes close the editor entirely (the entity is gone)
    if (isLorebook && isDelete) {
      this.closeEditor()
      return
    }

    // Lorebook entries and lorebook creates/updates keep existing behavior
    // (the lorebook editor handles multi-entry iteration natively)
    if (isLorebookEntry || (isLorebook && !isDelete)) return

    // Characters and scenarios: transition to view mode so the user can
    // review the result and make direct edits or continue iterating.
    const entityId = 'entityId' in change ? (change.entityId as string) : null
    if (!entityId) {
      this.closeEditor()
      return
    }

    const entityType = change.entityType === 'character' ? 'character' : 'scenario'

    // If the editor is open and showing either the same change or another
    // change for the same entity, transition to view mode for that entity.
    // If the editor is showing a completely different entity, skip the
    // transition — we don't want to yank the user away from their work.
    if (this.editorOpen && this.activeChange) {
      const activeEntityId =
        'entityId' in this.activeChange ? (this.activeChange.entityId as string) : null
      const activeEntityType = this.activeChange.entityType

      if (activeEntityId === entityId && activeEntityType === change.entityType) {
        // Same entity — transition to view mode so the approved change
        // is visible in the composed data
        this.viewMode = true
        this.viewEntityId = entityId
        this.viewEntityType = entityType
      }
      // Different entity — leave editor as-is; the composed data getter
      // now reads from the vault so it will reflect the approved change
    }
  }

  /**
   * Re-index remaining pending lorebook-entry changes after an approval
   * that modified the entries array (delete or merge).
   * Mutates in-place so all refs (including snapshots in approveAll) stay current.
   */
  private _reindexAfterApproval(approvedChange: VaultPendingChange): void {
    // Only lorebook-entry changes need re-indexing
    if (approvedChange.entityType !== 'lorebook-entry') return
    if (approvedChange.action !== 'delete' && approvedChange.action !== 'merge') return

    const lorebookId =
      approvedChange.entityType === 'lorebook-entry' ? approvedChange.lorebookId : null
    if (!lorebookId) return

    // Update pendingChanges in-place (entries are $state proxy objects)
    for (let i = 0; i < this.pendingChanges.length; i++) {
      const c = this.pendingChanges[i]
      if (
        c.entityType !== 'lorebook-entry' ||
        c.status !== 'pending' ||
        c.id === approvedChange.id
      ) {
        continue
      }
      const entryChange = c as Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>
      if (entryChange.lorebookId !== lorebookId) continue

      const result = this._shiftIndexForApproval(approvedChange, entryChange)
      if (result !== null) {
        if (entryChange.action === 'delete' || entryChange.action === 'update') {
          entryChange.entryIndex = result
        }
        // For merge, entryIndices was already mutated in-place by _shiftIndexForApproval
      }
    }

    // Also update _editedChanges — SvelteMap values are proxied, mutate in-place
    for (const id of [...this._editedChanges.keys()]) {
      const edited = this._editedChanges.get(id)
      if (
        !edited ||
        edited.entityType !== 'lorebook-entry' ||
        edited.id === approvedChange.id ||
        (edited as Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>).lorebookId !==
          lorebookId
      ) {
        continue
      }
      const entryEdited = edited as Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>
      const result = this._shiftIndexForApproval(approvedChange, entryEdited)
      if (result !== null) {
        if (entryEdited.action === 'delete' || entryEdited.action === 'update') {
          entryEdited.entryIndex = result
        }
        // For merge, entryIndices was already mutated in-place by _shiftIndexForApproval
      }
    }
  }

  /**
   * Compute the new index for a pending change after an approval.
   * Returns null if no change needed.
   */
  private _shiftIndexForApproval(
    approved: VaultPendingChange,
    pending: Extract<VaultPendingChange, { entityType: 'lorebook-entry' }>,
  ): number | null {
    if (approved.entityType !== 'lorebook-entry') return null

    if (approved.action === 'delete') {
      const deletedIndex = approved.entryIndex
      if (pending.action === 'delete' || pending.action === 'update') {
        const pendingIndex = pending.entryIndex
        if (pendingIndex > deletedIndex) {
          return pendingIndex - 1
        }
      } else if (pending.action === 'merge') {
        // Merge has entryIndices array - shift each one
        const newIndices = pending.entryIndices.map((idx) => (idx > deletedIndex ? idx - 1 : idx))
        // Check if array changed
        if (newIndices.some((idx, i) => idx !== pending.entryIndices[i])) {
          ;(
            pending as Extract<
              VaultPendingChange,
              { entityType: 'lorebook-entry'; action: 'merge' }
            >
          ).entryIndices = newIndices
          // Return 0 to signal a change happened (the caller will use the mutated entryIndices)
          return 0
        }
      }
    } else if (approved.action === 'merge') {
      // Merge removes source entries (in descending order) then appends the result
      const removedIndices = [...approved.entryIndices].sort((a, b) => b - a) // descending
      let totalShift = 0
      let mergeChanged = false
      for (const removedIdx of removedIndices) {
        if (pending.action === 'delete' || pending.action === 'update') {
          if (pending.entryIndex > removedIdx) {
            totalShift++
          }
        } else if (pending.action === 'merge') {
          // Shift indices in the merge's entryIndices array
          const newIndices = pending.entryIndices.map((idx) => (idx > removedIdx ? idx - 1 : idx))
          ;(
            pending as Extract<
              VaultPendingChange,
              { entityType: 'lorebook-entry'; action: 'merge' }
            >
          ).entryIndices = newIndices
          mergeChanged = true
        }
      }
      if ((pending.action === 'delete' || pending.action === 'update') && totalShift > 0) {
        return pending.entryIndex - totalShift
      }
      if (pending.action === 'merge' && mergeChanged) {
        return 0
      }
    }
    return null
  }
}

export const vaultEditor = new VaultEditorStore()

import { type Genre, scenarioService } from '$lib/services/ai/wizard/ScenarioService'
import { aiService } from '$lib/services/ai'
import { TranslationService } from '$lib/services/ai/utils/TranslationService'
import { settings } from '$lib/stores/settings.svelte'
import { characterVault } from '$lib/stores/characterVault.svelte'
import type { StoryMode, POV, VaultCharacter } from '$lib/types'
import { descriptorsToString, stringToDescriptors } from '$lib/utils/visualDescriptors'
import { CharacterCardImport } from '$lib/services/characterCardImport'
import type {
  ExpandedSetting,
  GeneratedCharacter,
  GeneratedProtagonist,
} from '$lib/services/ai/sdk'
import { SvelteSet } from 'svelte/reactivity'
import { generatePlainText } from '$lib/services/ai/sdk'

export class CharacterStore {
  // Protagonist State
  protagonist = $state<GeneratedProtagonist | null>(null)
  protagonistTranslated = $state<GeneratedProtagonist | null>(null)
  isGeneratingProtagonist = $state(false)
  isExpandingCharacter = $state(false)
  isRefiningCharacter = $state(false)
  protagonistError = $state<string | null>(null)
  isGeneratingPortraitDescription = $state(false)

  // Manual Input State
  manualCharacterName = $state('')
  manualCharacterDescription = $state('')
  manualCharacterBackground = $state('')
  manualCharacterMotivation = $state('')
  manualCharacterTraits = $state('')
  showManualInput = $state(true)
  characterElaborationGuidance = $state('')

  // Supporting Characters State
  supportingCharacters = $state<GeneratedCharacter[]>([])
  supportingCharactersTranslated = $state<GeneratedCharacter[]>([])
  isGeneratingCharacters = $state(false)

  // Supporting Character Form State
  showSupportingCharacterForm = $state(false)
  editingSupportingCharacterIndex = $state<number | null>(null)
  supportingCharacterName = $state('')
  supportingCharacterRole = $state('')
  supportingCharacterDescription = $state('')
  supportingCharacterRelationship = $state('')
  supportingCharacterTraits = $state('')
  isElaboratingSupportingCharacter = $state(false)
  supportingCharacterGuidance = $state('')
  supportingCharacterVaultId = $state<string | null>(null)

  // Vault Integration
  showProtagonistVaultPicker = $state(false)
  showSupportingVaultPicker = $state(false)
  savedToVaultConfirm = $state(false)

  // Card Import State
  isImportingCard = $state(false)
  cardImportError = $state<string | null>(null)
  importedCardNpcs = $state<GeneratedCharacter[]>([])
  cardImportFileInput: HTMLInputElement | null = null // DOM ref, maybe keep in component but logic needs access?
  // Stores these from card import for use in other steps (Setting/Opening)
  cardImportedTitle = $state<string | null>(null)
  cardImportedFirstMessage = $state<string | null>(null)
  cardImportedAlternateGreetings = $state<string[]>([])
  selectedGreetingIndex = $state<number>(0)

  // Also setting seed from card import
  importedSettingSeed = $state<string | null>(null)

  // Derived
  protagonistDisplay = $derived(this.protagonistTranslated ?? this.protagonist)
  supportingCharactersDisplay = $derived(
    this.supportingCharactersTranslated.length > 0
      ? this.supportingCharactersTranslated
      : this.supportingCharacters,
  )

  // Protagonist Actions
  async generatePortraitDescription(expandedSetting: ExpandedSetting | null): Promise<void> {
    if (this.isGeneratingPortraitDescription) return
    this.isGeneratingPortraitDescription = true
    this.protagonistError = null
    try {
      this.manualCharacterDescription = await generatePlainText(
        {
          presetId: settings.servicePresetAssignments['wizard:characterElaboration'] || 'agentic',
          system:
            'You write concise physical and visual character descriptions for portrait generation. Return only the description, with no headings or commentary.',
          prompt: `Create a specific portrait-ready description for this character. Preserve the supplied identity and avoid inventing major biography. Include visible age range, build, face, hair, eyes, clothing, and distinctive features.\n\nName: ${this.manualCharacterName || 'Unnamed character'}\nCurrent description: ${this.manualCharacterDescription || 'None'}\nTraits: ${this.manualCharacterTraits || 'None'}\nSetting: ${expandedSetting?.description || 'Not specified'}`,
        },
        'wizard:portraitDescription',
      )
    } catch (error) {
      this.protagonistError =
        error instanceof Error ? error.message : 'Failed to generate description'
    } finally {
      this.isGeneratingPortraitDescription = false
    }
  }

  async generateProtagonist(
    expandedSetting: ExpandedSetting,
    selectedGenre: Genre,
    selectedMode: StoryMode,
    selectedPOV: POV,
    customGenre?: string,
  ) {
    if (!expandedSetting || this.isGeneratingProtagonist) return

    this.isGeneratingProtagonist = true
    this.protagonistError = null

    try {
      this.protagonist = await scenarioService.generateProtagonist(
        expandedSetting,
        selectedGenre,
        selectedMode,
        selectedPOV,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:protagonistGeneration'],
      )

      await this.translateProtagonist()
    } catch (error) {
      console.error('Failed to generate protagonist:', error)
      this.protagonistError =
        error instanceof Error ? error.message : 'Failed to generate protagonist'
    } finally {
      this.isGeneratingProtagonist = false
    }
  }

  useManualCharacter() {
    if (!this.manualCharacterName.trim()) return

    this.protagonist = {
      name: this.manualCharacterName.trim(),
      description: this.manualCharacterDescription.trim() || 'A mysterious figure.',
      background: this.manualCharacterBackground.trim() || '',
      motivation: this.manualCharacterMotivation.trim() || '',
      traits: this.manualCharacterTraits.trim()
        ? this.manualCharacterTraits
            .split(',')
            .map((t) => t.trim())
            .filter(Boolean)
        : [],
    }
    this.showManualInput = false
  }

  editCharacter() {
    if (this.protagonist) {
      this.manualCharacterName = this.protagonist.name || ''
      this.manualCharacterDescription = this.protagonist.description || ''
      this.manualCharacterBackground = this.protagonist.background || ''
      this.manualCharacterMotivation = this.protagonist.motivation || ''
      this.manualCharacterTraits = this.protagonist.traits?.join(', ') || ''
    }
    this.showManualInput = true
    this.protagonist = null
  }

  async elaborateCharacter(
    expandedSetting: ExpandedSetting | null,
    selectedGenre: Genre,
    customGenre?: string,
    useCurrentProtagonist: boolean = false,
  ) {
    if (this.isExpandingCharacter) return

    const sourceName =
      useCurrentProtagonist && this.protagonist
        ? this.protagonist.name
        : this.manualCharacterName.trim()
    const sourceDescription =
      useCurrentProtagonist && this.protagonist
        ? this.protagonist.description
        : this.manualCharacterDescription.trim()
    const sourceBackground =
      useCurrentProtagonist && this.protagonist
        ? this.protagonist.background
        : this.manualCharacterBackground.trim()
    const sourceMotivation =
      useCurrentProtagonist && this.protagonist
        ? this.protagonist.motivation
        : this.manualCharacterMotivation.trim()
    const sourceTraits =
      useCurrentProtagonist && this.protagonist
        ? this.protagonist.traits
        : this.manualCharacterTraits.trim()
          ? this.manualCharacterTraits
              .split(',')
              .map((t) => t.trim())
              .filter(Boolean)
          : undefined

    const hasInput = sourceName || sourceDescription || sourceBackground || sourceMotivation

    if (!hasInput) {
      this.protagonistError = 'Please enter at least some character details to elaborate on.'
      return
    }

    this.isExpandingCharacter = true
    this.protagonistError = null

    try {
      this.protagonist = await scenarioService.elaborateCharacter(
        {
          name: sourceName || undefined,
          description: sourceDescription || undefined,
          background: sourceBackground || undefined,
          motivation: sourceMotivation || undefined,
          traits: sourceTraits,
        },
        expandedSetting,
        selectedGenre,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:characterElaboration'],
        this.characterElaborationGuidance.trim() || undefined,
      )
      this.showManualInput = false
      this.characterElaborationGuidance = ''

      await this.translateProtagonist()
    } catch (error) {
      console.error('Failed to elaborate character:', error)
      this.protagonistError =
        error instanceof Error ? error.message : 'Failed to elaborate character'
    } finally {
      this.isExpandingCharacter = false
    }
  }

  async elaborateCharacterFurther(
    expandedSetting: ExpandedSetting | null,
    selectedGenre: Genre,
    customGenre?: string,
  ) {
    if (!this.protagonist || this.isRefiningCharacter) return

    this.isRefiningCharacter = true
    this.protagonistError = null

    try {
      this.protagonist = await scenarioService.refineCharacter(
        this.protagonist,
        expandedSetting,
        selectedGenre,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:characterRefinement'],
        this.characterElaborationGuidance.trim() || undefined,
      )
      this.characterElaborationGuidance = ''

      await this.translateProtagonist()
    } catch (error) {
      console.error('Failed to refine character:', error)
      this.protagonistError = error instanceof Error ? error.message : 'Failed to refine character'
    } finally {
      this.isRefiningCharacter = false
    }
  }

  // Supporting Character Actions
  async generateCharacters(
    expandedSetting: ExpandedSetting,
    selectedGenre: Genre,
    customGenre?: string,
  ) {
    if (!expandedSetting || !this.protagonist || this.isGeneratingCharacters) return

    this.isGeneratingCharacters = true

    try {
      this.supportingCharacters = await scenarioService.generateCharacters(
        expandedSetting,
        this.protagonist,
        selectedGenre,
        3,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:supportingCharacters'],
      )

      await this.translateSupportingCharacters()
    } catch (error) {
      console.error('Failed to generate characters:', error)
    } finally {
      this.isGeneratingCharacters = false
    }
  }

  openSupportingCharacterForm() {
    this.editingSupportingCharacterIndex = null
    this.supportingCharacterName = ''
    this.supportingCharacterRole = ''
    this.supportingCharacterDescription = ''
    this.supportingCharacterRelationship = ''
    this.supportingCharacterTraits = ''
    this.showSupportingCharacterForm = true
    this.supportingCharacterVaultId = null
  }

  editSupportingCharacter(index: number) {
    const char = this.supportingCharacters[index]
    this.editingSupportingCharacterIndex = index
    this.supportingCharacterName = char.name
    this.supportingCharacterRole = char.role || ''
    this.supportingCharacterDescription = char.description
    this.supportingCharacterRelationship = char.relationship || ''
    this.supportingCharacterTraits = char.traits?.join(', ') || ''
    this.showSupportingCharacterForm = true
  }

  cancelSupportingCharacterForm() {
    this.showSupportingCharacterForm = false
    this.editingSupportingCharacterIndex = null
    this.supportingCharacterName = ''
    this.supportingCharacterRole = ''
    this.supportingCharacterDescription = ''
    this.supportingCharacterRelationship = ''
    this.supportingCharacterTraits = ''
    this.supportingCharacterGuidance = ''
    this.supportingCharacterVaultId = null
  }

  useSupportingCharacterAsIs() {
    if (!this.supportingCharacterName.trim()) return

    const newChar: GeneratedCharacter = {
      npcId:
        this.editingSupportingCharacterIndex !== null
          ? this.supportingCharacters[this.editingSupportingCharacterIndex]?.npcId
          : crypto.randomUUID(),
      name: this.supportingCharacterName.trim(),
      role: this.supportingCharacterRole.trim() || 'supporting',
      description: this.supportingCharacterDescription.trim() || '',
      relationship: this.supportingCharacterRelationship.trim() || '',
      traits: this.supportingCharacterTraits.trim()
        ? this.supportingCharacterTraits
            .split(',')
            .map((t) => t.trim())
            .filter(Boolean)
        : [],
      vaultId: this.supportingCharacterVaultId ?? undefined,
    }

    if (this.editingSupportingCharacterIndex !== null) {
      this.supportingCharacters[this.editingSupportingCharacterIndex] = newChar
      // Trigger update
      this.supportingCharacters = [...this.supportingCharacters]
    } else {
      this.supportingCharacters = [...this.supportingCharacters, newChar]
    }

    this.cancelSupportingCharacterForm()
  }

  deleteSupportingCharacter(index: number) {
    this.supportingCharacters = this.supportingCharacters.filter((_, i) => i !== index)
  }

  async elaborateSupportingCharacter(
    expandedSetting: ExpandedSetting | null,
    selectedGenre: Genre,
    customGenre?: string,
  ) {
    if (this.isElaboratingSupportingCharacter) return

    const hasInput =
      this.supportingCharacterName.trim() ||
      this.supportingCharacterDescription.trim() ||
      this.supportingCharacterRelationship.trim()

    if (!hasInput) return

    this.isElaboratingSupportingCharacter = true

    try {
      const elaborated = await scenarioService.elaborateCharacter(
        {
          name: this.supportingCharacterName.trim() || undefined,
          description: this.supportingCharacterDescription.trim() || undefined,
          background: this.supportingCharacterRelationship.trim() || undefined,
          motivation: this.supportingCharacterRole.trim() || undefined,
          traits: this.supportingCharacterTraits.trim()
            ? this.supportingCharacterTraits
                .split(',')
                .map((t) => t.trim())
                .filter(Boolean)
            : undefined,
        },
        expandedSetting,
        selectedGenre,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:characterElaboration'],
        this.supportingCharacterGuidance.trim() || undefined,
      )

      const newChar: GeneratedCharacter = {
        npcId:
          this.editingSupportingCharacterIndex !== null
            ? this.supportingCharacters[this.editingSupportingCharacterIndex]?.npcId
            : crypto.randomUUID(),
        name: elaborated.name,
        role: this.supportingCharacterRole.trim() || 'supporting',
        description: elaborated.description,
        relationship: this.supportingCharacterRelationship.trim() || elaborated.background || '',
        traits: elaborated.traits || [],
      }

      if (this.editingSupportingCharacterIndex !== null) {
        this.supportingCharacters[this.editingSupportingCharacterIndex] = newChar
        this.supportingCharacters = [...this.supportingCharacters]
      } else {
        this.supportingCharacters = [...this.supportingCharacters, newChar]
      }

      this.supportingCharacterGuidance = ''
      this.cancelSupportingCharacterForm()
    } catch (error) {
      console.error('Failed to elaborate supporting character:', error)
    } finally {
      this.isElaboratingSupportingCharacter = false
    }
  }

  // Vault Actions
  handleSelectProtagonistFromVault(
    vaultCharacter: VaultCharacter,
    visualDescriptorsSetter: (v: string) => void,
    portraitSetter: (v: string | null) => void,
  ) {
    this.manualCharacterName = vaultCharacter.name
    this.manualCharacterDescription = vaultCharacter.description || ''
    const metadata = (vaultCharacter.metadata as Record<string, any>) || {}
    this.manualCharacterBackground = (metadata.background as string) || ''
    this.manualCharacterMotivation = (metadata.motivation as string) || ''
    this.manualCharacterTraits = vaultCharacter.traits.join(', ')
    visualDescriptorsSetter(descriptorsToString(vaultCharacter.visualDescriptors))
    portraitSetter(vaultCharacter.portrait)

    this.showProtagonistVaultPicker = false
    this.showManualInput = true
    this.useManualCharacter()
  }

  async handleSaveProtagonistToVault(visualDescriptors: string, portrait: string | null) {
    if (!this.manualCharacterName.trim()) return

    if (!characterVault.isLoaded) {
      await characterVault.load()
    }

    await characterVault.add({
      name: this.manualCharacterName.trim(),
      description: this.manualCharacterDescription.trim() || null,
      traits: this.manualCharacterTraits
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean),
      visualDescriptors: stringToDescriptors(visualDescriptors),
      portrait: portrait,
      tags: [],
      favorite: false,
      source: 'manual',
      originalStoryId: null,
      metadata: {
        characterType: 'protagonist',
        background: this.manualCharacterBackground.trim() || null,
        motivation: this.manualCharacterMotivation.trim() || null,
      },
    })

    this.savedToVaultConfirm = true
    setTimeout(() => (this.savedToVaultConfirm = false), 2000)
  }

  handleSelectSupportingFromVault(
    vaultCharacter: VaultCharacter,
    visualDescriptorsSetter: (name: string, v: string) => void,
    portraitSetter: (name: string, v: string | null) => void,
  ) {
    this.supportingCharacterName = vaultCharacter.name
    const metadata = (vaultCharacter.metadata as Record<string, any>) || {}
    this.supportingCharacterRole = (metadata.role as string) || ''
    this.supportingCharacterDescription = vaultCharacter.description || ''
    this.supportingCharacterRelationship = (metadata.relationshipTemplate as string) || ''
    this.supportingCharacterTraits = vaultCharacter.traits.join(', ')

    visualDescriptorsSetter(
      vaultCharacter.name,
      descriptorsToString(vaultCharacter.visualDescriptors),
    )
    portraitSetter(vaultCharacter.name, vaultCharacter.portrait)

    this.supportingCharacterVaultId = vaultCharacter.id

    this.showSupportingVaultPicker = false
    this.showSupportingCharacterForm = true
    this.useSupportingCharacterAsIs()
  }

  // Translation helpers
  async translateProtagonist() {
    const translationSettings = settings.translationSettings
    if (this.protagonist && TranslationService.shouldTranslate(translationSettings)) {
      try {
        const fields: Record<string, string> = {
          name: this.protagonist.name,
          description: this.protagonist.description,
        }

        if (this.protagonist.background) fields.background = this.protagonist.background
        if (this.protagonist.motivation) fields.motivation = this.protagonist.motivation
        if (this.protagonist.traits?.length) fields.traits = this.protagonist.traits.join(', ')

        const translated = await aiService.translateWizardBatch(
          fields,
          translationSettings.targetLanguage,
        )

        this.protagonistTranslated = {
          ...this.protagonist,
          name: translated.name || this.protagonist.name,
          description: translated.description || this.protagonist.description,
          background: translated.background || this.protagonist.background,
          motivation: translated.motivation || this.protagonist.motivation,
          traits: translated.traits
            ? translated.traits
                .split(',')
                .map((t) => t.trim())
                .filter(Boolean)
            : this.protagonist.traits,
        }
      } catch (translationError) {
        console.error('Protagonist translation failed (non-fatal):', translationError)
        this.protagonistTranslated = null
      }
    } else {
      this.protagonistTranslated = null
    }
  }

  async translateSupportingCharacters() {
    const translationSettings = settings.translationSettings
    if (
      this.supportingCharacters.length > 0 &&
      TranslationService.shouldTranslate(translationSettings)
    ) {
      try {
        this.supportingCharactersTranslated = await Promise.all(
          this.supportingCharacters.map((char) =>
            this.translateSupportingCharacter(char, translationSettings.targetLanguage),
          ),
        )
      } catch (translationError) {
        console.error('Supporting characters translation failed (non-fatal):', translationError)
        this.supportingCharactersTranslated = []
      }
    } else {
      this.supportingCharactersTranslated = []
    }
  }

  private async translateSupportingCharacter(
    char: GeneratedCharacter,
    targetLanguage: string,
  ): Promise<GeneratedCharacter> {
    const fields: Record<string, string> = {
      name: char.name,
      description: char.description,
    }

    if (char.role) fields.role = char.role
    if (char.relationship) fields.relationship = char.relationship
    if (char.traits?.length) fields.traits = char.traits.join(', ')

    const translated = await aiService.translateWizardBatch(fields, targetLanguage)

    return {
      ...char,
      name: translated.name || char.name,
      description: translated.description || char.description,
      role: translated.role || char.role,
      relationship: translated.relationship || char.relationship,
      traits: translated.traits
        ? translated.traits
            .split(',')
            .map((t) => t.trim())
            .filter(Boolean)
        : char.traits,
    }
  }

  // Card Import
  async handleCardImport(file: File, selectedGenre: Genre) {
    this.cardImportError = null
    this.isImportingCard = true

    try {
      const content = await CharacterCardImport.readFile(file)
      const result = await CharacterCardImport.clean(content, selectedGenre)

      if (!result.success && result.errors.length > 0) {
        this.cardImportError = result.errors.join('; ')
      }

      if (result.settingSeed) {
        this.importedSettingSeed = result.settingSeed
      }

      if (result.npcs && result.npcs.length > 0) {
        this.supportingCharacters = [...this.supportingCharacters, ...result.npcs]
        this.importedCardNpcs = result.npcs
      }

      if (result.storyTitle) {
        this.cardImportedTitle = result.storyTitle
      }
      if (result.firstMessage) {
        this.cardImportedFirstMessage = result.firstMessage
        this.cardImportedAlternateGreetings = result.alternateGreetings || []
        this.selectedGreetingIndex = 0
      }

      if (this.cardImportFileInput) {
        this.cardImportFileInput.value = ''
      }
    } catch (err) {
      this.cardImportError = err instanceof Error ? err.message : 'Failed to import character card'
    } finally {
      this.isImportingCard = false
    }
  }

  clearCardImport() {
    if (this.importedCardNpcs.length > 0) {
      const importedNames = new SvelteSet(this.importedCardNpcs.map((n) => n.name))
      this.supportingCharacters = this.supportingCharacters.filter(
        (c) => !importedNames.has(c.name),
      )
    }
    this.importedCardNpcs = []
    this.cardImportError = null
    this.cardImportedTitle = null
    this.cardImportedFirstMessage = null
    this.cardImportedAlternateGreetings = []
    this.selectedGreetingIndex = 0
    this.importedSettingSeed = null

    if (this.cardImportFileInput) {
      this.cardImportFileInput.value = ''
    }
  }
}

import { settings } from '$lib/stores/settings.svelte'
import {
  hasRequiredCredentials,
  getProviderDisplayName,
  generatePortrait as sdkGeneratePortrait,
} from '$lib/services/ai/image'
import { database } from '$lib/services/database'
import { ContextBuilder } from '$lib/services/context'
import { DEFAULT_FALLBACK_STYLE_PROMPT } from '$lib/services/ai/image/constants'
import { createLogger } from '$lib/log'
import type { GeneratedCharacter, GeneratedProtagonist } from '$lib/services/ai/sdk'

const log = createLogger('WizardPortrait')

/**
 * Get the style prompt for the selected style ID.
 * Image style templates are external (raw text) -- fetched directly from the database.
 */
async function getStylePrompt(styleId: string): Promise<string> {
  try {
    const template = await database.getPackTemplate('default-pack', styleId)
    if (template?.content) {
      return template.content
    }
  } catch {
    // Template not found, use fallback
  }
  return DEFAULT_FALLBACK_STYLE_PROMPT
}

/**
 * Build a portrait generation prompt using ContextBuilder pipeline.
 */
async function buildPortraitPrompt(
  stylePrompt: string,
  visualDescriptors: string,
  characterName: string,
): Promise<string> {
  const ctx = new ContextBuilder()
  ctx.add({
    mode: 'adventure',
    pov: 'second',
    tense: 'present',
    protagonistName: '',
    imageStylePrompt: stylePrompt,
    visualDescriptors,
    characterName,
  })
  const { system } = await ctx.render('image-portrait-generation')
  return system
}

export class ImageStore {
  protagonistVisualDescriptors = $state('')
  protagonistPortrait = $state<string | null>(null)
  isGeneratingProtagonistPortrait = $state(false)
  isUploadingProtagonistPortrait = $state(false)
  portraitError = $state<string | null>(null)

  supportingCharacterVisualDescriptors = $state<Record<string, string>>({})
  supportingCharacterPortraits = $state<Record<string, string | null>>({})
  generatingPortraitName = $state<string | null>(null)
  uploadingCharacterName = $state<string | null>(null)

  // Actions
  async generateProtagonistPortrait(protagonist: GeneratedProtagonist | null) {
    if (!protagonist || this.isGeneratingProtagonistPortrait) return

    const imageSettings = settings.systemServicesSettings.imageGeneration

    log('Starting protagonist portrait generation', {
      protagonistName: protagonist.name,
      model: settings.getImageProfile(imageSettings.portraitProfileId ?? '')?.model ?? '',
      styleId: imageSettings.portraitStyleId,
    })

    if (!hasRequiredCredentials()) {
      const providerName = getProviderDisplayName()
      log('Missing credentials for provider', { provider: providerName })
      this.portraitError = `${providerName} API key required for portrait generation`
      return
    }

    const descriptors = this.protagonistVisualDescriptors.trim()
    if (!descriptors) {
      log('No visual descriptors provided')
      this.portraitError = 'Add appearance descriptors first'
      return
    }

    this.isGeneratingProtagonistPortrait = true
    this.portraitError = null

    try {
      const stylePrompt = await getStylePrompt(imageSettings.styleId)
      const portraitPrompt = await buildPortraitPrompt(stylePrompt, descriptors, protagonist.name)

      log('Sending protagonist portrait request', {
        promptLength: portraitPrompt.length,
      })

      const base64 = await sdkGeneratePortrait(portraitPrompt)

      log('Protagonist portrait generated successfully', {
        protagonistName: protagonist.name,
      })

      this.protagonistPortrait = `data:image/png;base64,${base64}`
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to generate portrait'
      log('Protagonist portrait generation failed', {
        protagonistName: protagonist.name,
        error: errorMessage,
      })
      this.portraitError = errorMessage
    } finally {
      this.isGeneratingProtagonistPortrait = false
    }
  }

  async generateSupportingCharacterPortrait(
    charName: string,
    supportingCharacters: GeneratedCharacter[],
  ) {
    const char = supportingCharacters.find((c) => c.name === charName)
    if (!char || this.generatingPortraitName !== null) return

    const imageSettings = settings.systemServicesSettings.imageGeneration

    log('Starting supporting character portrait generation', {
      characterName: charName,
      model: settings.getImageProfile(imageSettings.portraitProfileId ?? '')?.model ?? '',
      styleId: imageSettings.portraitStyleId,
    })

    if (!hasRequiredCredentials()) {
      const providerName = getProviderDisplayName()
      log('Missing credentials for provider', { provider: providerName })
      this.portraitError = `${providerName} API key required for portrait generation`
      return
    }

    const descriptors = (this.supportingCharacterVisualDescriptors[charName] || '').trim()
    if (!descriptors) {
      log('No visual descriptors provided for character', { characterName: charName })
      this.portraitError = `Add appearance descriptors for ${char.name} first`
      return
    }

    this.generatingPortraitName = charName
    this.portraitError = null

    try {
      const stylePrompt = await getStylePrompt(imageSettings.portraitStyleId)
      const portraitPrompt = await buildPortraitPrompt(stylePrompt, descriptors, char.name)

      log('Sending supporting character portrait request', {
        characterName: charName,
        promptLength: portraitPrompt.length,
      })

      const base64 = await sdkGeneratePortrait(portraitPrompt)

      log('Supporting character portrait generated successfully', {
        characterName: charName,
      })

      this.supportingCharacterPortraits[charName] = `data:image/png;base64,${base64}`
      // Force update for reactive map
      this.supportingCharacterPortraits = { ...this.supportingCharacterPortraits }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to generate portrait'
      log('Supporting character portrait generation failed', {
        characterName: charName,
        error: errorMessage,
      })
      this.portraitError = errorMessage
    } finally {
      this.generatingPortraitName = null
    }
  }

  removeProtagonistPortrait() {
    this.protagonistPortrait = null
    this.portraitError = null
  }

  removeSupportingCharacterPortrait(charName: string) {
    this.supportingCharacterPortraits[charName] = null
    this.supportingCharacterPortraits = { ...this.supportingCharacterPortraits }
    this.portraitError = null
  }

  async handleProtagonistPortraitUpload(event: Event) {
    const input = event.target as HTMLInputElement
    const file = input.files?.[0]
    if (!file) return

    this.isUploadingProtagonistPortrait = true
    this.portraitError = null

    try {
      if (!file.type.startsWith('image/')) {
        throw new Error('Please select an image file')
      }

      if (file.size > 5 * 1024 * 1024) {
        throw new Error('Image must be smaller than 5MB')
      }

      const reader = new FileReader()
      const dataUrl = await new Promise<string>((resolve, reject) => {
        reader.onload = () => {
          const result = reader.result
          if (typeof result !== 'string' || !result.startsWith('data:image/')) {
            reject(new Error('Failed to read image data'))
            return
          }
          resolve(result)
        }
        reader.onerror = () => reject(new Error('Failed to read file'))
        reader.readAsDataURL(file)
      })

      this.protagonistPortrait = dataUrl
    } catch (error) {
      this.portraitError = error instanceof Error ? error.message : 'Failed to upload portrait'
    } finally {
      this.isUploadingProtagonistPortrait = false
      input.value = ''
    }
  }

  async handleSupportingCharacterPortraitUpload(event: Event, charName: string) {
    const input = event.target as HTMLInputElement
    const file = input.files?.[0]
    if (!file) return

    this.uploadingCharacterName = charName
    this.portraitError = null

    try {
      if (!file.type.startsWith('image/')) {
        throw new Error('Please select an image file')
      }

      if (file.size > 5 * 1024 * 1024) {
        throw new Error('Image must be smaller than 5MB')
      }

      const reader = new FileReader()
      const dataUrl = await new Promise<string>((resolve, reject) => {
        reader.onload = () => {
          const result = reader.result
          if (typeof result !== 'string' || !result.startsWith('data:image/')) {
            reject(new Error('Failed to read image data'))
            return
          }
          resolve(result)
        }
        reader.onerror = () => reject(new Error('Failed to read file'))
        reader.readAsDataURL(file)
      })

      this.supportingCharacterPortraits[charName] = dataUrl
      this.supportingCharacterPortraits = { ...this.supportingCharacterPortraits }
    } catch (error) {
      this.portraitError = error instanceof Error ? error.message : 'Failed to upload portrait'
    } finally {
      this.uploadingCharacterName = null
      input.value = ''
    }
  }
}

import {
  type Genre,
  type Tense,
  type WizardData,
  scenarioService,
} from '$lib/services/ai/wizard/ScenarioService'
import { aiService } from '$lib/services/ai'
import { TranslationService } from '$lib/services/ai/utils/TranslationService'
import { settings } from '$lib/stores/settings.svelte'
import type { StoryMode, POV, VaultLorebook } from '$lib/types'
import type { ImportedLorebookItem } from '$lib/components/wizard/wizardTypes'
import type { GeneratedOpening } from '$lib/services/ai/sdk'

export class NarrativeStore {
  // Step 1: Mode
  selectedMode = $state<StoryMode>('adventure')

  // Step 2: Lorebook
  importedLorebooks = $state<ImportedLorebookItem[]>([])
  importError = $state<string | null>(null)

  // Step 3: Genre
  selectedGenre = $state<Genre>('fantasy')
  customGenre = $state('')

  // Step 8: Writing Style
  selectedPOV = $state<POV>('first')
  selectedTense = $state<Tense>('present')
  tone = $state('immersive and engaging')
  visualProseMode = $state(false)
  imageGenerationMode = $state<'none' | 'agentic' | 'inline'>('none')
  backgroundImagesEnabled = $state(false)
  referenceMode = $state(false)

  // Step 9: Opening
  storyTitle = $state('')
  openingGuidance = $state('')
  generatedOpening = $state<GeneratedOpening | null>(null)
  generatedOpeningTranslated = $state<GeneratedOpening | null>(null)
  isGeneratingOpening = $state(false)
  isRefiningOpening = $state(false)
  openingError = $state<string | null>(null)
  isEditingOpening = $state(false)
  openingDraft = $state('')
  manualOpeningText = $state('')

  // Card Import Integration (for Opening)
  cardImportedFirstMessage = $state<string | null>(null)
  cardImportedAlternateGreetings = $state<string[]>([])
  selectedGreetingIndex = $state<number>(0)

  // Derived
  importedEntries = $derived(this.importedLorebooks.flatMap((lb) => lb.entries))

  generatedOpeningDisplay = $derived(this.generatedOpeningTranslated ?? this.generatedOpening)

  constructor() {
    // Update default POV and tense when mode changes
    // $effect(() => {
    //   if (this.selectedMode === "creative-writing") {
    //     if (this.selectedPOV === "first" || this.selectedPOV === "second") {
    //       this.selectedTense = "past";
    //     } else {
    //       this.selectedPOV = "third";
    //       this.selectedTense = "past";
    //     }
    //   } else {
    //     this.selectedPOV = "first";
    //     this.selectedTense = "present";
    //   }
    // });
  }

  // Genre Actions
  setCustomGenre(genre: string) {
    this.customGenre = genre
    this.selectedGenre = 'custom'
  }

  // Lorebook Actions
  addLorebookFromVault(vaultLorebook: VaultLorebook) {
    const entries = vaultLorebook.entries.map((e) => ({
      ...e,
    }))

    // Ensure metadata matches LorebookImportResult structure
    const baseMetadata = vaultLorebook.metadata || {
      format: 'aventura',
      totalEntries: entries.length,
      entryBreakdown: {
        character: 0,
        location: 0,
        item: 0,
        faction: 0,
        concept: 0,
        event: 0,
      },
    }

    const metadata = {
      format: baseMetadata.format,
      totalEntries: baseMetadata.totalEntries,
      importedEntries: entries.length,
      skippedEntries: 0,
    }

    this.importedLorebooks = [
      ...this.importedLorebooks,
      {
        id: crypto.randomUUID(),
        vaultId: vaultLorebook.id,
        filename: `${vaultLorebook.name} (from Vault)`,
        result: {
          success: true,
          entries: entries,
          errors: [],
          warnings: [],
          metadata: metadata,
        },
        entries: entries,
        expanded: true,
      },
    ]
  }

  removeLorebook(id: string) {
    this.importedLorebooks = this.importedLorebooks.filter((lb) => lb.id !== id)
    if (this.importedLorebooks.length === 0) {
      this.importError = null
    }
  }

  toggleLorebookExpanded(id: string) {
    this.importedLorebooks = this.importedLorebooks.map((lb) =>
      lb.id === id ? { ...lb, expanded: !lb.expanded } : lb,
    )
  }

  clearAllLorebooks() {
    this.importedLorebooks = []
    this.importError = null
  }

  // Opening Actions
  async generateOpeningScene(wizardData: WizardData) {
    if (this.isGeneratingOpening) return

    this.isGeneratingOpening = true
    this.openingError = null
    this.clearOpeningEditState()
    this.manualOpeningText = ''

    const lorebookContext =
      this.importedEntries.length > 0
        ? this.importedEntries.map((e) => ({
            name: e.name,
            type: e.type,
            description: e.description,
            hiddenInfo: undefined,
          }))
        : undefined

    try {
      this.generatedOpening = await scenarioService.generateOpening(
        wizardData,
        settings.servicePresetAssignments['wizard:openingGeneration'],
        lorebookContext,
      )

      await this.translateOpening()
    } catch (error) {
      console.error('Failed to generate opening:', error)
      this.openingError = error instanceof Error ? error.message : 'Failed to generate opening'
    } finally {
      this.isGeneratingOpening = false
    }
  }

  async refineOpeningScene(wizardData: WizardData) {
    if (!this.generatedOpening || this.isRefiningOpening) return

    this.isRefiningOpening = true
    this.openingError = null

    const lorebookContext =
      this.importedEntries.length > 0
        ? this.importedEntries.map((e) => ({
            name: e.name,
            type: e.type,
            description: e.description,
            hiddenInfo: undefined,
          }))
        : undefined

    try {
      const currentOpening = this.storyTitle.trim()
        ? { ...this.generatedOpening, title: this.storyTitle.trim() }
        : this.generatedOpening

      this.generatedOpening = await scenarioService.refineOpening(
        wizardData,
        currentOpening,
        settings.servicePresetAssignments['wizard:openingRefinement'],
        lorebookContext,
      )
      this.clearOpeningEditState()
      await this.translateOpening()
    } catch (error) {
      console.error('Failed to refine opening:', error)
      this.openingError = error instanceof Error ? error.message : 'Failed to refine opening'
    } finally {
      this.isRefiningOpening = false
    }
  }

  async translateOpening() {
    const translationSettings = settings.translationSettings
    if (this.generatedOpening && TranslationService.shouldTranslate(translationSettings)) {
      try {
        const fields: Record<string, string> = {
          scene: this.generatedOpening.scene,
          title: this.generatedOpening.title,
        }
        if (this.generatedOpening.initialLocation?.name) {
          fields.locName = this.generatedOpening.initialLocation.name
        }
        if (this.generatedOpening.initialLocation?.description) {
          fields.locDesc = this.generatedOpening.initialLocation.description
        }

        const translated = await aiService.translateWizardBatch(
          fields,
          translationSettings.targetLanguage,
        )

        this.generatedOpeningTranslated = {
          ...this.generatedOpening,
          scene: translated.scene || this.generatedOpening.scene,
          title: translated.title || this.generatedOpening.title,
          initialLocation: this.generatedOpening.initialLocation
            ? {
                name: translated.locName || this.generatedOpening.initialLocation.name,
                description:
                  translated.locDesc || this.generatedOpening.initialLocation.description,
              }
            : this.generatedOpening.initialLocation,
        }
      } catch (translationError) {
        console.error('Opening translation failed (non-fatal):', translationError)
        this.generatedOpeningTranslated = null
      }
    } else {
      this.generatedOpeningTranslated = null
    }
  }

  clearOpeningEditState() {
    this.isEditingOpening = false
    this.openingDraft = ''
  }

  clearGeneratedOpening() {
    this.generatedOpening = null
    this.generatedOpeningTranslated = null
    this.openingError = null
  }

  startOpeningEdit() {
    if (!this.generatedOpening || this.isEditingOpening) return
    this.openingError = null
    this.openingDraft = this.generatedOpening.scene
    this.isEditingOpening = true
  }

  saveOpeningEdit() {
    if (!this.generatedOpening) return
    if (!this.openingDraft?.trim()) {
      this.openingError = 'Opening text cannot be empty'
      return
    }
    this.generatedOpening = {
      ...this.generatedOpening,
      title: this.storyTitle.trim() || this.generatedOpening.title,
      scene: this.openingDraft,
    }
    this.clearOpeningEditState()
  }

  cancelOpeningEdit() {
    if (!this.generatedOpening) return
    this.clearOpeningEditState()
  }

  useCardOpening(options?: {
    firstMessage?: string | null
    alternateGreetings?: string[]
    selectedGreetingIndex?: number
    title?: string | null
  }) {
    const firstMessage = options?.firstMessage ?? this.cardImportedFirstMessage
    const alternateGreetings = options?.alternateGreetings ?? this.cardImportedAlternateGreetings
    const selectedGreetingIndex = options?.selectedGreetingIndex ?? this.selectedGreetingIndex

    const selectedScene =
      selectedGreetingIndex === 0 ? firstMessage : alternateGreetings[selectedGreetingIndex - 1]

    // Default location if none exists (will be populated from setting if available in orchestrator)
    this.generatedOpening = {
      title: options?.title || this.storyTitle,
      scene: selectedScene || '',
      initialLocation: {
        name: 'Starting Location',
        description: 'The scene begins here.',
      },
    }
    this.openingError = null
    this.clearOpeningEditState()
  }
}

import { scenarioService, type Genre } from '$lib/services/ai/wizard/ScenarioService'
import { type ExpandedSetting } from '$lib/services/ai/sdk'
import { aiService } from '$lib/services/ai'
import { TranslationService } from '$lib/services/ai/utils/TranslationService'
import { settings } from '$lib/stores/settings.svelte'
import { scenarioVault } from '$lib/stores/scenarioVault.svelte'
import { LorebookImportExport } from '$lib/services/lorebookImportExport'
import type { GeneratedCharacter } from '$lib/services/ai/sdk'

export class SettingStore {
  settingSeed = $state('')
  expandedSetting = $state<ExpandedSetting | null>(null)
  expandedSettingTranslated = $state<ExpandedSetting | null>(null)
  isExpandingSetting = $state(false)
  isRefiningSetting = $state(false)
  settingError = $state<string | null>(null)
  settingElaborationGuidance = $state('')
  previousExpandedSetting = $state<ExpandedSetting | null>(null)
  previousSettingSeed = $state('')
  isEditingSetting = $state(false)

  // Scenario Selection
  selectedScenarioId = $state<string | null>(null)

  // Vault Integration
  showScenarioVaultPicker = $state(false)
  savedScenarioToVaultConfirm = $state(false)

  // Derived
  expandedSettingDisplay = $derived<ExpandedSetting | null>(
    this.expandedSettingTranslated ?? this.expandedSetting,
  )

  // Actions
  clearSettingEditState() {
    this.isEditingSetting = false
    this.previousExpandedSetting = null
    this.previousSettingSeed = ''
  }

  cancelSettingEdit() {
    if (!this.isEditingSetting) return
    this.expandedSetting = this.previousExpandedSetting
    this.settingSeed = this.previousSettingSeed
    this.clearSettingEditState()
  }

  useSettingAsIs() {
    if (!this.settingSeed.trim()) return
    this.clearSettingEditState()
    this.expandedSetting = {
      name: this.settingSeed.split('.')[0].trim().slice(0, 50) || 'Custom Setting',
      description: this.settingSeed.trim(),
      keyLocations: [],
      atmosphere: '',
      themes: [],
      potentialConflicts: [],
    }
  }

  editSetting() {
    if (!this.expandedSetting) return
    this.previousExpandedSetting = this.expandedSetting
    this.previousSettingSeed = this.settingSeed
    this.isEditingSetting = true
    this.settingSeed = this.expandedSetting.description
    this.expandedSetting = null
  }

  async expandSetting(
    selectedGenre: Genre,
    customGenre: string,
    importedEntries: LorebookImportExport.ImportedEntry[] = [],
    seedOverride?: string,
  ) {
    const seed = seedOverride ?? this.settingSeed
    if (!seed.trim() || this.isExpandingSetting) return

    this.isExpandingSetting = true
    this.settingError = null

    try {
      const lorebookContext =
        importedEntries.length > 0
          ? importedEntries.map((e) => ({
              name: e.name,
              type: e.type,
              description: e.description,
              hiddenInfo: undefined,
            }))
          : undefined

      this.expandedSetting = await scenarioService.expandSetting(
        seed,
        selectedGenre,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:settingExpansion'],
        lorebookContext,
        this.settingElaborationGuidance.trim() || undefined,
      )
      this.clearSettingEditState()
      this.settingElaborationGuidance = ''

      await this.translateSetting()
    } catch (error) {
      console.error('Failed to expand setting:', error)
      this.settingError = error instanceof Error ? error.message : 'Failed to expand setting'
    } finally {
      this.isExpandingSetting = false
    }
  }

  async expandSettingFurther(
    selectedGenre: Genre,
    customGenre: string,
    importedEntries: LorebookImportExport.ImportedEntry[] = [],
  ) {
    if (!this.expandedSetting || this.isRefiningSetting) return

    this.isRefiningSetting = true
    this.settingError = null

    try {
      const lorebookContext =
        importedEntries.length > 0
          ? importedEntries.map((e) => ({
              name: e.name,
              type: e.type,
              description: e.description,
              hiddenInfo: undefined,
            }))
          : undefined

      this.expandedSetting = await scenarioService.refineSetting(
        this.expandedSetting,
        selectedGenre,
        customGenre || undefined,
        settings.servicePresetAssignments['wizard:settingRefinement'],
        lorebookContext,
        this.settingElaborationGuidance.trim() || undefined,
      )
      this.clearSettingEditState()
      this.settingElaborationGuidance = ''

      await this.translateSetting()
    } catch (error) {
      console.error('Failed to refine setting:', error)
      this.settingError = error instanceof Error ? error.message : 'Failed to refine setting'
    } finally {
      this.isRefiningSetting = false
    }
  }

  async translateSetting() {
    const translationSettings = settings.translationSettings
    if (this.expandedSetting && TranslationService.shouldTranslate(translationSettings)) {
      try {
        this.expandedSettingTranslated = await this.translateExpandedSetting(
          this.expandedSetting,
          translationSettings.targetLanguage,
        )
      } catch (translationError) {
        console.error('Setting translation failed (non-fatal):', translationError)
        this.expandedSettingTranslated = null
      }
    } else {
      this.expandedSettingTranslated = null
    }
  }

  private async translateExpandedSetting(
    setting: ExpandedSetting,
    targetLanguage: string,
  ): Promise<ExpandedSetting> {
    const fields: Record<string, string> = {
      name: setting.name,
      description: setting.description,
    }

    if (setting.atmosphere) fields.atmosphere = setting.atmosphere
    if (setting.themes?.length) fields.themes = setting.themes.join(', ')
    if (setting.potentialConflicts?.length) fields.conflicts = setting.potentialConflicts.join('; ')
    ;(setting.keyLocations || []).forEach((loc, i) => {
      fields[`loc_${i}_name`] = loc.name
      if (loc.description) fields[`loc_${i}_desc`] = loc.description
    })

    const translated = await aiService.translateWizardBatch(fields, targetLanguage)

    const translatedLocations = (setting.keyLocations || []).map((loc, i) => ({
      name: translated[`loc_${i}_name`] || loc.name,
      description: translated[`loc_${i}_desc`] || loc.description,
    }))

    return {
      ...setting,
      name: translated.name || setting.name,
      description: translated.description || setting.description,
      atmosphere: translated.atmosphere || setting.atmosphere,
      keyLocations: translatedLocations,
      themes: translated.themes
        ? translated.themes
            .split(',')
            .map((t) => t.trim())
            .filter(Boolean)
        : setting.themes,
      potentialConflicts: translated.conflicts
        ? translated.conflicts
            .split(';')
            .map((c) => c.trim())
            .filter(Boolean)
        : setting.potentialConflicts,
    }
  }

  async saveScenarioToVault(
    storyTitle: string,
    supportingCharacters: GeneratedCharacter[],
    cardImportedFirstMessage: string | null,
    cardImportedAlternateGreetings: string[],
  ) {
    if (!this.settingSeed.trim()) return

    if (!scenarioVault.isLoaded) {
      await scenarioVault.load()
    }

    const vaultNpcs = supportingCharacters.map((c) => ({
      id: c.npcId || crypto.randomUUID(),
      name: c.name,
      role: c.role || 'supporting',
      description: c.description,
      relationship: c.relationship || '',
      traits: c.traits || [],
    }))

    await scenarioVault.saveFromWizard(
      storyTitle || 'Untitled Scenario',
      this.settingSeed,
      vaultNpcs,
      {
        description: this.expandedSetting?.description,
        firstMessage: cardImportedFirstMessage || undefined,
        alternateGreetings: cardImportedAlternateGreetings,
        tags: ['wizard'],
      },
    )

    this.savedScenarioToVaultConfirm = true
    setTimeout(() => (this.savedScenarioToVaultConfirm = false), 2000)
  }
}

