import {
  type ExpandedSetting,
  type GeneratedCharacter,
} from '$lib/services/ai/sdk/schemas/scenario'
import {
  scenarioService,
  type WizardData,
  type Genre,
} from '$lib/services/ai/wizard/ScenarioService'
import { TranslationService } from '$lib/services/ai/utils/TranslationService'
import { QUICK_START_SEEDS } from '$lib/services/templates'
import { replaceUserPlaceholders } from '$lib/components/wizard/wizardTypes'
import type {
  Story,
  VaultScenario,
  Character,
  Entry,
  StoryEntry,
  CampaignSettings,
  CampaignType,
} from '$lib/types'
import { lorebookVault } from '$lib/stores/lorebookVault.svelte'
import { descriptorsToString, stringToDescriptors } from '$lib/utils/visualDescriptors'
