import type { PresetPack, CustomVariable } from '$lib/services/packs/types'
import { LorebookImportExport } from '$lib/services/lorebookImportExport'
import {
  isPartyPendingCreation,
  validatePartyPendingRoster,
} from '$lib/services/campaign/campaign-creation-rules'

// Import Modular Stores
import { NarrativeStore } from './narrativeStore.svelte'
import { SettingStore } from './settingStore.svelte'
import { CharacterStore } from './characterStore.svelte'
import { ImageStore } from './imageStore.svelte'
import { SvelteSet } from 'svelte/reactivity'

function buildWorldCharterFromWizard(data: WizardData): string {
  const genre = data.genre === 'custom' ? data.customGenre : data.genre
  const lines = [
    `Campaign: ${data.title}`,
    genre && `Genre: ${genre}`,
    `POV/Tense: ${data.writingStyle.pov}, ${data.writingStyle.tense}`,
    data.writingStyle.tone && `Tone: ${data.writingStyle.tone}`,
    data.settingSeed && `Premise: ${data.settingSeed}`,
    data.expandedSetting?.description && `Setting: ${data.expandedSetting.description}`,
    data.expandedSetting?.atmosphere && `Atmosphere: ${data.expandedSetting.atmosphere}`,
    data.expandedSetting?.themes?.length && `Themes: ${data.expandedSetting.themes.join(', ')}`,
    data.protagonist?.name && `Primary character: ${data.protagonist.name}`,
    data.characters?.length &&
      `Important characters: ${data.characters
        .map((character) => character.name)
        .filter(Boolean)
        .join(', ')}`,
    data.openingGuidance && `Opening guidance: ${data.openingGuidance}`,
  ].filter((line): line is string => typeof line === 'string' && line.trim().length > 0)

  return lines.join('\n')
}

export class WizardStore {
  // Sub-stores
  narrative = new NarrativeStore()
  setting = new SettingStore()
  character = new CharacterStore()
  image = new ImageStore()

  // Wizard State
  currentStep = $state(1)
  totalSteps = 9
  isCreatingStory = $state(false)
  campaignType = $state<CampaignType>('human_gm_solo')
  createPartyDuringSessionZero = $state(false)

  // Pack selection state
  selectedPackId = $state<string>('default-pack')
  availablePacks = $state<PresetPack[]>([])
  packVariables = $state<CustomVariable[]>([])
  customVariableValues = $state<Record<string, string>>({})
  packsLoaded = $state(false)

  aiPlayers = $state<import('$lib/types').AIPlayer[]>([])
  aiPlayerAssignments = $state<Record<string, string>>({})
  aiPlayerRosterIds = $state<string[]>([])
  aiPlayersLoaded = $state(false)

  // Track auto-linked lorebook IDs so they can be removed when source is cleared
  private _scenarioLinkedLorebookVaultId = $state<string | null>(null)
  private _protagonistLinkedLorebookVaultId = $state<string | null>(null)

  // Captured from the source campaign when prefilling from an existing story ("copy campaign"),
  // then applied to the newly created campaign so a duplicate keeps its configuration instead of
  // resetting to defaults.
  private _copiedRulesetId = $state<string | null>(null)
  private _copiedCampaignSettings = $state<Omit<
    CampaignSettings,
    'campaignId' | 'createdAt' | 'updatedAt'
  > | null>(null)

  onClose: () => void

  constructor(onClose: () => void) {
    this.onClose = onClose
  }

  private mapStoryGenreToWizard(genre: string | null): {
    selectedGenre: Genre
    customGenre: string
  } {
    if (!genre) return { selectedGenre: 'fantasy', customGenre: '' }

    const normalized = genre.trim().toLowerCase()
    switch (normalized) {
      case 'fantasy':
      case 'sci-fi':
      case 'mystery':
      case 'horror':
      case 'slice of life':
      case 'historical':
        return { selectedGenre: normalized as Genre, customGenre: '' }
      default:
        return { selectedGenre: 'custom', customGenre: genre }
    }
  }

  private toImportedEntry(entry: Entry): LorebookImportExport.ImportedEntry {
    return {
      name: entry.name,
      type: entry.type,
      description: entry.description,
      keywords: entry.injection?.keywords ?? [],
      aliases: entry.aliases ?? [],
      injectionMode: entry.injection?.mode ?? 'keyword',
      priority: entry.injection?.priority ?? 50,
    }
  }

  private pickProtagonist(characters: Character[]): Character | null {
    if (characters.length === 0) return null
    const self = characters.find((c) => c.relationship === 'self')
    return self ?? characters[0]
  }

  private pickOpening(entries: StoryEntry[]): string {
    const firstNarration = entries.find((e) => e.type === 'narration' && e.content?.trim())
    if (firstNarration) return firstNarration.content

    const firstEntry = entries.find((e) => e.content?.trim())
    return firstEntry?.content ?? ''
  }

  async prefillFromStory(sourceStory: Story): Promise<void> {
    // Core metadata
    this.narrative.selectedMode = sourceStory.mode
    const { selectedGenre, customGenre } = this.mapStoryGenreToWizard(sourceStory.genre)
    this.narrative.selectedGenre = selectedGenre
    // Step 3 displays the genre text field directly, so keep it populated for all stories.
    this.narrative.customGenre = sourceStory.genre ?? customGenre

    // Story settings
    const storySettings = sourceStory.settings ?? {}
    this.narrative.selectedPOV = storySettings.pov ?? 'first'
    this.narrative.selectedTense = storySettings.tense ?? 'present'
    this.narrative.tone = storySettings.tone ?? 'immersive and engaging'
    this.narrative.visualProseMode = storySettings.visualProseMode ?? false
    this.narrative.imageGenerationMode = storySettings.imageGenerationMode ?? 'none'
    this.narrative.backgroundImagesEnabled = storySettings.backgroundImagesEnabled ?? false
    this.narrative.referenceMode = storySettings.referenceMode ?? false

    // Story title (make copy intention explicit)
    this.narrative.storyTitle = `${sourceStory.title} (Copy)`

    // Pack + custom variables
    await this.loadPacks()
    const packId = (await database.getStoryPackId(sourceStory.id)) ?? 'default-pack'
    this.selectedPackId = packId
    await this.loadPackVariables(packId)
    const customVars = await database.getStoryCustomVariables(sourceStory.id)
    if (customVars) {
      this.customVariableValues = {
        ...this.customVariableValues,
        ...customVars,
      }
    }

    const branchId = sourceStory.currentBranchId ?? null

    // Campaign settings (ruleset, party sizing, AI Players, content intensity, etc.) so a
    // duplicated campaign keeps the same configuration instead of resetting to defaults.
    const sourceCampaign = await database.getCampaignByStoryId(sourceStory.id)
    if (sourceCampaign) {
      this._copiedRulesetId = sourceCampaign.rulesetId
      const sourceSettings = await database.getCampaignSettings(sourceCampaign.id)
      if (sourceSettings) {
        const {
          campaignId: _campaignId,
          createdAt: _createdAt,
          updatedAt: _updatedAt,
          ...rest
        } = sourceSettings
        this._copiedCampaignSettings = rest
      }
    }

    // Setting seed from current location (fallback to story description)
    const locations = await database.getLocationsForBranch(sourceStory.id, branchId)
    const currentLocation = locations.find((l) => l.current) ?? locations[0]
    const settingSeed =
      currentLocation?.description?.trim() || sourceStory.description?.trim() || ''
    this.setting.settingSeed = settingSeed
    if (settingSeed) {
      this.setting.useSettingAsIs()
    }

    // Characters + portrait descriptors
    const characters = await database.getCharactersForBranch(sourceStory.id, branchId)
    const protagonist = this.pickProtagonist(characters)
    if (protagonist) {
      this.character.manualCharacterName = protagonist.name
      this.character.manualCharacterDescription = protagonist.description ?? ''
      this.character.manualCharacterBackground = ''
      this.character.manualCharacterMotivation = ''
      this.character.manualCharacterTraits = protagonist.traits.join(', ')
      this.character.useManualCharacter()

      this.image.protagonistVisualDescriptors = descriptorsToString(protagonist.visualDescriptors)
      this.image.protagonistPortrait = protagonist.portrait
    }

    const supportingCharacters = characters
      .filter((c) => c.id !== protagonist?.id)
      .map((c) => ({
        name: c.name,
        role: ((c.metadata as Record<string, unknown> | null)?.role as string | undefined) || '',
        description: c.description ?? '',
        relationship: c.relationship ?? '',
        traits: c.traits,
      }))

    this.character.supportingCharacters = supportingCharacters
    this.image.supportingCharacterVisualDescriptors = Object.fromEntries(
      supportingCharacters.map((c) => {
        const source = characters.find((x) => x.name === c.name)
        return [c.name, descriptorsToString(source?.visualDescriptors ?? {})]
      }),
    )
    this.image.supportingCharacterPortraits = Object.fromEntries(
      supportingCharacters.map((c) => {
        const source = characters.find((x) => x.name === c.name)
        return [c.name, source?.portrait ?? null]
      }),
    )

    // Lorebook entries -> imported lorebook list
    const entries = await database.getEntriesForBranch(sourceStory.id, branchId)
    if (entries.length > 0) {
      const importedEntries = entries.map((e) => this.toImportedEntry(e))
      this.narrative.importedLorebooks = [
        {
          id: crypto.randomUUID(),
          filename: `${sourceStory.title} (From Story)`,
          entries: importedEntries,
          expanded: false,
          result: {
            success: true,
            entries: importedEntries,
            errors: [],
            warnings: [],
            metadata: {
              format: 'aventura',
              totalEntries: importedEntries.length,
              importedEntries: importedEntries.length,
              skippedEntries: 0,
            },
          },
        },
      ]
    } else {
      this.narrative.importedLorebooks = []
    }

    // Opening scene prefill
    const storyEntries = await database.getStoryEntriesForBranch(sourceStory.id, branchId)
    const openingScene = this.pickOpening(storyEntries)
    if (openingScene) {
      this.narrative.generatedOpening = {
        title: this.narrative.storyTitle,
        scene: openingScene,
        initialLocation: {
          name: currentLocation?.name ?? 'Starting Location',
          description: currentLocation?.description ?? 'The story begins here.',
        },
      }
      this.narrative.generatedOpeningTranslated = null
      this.narrative.manualOpeningText = ''
    }
  }

  // Navigation
  canProceed(): boolean {
    switch (this.currentStep) {
      case 1: // Pack Selection
        return this.allVariablesFilled()
      case 2: // World & Setting
        return this.setting.settingSeed.trim().length > 0
      case 3: // Character (required - must have protagonist)
        return this.isPartyPendingCreation || this.character.protagonist !== null
      case 4: // Supporting Cast (optional)
        return true
      case 5: // Lorebook (optional)
        return true
      case 6: // Portraits (optional)
        return true
      case 7: // Writing Style
        return true
      case 8: // AI Player assignments (optional)
        return validatePartyPendingRoster(
          this.campaignType,
          this.createPartyDuringSessionZero,
          this.aiPlayerRosterIds,
        )
      case 9: // Opening
        return this.narrative.storyTitle.trim().length > 0
      default:
        return false
    }
  }

  get isPartyPendingCreation(): boolean {
    return isPartyPendingCreation(this.campaignType, this.createPartyDuringSessionZero)
  }

  setCampaignType(type: CampaignType): void {
    this.campaignType = type
    if (type !== 'human_gm_ai_players') this.createPartyDuringSessionZero = false
  }

  setAIPlayerRosterMembership(aiPlayerId: string, included: boolean): void {
    this.aiPlayerRosterIds = included
      ? [...new SvelteSet([...this.aiPlayerRosterIds, aiPlayerId])]
      : this.aiPlayerRosterIds.filter((id) => id !== aiPlayerId)
  }

  nextStep() {
    if (this.currentStep < this.totalSteps && this.canProceed()) {
      this.currentStep++

      // Auto-scroll logic for scenario carousel is UI-side, but state trigger is here
      // We could use an effect in the component to watch currentStep
    }
  }

  prevStep() {
    if (this.currentStep > 1) {
      this.currentStep--
    }
  }

  // Pack selection methods

  async loadPacks(): Promise<void> {
    if (this.packsLoaded) return
    this.availablePacks = await packService.getAllPacks()
    this.packsLoaded = true
    await this.loadPackVariables(this.selectedPackId)
  }

  async loadAIPlayers(): Promise<void> {
    if (this.aiPlayersLoaded) return
    this.aiPlayers = await database.listAIPlayers()
    this.aiPlayersLoaded = true
  }

  setAIPlayerAssignment(characterName: string, aiPlayerId: string): void {
    const next = { ...this.aiPlayerAssignments }
    if (aiPlayerId) next[characterName] = aiPlayerId
    else delete next[characterName]
    this.aiPlayerAssignments = next
  }

  async loadPackVariables(packId: string): Promise<void> {
    this.packVariables = await database.getPackVariables(packId)
    const newValues: Record<string, string> = {}
    for (const v of this.packVariables) {
      newValues[v.variableName] = v.defaultValue ?? ''
    }
    this.customVariableValues = newValues
  }

  async selectPack(packId: string): Promise<void> {
    this.selectedPackId = packId
    await this.loadPackVariables(packId)
  }

  setVariableValue(variableName: string, value: string): void {
    this.customVariableValues = { ...this.customVariableValues, [variableName]: value }
  }

  allVariablesFilled(): boolean {
    return this.packVariables.every((v) => {
      const val = this.customVariableValues[v.variableName]
      if (v.variableType === 'boolean') return true
      return val !== undefined && val !== ''
    })
  }

  // Orchestrations

  // Select Scenario (Cross-store)
  selectScenario(scenarioId: string) {
    const scenario = QUICK_START_SEEDS.find((s) => s.id === scenarioId)
    if (!scenario) return

    this.setting.selectedScenarioId = scenarioId

    // Narrative: Genre
    // Always set to 'custom' so that the text field (customGenre) is treated as the source of truth
    // for the genre label in scenarioService.
    this.narrative.selectedGenre = 'custom'
    this.narrative.customGenre = scenario.genre

    // Setting: Seed
    const locationDesc = scenario.initialState.startingLocation?.description
    if (locationDesc) {
      this.setting.settingSeed = locationDesc
      this.setting.useSettingAsIs()
    }

    // Character: Protagonist Manual Input
    const proto = scenario.initialState.protagonist
    if (proto) {
      this.character.manualCharacterName = proto.name ?? ''
      this.character.manualCharacterDescription = proto.description ?? ''
      // Type assertion needed as Character type doesn't have background/motivation directly
      this.character.manualCharacterBackground = (proto as any).background ?? ''
      this.character.manualCharacterMotivation = (proto as any).motivation ?? ''
      this.character.manualCharacterTraits = proto.traits?.join(', ') ?? ''
      this.character.showManualInput = true
      this.character.useManualCharacter()
    }
  }

  selectScenarioFromVault(scenario: VaultScenario) {
    // 1. Setting
    this.setting.settingSeed = scenario.settingSeed
    this.setting.expandedSetting = null
    this.setting.clearSettingEditState()

    // 2. NPCs (Character Store)
    const importedNpcs: GeneratedCharacter[] = scenario.npcs.map((npc) => ({
      npcId: npc.id,
      name: npc.name,
      role: npc.role,
      description: npc.description,
      relationship: npc.relationship,
      traits: npc.traits || [],
    }))

    // Filter duplicates if any existing imported NPCs
    if (this.character.importedCardNpcs.length > 0) {
      const prevImportedNames = new SvelteSet(this.character.importedCardNpcs.map((n) => n.name))
      this.character.supportingCharacters = this.character.supportingCharacters.filter(
        (c) => !prevImportedNames.has(c.name),
      )
    }

    this.character.supportingCharacters = [...this.character.supportingCharacters, ...importedNpcs]
    this.character.importedCardNpcs = importedNpcs

    // 3. Title (Narrative Store)
    if (scenario.name) {
      this.character.cardImportedTitle = scenario.name
      this.narrative.storyTitle = scenario.name
    }

    // 4. Opening (Character/Narrative Store Integration)
    if (scenario.firstMessage) {
      this.character.cardImportedFirstMessage = scenario.firstMessage
      this.character.cardImportedAlternateGreetings = scenario.alternateGreetings || []
      this.character.selectedGreetingIndex = 0
    } else {
      this.character.cardImportedFirstMessage = null
      this.character.cardImportedAlternateGreetings = []
    }

    // 5. Auto-link embedded lorebook if available
    // Remove previously auto-linked scenario lorebook first
    if (this._scenarioLinkedLorebookVaultId) {
      this._removeLinkedLorebook(this._scenarioLinkedLorebookVaultId)
      this._scenarioLinkedLorebookVaultId = null
    }
    if (scenario.metadata?.linkedLorebookId) {
      const linkedId = scenario.metadata.linkedLorebookId as string
      const lorebook = lorebookVault.getById(linkedId)
      if (lorebook) {
        const alreadyAdded = this.narrative.importedLorebooks.some((lb) => lb.vaultId === linkedId)
        if (!alreadyAdded) {
          this.narrative.addLorebookFromVault(lorebook)
          ui.showToast(`Added embedded lorebook: ${lorebook.name}`, 'info')
        }
        this._scenarioLinkedLorebookVaultId = linkedId
      }
    }

    this.setting.showScenarioVaultPicker = false
    this.setting.useSettingAsIs()
  }

  /** Remove auto-linked lorebook by vault lorebook ID */
  _removeLinkedLorebook(lorebookVaultId: string) {
    const imported = this.narrative.importedLorebooks.find((lb) => lb.vaultId === lorebookVaultId)
    if (imported) {
      const name = lorebookVault.getById(lorebookVaultId)?.name ?? 'lorebook'
      this.narrative.removeLorebook(imported.id)
      ui.showToast(`Removed embedded lorebook: ${name}`, 'info')
    }
  }

  /** Clear scenario's auto-linked lorebook (called when clearing card import) */
  clearScenarioLinkedLorebook() {
    if (this._scenarioLinkedLorebookVaultId) {
      this._removeLinkedLorebook(this._scenarioLinkedLorebookVaultId)
      this._scenarioLinkedLorebookVaultId = null
    }
  }

  /** Track/untrack protagonist linked lorebook */
  setProtagonistLinkedLorebook(lorebookVaultId: string | null) {
    if (this._protagonistLinkedLorebookVaultId) {
      this._removeLinkedLorebook(this._protagonistLinkedLorebookVaultId)
    }
    this._protagonistLinkedLorebookVaultId = lorebookVaultId
  }

  // Wrapper for Generate Opening (Needs data from all stores)
  async generateOpeningScene() {
    const wizardData: WizardData = {
      mode: this.narrative.selectedMode,
      genre: this.narrative.selectedGenre,
      customGenre: this.narrative.customGenre || undefined,
      settingSeed: this.setting.settingSeed,
      expandedSetting: this.setting.expandedSetting || undefined,
      protagonist: this.character.protagonist || undefined,
      characters:
        this.character.supportingCharacters.length > 0
          ? this.character.supportingCharacters
          : undefined,
      writingStyle: {
        pov: this.narrative.selectedPOV,
        tense: this.narrative.selectedTense,
        tone: this.narrative.tone,
      },
      title: this.narrative.storyTitle,
      openingGuidance: this.narrative.openingGuidance.trim() || undefined,
    }

    await this.narrative.generateOpeningScene(wizardData)
  }

  // Wrapper for Refine Opening
  async refineOpeningScene() {
    const wizardData: WizardData = {
      mode: this.narrative.selectedMode,
      genre: this.narrative.selectedGenre,
      customGenre: this.narrative.customGenre || undefined,
      settingSeed: this.setting.settingSeed,
      expandedSetting: this.setting.expandedSetting || undefined,
      protagonist: this.character.protagonist || undefined,
      characters:
        this.character.supportingCharacters.length > 0
          ? this.character.supportingCharacters
          : undefined,
      writingStyle: {
        pov: this.narrative.selectedPOV,
        tense: this.narrative.selectedTense,
        tone: this.narrative.tone,
      },
      title: this.narrative.storyTitle,
      openingGuidance: this.narrative.openingGuidance.trim() || undefined,
    }

    await this.narrative.refineOpeningScene(wizardData)
  }

  // Create Story
  async createStory() {
    if (!this.narrative.storyTitle.trim() || this.isCreatingStory) return
    const partyPendingCreation = isPartyPendingCreation(
      this.campaignType,
      this.createPartyDuringSessionZero,
    )
    const requestedCampaignType = this.campaignType
    const requestedRosterIds = [...this.aiPlayerRosterIds]
    const requestedPackId = this.selectedPackId
    const requestedCustomVariableValues = { ...this.customVariableValues }

    // Use manual opening if provided
    if (!this.narrative.generatedOpening && this.narrative.manualOpeningText.trim()) {
      this.narrative.generatedOpening = {
        scene: this.narrative.manualOpeningText.trim(),
        title: this.narrative.storyTitle || 'Untitled Story',
        initialLocation: {
          name: 'Starting Location',
          description: 'The place where your journey begins.',
        },
      }
    }

    // Use card imported opening if available
    if (!this.narrative.generatedOpening && this.character.cardImportedFirstMessage) {
      const selectedCardScene =
        this.character.selectedGreetingIndex === 0
          ? this.character.cardImportedFirstMessage
          : this.character.cardImportedAlternateGreetings[this.character.selectedGreetingIndex - 1]

      this.narrative.generatedOpening = {
        scene: selectedCardScene || this.character.cardImportedFirstMessage,
        title: this.character.cardImportedTitle || this.narrative.storyTitle || 'Untitled Story',
        initialLocation: {
          name: 'Starting Location',
          description: 'The place where your journey begins.',
        },
      }
    }

    if (!this.narrative.generatedOpening?.scene?.trim() && !partyPendingCreation) {
      this.narrative.openingError =
        'Please provide an opening scene (write your own or generate with AI)'
      return
    }

    if (!this.narrative.generatedOpening && partyPendingCreation) {
      this.narrative.generatedOpening = {
        scene: '',
        title: this.narrative.storyTitle,
        initialLocation: {
          name: this.setting.expandedSetting?.keyLocations[0]?.name || 'Campaign Setting',
          description:
            this.setting.expandedSetting?.keyLocations[0]?.description || this.setting.settingSeed,
        },
      }
    }

    const protagonistName = this.character.protagonist?.name || 'the protagonist'

    const processedSettingSeed = replaceUserPlaceholders(this.setting.settingSeed, protagonistName)

    let processedExpandedSetting: ExpandedSetting | null = null
    if (this.setting.expandedSetting) {
      processedExpandedSetting = {
        ...this.setting.expandedSetting,
        description: replaceUserPlaceholders(
          this.setting.expandedSetting.description,
          protagonistName,
        ),
        keyLocations: this.setting.expandedSetting.keyLocations.map((l) => ({
          ...l,
          description: replaceUserPlaceholders(l.description, protagonistName),
        })),
        atmosphere: replaceUserPlaceholders(
          this.setting.expandedSetting.atmosphere,
          protagonistName,
        ),
        themes: this.setting.expandedSetting.themes.map((t) =>
          replaceUserPlaceholders(t, protagonistName),
        ),
        potentialConflicts: this.setting.expandedSetting.potentialConflicts.map((c) =>
          replaceUserPlaceholders(c, protagonistName),
        ),
      }
    }

    const generatedOpening = this.narrative.generatedOpening ?? {
      title: 'Untitled Opening',
      scene: '',
      initialLocation: { name: '', description: '' },
    }
    const processedOpening = {
      ...generatedOpening,
      title: generatedOpening.title ?? 'Untitled Opening',
      scene: replaceUserPlaceholders(generatedOpening.scene ?? '', protagonistName),
      initialLocation: generatedOpening.initialLocation ?? { name: '', description: '' },
    }

    if (!processedOpening.scene.trim() && !partyPendingCreation) {
      this.narrative.openingError =
        'The opening scene is empty. Please write or generate an opening before starting.'
      return
    }

    this.isCreatingStory = true

    const processedCharacters = this.character.supportingCharacters.map((char) => ({
      ...char,
      name: replaceUserPlaceholders(char.name, protagonistName),
      description: replaceUserPlaceholders(char.description, protagonistName),
      role: char.role ? replaceUserPlaceholders(char.role, protagonistName) : '',
      relationship: char.relationship
        ? replaceUserPlaceholders(char.relationship, protagonistName)
        : '',
      traits: char.traits.map((t) => replaceUserPlaceholders(t, protagonistName)),
    }))

    const processedEntries = this.narrative.importedEntries.map((e) => ({
      ...e,
      name: replaceUserPlaceholders(e.name, protagonistName),
      description: replaceUserPlaceholders(e.description, protagonistName),
      keywords: e.keywords.map((k) => replaceUserPlaceholders(k, protagonistName)),
      // To fix a regression issue where lorebooks from older versions didnt default to empty array when no aliases were set
      aliases: e.aliases ?? [],
    }))

    const wizardData: WizardData = {
      mode: this.narrative.selectedMode,
      genre: this.narrative.selectedGenre,
      customGenre: this.narrative.customGenre || undefined,
      settingSeed: processedSettingSeed,
      expandedSetting: processedExpandedSetting || undefined,
      protagonist: this.character.protagonist || undefined,
      characters: processedCharacters.length > 0 ? processedCharacters : undefined,
      writingStyle: {
        pov: this.narrative.selectedPOV,
        tense: this.narrative.selectedTense,
        tone: this.narrative.tone,
        visualProseMode: this.narrative.visualProseMode,
        imageGenerationMode: this.narrative.imageGenerationMode,
        backgroundImagesEnabled: this.narrative.backgroundImagesEnabled,
        referenceMode: this.narrative.referenceMode,
      },
      title: this.narrative.storyTitle,
      openingGuidance: this.narrative.openingGuidance.trim() || undefined,
    }

    const storyData = await scenarioService.prepareStoryData(wizardData, processedOpening)
    if (partyPendingCreation) {
      storyData.protagonist = {}
      storyData.characters = []
    }
    const worldCharter = buildWorldCharterFromWizard(wizardData)

    if (storyData.protagonist) {
      storyData.protagonist.portrait = this.image.protagonistPortrait ?? undefined
      storyData.protagonist.visualDescriptors = this.image.protagonistVisualDescriptors
        ? stringToDescriptors(this.image.protagonistVisualDescriptors)
        : {}
    }

    storyData.characters = storyData.characters.map((char) => ({
      ...char,
      portrait: char.name
        ? (this.image.supportingCharacterPortraits[char.name] ?? undefined)
        : undefined,
      visualDescriptors:
        char.name && this.image.supportingCharacterVisualDescriptors[char.name]
          ? stringToDescriptors(this.image.supportingCharacterVisualDescriptors[char.name])
          : {},
    }))

    // Build translations object if we have translations
    const translationSettings = settings.translationSettings
    let translations:
      | {
          language: string
          openingScene?: string
          protagonist?: {
            name?: string
            description?: string
            traits?: string[]
            visualDescriptors?: string[]
          }
          startingLocation?: { name?: string; description?: string }
          characters?: {
            [originalName: string]: {
              name?: string
              description?: string
              relationship?: string
              traits?: string[]
              visualDescriptors?: string[]
            }
          }
        }
      | undefined

    if (TranslationService.shouldTranslate(translationSettings)) {
      const targetLanguage = translationSettings.targetLanguage
      translations = { language: targetLanguage }

      // Opening scene translation
      if (this.narrative.generatedOpeningTranslated?.scene) {
        translations.openingScene = this.narrative.generatedOpeningTranslated.scene
      }

      // Protagonist translation
      if (this.character.protagonistTranslated) {
        // Translate visual descriptors if present
        let protagonistVisualDescriptorsTranslated: string[] | undefined
        if (this.image.protagonistVisualDescriptors?.trim()) {
          try {
            const visualDescriptorsArray = this.image.protagonistVisualDescriptors
              .split(',')
              .map((d) => d.trim())
              .filter(Boolean)
            if (visualDescriptorsArray.length > 0) {
              const translated = await aiService.translateWizardBatch(
                { visualDescriptors: visualDescriptorsArray.join(', ') },
                targetLanguage,
              )
              if (translated.visualDescriptors) {
                protagonistVisualDescriptorsTranslated = translated.visualDescriptors
                  .split(',')
                  .map((d) => d.trim())
                  .filter(Boolean)
              }
            }
          } catch (e) {
            console.error('[Wizard] Failed to translate protagonist visual descriptors:', e)
          }
        }
        translations.protagonist = {
          name: this.character.protagonistTranslated.name,
          description: this.character.protagonistTranslated.description,
          traits: this.character.protagonistTranslated.traits,
          visualDescriptors: protagonistVisualDescriptorsTranslated,
        }
      }

      // Starting location translation (from opening's initialLocation)
      if (this.narrative.generatedOpeningTranslated?.initialLocation) {
        translations.startingLocation = {
          name: this.narrative.generatedOpeningTranslated.initialLocation.name,
          description: this.narrative.generatedOpeningTranslated.initialLocation.description,
        }
      }

      // Supporting characters translation - key by processed name (after placeholder replacement)
      if (this.character.supportingCharactersTranslated.length > 0) {
        translations.characters = {}
        for (let i = 0; i < this.character.supportingCharacters.length; i++) {
          const processed = processedCharacters[i]
          const translated = this.character.supportingCharactersTranslated[i]
          // Use processed name as key since createStoryFromWizard looks up by processed name
          if (processed?.name && translated) {
            // Translate visual descriptors if present for this character
            let charVisualDescriptorsTranslated: string[] | undefined
            const charVisualDescriptors =
              this.image.supportingCharacterVisualDescriptors[processed.name]
            if (charVisualDescriptors?.trim()) {
              try {
                const visualDescriptorsArray = charVisualDescriptors
                  .split(',')
                  .map((d) => d.trim())
                  .filter(Boolean)
                if (visualDescriptorsArray.length > 0) {
                  const translatedVD = await aiService.translateWizardBatch(
                    { visualDescriptors: visualDescriptorsArray.join(', ') },
                    targetLanguage,
                  )
                  if (translatedVD.visualDescriptors) {
                    charVisualDescriptorsTranslated = translatedVD.visualDescriptors
                      .split(',')
                      .map((d) => d.trim())
                      .filter(Boolean)
                  }
                }
              } catch (e) {
                console.error('[Wizard] Failed to translate character visual descriptors:', e)
              }
            }
            translations.characters[processed.name] = {
              name: translated.name,
              description: translated.description,
              relationship: translated.relationship,
              traits: translated.traits,
              visualDescriptors: charVisualDescriptorsTranslated,
            }
          }
        }
      }

      // Debug: log what translations we're passing
      console.log('[Wizard] Translations being passed to createStoryFromWizard:', {
        hasOpeningScene: !!translations.openingScene,
        hasProtagonist: !!translations.protagonist,
        hasStartingLocation: !!translations.startingLocation,
        startingLocation: translations.startingLocation,
        characterCount: translations.characters ? Object.keys(translations.characters).length : 0,
        characters: translations.characters,
      })
    }

    try {
      console.info('[Wizard] Starting campaign persistence', {
        title: storyData.title,
        packId: requestedPackId,
        customVariableCount: Object.keys(requestedCustomVariableValues).length,
      })
      const newStory = await story.createStoryFromWizard({
        ...storyData,
        allowEmptyOpening: partyPendingCreation,
        importedEntries: processedEntries.length > 0 ? processedEntries : undefined,
        packId: requestedPackId,
        customVariableValues: requestedCustomVariableValues,
        translations,
      })
      console.info('[Wizard] Story transaction completed', { storyId: newStory.id })

      // Assign pack and save custom variable values
      console.info('[Wizard] Assigning story pack', {
        storyId: newStory.id,
        packId: requestedPackId,
      })
      await database.setStoryPack(newStory.id, requestedPackId)
      console.info('[Wizard] Story pack assigned', { storyId: newStory.id })
      if (Object.keys(requestedCustomVariableValues).length > 0) {
        console.info('[Wizard] Saving custom variable values', {
          storyId: newStory.id,
          count: Object.keys(requestedCustomVariableValues).length,
        })
        await database.setStoryCustomVariables(newStory.id, requestedCustomVariableValues)
        console.info('[Wizard] Custom variable values saved', { storyId: newStory.id })
      }

      console.info('[Wizard] Reloading created campaign', { storyId: newStory.id })
      await story.loadStory(newStory.id)
      const createdCampaign = await database.getCampaignByStoryId(newStory.id)
      if (!createdCampaign) throw new Error('Created campaign row could not be loaded')
      await database.updateCampaignType(createdCampaign.id, requestedCampaignType)
      {
        const createdCharacters = await database.getCharacters(newStory.id)
        const assignments = Object.entries(this.aiPlayerAssignments)
        for (const [characterName, aiPlayerId] of assignments) {
          const character = createdCharacters.find((item) => item.name === characterName)
          if (!character) continue
          await database.upsertPlayerCharacter({
            id: crypto.randomUUID(),
            campaignId: createdCampaign.id,
            aiPlayerId,
            characterId: character.id,
            roleplayNotes: null,
            characterSecrets: [],
            interPlayerRelationshipOverrides: {},
            joinedAt: Date.now(),
            leftAt: null,
          })
        }
        const rosterIds = new SvelteSet([
          ...requestedRosterIds,
          ...Object.values(this.aiPlayerAssignments),
        ])
        const now = Date.now()
        for (const aiPlayerId of rosterIds) {
          await database.upsertCampaignAIPlayer({
            id: crypto.randomUUID(),
            campaignId: createdCampaign.id,
            aiPlayerId,
            joinedAt: now,
            leftAt: null,
          })
        }
        if (partyPendingCreation) {
          await database.upsertCampaignFormationState({
            campaignId: createdCampaign.id,
            status: 'party_pending',
            requiredAIPlayerIds: [...rosterIds],
            source: 'created_pending',
            createdAt: now,
            updatedAt: now,
          })
        }
      }
      console.info('[Wizard] Created campaign reloaded', { storyId: newStory.id })
      if (
        campaign.current &&
        this._copiedRulesetId &&
        campaign.current.rulesetId !== this._copiedRulesetId
      ) {
        console.info('[Wizard] Applying copied ruleset', { storyId: newStory.id })
        await campaign.setRuleset(this._copiedRulesetId)
      }
      if (campaign.settings && this._copiedCampaignSettings) {
        console.info('[Wizard] Applying copied campaign settings', { storyId: newStory.id })
        await campaign.updateSettings(this._copiedCampaignSettings)
      }
      if (campaign.settings && !campaign.settings.worldCharter && worldCharter) {
        console.info('[Wizard] Saving generated world charter', { storyId: newStory.id })
        await campaign.updateSettings({ worldCharter })
      }
      if (Object.keys(this.aiPlayerAssignments).length > 0 || requestedRosterIds.length > 0) {
        console.info('[Wizard] Enabling AI Players for assigned profiles', { storyId: newStory.id })
        await database.updateCampaignSettings(createdCampaign.id, { aiPlayersEnabled: true })
      }
      await campaign.loadForStory(newStory.id)
      ui.setActivePanel('story')
      this.onClose()
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : typeof error === 'string'
            ? error
            : error && typeof error === 'object'
              ? JSON.stringify(error)
              : 'Failed to create campaign'
      console.error('[Wizard] Campaign creation failed', { message, error })
      ui.showToast(message, 'error')
      // Do NOT close the modal on error - let user retry or cancel
    } finally {
      this.isCreatingStory = false
    }
  }
}
